INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct, client_needs_category, client_needs_subcategory, nursing_subject, body_system, topic, subtopic, difficulty, bloom_level, tags, marks, is_published, is_builder_visible, is_free_sample, batch_id, question_ref
) VALUES
('NCLEX_SATA_399001', 'SATA', 'A nurse assesses a client taking digoxin. Which findings indicate possible digoxin toxicity? Select all that apply.', 'GI upset, visual halos, and bradycardia are classic signs of digoxin toxicity.', '{"options":[{"id":"A","text":"Nausea and vomiting"},{"id":"B","text":"Visual disturbances (yellow-green halos)"},{"id":"C","text":"Bradycardia"},{"id":"D","text":"Hypertension"},{"id":"E","text":"Increased appetite"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin toxicity', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_399001', 'SELECT_N', 'Which 3 tasks can the nurse appropriately delegate to unlicensed assistive personnel?', 'UAP may perform stable ADLs and data collection, not assessment or medication administration.', '{"options":[{"id":"A","text":"Assisting a stable client with bathing"},{"id":"B","text":"Recording oral intake and output"},{"id":"C","text":"Ambulating a stable postoperative client"},{"id":"D","text":"Performing initial admission assessment"},{"id":"E","text":"Administering oral medications"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', NULL, 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_399001', 'CLOZE', 'Based on the assessment, the client is most likely experiencing {1}, evidenced by the presence of {2}.', 'Elevated BNP with bilateral crackles indicates heart failure exacerbation.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"heart failure"},{"id":"c2","text":"pulmonary embolism"},{"id":"c3","text":"pneumonia"}]},{"id":"b2","choices":[{"id":"c1","text":"bilateral crackles"},{"id":"c2","text":"wheezing"},{"id":"c3","text":"stridor"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Heart failure', NULL, 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_399001', 'DRAG_CLOZE', 'A client taking furosemide has a potassium level of [1]; the nurse anticipates a replacement goal of [2].', 'Furosemide causes hypokalemia; the goal is a normal potassium of ~4.2 mEq/L.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"2.9 mEq/L"},{"id":"t2","text":"4.2 mEq/L"},{"id":"t3","text":"4.8 mEq/L"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Genitourinary', 'Electrolytes', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_399001', 'DRAG_ORDER', 'A postoperative client suddenly reports shortness of breath. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Apply oxygen"},{"id":"t2","text":"Elevate the head of the bed"},{"id":"t3","text":"Notify the provider"},{"id":"t4","text":"Obtain an ECG"},{"id":"t5","text":"Document the event"},{"id":"t6","text":"Offer oral fluids"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Emergency response', NULL, 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334001', 'MCQ', 'A nurse is administering a continuous enteral feeding through a nasogastric tube. The client begins coughing and reports feeling short of breath. After stopping the feeding, which action should the nurse take NEXT?', 'Coughing and dyspnea during a feeding suggest possible aspiration; stopping the feed and raising the head of the bed protects the airway before further assessment.', '{"options":[{"id":"A","text":"Raise the head of the bed to at least 30 to 45 degrees"},{"id":"B","text":"Flush the tube with 60 mL of warm water"},{"id":"C","text":"Increase the feeding rate to clear the tube"},{"id":"D","text":"Remove the nasogastric tube immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevating the head reduces aspiration risk and eases breathing while the nurse assesses further.","B":"Incorrect. Flushing does not address possible aspiration and could worsen it.","C":"Incorrect. Resuming or increasing the feed during respiratory distress is unsafe.","D":"Incorrect. Removal is not indicated before assessment and could be premature."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Aspiration prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334002', 'MCQ', 'A nurse is caring for an immobile client on bed rest with a Braden score of 12. Which intervention BEST addresses this client''s pressure-injury risk?', 'A low Braden score signals high risk; scheduled repositioning is the cornerstone of pressure-injury prevention.', '{"options":[{"id":"A","text":"Reposition the client at least every 2 hours"},{"id":"B","text":"Massage reddened bony prominences vigorously"},{"id":"C","text":"Keep the head of the bed elevated at 60 degrees at all times"},{"id":"D","text":"Use a doughnut-shaped ring cushion under the sacrum"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A Braden of 12 indicates high risk; regular repositioning relieves prolonged tissue pressure.","B":"Incorrect. Massaging over bony prominences can damage fragile tissue.","C":"Incorrect. High elevation increases shear and sacral pressure.","D":"Incorrect. Ring cushions concentrate pressure at the edges and are discouraged."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', 'Repositioning', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334003', 'MCQ', 'A nurse teaches a client with left-sided weakness how to use a cane safely. Which instruction indicates the nurse understands correct technique?', 'A cane is held on the strong side and moves with the weaker leg, widening the base of support during the weak-leg step.', '{"options":[{"id":"A","text":"Hold the cane in the right hand and advance it with the left leg"},{"id":"B","text":"Hold the cane in the left hand and advance it with the right leg"},{"id":"C","text":"Advance the strong leg first, then the cane"},{"id":"D","text":"Keep the cane 30 cm to the side of the strong foot while walking"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The cane is held on the strong side and moves together with the weak leg.","B":"Incorrect. The cane belongs on the stronger (right) side.","C":"Incorrect. The cane and weak leg advance together for support.","D":"Incorrect. The cane should be about 15 cm to the side for a stable base."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Cane use', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334004', 'MCQ', 'A client has continuous bladder irrigation after a transurethral prostate resection. The nurse notes bright-red drainage with numerous clots and decreased outflow. Which action is the priority?', 'Bright-red drainage with clots and reduced outflow signals impending obstruction; increasing the irrigation rate maintains patency.', '{"options":[{"id":"A","text":"Increase the irrigation flow rate and assess for tube patency"},{"id":"B","text":"Clamp the catheter and notify the provider in one hour"},{"id":"C","text":"Slow the irrigation to concentrate the drainage"},{"id":"D","text":"Remove the catheter and reinsert a new one"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Increasing the flow helps flush bright-red clotted drainage and prevents catheter obstruction.","B":"Incorrect. Clamping risks bladder distention and worsens obstruction.","C":"Incorrect. Slowing flow allows clots to obstruct outflow.","D":"Incorrect. Removal is outside nursing scope in this early postoperative setting."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bladder irrigation', 'Continuous irrigation', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334005', 'MCQ', 'A client with chronic low-back pain wishes to reduce reliance on opioids. Which nonpharmacologic comfort measure should the nurse suggest FIRST?', 'Heat plus relaxation and imagery are safe first-line nonpharmacologic measures that support the client''s goal of reducing opioid use.', '{"options":[{"id":"A","text":"Applying heat and practicing guided imagery"},{"id":"B","text":"Strict bed rest until the pain fully resolves"},{"id":"C","text":"Increasing the opioid dose independently"},{"id":"D","text":"Applying an ice pack continuously for 4 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Heat and relaxation techniques are low-risk, evidence-based measures for chronic musculoskeletal pain.","B":"Incorrect. Prolonged bed rest worsens chronic back pain.","C":"Incorrect. This contradicts the client''s goal and requires a prescription.","D":"Incorrect. Continuous prolonged ice risks tissue injury and is less effective for chronic pain."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Nonpharmacologic pain management', 'Distraction', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334006', 'MCQ', 'A nurse is feeding a client who had a stroke and has dysphagia. Which action best reduces the client''s risk of aspiration during meals?', 'Upright positioning with a chin-tuck maneuver optimizes airway protection for a client with dysphagia.', '{"options":[{"id":"A","text":"Position the client upright and have the chin tucked while swallowing"},{"id":"B","text":"Offer thin liquids frequently to help clear the throat"},{"id":"C","text":"Encourage the client to eat quickly before fatigue sets in"},{"id":"D","text":"Have the client lie back at 30 degrees to relax the throat"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Upright positioning with a chin tuck protects the airway during swallowing.","B":"Incorrect. Thin liquids are the hardest to control and increase aspiration risk in dysphagia.","C":"Incorrect. Rapid eating increases aspiration risk; small, slow bites are safer.","D":"Incorrect. Reclining reduces airway protection during swallowing."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Nutrition', 'Dysphagia', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334007', 'MCQ', 'A client with a newly applied fiberglass leg cast reports increasing pain unrelieved by analgesia, along with numbness of the toes. Which nursing action is the priority?', 'Severe unrelieved pain with numbness in a casted limb points to compartment syndrome and requires immediate provider notification.', '{"options":[{"id":"A","text":"Notify the provider of possible compartment syndrome"},{"id":"B","text":"Elevate the leg and reassess in 2 hours"},{"id":"C","text":"Administer an additional dose of opioid analgesia"},{"id":"D","text":"Apply ice over the cast to reduce swelling"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Unrelenting pain with neurovascular changes suggests compartment syndrome, an emergency.","B":"Incorrect. Delayed reassessment risks permanent tissue damage.","C":"Incorrect. Medicating without escalation masks a limb-threatening emergency.","D":"Incorrect. Ice does not relieve compartment pressure and delays treatment."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Cast care', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334008', 'MCQ', 'A hospitalized older adult reports difficulty sleeping. Which nursing intervention best promotes rest without medication?', 'Clustering care to minimize nighttime interruptions is a first-line nonpharmacologic strategy to improve hospital sleep.', '{"options":[{"id":"A","text":"Cluster nighttime care to allow uninterrupted rest periods"},{"id":"B","text":"Offer a caffeinated beverage in the evening to prevent early waking"},{"id":"C","text":"Keep the overhead lights on so staff can check on the client"},{"id":"D","text":"Encourage a long afternoon nap to make up lost sleep"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Grouping care reduces awakenings and supports natural sleep cycles.","B":"Incorrect. Caffeine disrupts sleep onset.","C":"Incorrect. Bright light suppresses melatonin and disturbs sleep.","D":"Incorrect. Long daytime naps reduce nighttime sleep drive."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Sleep and rest', 'Sleep hygiene', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334009', 'MCQ', 'A postoperative client has not voided 8 hours after surgery and reports lower-abdominal fullness. A bladder scan shows 620 mL. Which action should the nurse take FIRST?', 'For postoperative retention, noninvasive voiding measures (privacy, positioning, running water) are attempted before catheterization.', '{"options":[{"id":"A","text":"Assist the client to a normal voiding position and run warm water"},{"id":"B","text":"Perform straight catheterization without further attempts"},{"id":"C","text":"Restrict oral fluids to reduce bladder filling"},{"id":"D","text":"Apply firm downward pressure over the bladder (Credé)"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Noninvasive measures to stimulate voiding are attempted before catheterization.","B":"Incorrect. Noninvasive measures should be tried first to avoid infection risk.","C":"Incorrect. Fluid restriction does not relieve retention.","D":"Incorrect. Credé is not first-line and can be unsafe post-operatively."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bowel and bladder elimination', 'Urinary retention', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334010', 'MCQ', 'A nurse reviews a client''s 12-hour record: oral intake 700 mL, IV fluids 500 mL, urine output 350 mL, emesis 200 mL, and wound drainage 150 mL. What does the nurse conclude?', 'Total intake (1200 mL) minus total output (700 mL) yields a positive balance of 500 mL, prompting monitoring for fluid retention.', '{"options":[{"id":"A","text":"The client has a net positive fluid balance and may need monitoring for retention"},{"id":"B","text":"The client has a net negative fluid balance and needs more fluids"},{"id":"C","text":"Intake and output are equal and require no action"},{"id":"D","text":"Emesis and wound drainage are not counted as output"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Intake 1200 mL exceeds output 700 mL, a positive balance warranting monitoring.","B":"Incorrect. Intake exceeds output, so the balance is positive.","C":"Incorrect. There is a 500 mL positive difference.","D":"Incorrect. All measurable fluid losses count as output."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Intake and output', 'Fluid balance', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334011', 'MCQ', 'A nurse performs passive range-of-motion exercises for an unconscious client. Which technique reflects safe practice?', 'Passive ROM is done slowly, supporting the joint proximally and distally and stopping at resistance to avoid injury.', '{"options":[{"id":"A","text":"Support the joint above and below while moving it slowly to the point of resistance"},{"id":"B","text":"Move each joint quickly beyond its normal range to maintain flexibility"},{"id":"C","text":"Perform exercises only once daily to conserve the client''s energy"},{"id":"D","text":"Push through mild resistance to stretch stiff joints fully"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Supporting the joint and stopping at resistance prevents injury.","B":"Incorrect. Forcing past the range causes injury.","C":"Incorrect. ROM is typically performed several times daily to prevent contractures.","D":"Incorrect. Movement should stop at resistance, not push through it."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Mobility and ROM', 'Passive ROM', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_334012', 'MCQ', 'A nurse is assisting a client with a bed bath. Which action best preserves the client''s dignity?', 'Draping unwashed areas and ensuring a closed door maintain the client''s privacy and dignity during personal care.', '{"options":[{"id":"A","text":"Keep areas of the body not being washed covered and close the room door"},{"id":"B","text":"Leave the door open so other staff can help quickly"},{"id":"C","text":"Uncover the whole body to complete the bath efficiently"},{"id":"D","text":"Discuss the client''s condition with a visitor during the bath"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Draping and closing the door protect privacy and dignity.","B":"Incorrect. An open door exposes the client unnecessarily.","C":"Incorrect. Full exposure compromises dignity.","D":"Incorrect. This breaches confidentiality and dignity."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Dignity and privacy', 'Personal care', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_334013', 'SATA', 'A nurse develops a plan to prevent pressure injuries in a bedbound client with incontinence. Which interventions should the nurse include? Select all that apply.', 'Repositioning, moisture management, offloading bony prominences, and adequate nutrition prevent pressure injuries; massaging reddened areas and constant high elevation are harmful.', '{"options":[{"id":"A","text":"Reposition the client on a scheduled basis"},{"id":"B","text":"Keep the skin clean and dry, applying a moisture barrier"},{"id":"C","text":"Use pillows to keep bony prominences from direct contact"},{"id":"D","text":"Maintain adequate protein and fluid intake"},{"id":"E","text":"Massage reddened areas over bony prominences to improve circulation"},{"id":"F","text":"Elevate the head of the bed as high as possible at all times"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_334014', 'SATA', 'A nurse cares for a client receiving intermittent tube feedings through a gastrostomy tube. Which actions are appropriate? Select all that apply.', 'Residual checks, head-of-bed elevation, flushing, and placement verification are standard; rapid boluses and prolonged hang times risk aspiration and contamination.', '{"options":[{"id":"A","text":"Check gastric residual volume per facility protocol"},{"id":"B","text":"Keep the head of the bed elevated during and after the feeding"},{"id":"C","text":"Flush the tube with water before and after the feeding"},{"id":"D","text":"Verify tube placement before administering the feeding"},{"id":"E","text":"Administer the feeding rapidly to reduce the client''s discomfort"},{"id":"F","text":"Hang a formula bag continuously for 24 hours to save time"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_334015', 'SATA', 'A nurse plans nonpharmacologic pain relief for a client with osteoarthritis. Which measures are appropriate? Select all that apply.', 'Heat, gentle movement, and relaxation techniques are appropriate nonpharmacologic measures for osteoarthritis; immobilization and ignoring pain are not.', '{"options":[{"id":"A","text":"Apply warm compresses to affected joints"},{"id":"B","text":"Encourage gentle range-of-motion exercises"},{"id":"C","text":"Teach relaxation breathing and guided imagery"},{"id":"D","text":"Recommend prolonged complete joint immobilization"},{"id":"E","text":"Advise the client to ignore the pain until it worsens"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nonpharmacologic pain management', NULL, 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_334016', 'SATA', 'A nurse provides postmortem care after a client''s death. Which actions are appropriate? Select all that apply.', 'Postmortem care includes aligning the body early, providing family privacy, following policy on tubes and identification; dentures are usually kept in place and care is not indefinitely delayed.', '{"options":[{"id":"A","text":"Position the body in normal alignment before rigor mortis"},{"id":"B","text":"Provide privacy and allow the family to view the body"},{"id":"C","text":"Follow facility policy for removing tubes and lines"},{"id":"D","text":"Apply identification tags per facility protocol"},{"id":"E","text":"Remove the client''s dentures and discard them"},{"id":"F","text":"Delay all care until the family has left the unit"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Postmortem care', NULL, 'Medium', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_334017', 'SATA', 'A nurse educates a client at risk for constipation about promoting normal bowel elimination. Which recommendations are appropriate? Select all that apply.', 'Fiber, fluids, routine, and activity promote normal elimination; routine stimulant-laxative dependence and habitually ignoring the urge worsen constipation.', '{"options":[{"id":"A","text":"Increase dietary fiber gradually"},{"id":"B","text":"Drink adequate fluids throughout the day"},{"id":"C","text":"Establish a regular time for bowel movements"},{"id":"D","text":"Engage in regular physical activity"},{"id":"E","text":"Rely on daily stimulant laxatives for regularity"},{"id":"F","text":"Suppress the urge to defecate until a convenient time"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Nutrition', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_334018', 'SELECT_N', 'A nurse reinforces safe walker use with an older adult. Which 3 instructions are correct?', 'Safe walker use requires stabilizing all legs before stepping, small steps within the frame, and nonslip footwear; leaning forward and using it on unstable furniture risk falls.', '{"options":[{"id":"A","text":"Keep all four walker legs on the floor before stepping forward"},{"id":"B","text":"Take small steps and stay within the frame of the walker"},{"id":"C","text":"Wear well-fitting, nonslip footwear"},{"id":"D","text":"Lean far forward over the walker while walking"},{"id":"E","text":"Use the walker to help lower into a soft, wheeled chair"},{"id":"F","text":"Push the walker well ahead and then step quickly to catch up"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Walker safety', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_334019', 'TF', 'For a client in skeletal traction, the prescribed weights should hang freely and never rest on the floor or bed frame.', 'Traction weights must hang freely to maintain the prescribed pull; resting them removes the therapeutic force.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Skeletal traction', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_334020', 'TF', 'To promote urine drainage, a nurse should routinely place the indwelling urinary catheter collection bag above the level of the bladder.', 'The collection bag must stay below bladder level to allow gravity drainage and prevent backflow and infection.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bowel and bladder elimination', 'Catheter care', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_334021', 'MATRIX', 'For each client situation, click to indicate the most appropriate position.', 'Semi-Fowler position aids feedings and breathing; a lateral (side-lying) position promotes secretion drainage and is used for enema administration.', '{"row_label":"Client position","rows":[{"id":"r1","text":"Client receiving a tube feeding to reduce aspiration"},{"id":"r2","text":"Client with dyspnea from heart failure"},{"id":"r3","text":"Unconscious client to promote drainage of secretions"},{"id":"r4","text":"Client receiving a cleansing enema"}],"columns":[{"id":"c1","text":"Semi-Fowler"},{"id":"c2","text":"Left side-lying"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Positioning', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_334022', 'MATRIX_MR', 'For each pressure-injury stage, select all findings that apply (a stage may have more than one).', 'Stage 1 is nonblanchable erythema of intact skin; Stage 2 is partial-thickness shallow loss; Stage 3 is full-thickness with fat but no exposed bone, tendon, or muscle.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Intact skin with nonblanchable redness"},{"id":"r2","text":"Partial-thickness loss with a shallow open ulcer"},{"id":"r3","text":"Full-thickness loss with visible subcutaneous fat"},{"id":"r4","text":"No exposed bone, tendon, or muscle"}],"columns":[{"id":"c1","text":"Stage 1"},{"id":"c2","text":"Stage 2"},{"id":"c3","text":"Stage 3"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c3"],"r4":["c1","c2","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Skin and tissue integrity', NULL, 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_334023', 'CLOZE', 'Before administering an intermittent gastrostomy feeding, the nurse should first {1}, and to reduce aspiration risk should keep the client positioned {2} during and after the feeding.', 'Tube placement is verified before feeding, and head-of-bed elevation during and after feeding minimizes aspiration risk.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"verify tube placement"},{"id":"c2","text":"increase the feeding rate"},{"id":"c3","text":"clamp the tube for one hour"}]},{"id":"b2","choices":[{"id":"c1","text":"with the head of the bed elevated"},{"id":"c2","text":"flat and supine"},{"id":"c3","text":"in Trendelenburg"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_334024', 'HIGHLIGHT', 'Highlight the findings in this bedbound client that increase the risk of a pressure injury. The client has [[limited mobility]], [[intact and well-hydrated skin]], [[urinary incontinence]], a serum albumin of [[2.4 g/dL]], and reports [[a healthy appetite with full meals]].', 'Immobility, incontinence-related moisture, and low albumin increase pressure-injury risk; intact skin and good intake are protective.', '{"chunks":[{"id":"h1","text":"limited mobility"},{"id":"h2","text":"intact and well-hydrated skin"},{"id":"h3","text":"urinary incontinence"},{"id":"h4","text":"2.4 g/dL"},{"id":"h5","text":"a healthy appetite with full meals"}]}'::jsonb, '{"correct_ids":["h1","h3","h4"],"feedback":{"h1":"Immobility is a major pressure-injury risk factor.","h2":"Healthy skin is protective, not a risk factor.","h3":"Moisture from incontinence macerates skin and raises risk.","h4":"Low albumin reflects poor nutrition, impairing tissue integrity.","h5":"Good intake supports tissue health and is not a risk."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_334025', 'BOWTIE', 'A postoperative client has not voided in 9 hours, reports bladder fullness, and a bladder scan shows 550 mL. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'The scenario indicates urinary retention; noninvasive voiding measures are used first, and voided volume plus bladder residual are monitored.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Assist to a natural voiding position with privacy"},{"id":"lt2","text":"Run warm water or pour warm water over the perineum"},{"id":"lt3","text":"Restrict oral fluids"},{"id":"lt4","text":"Apply firm suprapubic pressure immediately"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Urinary retention"},{"id":"ct2","text":"Urinary tract infection"},{"id":"ct3","text":"Dehydration"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Voided volume after intervention"},{"id":"rt2","text":"Bladder scan residual volume"},{"id":"rt3","text":"Serum potassium level"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Bowel and bladder elimination', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_334026', 'DRAG_CLOZE', 'When fitting axillary crutches, the nurse ensures the elbows are flexed about [1], and to prevent nerve injury the crutch pads rest about [2] below the axilla.', 'Proper crutch fit uses roughly 30 degrees of elbow flexion, with pads two to three finger-widths below the axilla to avoid brachial nerve compression.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"30 degrees"},{"id":"t2","text":"two finger-widths"},{"id":"t3","text":"90 degrees"},{"id":"t4","text":"directly against the axilla"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Crutch fitting', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_334027', 'DRAG_ORDER', 'Place the steps for administering an intermittent gastrostomy tube feeding in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and elevate the head of the bed"},{"id":"t2","text":"Verify tube placement and check gastric residual"},{"id":"t3","text":"Flush the tube with water"},{"id":"t4","text":"Administer the prescribed formula"},{"id":"t5","text":"Flush the tube again and keep the client upright"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Administration steps', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335001', 'MCQ', 'A nurse is preparing to administer a bolus feeding through a client''s nasogastric tube. After confirming placement, the nurse aspirates 320 mL of gastric residual. The last feeding was 240 mL given 4 hours ago. Which action should the nurse take?', 'A gastric residual exceeding the prior feeding volume signals intolerance; the feeding is held and the provider notified.', '{"options":[{"id":"A","text":"Hold the feeding and notify the provider"},{"id":"B","text":"Discard the aspirate and give the scheduled feeding"},{"id":"C","text":"Flush the tube with 60 mL of water and continue"},{"id":"D","text":"Reposition the client and re-aspirate immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A residual greater than the prior feeding volume suggests delayed emptying and intolerance; hold and report.","B":"Incorrect. Discarding removes electrolytes and fluid, and proceeding ignores the high residual.","C":"Incorrect. Flushing does not address the high residual indicating intolerance.","D":"Incorrect. Immediate re-aspiration does not resolve documented delayed emptying."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Tube placement', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335002', 'MCQ', 'A nurse is caring for a bedbound client with limited mobility. Which repositioning approach best reduces the risk of pressure injury over the sacrum?', 'Repositioning every 2 hours with a 30-degree lateral tilt offloads bony prominences without creating new pressure points.', '{"options":[{"id":"A","text":"Reposition at least every 2 hours using a 30-degree lateral tilt"},{"id":"B","text":"Elevate the head of the bed to 90 degrees continuously"},{"id":"C","text":"Massage reddened bony prominences vigorously"},{"id":"D","text":"Place the client directly on the trochanter when side-lying"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Frequent turning with a 30-degree tilt offloads the sacrum and trochanter.","B":"Incorrect. High elevation increases shear and sacral pressure.","C":"Incorrect. Massaging reddened areas can worsen tissue damage.","D":"Incorrect. Direct trochanter pressure creates a new injury risk."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Pressure injury prevention', 'Repositioning', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335003', 'MCQ', 'A nurse teaches a client with left-knee osteoarthritis to use a cane. Which instruction is correct?', 'A cane is held on the stronger side and advanced with the affected leg so the two share the load.', '{"options":[{"id":"A","text":"Hold the cane in the right hand and advance it with the left leg"},{"id":"B","text":"Hold the cane in the left hand and advance it with the left leg"},{"id":"C","text":"Advance the strong leg first, then the cane"},{"id":"D","text":"Keep the cane tip 30 cm to the side of the foot"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The cane is held on the strong side and moves with the affected leg to share weight.","B":"Incorrect. The cane goes on the unaffected side.","C":"Incorrect. The cane and weak leg move together.","D":"Incorrect. The tip should be about 15 cm to the side for stability."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Cane use', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335004', 'MCQ', 'A client has continuous bladder irrigation after a transurethral prostate resection. The nurse notes the outflow has become bright red with clots and the client reports bladder spasms and fullness. Which action should the nurse take first?', 'Bright bleeding with clots and fullness suggest obstruction; increasing irrigation flow and confirming patency clear the clot and relieve the spasm.', '{"options":[{"id":"A","text":"Increase the irrigation flow rate and assess catheter patency"},{"id":"B","text":"Stop the irrigation and clamp the catheter"},{"id":"C","text":"Administer a PRN analgesic and continue monitoring"},{"id":"D","text":"Deflate the catheter balloon to relieve pressure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Increasing flow clears clots and checking patency addresses possible obstruction causing the spasm and fullness.","B":"Incorrect. Clamping worsens distention and clot retention.","C":"Incorrect. This ignores the likely obstruction causing the spasm.","D":"Incorrect. Deflating the balloon risks catheter displacement and hemorrhage."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Renal/Genitourinary', 'Bladder irrigation', 'CBI', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335005', 'MCQ', 'A nurse must assess pain in an older adult client with advanced dementia who cannot self-report. Which assessment method is most appropriate?', 'For nonverbal clients with dementia, a validated behavioral pain tool such as PAINAD is the recommended assessment.', '{"options":[{"id":"A","text":"Use a behavioral observation tool such as PAINAD"},{"id":"B","text":"Ask a family member to rate the pain on a 0-10 scale"},{"id":"C","text":"Assume the client is pain-free if lying quietly"},{"id":"D","text":"Use the numeric rating scale with picture prompts"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A validated behavioral scale is the standard for nonverbal clients.","B":"Incorrect. Proxy numeric ratings are less reliable than direct behavioral observation.","C":"Incorrect. Quietness does not rule out pain in dementia.","D":"Incorrect. Advanced dementia limits reliable use of self-report scales."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Pain assessment', 'Nonverbal client', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335006', 'MCQ', 'A hospitalized client reports difficulty sleeping. Which nursing intervention best promotes sleep using a nonpharmacologic approach?', 'Clustering care to minimize interruptions preserves sleep cycles and is a first-line nonpharmacologic strategy.', '{"options":[{"id":"A","text":"Cluster nighttime care to allow uninterrupted rest periods"},{"id":"B","text":"Offer a caffeinated beverage in the evening for comfort"},{"id":"C","text":"Keep overhead lighting on for nighttime safety checks"},{"id":"D","text":"Encourage a 2-hour nap in the late afternoon"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Clustering care reduces awakenings and supports sleep cycles.","B":"Incorrect. Caffeine impairs sleep onset.","C":"Incorrect. Bright light suppresses melatonin and disrupts sleep.","D":"Incorrect. Long late naps reduce nighttime sleep drive."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Sleep and rest', 'Sleep hygiene', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335007', 'MCQ', 'A client returns from casting of a fractured tibia. Six hours later the client reports increasing pain unrelieved by analgesics and numbness of the toes. Which finding most requires immediate action?', 'Unrelieved escalating pain with paresthesia is a hallmark of acute compartment syndrome and requires immediate intervention.', '{"options":[{"id":"A","text":"Pain out of proportion with paresthesia of the toes"},{"id":"B","text":"Mild itching under the cast"},{"id":"C","text":"A dependent area of dried blood on the cast"},{"id":"D","text":"Warmth of the cast during the drying period"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Escalating unrelieved pain with paresthesia signals compartment syndrome, a limb-threatening emergency.","B":"Incorrect. Itching is common and not urgent.","C":"Incorrect. A stable, marked drainage area is monitored, not emergent.","D":"Incorrect. Warmth from an exothermic setting reaction is expected."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Cast care', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335008', 'MCQ', 'A client on prolonged bed rest and opioid therapy has not had a bowel movement in 3 days and reports abdominal fullness. Which intervention should the nurse implement first?', 'Increasing fluids, fiber, and mobility addresses the underlying causes of constipation before escalating to enemas or disimpaction.', '{"options":[{"id":"A","text":"Increase fluid and dietary fiber intake and encourage activity as tolerated"},{"id":"B","text":"Administer a soap-suds enema immediately"},{"id":"C","text":"Perform digital disimpaction"},{"id":"D","text":"Withhold all fluids until the client passes stool"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nonpharmacologic measures addressing the cause are first-line for opioid- and immobility-related constipation.","B":"Incorrect. An enema is not the first step before conservative measures and orders.","C":"Incorrect. Disimpaction is reserved for confirmed impaction and requires assessment.","D":"Incorrect. Restricting fluids worsens constipation."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Bowel elimination', 'Constipation', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335009', 'MCQ', 'A nurse is providing postmortem care shortly after a client''s death, and the family will view the body. Which action is appropriate?', 'Supine positioning with slight head elevation, closed eyes, and reinserted dentures preserves a natural, dignified appearance for viewing.', '{"options":[{"id":"A","text":"Position the body supine with the head slightly elevated and close the eyes"},{"id":"B","text":"Remove all dentures before the family arrives"},{"id":"C","text":"Delay removing tubes and lines until after the family views the body"},{"id":"D","text":"Lower the head flat and tightly restrain the arms at the sides"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Supine positioning with slight head elevation and closed eyes preserves a natural appearance and limits discoloration.","B":"Incorrect. Dentures are reinserted to maintain facial contour before viewing.","C":"Incorrect. When permitted, lines are removed to improve appearance before viewing.","D":"Incorrect. Flat positioning promotes facial discoloration and restraints are inappropriate."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Postmortem care', 'Procedure', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335010', 'MCQ', 'A client recovering from a stroke has dysphagia. Which nursing action best reduces the risk of aspiration during meals?', 'Upright positioning with a chin-tuck maneuver protects the airway and reduces aspiration during swallowing.', '{"options":[{"id":"A","text":"Position the client upright and have them tuck the chin while swallowing"},{"id":"B","text":"Offer thin liquids to make swallowing easier"},{"id":"C","text":"Encourage rapid eating to limit fatigue"},{"id":"D","text":"Have the client lie back at 30 degrees during meals"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Upright positioning with a chin tuck protects the airway during swallowing.","B":"Incorrect. Thin liquids increase aspiration risk in dysphagia.","C":"Incorrect. Rapid eating increases aspiration risk.","D":"Incorrect. Reclined positioning promotes aspiration."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'GI', 'Nutrition status', 'Dysphagia', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335011', 'MCQ', 'A nurse performs passive range-of-motion exercises for an unconscious client. Which technique is correct?', 'Passive ROM is performed slowly to the point of resistance without forcing, preserving mobility and preventing injury.', '{"options":[{"id":"A","text":"Move each joint slowly to the point of resistance, not beyond"},{"id":"B","text":"Move joints quickly through their full range to save time"},{"id":"C","text":"Continue past resistance until the joint fully extends"},{"id":"D","text":"Exercise only the lower extremities to prevent fatigue"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Moving to resistance without forcing prevents injury while maintaining joint mobility.","B":"Incorrect. Rapid movement risks injury.","C":"Incorrect. Forcing past resistance can cause injury.","D":"Incorrect. All accessible joints should be exercised to prevent contractures."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Mobility and ROM', 'Passive ROM', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335012', 'MCQ', 'A nurse is calculating a client''s 8-hour intake, which included 240 mL of ice chips, 120 mL of gelatin, 200 mL of IV fluid, and 180 mL of water. Which total should the nurse document for oral and IV intake combined?', 'Ice chips are recorded as half their measured volume, so 120 + 120 + 200 + 180 = 620 mL.', '{"options":[{"id":"A","text":"620 mL"},{"id":"B","text":"740 mL"},{"id":"C","text":"500 mL"},{"id":"D","text":"420 mL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Ice chips count as half their volume (120 mL) plus 120 + 200 + 180 = 620 mL.","B":"Incorrect. This counts ice chips at full volume.","C":"Incorrect. This omits the ice chip contribution.","D":"Incorrect. This omits both the IV fluid and ice chips."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Renal/Genitourinary', 'Intake and output', 'I&O measurement', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_335013', 'MCQ', 'A nurse assists a client of a conservative cultural background with a bed bath. Which action best preserves dignity and privacy?', 'Draping the client and exposing only the area being washed maintains dignity and privacy during hygiene care.', '{"options":[{"id":"A","text":"Expose only the body part being washed and keep the rest draped"},{"id":"B","text":"Leave the door open so help is nearby"},{"id":"C","text":"Complete the bath quickly with full exposure to save time"},{"id":"D","text":"Assign the task to any available staff member regardless of client preference"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Draping and exposing only the area being cleaned protects dignity and privacy.","B":"Incorrect. An open door compromises privacy.","C":"Incorrect. Full exposure violates dignity.","D":"Incorrect. Cultural preferences about caregiver gender should be respected when possible."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Dignity and privacy', 'Personal hygiene', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_335014', 'SATA', 'A nurse develops a plan to prevent pressure injuries in an immobile, incontinent client. Which interventions should the nurse include? Select all that apply.', 'Turning, moisture control, support surfaces, and nutrition prevent pressure injury; massaging reddened areas and high HOB elevation are harmful.', '{"options":[{"id":"A","text":"Reposition the client at least every 2 hours"},{"id":"B","text":"Keep the skin clean and dry after episodes of incontinence"},{"id":"C","text":"Use a pressure-redistributing support surface"},{"id":"D","text":"Ensure adequate protein and fluid intake"},{"id":"E","text":"Massage bony prominences that appear reddened"},{"id":"F","text":"Elevate the head of the bed to 90 degrees for long periods"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Pressure injury prevention', 'Risk reduction', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_335015', 'SATA', 'A nurse is caring for a client receiving continuous tube feeding. Which actions reduce the risk of aspiration? Select all that apply.', 'Elevated HOB, placement verification, residual monitoring, and flushing reduce aspiration; lying flat and rate boluses increase risk.', '{"options":[{"id":"A","text":"Keep the head of the bed elevated at least 30 degrees"},{"id":"B","text":"Verify tube placement per facility protocol"},{"id":"C","text":"Monitor for gastric residual volume as ordered"},{"id":"D","text":"Lay the client flat during feeding to improve comfort"},{"id":"E","text":"Flush the tube with the ordered water volume"},{"id":"F","text":"Increase the feeding rate to finish faster when behind schedule"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Aspiration prevention', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_335016', 'SATA', 'A nurse plans nonpharmacologic comfort measures for a client with chronic low-back pain. Which interventions are appropriate? Select all that apply.', 'Heat/cold, relaxation, movement, and distraction ease chronic pain; prolonged bed rest and inactivity worsen it.', '{"options":[{"id":"A","text":"Apply heat or cold therapy as tolerated"},{"id":"B","text":"Teach guided imagery and relaxation breathing"},{"id":"C","text":"Encourage frequent position changes and gentle stretching"},{"id":"D","text":"Recommend strict bed rest until pain fully resolves"},{"id":"E","text":"Offer distraction through music or activities"},{"id":"F","text":"Discontinue all activity to avoid triggering pain"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Neurological', 'Nonpharmacologic comfort', 'Pain management', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_335017', 'SATA', 'A client is in skeletal traction for a femur fracture. Which nursing actions are appropriate? Select all that apply.', 'Traction requires free-hanging weights, pin care, neurovascular checks, and alignment; weights must not be removed or loosened by the nurse.', '{"options":[{"id":"A","text":"Keep the weights hanging freely and off the floor"},{"id":"B","text":"Perform pin-site care per protocol"},{"id":"C","text":"Assess neurovascular status of the affected limb"},{"id":"D","text":"Remove the weights when repositioning the client"},{"id":"E","text":"Maintain proper body alignment"},{"id":"F","text":"Loosen the traction if the client reports discomfort"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Musculoskeletal', 'Orthopedic devices', 'Skeletal traction', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_335018', 'SATA', 'A nurse assesses an older adult client for signs of malnutrition. Which findings support this concern? Select all that apply.', 'Weight loss, poor healing, low albumin, and skin/hair changes indicate malnutrition; hypertension and muscle gain do not.', '{"options":[{"id":"A","text":"Unintentional weight loss over the past month"},{"id":"B","text":"Poor wound healing"},{"id":"C","text":"Low serum albumin"},{"id":"D","text":"Brittle hair and dry, flaky skin"},{"id":"E","text":"Elevated blood pressure"},{"id":"F","text":"Increased muscle mass"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'GI', 'Nutrition status', 'Malnutrition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_335019', 'SELECT_N', 'A nurse prepares to transfer a partially dependent client from bed to a chair. Which 3 actions promote a safe transfer?', 'Locking wheels, chair placement on the strong side, and a gait belt make the transfer safe; underarm lifting, bare feet, and waist bending risk injury.', '{"options":[{"id":"A","text":"Lock the wheels of the bed and the chair"},{"id":"B","text":"Position the chair on the client''s stronger side"},{"id":"C","text":"Use a gait belt and the client''s remaining strength"},{"id":"D","text":"Lift the client under the arms to standing"},{"id":"E","text":"Transfer without footwear to increase floor grip"},{"id":"F","text":"Bend at the waist to raise the client"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'ADLs and assistance', 'Safe transfer', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_335020', 'TF', 'A stage 1 pressure injury is characterized by a partial-thickness loss of the dermis presenting as a shallow open ulcer.', 'A stage 1 injury is intact skin with nonblanchable erythema; the partial-thickness open ulcer describes a stage 2 injury.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Integumentary', 'Pressure injury prevention', 'Skin assessment', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_335021', 'MATRIX', 'For each clinical goal, click to indicate which client position best supports it.', 'Semi-Fowler eases breathing and reduces aspiration; left lateral/Sims aids enema administration and secretion drainage.', '{"row_label":"Position","rows":[{"id":"r1","text":"Easing dyspnea in a client with heart failure"},{"id":"r2","text":"Administering an enema"},{"id":"r3","text":"Reducing aspiration risk during tube feeding"},{"id":"r4","text":"Positioning an unconscious client to promote drainage of secretions"}],"columns":[{"id":"c1","text":"Semi-Fowler"},{"id":"c2","text":"Left lateral (Sims)"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Positioning', 'Therapeutic positions', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_335022', 'MATRIX_MR', 'For each nonpharmacologic comfort measure, select all benefits it may provide (more than one may apply).', 'Imagery addresses pain, relaxation, and sleep; cold mainly reduces pain; massage and a calm environment promote relaxation and sleep.', '{"row_label":"Comfort measure","rows":[{"id":"r1","text":"Guided imagery"},{"id":"r2","text":"Cold application to an acute injury"},{"id":"r3","text":"Back massage at bedtime"},{"id":"r4","text":"Quiet, dimmed environment"}],"columns":[{"id":"c1","text":"Reduces pain perception"},{"id":"c2","text":"Promotes relaxation"},{"id":"c3","text":"Improves sleep"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1"],"r3":["c2","c3"],"r4":["c2","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Multisystem', 'Nonpharmacologic comfort', 'Complementary therapies', 'Medium', 'Understand', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_335023', 'CLOZE', 'A postoperative client has not voided in 8 hours and reports lower abdominal fullness. The nurse recognizes the client is most likely experiencing {1}, and the priority noninvasive nursing action is to {2}.', 'Bladder fullness with no voiding indicates retention; noninvasive measures such as normal positioning and warm water are tried before catheterization.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"urinary retention"},{"id":"c2","text":"a urinary tract infection"},{"id":"c3","text":"dehydration"}]},{"id":"b2","choices":[{"id":"c1","text":"assist the client to a normal voiding position and run warm water"},{"id":"c2","text":"restrict oral fluids"},{"id":"c3","text":"insert an indwelling catheter immediately"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Renal/Genitourinary', 'Bladder elimination', 'Urinary retention', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_335024', 'HIGHLIGHT', 'Highlight the findings at a sacral wound that indicate impaired healing or infection. The nurse inspects the wound: [[edges approximated]], surrounding skin [[warm and erythematous]], [[purulent green drainage]], [[foul odor]], granulation tissue [[pink and moist]], and the client reports [[increasing pain]].', 'Warmth, erythema, purulent drainage, foul odor, and increasing pain indicate infection; approximated edges and pink moist granulation are normal.', '{"chunks":[{"id":"h1","text":"edges approximated"},{"id":"h2","text":"warm and erythematous"},{"id":"h3","text":"purulent green drainage"},{"id":"h4","text":"foul odor"},{"id":"h5","text":"pink and moist"},{"id":"h6","text":"increasing pain"}]}'::jsonb, '{"correct_ids":["h2","h3","h4","h6"],"feedback":{"h1":"Approximated edges indicate normal healing.","h2":"Warmth and redness suggest infection.","h3":"Purulent drainage indicates infection.","h4":"Foul odor suggests infection.","h5":"Pink, moist granulation is a sign of healthy healing.","h6":"Increasing pain can signal infection or deterioration."}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'Integumentary', 'Skin and tissue integrity', 'Wound assessment', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_335025', 'BOWTIE', 'A severely malnourished client is starting enteral nutrition. Complete the diagram by selecting the condition to monitor for, the actions to take, and parameters to monitor.', 'Rapid refeeding of a malnourished client risks refeeding syndrome; feeding is advanced slowly with close monitoring of phosphate, potassium, and magnesium.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Start feeding at a low rate and advance slowly"},{"id":"lt2","text":"Monitor electrolytes closely"},{"id":"lt3","text":"Begin feeding at full goal rate immediately"},{"id":"lt4","text":"Withhold all electrolyte replacement"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Refeeding syndrome"},{"id":"ct2","text":"Dumping syndrome"},{"id":"ct3","text":"Aspiration pneumonia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Serum phosphate"},{"id":"rt2","text":"Serum potassium and magnesium"},{"id":"rt3","text":"Deep tendon reflexes only"},{"id":"rt4","text":"Pupil response"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Medical-Surgical', 'GI', 'Nutrition status', 'Refeeding risk', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_335026', 'DRAG_CLOZE', 'When teaching a client to climb stairs with crutches, the nurse instructs the client to lead with the [1] leg going up and with the [2] going down.', 'Going up stairs the stronger leg leads; going down the crutches and weaker leg lead, following the phrase ''up with the good, down with the bad.''', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"stronger"},{"id":"t2","text":"crutches and weaker leg"},{"id":"t3","text":"weaker"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'Musculoskeletal', 'Assistive devices', 'Crutch walking', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_335027', 'DRAG_ORDER', 'A nurse is administering a bolus feeding through a gastrostomy tube. Place the steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"},{"id":"s6","target_text":"6th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene and verify tube placement"},{"id":"t2","text":"Elevate the head of the bed to at least 30 degrees"},{"id":"t3","text":"Check gastric residual volume"},{"id":"t4","text":"Administer the feeding by gravity"},{"id":"t5","text":"Flush the tube with water"},{"id":"t6","text":"Keep the client upright after the feeding"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5","s6":"t6"}}'::jsonb, 'Physiological Integrity', 'Basic Care and Comfort', 'Fundamentals of Nursing', 'GI', 'Enteral feedings', 'Bolus feeding procedure', 'Medium', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330001', 'MCQ', 'A nurse is counseling a woman at her first prenatal visit at 8 weeks gestation. Which statement by the nurse best supports neural tube defect prevention?', 'Folic acid supplementation in early pregnancy is the key preventive measure against neural tube defects.', '{"options":[{"id":"A","text":"Take 400 to 800 mcg of folic acid daily throughout early pregnancy"},{"id":"B","text":"Increase your daily vitamin A intake with liver several times a week"},{"id":"C","text":"Begin iron supplementation only if you become anemic in the third trimester"},{"id":"D","text":"Limit all leafy green vegetables to reduce nausea"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Adequate folic acid before and during early pregnancy reduces neural tube defect risk.","B":"Incorrect. Excess preformed vitamin A is teratogenic.","C":"Incorrect. This does not address neural tube defects.","D":"Incorrect. Leafy greens are a folate source and should be encouraged."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'Nutrition education', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330002', 'MCQ', 'A parent brings an 18-month-old for a well-child visit. Which finding should the nurse recognize as expected for this age?', 'At 18 months a toddler walks up stairs with a hand held and uses single words, consistent with normal development.', '{"options":[{"id":"A","text":"Walks up stairs with one hand held and says several single words"},{"id":"B","text":"Speaks in three-word sentences and rides a tricycle"},{"id":"C","text":"Sits without support but does not yet crawl"},{"id":"D","text":"Builds a tower of eight cubes and copies a circle"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These are typical 18-month gross-motor and language milestones.","B":"Incorrect. These are closer to 3-year milestones.","C":"Incorrect. This suggests around 6 months and would be delayed.","D":"Incorrect. These are preschool-age skills."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Toddler milestones', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330003', 'MCQ', 'A 66-year-old client with no chronic illness asks which vaccines are recommended at this age. Which response by the nurse is most accurate?', 'Adults 65 and older are advised to receive pneumococcal and annual influenza vaccination.', '{"options":[{"id":"A","text":"You should receive the pneumococcal vaccine and an annual influenza vaccine"},{"id":"B","text":"No further vaccines are needed once you are over 65"},{"id":"C","text":"You only need a tetanus booster every 20 years"},{"id":"D","text":"Live vaccines such as MMR should be repeated yearly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pneumococcal vaccination and annual influenza are recommended for adults 65 and older.","B":"Incorrect. Older adults have specific recommended vaccines.","C":"Incorrect. Td boosters are every 10 years and this ignores other vaccines.","D":"Incorrect. MMR is not an annual vaccine for adults."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Immunizations', 'Adult schedule', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330004', 'MCQ', 'A postpartum client who is breastfeeding reports sore, cracked nipples on day 3. Which teaching point should the nurse emphasize first?', 'Correcting the latch so the areola is in the infant''s mouth resolves most nipple soreness.', '{"options":[{"id":"A","text":"Ensure the infant latches with the areola, not just the nipple, in the mouth"},{"id":"B","text":"Limit each feeding to five minutes per breast"},{"id":"C","text":"Switch to formula until the nipples heal completely"},{"id":"D","text":"Wash the nipples with soap before each feeding"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Poor latch is the most common cause of nipple trauma.","B":"Incorrect. Time limits do not fix the underlying latch problem.","C":"Incorrect. Stopping breastfeeding is unnecessary and not first-line.","D":"Incorrect. Soap dries and worsens cracking."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum care', 'Breastfeeding education', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330005', 'MCQ', 'A 52-year-old client with no family history of cancer asks about recommended screenings. Which screening should the nurse discuss as newly due at this age?', 'Colorectal cancer screening is recommended for average-risk adults starting at 45 to 50 years.', '{"options":[{"id":"A","text":"Colorectal cancer screening"},{"id":"B","text":"Annual bone density scanning"},{"id":"C","text":"Yearly abdominal aortic aneurysm ultrasound for all adults"},{"id":"D","text":"Prostate biopsy for every man over 50"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Average-risk colorectal screening is recommended beginning at age 45 to 50.","B":"Incorrect. Routine DEXA screening typically begins later, at 65 for women.","C":"Incorrect. AAA screening is a one-time test for certain men who smoked.","D":"Incorrect. Biopsy is not a screening test."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Health screening', 'Colorectal screening', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330006', 'MCQ', 'A nurse teaches parents of a 4-month-old about injury prevention. Which instruction is most appropriate for this developmental stage?', 'Because 4-month-olds start to roll, never leaving them unattended on elevated surfaces prevents falls.', '{"options":[{"id":"A","text":"Never leave the infant unattended on a changing table or bed"},{"id":"B","text":"Place soft pillows around the infant in the crib for comfort"},{"id":"C","text":"Begin using a forward-facing car seat"},{"id":"D","text":"Allow the infant to hold small solid finger foods"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. At 4 months infants begin rolling, creating a fall risk.","B":"Incorrect. Soft bedding increases suffocation and SIDS risk.","C":"Incorrect. Infants remain rear-facing well beyond this age.","D":"Incorrect. This is a choking hazard and premature."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Infant safety', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330007', 'MCQ', 'During a routine visit, a nurse administers a depression screening tool to an adult client. Which client response most warrants immediate further assessment?', 'A positive screen for suicidal ideation requires immediate, focused safety assessment.', '{"options":[{"id":"A","text":"Reports recent thoughts that life is not worth living"},{"id":"B","text":"States feeling tired more often since starting a new job"},{"id":"C","text":"Describes occasional worry about finances"},{"id":"D","text":"Mentions eating slightly less on busy days"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Any indication of suicidal ideation requires immediate follow-up.","B":"Incorrect. Fatigue alone is nonspecific and not urgent.","C":"Incorrect. Situational worry is common and not an emergency.","D":"Incorrect. Minor appetite variation is not urgent."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Mental Health', 'Psychiatric/Mental Health', 'Screening', 'Depression screening', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330008', 'MCQ', 'A nurse plans discharge teaching for a newly diagnosed diabetic client. Which client cue best indicates readiness to learn?', 'A client who initiates relevant questions demonstrates motivation and readiness to learn.', '{"options":[{"id":"A","text":"The client asks how to prepare the insulin syringe correctly"},{"id":"B","text":"The client is in severe pain and requesting medication"},{"id":"C","text":"The client states there is no need to learn any of this"},{"id":"D","text":"The client is drowsy from recent sedation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Asking task-specific questions signals engagement and readiness.","B":"Incorrect. Unmet physical needs impair learning readiness.","C":"Incorrect. This reflects a barrier, not readiness.","D":"Incorrect. Reduced alertness impairs learning."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Patient education', 'Readiness to learn', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330009', 'MCQ', 'A client who smokes a pack of cigarettes daily tells the nurse, ''I have been thinking maybe I should quit one of these days.'' Which response best supports this client''s stage of change?', 'A client contemplating change benefits from exploring personal benefits, which builds intrinsic motivation.', '{"options":[{"id":"A","text":"What benefits do you think quitting could bring you?"},{"id":"B","text":"Here is a schedule to taper your cigarettes starting today"},{"id":"C","text":"You must stop smoking immediately to avoid lung cancer"},{"id":"D","text":"Since you are not ready, we will revisit this in a year"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Exploring perceived benefits fits a contemplative client and strengthens motivation.","B":"Incorrect. An action plan is premature before commitment.","C":"Incorrect. Confrontation can raise resistance at this stage.","D":"Incorrect. Dismissing the opening misses a motivational opportunity."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Respiratory', 'High-risk behavior', 'Smoking cessation', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330010', 'MCQ', 'A nurse provides education to a client at 28 weeks gestation about warning signs to report. Which symptom, if reported, requires the most urgent evaluation?', 'Severe headache, visual disturbances, and facial edema are classic warning signs of preeclampsia.', '{"options":[{"id":"A","text":"Severe headache with visual changes and swelling of the face"},{"id":"B","text":"Occasional mild lower back ache after standing"},{"id":"C","text":"Increased clear vaginal discharge without odor"},{"id":"D","text":"Feeling fetal movements several times a day"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These suggest preeclampsia and require urgent evaluation.","B":"Incorrect. Mild back ache is common in pregnancy.","C":"Incorrect. Increased leukorrhea is normal.","D":"Incorrect. Regular fetal movement is reassuring."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Antepartum care', 'Danger signs', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330011', 'MCQ', 'A home-health nurse assesses a 78-year-old client living alone. Which finding is the priority to address for fall prevention?', 'Removing loose throw rugs eliminates a common and easily corrected home fall hazard.', '{"options":[{"id":"A","text":"Loose throw rugs on the walkway between rooms"},{"id":"B","text":"A calendar of upcoming medical appointments on the wall"},{"id":"C","text":"A landline telephone in the kitchen"},{"id":"D","text":"Family photographs displayed on a bookshelf"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Loose rugs are a leading modifiable home fall hazard.","B":"Incorrect. This is unrelated to fall risk.","C":"Incorrect. A phone is a communication resource, not a hazard.","D":"Incorrect. This poses no fall risk."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Musculoskeletal', 'Older adult health', 'Fall prevention at home', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_330012', 'MCQ', 'A parent asks when to begin introducing solid foods to their healthy infant. Which response by the nurse is most appropriate?', 'Solid foods are introduced around 6 months when developmental readiness signs appear.', '{"options":[{"id":"A","text":"Around 6 months, when the infant can sit with support and shows interest in food"},{"id":"B","text":"At 2 months, adding cereal to the bottle to help sleep"},{"id":"C","text":"Only after the first birthday to avoid all allergies"},{"id":"D","text":"Whenever the infant doubles the birth weight, regardless of age"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Developmental readiness around 6 months guides solid introduction.","B":"Incorrect. Early solids and cereal in bottles are not recommended.","C":"Incorrect. Delaying to 12 months is not recommended.","D":"Incorrect. Weight alone does not determine readiness."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'GI', 'Growth and development', 'Nutrition introduction', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_330013', 'SATA', 'A nurse teaches a pregnant client about common discomforts and self-care. Which self-care measures are appropriate to include? Select all that apply.', 'Positional changes, small meals, leg elevation, and pelvic tilts are safe measures; fluid restriction and unsupervised medication use are not.', '{"options":[{"id":"A","text":"Rise slowly from lying to standing to reduce dizziness"},{"id":"B","text":"Eat small frequent meals to ease nausea"},{"id":"C","text":"Elevate the legs periodically to relieve dependent edema"},{"id":"D","text":"Perform pelvic tilt exercises for low back discomfort"},{"id":"E","text":"Restrict all fluids to prevent frequent urination"},{"id":"F","text":"Take over-the-counter medications freely for any symptom"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal education', 'Self-care', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_330014', 'SATA', 'A nurse counsels an adult with prehypertension on lifestyle changes. Which recommendations are appropriate? Select all that apply.', 'Sodium reduction, exercise, alcohol limitation, and weight management lower blood pressure; processed foods and inactivity worsen it.', '{"options":[{"id":"A","text":"Reduce dietary sodium intake"},{"id":"B","text":"Engage in regular aerobic physical activity"},{"id":"C","text":"Limit alcohol consumption"},{"id":"D","text":"Maintain a healthy body weight"},{"id":"E","text":"Increase intake of processed and canned foods"},{"id":"F","text":"Adopt a sedentary routine to conserve energy"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Cardiovascular', 'Lifestyle modification', 'Hypertension prevention', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_330015', 'SATA', 'A nurse reviews an immunization schedule for a child. Which situations warrant delaying or withholding a scheduled vaccine? Select all that apply.', 'Anaphylaxis to a prior dose, moderate-severe febrile illness, and immunocompromise for live vaccines are true precautions; minor illness and local soreness are not.', '{"options":[{"id":"A","text":"A severe anaphylactic reaction to a previous dose of the same vaccine"},{"id":"B","text":"Current moderate to severe acute illness with fever"},{"id":"C","text":"Known immunocompromise before a live vaccine"},{"id":"D","text":"A mild upper respiratory infection without fever"},{"id":"E","text":"Mild soreness at a prior injection site"},{"id":"F","text":"Current breastfeeding by the mother"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Immune', 'Immunizations', 'Contraindications', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_330016', 'SATA', 'A nurse conducts a community screening for type 2 diabetes risk. Which client factors increase risk and support screening? Select all that apply.', 'Obesity, family history, and prior gestational diabetes raise type 2 diabetes risk; an active, normal-weight young adult without risk factors is lower risk.', '{"options":[{"id":"A","text":"Body mass index in the obese range"},{"id":"B","text":"A first-degree relative with type 2 diabetes"},{"id":"C","text":"History of gestational diabetes"},{"id":"D","text":"Physically active with normal weight and no family history"},{"id":"E","text":"Age under 20 with no other risk factors"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Endocrine', 'Health screening', 'Diabetes risk', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_330017', 'SATA', 'A nurse assesses factors that may act as barriers to a client''s learning during discharge teaching. Which findings represent barriers to learning? Select all that apply.', 'Language mismatch, high anxiety, sensory impairment, and literacy limits impede learning; engagement and support facilitate it.', '{"options":[{"id":"A","text":"Client speaks a language different from the nurse and no interpreter is present"},{"id":"B","text":"Client reports significant anxiety about going home"},{"id":"C","text":"Client has uncorrected hearing impairment"},{"id":"D","text":"Client has a low literacy level with written materials only"},{"id":"E","text":"Client asks clarifying questions and takes notes"},{"id":"F","text":"Client has a supportive family member present"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Patient education', 'Barriers to learning', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_330018', 'SELECT_N', 'Which 3 findings are expected developmental milestones for a healthy 4-year-old child?', 'Hopping, drawing a multi-part person, and multi-word sentences are typical at 4 years; shoe-tying is later and single words or unsteady gait are earlier or abnormal.', '{"options":[{"id":"A","text":"Hops on one foot"},{"id":"B","text":"Draws a person with several body parts"},{"id":"C","text":"Uses sentences of four or more words"},{"id":"D","text":"Ties shoelaces independently"},{"id":"E","text":"Speaks only single words"},{"id":"F","text":"Walks unsteadily with a wide-based gait"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Preschool milestones', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_330019', 'TF', 'Routine cervical cancer screening with a Papanicolaou (Pap) test is generally recommended to begin at age 21 for individuals with a cervix, regardless of sexual history.', 'Cervical cancer screening is recommended to start at age 21 irrespective of sexual activity onset.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Reproductive', 'Health screening', 'Cervical screening', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_330020', 'TF', 'Placing a healthy infant to sleep in the prone (on the stomach) position is the recommended way to reduce the risk of sudden infant death syndrome.', 'Infants should be placed supine (on the back) to sleep; the prone position increases SIDS risk.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Infant care', 'Safe sleep', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_330021', 'MATRIX', 'For each preventive screening, click to indicate whether it is typically recommended for a healthy adult woman or a healthy older adult of either sex.', 'Mammography and Pap screening target adult women, while DEXA and AAA screening are aimed at older adults.', '{"row_label":"Client","rows":[{"id":"r1","text":"Mammography every 1 to 2 years"},{"id":"r2","text":"Bone mineral density (DEXA) screening"},{"id":"r3","text":"Cervical cytology (Pap) screening"},{"id":"r4","text":"One-time abdominal aortic aneurysm screening (in men who smoked)"}],"columns":[{"id":"c1","text":"Adult woman (average risk)"},{"id":"c2","text":"Older adult 65+"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Preventive screening', 'Age-based screening', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_330022', 'MATRIX_MR', 'For each life stage, select all anticipatory-guidance topics that a nurse should prioritize (more than one may apply).', 'Toddlers need car-seat and fall guidance, adolescents need substance-use screening, and older adults need fall prevention.', '{"row_label":"Life stage","rows":[{"id":"r1","text":"Toddler"},{"id":"r2","text":"Adolescent"},{"id":"r3","text":"Older adult"}],"columns":[{"id":"c1","text":"Car/booster seat safety"},{"id":"c2","text":"Fall prevention"},{"id":"c3","text":"Substance use screening"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c2"]},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Health maintenance', 'Anticipatory guidance', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_330023', 'CLOZE', 'At a routine visit, the nurse measures the fundal height. By approximately {1} weeks gestation, the fundus is normally expected to reach the level of the {2}.', 'The fundus reaches the umbilicus around 20 weeks gestation, a useful marker of expected growth.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"20"},{"id":"c2","text":"12"},{"id":"c3","text":"36"}]},{"id":"b2","choices":[{"id":"c1","text":"umbilicus"},{"id":"c2","text":"symphysis pubis"},{"id":"c3","text":"xiphoid process"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal assessment', 'Fundal height', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_330024', 'HIGHLIGHT', 'A home-health nurse visits an older adult. Highlight the findings that indicate a need for further intervention. The client [[walks with a steady gait using a cane]]. There are [[loose electrical cords across the hallway]]. The [[bathroom has grab bars installed]]. Medications are [[stored in unlabeled containers]]. The stairwell is [[poorly lit with no handrail]].', 'Loose cords, unlabeled medications, and an unsafe stairwell require intervention; assisted steady gait and grab bars are protective.', '{"chunks":[{"id":"h1","text":"walks with a steady gait using a cane"},{"id":"h2","text":"loose electrical cords across the hallway"},{"id":"h3","text":"bathroom has grab bars installed"},{"id":"h4","text":"stored in unlabeled containers"},{"id":"h5","text":"poorly lit with no handrail"}]}'::jsonb, '{"correct_ids":["h2","h4","h5"],"feedback":{"h1":"A steady assisted gait is reassuring.","h2":"A tripping hazard requiring intervention.","h3":"Grab bars are a positive safety feature.","h4":"Unlabeled medications risk errors and need intervention.","h5":"A poorly lit railless stairwell is a major fall hazard."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult assessment', 'Home safety cues', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_330025', 'BOWTIE', 'A nurse prepares discharge teaching for a first-time mother and her healthy newborn. Complete the diagram by selecting the teaching priority, actions to teach, and outcomes to monitor.', 'Safe newborn care centers on supine sleep and head support, with hydration and weight gain as key monitored outcomes.', '{"left":{"label":"Actions to teach","tokens":[{"id":"lt1","text":"Place the newborn supine for every sleep"},{"id":"lt2","text":"Support the newborn''s head when holding"},{"id":"lt3","text":"Add rice cereal to bottles at night"},{"id":"lt4","text":"Position the newborn prone to prevent choking"}]},"centre":{"label":"Teaching priority","tokens":[{"id":"ct1","text":"Safe newborn care and feeding"},{"id":"ct2","text":"Toddler discipline strategies"},{"id":"ct3","text":"Adolescent risk counseling"}]},"right":{"label":"Outcomes to monitor","tokens":[{"id":"rt1","text":"Adequate number of wet diapers per day"},{"id":"rt2","text":"Steady weight gain after initial loss"},{"id":"rt3","text":"Ability to walk independently"},{"id":"rt4","text":"First words spoken"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum education', 'Newborn care', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_330026', 'DRAG_CLOZE', 'The nurse reviews milestones with parents. A healthy infant typically sits without support at about [1] and begins to walk independently at about [2].', 'Independent sitting emerges around 6 months and independent walking around 12 months.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"6 months"},{"id":"t2","text":"12 months"},{"id":"t3","text":"3 months"},{"id":"t4","text":"24 months"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Milestone timing', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_330027', 'DRAG_ORDER', 'A nurse plans structured health-promotion teaching for a client. Place the steps of the teaching process in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Assess the client''s learning needs and readiness"},{"id":"t2","text":"Set mutual learning goals with the client"},{"id":"t3","text":"Select and deliver appropriate teaching methods"},{"id":"t4","text":"Evaluate the client''s understanding with teach-back"},{"id":"t5","text":"Document the teaching and the client''s response"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Patient education', 'Teaching process', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331001', 'MCQ', 'A nurse is counseling a woman at her first prenatal visit at 8 weeks gestation. The client reports she does not take any supplements. Which teaching point is the highest priority to prevent a birth defect?', 'Folic acid taken in the first trimester prevents neural tube defects such as spina bifida.', '{"options":[{"id":"A","text":"Take 400 mcg of folic acid daily to reduce neural tube defects"},{"id":"B","text":"Increase calcium intake to prevent maternal osteoporosis"},{"id":"C","text":"Begin iron supplementation to prevent anemia"},{"id":"D","text":"Limit vitamin A to avoid excessive weight gain"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Folic acid in early pregnancy reduces neural tube defect risk.","B":"Incorrect. Calcium is important but not the priority for defect prevention.","C":"Incorrect. Iron addresses anemia, not neural tube defects.","D":"Incorrect. This does not prevent a birth defect at this stage."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal care', 'Nutrition education', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331002', 'MCQ', 'A nurse is providing discharge teaching to a client who is 2 days postpartum. Which statement by the client indicates a need for further teaching?', 'Unilateral calf redness, warmth, and pain suggest deep vein thrombosis, a postpartum emergency, not a normal finding.', '{"options":[{"id":"A","text":"I should call my provider if I soak a pad in less than an hour"},{"id":"B","text":"A small amount of pink-tinged discharge is expected next week"},{"id":"C","text":"I can resume my normal exercise routine as soon as I feel able"},{"id":"D","text":"Redness and warmth in my calf are normal after delivery"}]}'::jsonb, '{"answer":"D","feedback":{"A":"Incorrect. This is correct teaching about hemorrhage warning signs.","B":"Incorrect. Serosanguineous lochia is normal.","C":"Incorrect but not the most concerning statement.","D":"Correct. Calf redness and warmth suggest DVT and require follow-up, not reassurance."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum care', 'Discharge teaching', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331003', 'MCQ', 'A nurse assesses a healthy 9-month-old at a well-child visit. Which finding would the nurse expect for this age?', 'By 9 months an infant sits without support and pulls to stand; walking and phrases come later.', '{"options":[{"id":"A","text":"Sits without support and pulls to a stand"},{"id":"B","text":"Walks independently across the room"},{"id":"C","text":"Speaks two-word phrases"},{"id":"D","text":"Has no head lag when pulled to sit"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A 9-month-old typically sits unsupported and pulls to stand.","B":"Incorrect. Independent walking usually occurs around 12–15 months.","C":"Incorrect. Two-word phrases appear around 24 months.","D":"Incorrect. This is expected by about 4 months, not a marker of 9 months."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Growth and development', 'Infant milestones', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331004', 'MCQ', 'A nurse is preparing to administer routine vaccines at a well-child clinic. Which situation is a true contraindication to giving the MMR vaccine today?', 'MMR is a live-attenuated vaccine and is contraindicated in significantly immunocompromised children.', '{"options":[{"id":"A","text":"The child has a mild runny nose and no fever"},{"id":"B","text":"The child is receiving high-dose immunosuppressive therapy"},{"id":"C","text":"The child had mild soreness after a prior vaccine"},{"id":"D","text":"The child is currently teething"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Mild illness is not a contraindication.","B":"Correct. Live vaccines like MMR are contraindicated with significant immunosuppression.","C":"Incorrect. Local soreness is not a contraindication.","D":"Incorrect. Teething is unrelated to vaccination safety."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Immune', 'Immunizations', 'Contraindications', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331005', 'MCQ', 'A community health nurse is planning preventive screening for a group of independent adults aged 65 and older. Which screening is most appropriate to recommend annually for this population?', 'Falls are a leading cause of injury in older adults; annual fall-risk screening enables early intervention.', '{"options":[{"id":"A","text":"Fall-risk assessment"},{"id":"B","text":"Routine chest x-ray for lung cancer"},{"id":"C","text":"Annual whole-body CT scan"},{"id":"D","text":"Yearly tonsillectomy evaluation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Annual fall-risk screening is a priority for older adults.","B":"Incorrect. Chest x-ray is not recommended for routine lung cancer screening.","C":"Incorrect. This is not an evidence-based preventive screen.","D":"Incorrect. This is not a preventive measure."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult health', 'Screening', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331006', 'MCQ', 'A nurse is counseling an adult client who states, "I know I should quit smoking, but I have tried before and failed." Using the stages of change, which response best matches the client''s readiness?', 'A client weighing pros and cons is in contemplation; exploring prior attempts supports movement toward action.', '{"options":[{"id":"A","text":"Let''s set your quit date for this week and choose a nicotine patch"},{"id":"B","text":"Let''s talk about what worked and what got in the way last time"},{"id":"C","text":"Since you failed before, quitting may not be realistic for you"},{"id":"D","text":"You do not seem interested, so we can revisit this in a year"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This assumes the client is ready to act now.","B":"Correct. Exploring past attempts fits a client contemplating change.","C":"Incorrect. This is discouraging and non-therapeutic.","D":"Incorrect. The client is expressing ambivalence, not disinterest."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Respiratory', 'High-risk behavior education', 'Smoking cessation', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331007', 'MCQ', 'A nurse provides anticipatory guidance to the parent of a 14-year-old. Which statement reflects appropriate developmental expectations for this adolescent?', 'Adolescents form identity strongly influenced by peers, per Erikson''s identity vs. role confusion stage.', '{"options":[{"id":"A","text":"Peer relationships become increasingly important to identity"},{"id":"B","text":"Parallel play is the expected form of social interaction"},{"id":"C","text":"Separation anxiety is the primary emotional concern"},{"id":"D","text":"Magical thinking dominates the child''s reasoning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Peer influence and identity formation are central in adolescence.","B":"Incorrect. Parallel play is characteristic of toddlers.","C":"Incorrect. This is typical of infancy.","D":"Incorrect. Magical thinking is a preschool trait."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Adolescent health', 'Anticipatory guidance', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331008', 'MCQ', 'A nurse plans discharge education for a newly diagnosed diabetic client who was admitted in ketoacidosis this morning and is still nauseated and drowsy. Which action is most appropriate?', 'Readiness to learn requires the client be free of acute physiologic distress before meaningful teaching.', '{"options":[{"id":"A","text":"Delay detailed teaching until the client is physiologically stable and alert"},{"id":"B","text":"Provide the full insulin self-injection demonstration now"},{"id":"C","text":"Give the client written materials to read independently now"},{"id":"D","text":"Ask a family member to complete all diabetes care permanently"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Physiologic distress impairs readiness to learn.","B":"Incorrect. The client cannot absorb complex teaching while ill.","C":"Incorrect. Drowsiness and nausea reduce comprehension.","D":"Incorrect. This removes the client from self-management."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Readiness to learn', 'Teaching principles', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331009', 'MCQ', 'A nurse teaches a client at 28 weeks gestation about warning signs to report. Which symptom should the client be taught to report immediately?', 'Severe headache with visual changes suggests preeclampsia, an obstetric emergency.', '{"options":[{"id":"A","text":"A persistent, severe headache with blurred vision"},{"id":"B","text":"Mild ankle swelling at the end of the day"},{"id":"C","text":"Occasional Braxton Hicks contractions"},{"id":"D","text":"Increased frequency of urination"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These may indicate preeclampsia and require immediate evaluation.","B":"Incorrect. Dependent edema is common in pregnancy.","C":"Incorrect. Irregular painless contractions are normal.","D":"Incorrect. This is an expected finding."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Antepartum care', 'Danger signs', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331010', 'MCQ', 'A nurse teaches a first-time mother about infant feeding. Which statement indicates the teaching was effective?', 'Newborns are fed on demand every 2–3 hours; solids and water are inappropriate this young.', '{"options":[{"id":"A","text":"I will feed my newborn on demand, about every 2 to 3 hours"},{"id":"B","text":"I can add cereal to the bottle so my baby sleeps longer"},{"id":"C","text":"I should give water between feedings to prevent dehydration"},{"id":"D","text":"I will prop the bottle so my baby can feed alone"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. On-demand feeding every 2–3 hours is appropriate for newborns.","B":"Incorrect. Solids are not recommended before 6 months.","C":"Incorrect. Water can cause hyponatremia in newborns.","D":"Incorrect. Bottle propping risks aspiration and ear infection."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'GI', 'Newborn care', 'Feeding education', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_331011', 'MCQ', 'A nurse at a workplace wellness clinic reviews health maintenance for a 45-year-old man with a family history of colon cancer. Which recommendation is most appropriate?', 'A first-degree relative with colon cancer indicates earlier and more frequent colorectal screening.', '{"options":[{"id":"A","text":"Begin colorectal cancer screening earlier than the general population"},{"id":"B","text":"Screening is unnecessary until age 75"},{"id":"C","text":"Colonoscopy is only needed if he develops symptoms"},{"id":"D","text":"Diet alone eliminates the need for screening"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A first-degree family history warrants earlier screening.","B":"Incorrect. Family history increases risk and moves screening earlier.","C":"Incorrect. Screening is preventive, not symptom-driven.","D":"Incorrect. Diet does not replace screening in high-risk clients."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Endocrine', 'Adult health maintenance', 'Screening', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_331012', 'SATA', 'A nurse teaches a pregnant client about healthy lifestyle during pregnancy. Which client statements indicate correct understanding? Select all that apply.', 'Avoiding alcohol, high-mercury fish, and undercooked meats plus regular activity and hygiene supports a healthy pregnancy; hot tubs are discouraged.', '{"options":[{"id":"A","text":"I will avoid alcohol completely during my pregnancy"},{"id":"B","text":"I should limit high-mercury fish like swordfish"},{"id":"C","text":"Moderate walking most days of the week is beneficial"},{"id":"D","text":"I can continue to soak in a hot tub daily"},{"id":"E","text":"I should eat undercooked deli meats for extra protein"},{"id":"F","text":"Handwashing before eating helps prevent infection"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Prenatal education', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_331013', 'SATA', 'A nurse provides anticipatory guidance to the parents of a 2-year-old. Which safety measures should the nurse include? Select all that apply.', 'Toddlers are at high risk for poisoning, aspiration, and drowning; safe storage, supervision, and car seats are essential.', '{"options":[{"id":"A","text":"Keep cleaning products in locked cabinets"},{"id":"B","text":"Use a rear-facing or forward-facing car seat per weight and height"},{"id":"C","text":"Supervise the child closely near water at all times"},{"id":"D","text":"Allow the toddler to play with small coins to build fine motor skills"},{"id":"E","text":"Place the toddler to sleep in a safe crib without loose bedding"},{"id":"F","text":"Leave medications on the counter for easy access"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Toddler safety', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_331014', 'SATA', 'A home-care nurse assesses an older adult client''s ability to live independently. Which findings indicate a need for additional home support? Select all that apply.', 'Medication disorganization, fall hazards, poor nutrition, and neglected affairs signal declining self-care and need for support.', '{"options":[{"id":"A","text":"Expired medications mixed with current prescriptions"},{"id":"B","text":"Several throw rugs on slippery floors"},{"id":"C","text":"A working smoke detector in the hallway"},{"id":"D","text":"Little food in the home and reported weight loss"},{"id":"E","text":"Grab bars installed in the bathroom"},{"id":"F","text":"Unopened mail and unpaid utility bills piling up"}]}'::jsonb, '{"answers":["A","B","D","F"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Older adult health maintenance', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_331015', 'SATA', 'A nurse conducts a comprehensive health assessment during a routine adult visit. Which components are part of a health promotion assessment? Select all that apply.', 'A health promotion assessment includes lifestyle, immunizations, nutrition, activity, and substance use, not irrelevant personal data.', '{"options":[{"id":"A","text":"Immunization history"},{"id":"B","text":"Nutrition and dietary patterns"},{"id":"C","text":"Tobacco, alcohol, and substance use"},{"id":"D","text":"The client''s credit card number"},{"id":"E","text":"Exercise and physical activity level"},{"id":"F","text":"Names of the client''s coworkers"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Health assessment', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_331016', 'SATA', 'A nurse teaches a breastfeeding mother before discharge. Which statements indicate the mother understands effective breastfeeding? Select all that apply.', 'A deep latch, adequate wet diapers, audible swallowing, and softening after feeds indicate effective breastfeeding; rigid scheduling and painful cracked nipples are not normal.', '{"options":[{"id":"A","text":"My baby should latch with a wide-open mouth covering the areola"},{"id":"B","text":"Six or more wet diapers a day means my baby is getting enough milk"},{"id":"C","text":"I should hear or see my baby swallowing during feeds"},{"id":"D","text":"I should only breastfeed on a strict 4-hour schedule"},{"id":"E","text":"Some breast fullness that softens after feeding is expected"},{"id":"F","text":"Cracked, bleeding nipples are a normal part of nursing"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Postpartum education', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_331017', 'SELECT_N', 'A nurse plans primary prevention activities for a community. Which 3 activities are examples of PRIMARY prevention?', 'Primary prevention stops disease before it occurs (immunization, education); screening is secondary and rehabilitation is tertiary.', '{"options":[{"id":"A","text":"Providing immunizations at a school clinic"},{"id":"B","text":"Teaching a smoking-cessation class to well adults"},{"id":"C","text":"Conducting a car-seat installation education program"},{"id":"D","text":"Screening adults for high blood pressure"},{"id":"E","text":"Rehabilitating a client after a stroke"},{"id":"F","text":"Performing mammograms for early cancer detection"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Preventive care', NULL, 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_331018', 'SELECT_N', 'A nurse screens a 4-year-old at a well-child visit. Which 2 findings would prompt referral for further developmental evaluation?', 'By age 4, a child should speak understandably, hop, and draw a person; absence of these warrants referral.', '{"options":[{"id":"A","text":"Cannot speak in short sentences understandable to strangers"},{"id":"B","text":"Does not hop on one foot or draw a simple person"},{"id":"C","text":"Enjoys imaginative play with peers"},{"id":"D","text":"Can state first and last name"},{"id":"E","text":"Follows a three-step command"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Neurological', 'Developmental screening', NULL, 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_331019', 'TF', 'A mild upper respiratory infection with a low-grade fever is a contraindication to administering routine childhood vaccines.', 'Mild illness with or without low-grade fever is not a contraindication; vaccines may still be given.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Immune', 'Immunizations', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_331020', 'TF', 'When a client faces a language barrier, using a trained medical interpreter rather than a family member improves the accuracy of health teaching.', 'Trained interpreters provide accurate, unbiased communication and protect confidentiality better than family members.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Patient teaching', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_331021', 'MATRIX', 'For each nursing activity, click to classify it as primary or secondary prevention.', 'Primary prevention avoids disease onset; secondary prevention detects disease early through screening.', '{"row_label":"Activity","rows":[{"id":"r1","text":"Administering influenza vaccine to healthy adults"},{"id":"r2","text":"Screening blood glucose at a health fair"},{"id":"r3","text":"Teaching helmet use to prevent head injury"},{"id":"r4","text":"Performing a Papanicolaou (Pap) test"}],"columns":[{"id":"c1","text":"Primary prevention"},{"id":"c2","text":"Secondary prevention"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Levels of prevention', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_331022', 'MATRIX_MR', 'For each age group, select all milestones typically expected at that age (a milestone may apply to more than one group).', 'Sitting emerges near 6 months, first words near 12 months, and walking with phrases by 24 months.', '{"row_label":"Age group","rows":[{"id":"r1","text":"Sits with support / rolls over"},{"id":"r2","text":"Says a few single words"},{"id":"r3","text":"Walks well and climbs stairs with help"},{"id":"r4","text":"Runs and uses two-word phrases"}],"columns":[{"id":"c1","text":"6 months"},{"id":"c2","text":"12 months"},{"id":"c3","text":"24 months"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c3"],"r4":["c3"]},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Multisystem', 'Developmental milestones', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_331023', 'CLOZE', 'During a routine postpartum check on day 1, the nurse expects the fundus to be firm and located at {1}. If the fundus is boggy, the nurse should first {2}.', 'On day 1 the fundus is at the umbilicus; a boggy fundus is first managed with fundal massage to promote contraction.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"the level of the umbilicus"},{"id":"c2","text":"the xiphoid process"},{"id":"c3","text":"the symphysis pubis"}]},{"id":"b2","choices":[{"id":"c1","text":"massage the fundus"},{"id":"c2","text":"administer an analgesic"},{"id":"c3","text":"increase IV fluids to 200 mL/hr"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Fundal assessment', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_331024', 'HIGHLIGHT', 'A home-care nurse assesses the home of an older adult at risk for falls. Highlight the findings that require intervention. The home has [[loose electrical cords across the walkway]], [[grab bars in the shower]], [[poor lighting on the staircase]], a [[nightlight in the hallway]], and [[a cluttered floor with stacked boxes]].', 'Loose cords, poor stair lighting, and floor clutter are fall hazards; grab bars and nightlights are protective.', '{"chunks":[{"id":"h1","text":"loose electrical cords across the walkway"},{"id":"h2","text":"grab bars in the shower"},{"id":"h3","text":"poor lighting on the staircase"},{"id":"h4","text":"nightlight in the hallway"},{"id":"h5","text":"a cluttered floor with stacked boxes"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"A tripping hazard requiring intervention.","h2":"A safety feature, not a hazard.","h3":"Poor lighting increases fall risk.","h4":"A protective measure.","h5":"Clutter obstructs safe walking."}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Community Health', 'Multisystem', 'Home safety assessment', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_331025', 'BOWTIE', 'A pregnant client is newly diagnosed with gestational diabetes. Complete the diagram by selecting the priority education topics, the condition, and the outcomes to monitor.', 'Gestational diabetes management centers on glucose monitoring and diet, with follow-up of maternal glucose and fetal growth.', '{"left":{"label":"Education to provide","tokens":[{"id":"lt1","text":"Monitor and record blood glucose as directed"},{"id":"lt2","text":"Follow the prescribed carbohydrate-controlled diet"},{"id":"lt3","text":"Stop all physical activity for the pregnancy"},{"id":"lt4","text":"Skip meals to keep glucose low"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Gestational diabetes"},{"id":"ct2","text":"Preeclampsia"},{"id":"ct3","text":"Placenta previa"}]},"right":{"label":"Outcomes to monitor","tokens":[{"id":"rt1","text":"Maternal blood glucose levels"},{"id":"rt2","text":"Fetal growth and size"},{"id":"rt3","text":"Maternal hearing acuity"},{"id":"rt4","text":"Client''s dental alignment"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Maternity', 'Reproductive', 'Gestational diabetes education', NULL, 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_331026', 'DRAG_CLOZE', 'A nurse reviews the childhood immunization schedule. The first dose of the hepatitis B vaccine is given at [1], and the MMR vaccine is first given at [2].', 'Hepatitis B is given at birth; the first MMR dose is given at 12–15 months.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"birth"},{"id":"t2","text":"12 months"},{"id":"t3","text":"6 years"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Pediatrics', 'Immune', 'Immunization schedule', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_331027', 'DRAG_ORDER', 'A nurse plans a health education session for a client learning to manage a new diagnosis. Place the steps of the teaching process in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Assess the client''s learning needs and readiness"},{"id":"t2","text":"Set mutual learning goals with the client"},{"id":"t3","text":"Implement the teaching plan"},{"id":"t4","text":"Evaluate the client''s understanding"},{"id":"t5","text":"Document the teaching and response"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Health Promotion and Maintenance', 'Health Promotion and Maintenance', 'Fundamentals of Nursing', 'Multisystem', 'Patient teaching process', NULL, 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323001', 'MCQ', 'A charge nurse is assigning tasks on a busy medical unit. Which client is MOST appropriate to assign to a licensed practical/vocational nurse (LPN/LVN)?', 'The LPN/LVN may care for stable clients performing predictable tasks; assessment, evaluation, and care planning remain with the RN.', '{"options":[{"id":"A","text":"A stable client with a chronic wound requiring a routine dry dressing change"},{"id":"B","text":"A newly admitted client requiring an initial admission assessment"},{"id":"C","text":"A client receiving the first dose of IV antibiotics"},{"id":"D","text":"A client whose plan of care needs to be evaluated and updated"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A stable client needing a routine, predictable task is within the LPN/LVN scope.","B":"Incorrect. Initial assessment and care planning are the RN''s responsibility.","C":"Incorrect. Evaluating a first-dose response requires RN assessment.","D":"Incorrect. Evaluating and revising the plan of care is an RN function."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'LPN scope', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323002', 'MCQ', 'A nurse receives report on four clients. Which client should the nurse assess FIRST?', 'A significant drop in oxygen saturation reflects an airway/breathing problem, taking priority using the ABC framework.', '{"options":[{"id":"A","text":"A client 1 day postoperative reporting incisional pain rated 5/10"},{"id":"B","text":"A client with pneumonia whose oxygen saturation dropped from 94% to 86%"},{"id":"C","text":"A client awaiting discharge teaching for a new oral medication"},{"id":"D","text":"A client requesting assistance to the bathroom"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Expected postoperative pain is a priority but not life-threatening.","B":"Correct. A falling saturation signals worsening oxygenation and requires immediate assessment.","C":"Incorrect. Discharge teaching is not urgent.","D":"Incorrect. A routine request can be delegated or addressed after urgent needs."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323003', 'MCQ', 'A client scheduled for surgery tells the nurse, "I''m not really sure what they''re going to do to me." The surgical consent is already signed. What is the nurse''s BEST action?', 'When a client lacks understanding of a procedure, the nurse advocates by notifying the provider, who is responsible for informed consent.', '{"options":[{"id":"A","text":"Reassure the client that the surgeon is very experienced"},{"id":"B","text":"Witness that the client changed their mind and cancel the surgery"},{"id":"C","text":"Notify the surgeon so they can clarify the procedure before surgery"},{"id":"D","text":"Explain the details of the surgical procedure to the client"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Reassurance does not address the knowledge deficit.","B":"Incorrect. The nurse cannot unilaterally cancel; the client has not withdrawn consent.","C":"Correct. Obtaining informed consent and explaining the procedure is the provider''s duty; the nurse acts as advocate.","D":"Incorrect. Disclosing procedure details is the surgeon''s responsibility, not the nurse''s."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323004', 'MCQ', 'A nurse wants to post about an unusual case on a personal social media account without using the client''s name. Which statement about this action is correct?', 'Sharing protected health information on social media breaches confidentiality whenever the client could be identified, even without a name.', '{"options":[{"id":"A","text":"It is acceptable as long as the client''s name is omitted"},{"id":"B","text":"It is a breach of confidentiality if the client could be identified from the details"},{"id":"C","text":"It is permitted because personal accounts are not covered by HIPAA"},{"id":"D","text":"It is allowed if the post is set to a private audience"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Identifiable details beyond the name can still breach confidentiality.","B":"Correct. Any identifiable information shared without authorization violates HIPAA.","C":"Incorrect. HIPAA applies regardless of the platform or account type.","D":"Incorrect. Privacy settings do not authorize disclosure of protected information."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA / social media', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323005', 'MCQ', 'A client with a valid do-not-resuscitate (DNR) order becomes unresponsive and stops breathing. A family member at the bedside shouts, "Do something, save him!" What should the nurse do?', 'A valid DNR order directs the team to withhold resuscitation; family distress is addressed with support while honoring the client''s wishes.', '{"options":[{"id":"A","text":"Begin cardiopulmonary resuscitation at the family''s request"},{"id":"B","text":"Honor the DNR order and provide supportive, comfort-focused care"},{"id":"C","text":"Call the provider to ask whether to start resuscitation"},{"id":"D","text":"Ask the family to sign a form reversing the DNR"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. The family cannot override a valid DNR order.","B":"Correct. A valid DNR must be honored; the nurse supports the client and family.","C":"Incorrect. Delaying to seek permission is unnecessary; the order is already in place.","D":"Incorrect. Only the client or authorized decision-maker may revise the directive."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323006', 'MCQ', 'A nurse receives a written order that reads "heparin 5000 units subcut q12h" but the dose appears unusually high for the client. What should the nurse do FIRST?', 'The nurse is accountable for verifying and clarifying any order that appears erroneous with the prescriber before implementing it.', '{"options":[{"id":"A","text":"Administer the dose as written since it is a legal order"},{"id":"B","text":"Clarify the order with the prescribing provider before administering"},{"id":"C","text":"Reduce the dose to a safer amount and give it"},{"id":"D","text":"Hold the medication and take no further action"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A nurse must not carry out an order believed to be unsafe.","B":"Correct. The nurse questions and clarifies any order that appears incorrect before acting.","C":"Incorrect. The nurse cannot alter a dose without a new order.","D":"Incorrect. Simply holding without clarification leaves the concern unresolved."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying orders', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323007', 'MCQ', 'A home health nurse notes patterned bruising and repeated unexplained injuries on an older adult client who lives with a caregiver. What is the nurse''s legal responsibility?', 'Nurses are mandated reporters and must report reasonable suspicion of vulnerable-adult abuse to the appropriate agency without waiting for proof.', '{"options":[{"id":"A","text":"Confront the caregiver about the suspected abuse"},{"id":"B","text":"Wait to gather definitive proof before taking any action"},{"id":"C","text":"Report the suspected abuse to the appropriate authorities"},{"id":"D","text":"Document the findings and address it at the next scheduled visit"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Confrontation can escalate risk and is not the nurse''s role.","B":"Incorrect. Reporting is based on reasonable suspicion, not proof.","C":"Correct. Nurses are mandatory reporters and must report reasonable suspicion of abuse.","D":"Incorrect. Delaying a report of suspected abuse endangers the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', 'Abuse', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323008', 'MCQ', 'A client recovering from a stroke will be discharged home with limited mobility and a new feeding regimen. Which referral is MOST appropriate for the nurse to initiate to promote continuity of care?', 'Coordinating a home health referral ensures continuity of skilled nursing and therapy for the client''s new post-stroke care needs.', '{"options":[{"id":"A","text":"A home health nursing and therapy referral"},{"id":"B","text":"A referral to hospice care"},{"id":"C","text":"A referral to a smoking-cessation program"},{"id":"D","text":"No referral, since the family can manage independently"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Home health provides skilled follow-up, therapy, and support for the new care needs.","B":"Incorrect. Hospice is for end-of-life care, not rehabilitation.","C":"Incorrect. This does not address the client''s mobility or feeding needs.","D":"Incorrect. The complexity of new needs warrants skilled support."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Continuity of care', 'Referrals', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323009', 'MCQ', 'Two nurses on a unit are in an escalating disagreement about how to divide the workload, and it is affecting the team. Which approach by the charge nurse is MOST constructive?', 'Facilitating a collaborative, private conversation to reach a mutual solution addresses the conflict''s source and maintains a functioning team.', '{"options":[{"id":"A","text":"Assign both nurses to separate areas so they avoid each other"},{"id":"B","text":"Facilitate a private discussion to identify a mutually acceptable solution"},{"id":"C","text":"Tell both nurses to keep their opinions to themselves during the shift"},{"id":"D","text":"Report both nurses to management for disciplinary action"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Avoidance does not resolve the underlying issue.","B":"Correct. Collaboration through open discussion addresses the root problem and preserves teamwork.","C":"Incorrect. Suppressing concerns does not resolve conflict.","D":"Incorrect. Discipline is premature before attempting resolution."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323010', 'MCQ', 'A competent adult client refuses a prescribed blood transfusion for personal reasons after being fully informed of the risks. What is the nurse''s BEST response?', 'A competent, informed client has the legal right to refuse treatment; the nurse respects autonomy and notifies the provider.', '{"options":[{"id":"A","text":"Proceed with the transfusion because it is medically necessary"},{"id":"B","text":"Respect the client''s decision and notify the provider"},{"id":"C","text":"Have the family sign a consent form to override the refusal"},{"id":"D","text":"Document that the client is being noncompliant with care"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Administering treatment against a competent client''s wishes is battery.","B":"Correct. A competent, informed client has the right to refuse treatment; the nurse advocates and informs the provider.","C":"Incorrect. Family cannot override a competent client''s decision.","D":"Incorrect. Exercising the right to refuse is not noncompliance."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy', 'Rights', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323011', 'MCQ', 'A nurse is charting after finding a client on the floor. Which entry is the MOST appropriate documentation?', 'Documentation must be objective, factual, and free of assumptions or blame, recording only what was observed and the actions taken.', '{"options":[{"id":"A","text":"\"Client fell out of bed because the side rail was down.\""},{"id":"B","text":"\"Client found sitting on the floor beside the bed; alert, denies pain; provider notified.\""},{"id":"C","text":"\"Client appears to have had a bad fall and seems confused.\""},{"id":"D","text":"\"Client is careless and keeps trying to get up alone.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This states an unwitnessed cause and assigns blame.","B":"Correct. Objective, factual charting describes what was observed without assumptions.","C":"Incorrect. Vague, subjective wording is not measurable or factual.","D":"Incorrect. Judgmental language is inappropriate in the record."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', 'Terminology', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323012', 'MCQ', 'A nurse manager wants to reduce supply waste on the unit without compromising client safety. Which strategy BEST supports cost-effective care?', 'Cost-effective care includes efficient use of resources; gathering only needed supplies reduces waste without compromising safety.', '{"options":[{"id":"A","text":"Stocking each client room with a full week of supplies in advance"},{"id":"B","text":"Gathering only the supplies needed for each planned procedure"},{"id":"C","text":"Using sterile packs for all tasks to save selection time"},{"id":"D","text":"Discarding opened but unused supplies to avoid confusion"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Overstocking leads to waste and expired supplies.","B":"Correct. Bringing only what is needed reduces waste while maintaining safe care.","C":"Incorrect. Using sterile supplies for clean tasks is wasteful.","D":"Incorrect. Unnecessary discarding increases cost and waste."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Cost-effective care', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_323013', 'TF', 'It is appropriate for a registered nurse to delegate the evaluation of a client''s response to a newly administered medication to unlicensed assistive personnel.', 'Evaluation of a client''s response to treatment requires nursing judgment and cannot be delegated to UAP; only stable, predictable tasks may be delegated.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_323014', 'SATA', 'A nurse is preparing an SBAR handoff report when transferring a client to another unit. Which elements should be included? Select all that apply.', 'SBAR structures handoff into Situation, Background, Assessment, and Recommendation; subjective opinions and irrelevant information are excluded.', '{"options":[{"id":"A","text":"The client''s current diagnosis and reason for transfer"},{"id":"B","text":"Relevant background such as pertinent history and current treatments"},{"id":"C","text":"The most recent assessment findings and vital signs"},{"id":"D","text":"Recommendations and pending orders or follow-up needs"},{"id":"E","text":"The nurse''s personal opinion of the client''s family dynamics"},{"id":"F","text":"Unrelated gossip about the receiving unit''s staffing"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'SBAR handoff', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_323015', 'SATA', 'Which tasks can the registered nurse appropriately delegate to unlicensed assistive personnel (UAP)? Select all that apply.', 'UAP may perform stable, routine ADLs and data collection; assessment, teaching, care planning, and medication administration remain with the RN.', '{"options":[{"id":"A","text":"Measuring and recording vital signs on a stable client"},{"id":"B","text":"Assisting a stable client with feeding at mealtime"},{"id":"C","text":"Ambulating a stable client who has been cleared for activity"},{"id":"D","text":"Developing the nursing plan of care for a new admission"},{"id":"E","text":"Teaching a client about a new diagnosis"},{"id":"F","text":"Administering an intravenous medication"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'UAP scope', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_323016', 'SATA', 'A nurse is reviewing ethical principles that guide practice. Which actions demonstrate the principle of client advocacy? Select all that apply.', 'Advocacy involves protecting the client''s rights, autonomy, and informed participation; overriding wishes or withholding information contradicts it.', '{"options":[{"id":"A","text":"Ensuring the client''s questions are answered before a procedure"},{"id":"B","text":"Supporting a competent client''s right to refuse treatment"},{"id":"C","text":"Speaking up when the client''s wishes are being overlooked"},{"id":"D","text":"Making treatment decisions for the client based on staff preference"},{"id":"E","text":"Withholding information the client has requested about their care"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Ethical principles', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_323017', 'SATA', 'A nurse is coordinating discharge for a client with new self-care needs. Which actions support safe, effective discharge planning? Select all that apply.', 'Effective discharge planning confirms understanding, arranges follow-up and referrals, reconciles medications, and provides accessible instructions.', '{"options":[{"id":"A","text":"Verifying the client can demonstrate new self-care skills"},{"id":"B","text":"Confirming follow-up appointments are scheduled"},{"id":"C","text":"Providing written and verbal instructions in the client''s preferred language"},{"id":"D","text":"Arranging needed referrals such as home health or equipment"},{"id":"E","text":"Delaying medication reconciliation until after discharge"},{"id":"F","text":"Assuming the client understands without confirming comprehension"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Discharge planning', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_323018', 'SELECT_N', 'A nurse begins a shift with several clients. Select the 3 clients the nurse should assess before the others.', 'Airway/breathing compromise, hypotension, and possible stroke are unstable, life-threatening situations that take priority over routine needs.', '{"options":[{"id":"A","text":"A client reporting new, sudden shortness of breath"},{"id":"B","text":"A client with a systolic blood pressure of 78 mmHg"},{"id":"C","text":"A client with a new onset of slurred speech and facial droop"},{"id":"D","text":"A client requesting a refill of the water pitcher"},{"id":"E","text":"A stable client awaiting routine morning medications"},{"id":"F","text":"A client who wants to review the lunch menu"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_323019', 'SELECT_N', 'A unit is implementing a quality/performance improvement initiative to reduce medication errors. Select the 2 actions that BEST reflect a quality improvement approach.', 'Quality improvement uses aggregate data and iterative process changes in a nonpunitive, system-focused way rather than assigning individual blame.', '{"options":[{"id":"A","text":"Analyzing aggregate error and near-miss data to find system patterns"},{"id":"B","text":"Implementing and re-measuring a process change such as barcode scanning"},{"id":"C","text":"Assigning individual blame to the nurse involved in each error"},{"id":"D","text":"Discouraging staff from reporting near-misses to keep numbers low"},{"id":"E","text":"Ignoring errors that did not reach the client"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality improvement', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_323020', 'MATRIX', 'For each task, click to indicate whether it may be delegated to unlicensed assistive personnel (UAP) or must be retained by the registered nurse (RN).', 'UAP may perform stable routine tasks and data collection; assessment and evaluation require the RN''s judgment.', '{"row_label":"Task","rows":[{"id":"r1","text":"Assisting a stable client with a bed bath"},{"id":"r2","text":"Performing the initial admission assessment"},{"id":"r3","text":"Recording a client''s oral intake and output"},{"id":"r4","text":"Evaluating whether a new medication is effective"},{"id":"r5","text":"Turning and repositioning a stable client"}],"columns":[{"id":"c1","text":"Delegate to UAP"},{"id":"c2","text":"Retain with RN"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'Scope of practice', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_323021', 'MATRIX_MR', 'For each client need, select all disciplines the nurse should involve in the plan of care (more than one may apply).', 'Coordinating the right disciplines for each need reflects effective multidisciplinary collaboration and continuity of care.', '{"row_label":"Client","rows":[{"id":"r1","text":"Client with new mobility limits who cannot afford home equipment"},{"id":"r2","text":"Client with diabetes struggling with meal planning"},{"id":"r3","text":"Client being discharged with no home support and new therapy needs"},{"id":"r4","text":"Client with dysphagia needing texture-modified diet and swallow retraining"}],"columns":[{"id":"c1","text":"Physical therapy"},{"id":"c2","text":"Dietitian"},{"id":"c3","text":"Social work"}]}'::jsonb, '{"cells":{"r1":["c1","c3"],"r2":["c2"],"r3":["c1","c3"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', 'Referrals', 'Medium', 'Analyze', '{}', 7, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_323022', 'CLOZE', 'When prioritizing care for multiple clients, the nurse first addresses the client with the {1} because it follows the {2} framework.', 'Life-threatening problems are prioritized using the ABC framework, so a compromised airway is addressed before lower-acuity needs.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"compromised airway"},{"id":"c2","text":"request for a snack"},{"id":"c3","text":"scheduled discharge teaching"}]},{"id":"b2","choices":[{"id":"c1","text":"airway-breathing-circulation (ABC)"},{"id":"c2","text":"alphabetical order"},{"id":"c3","text":"first-come, first-served"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation frameworks', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_323023', 'HIGHLIGHT', 'A nurse observes a colleague during a shift. Highlight the findings that represent a breach of safe or ethical practice requiring follow-up. The colleague [[documented a medication as given before administering it]], [[performed hand hygiene between clients]], [[discussed a client''s diagnosis in a crowded elevator]], verified two client identifiers before a blood draw, and [[shared a computer login password with a student]].', 'Charting before administration, discussing PHI in public, and sharing login credentials all breach safe/ethical practice; hand hygiene is correct.', '{"chunks":[{"id":"h1","text":"documented a medication as given before administering it"},{"id":"h2","text":"performed hand hygiene between clients"},{"id":"h3","text":"discussed a client''s diagnosis in a crowded elevator"},{"id":"h4","text":"shared a computer login password with a student"}]}'::jsonb, '{"correct_ids":["h1","h3","h4"],"feedback":{"h1":"Charting before administration is falsification and unsafe.","h2":"This is correct, safe practice.","h3":"This breaches client confidentiality.","h4":"Sharing credentials violates security and confidentiality policy."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Reporting unsafe practice', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_323024', 'BOWTIE', 'A client is found on the floor after an unwitnessed fall. Complete the diagram by selecting the priority problem, actions to take, and follow-up steps.', 'After a fall the nurse assesses for injury and notifies the provider, then files an incident report and revises the fall-prevention plan.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Assess the client for injury before moving them"},{"id":"lt2","text":"Notify the provider of the event"},{"id":"lt3","text":"Immediately lift the client back into bed"},{"id":"lt4","text":"Restrain the client to prevent another fall"}]},"centre":{"label":"Priority concern","tokens":[{"id":"ct1","text":"Risk of injury from the fall"},{"id":"ct2","text":"Risk of infection"},{"id":"ct3","text":"Risk of dehydration"}]},"right":{"label":"Follow-up steps","tokens":[{"id":"rt1","text":"Complete an incident/occurrence report"},{"id":"rt2","text":"Reassess and update the fall-prevention plan"},{"id":"rt3","text":"Chart that the client caused the fall"},{"id":"rt4","text":"Withhold the information from the next shift"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client falls', 'Incident management', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_323025', 'DRAG_CLOZE', 'When making assignments, the nurse assigns the client requiring [1] to the RN, and the stable client needing [2] to the LPN/LVN.', 'Initial assessment requires the RN''s judgment, while a stable client''s routine, predictable task is within the LPN/LVN scope.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"an initial admission assessment"},{"id":"t2","text":"a routine dressing change"},{"id":"t3","text":"no nursing care at all"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice', 'Assignment', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_323026', 'DRAG_ORDER', 'A nurse is transferring a stable client to another unit. Place the steps of a safe transfer in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Confirm the receiving unit is ready to accept the client"},{"id":"t2","text":"Give an SBAR handoff report to the receiving nurse"},{"id":"t3","text":"Ensure the client and belongings are prepared for transport"},{"id":"t4","text":"Transport the client to the receiving unit"},{"id":"t5","text":"Document the transfer and the client''s condition on arrival"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Transfer process', 'Handoff', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_323027', 'MCQ', 'A nurse begins a shift with several tasks competing for attention. Which action reflects the BEST time-management practice?', 'Effective time management organizes and clusters care by client acuity and priority, and uses appropriate delegation.', '{"options":[{"id":"A","text":"Complete tasks in the order clients request them"},{"id":"B","text":"Cluster care and organize tasks by client acuity and priority"},{"id":"C","text":"Do the quickest tasks first regardless of urgency"},{"id":"D","text":"Avoid delegating so that all care is done personally"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Order of request does not reflect clinical priority.","B":"Correct. Prioritizing by acuity and clustering care makes efficient, safe use of time.","C":"Incorrect. Speed alone ignores client safety and priority.","D":"Incorrect. Appropriate delegation improves efficiency and care."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Time management', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324001', 'MCQ', 'A charge nurse is assigning tasks on a busy medical unit. Which task is MOST appropriate to assign to a licensed practical nurse (LPN)?', 'LPNs may give routine medications to stable clients, but assessment, care planning, and unstable client management remain with the RN.', '{"options":[{"id":"A","text":"Administering an oral antibiotic to a stable client"},{"id":"B","text":"Developing the initial plan of care for a new admission"},{"id":"C","text":"Performing the admission assessment on a new client"},{"id":"D","text":"Administering IV push medication to an unstable client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Administering routine oral medications to a stable client is within the LPN scope.","B":"Incorrect. Care planning and initial assessment are RN responsibilities.","C":"Incorrect. Initial assessment is an RN task.","D":"Incorrect. IV push to an unstable client exceeds LPN scope in most settings."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'LPN scope', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324002', 'MCQ', 'A nurse receives report on four clients. Which client should the nurse assess FIRST?', 'Using the ABC framework, the client with hypoxia and respiratory distress is assessed first.', '{"options":[{"id":"A","text":"A client with new-onset shortness of breath and an SpO2 of 88%"},{"id":"B","text":"A client requesting pain medication for a headache"},{"id":"C","text":"A client awaiting discharge teaching"},{"id":"D","text":"A client with a scheduled dressing change"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Airway/breathing compromise is the highest priority.","B":"Incorrect. Pain is important but not immediately life-threatening.","C":"Incorrect. Discharge teaching is not urgent.","D":"Incorrect. A routine dressing change can wait."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324003', 'MCQ', 'During an SBAR handoff, which piece of information belongs in the ''Recommendation'' component?', 'In SBAR, Recommendation states what the nurse wants done or suggests as the next step.', '{"options":[{"id":"A","text":"\"I think the client needs a stat chest X-ray and a provider evaluation.\""},{"id":"B","text":"\"The client is a 68-year-old admitted with pneumonia.\""},{"id":"C","text":"\"The client''s oxygen saturation dropped to 89%.\""},{"id":"D","text":"\"The client has a history of COPD.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A suggested action or request is the Recommendation.","B":"Incorrect. This is Situation/Background.","C":"Incorrect. This is Assessment data.","D":"Incorrect. This is Background."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff (SBAR)', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324004', 'MCQ', 'A client scheduled for surgery tells the nurse, "I don''t really understand what they''re going to do to me." The consent form is already signed. What is the nurse''s BEST action?', 'Obtaining informed consent (disclosure) is the provider''s duty; the nurse verifies understanding and notifies the provider of gaps.', '{"options":[{"id":"A","text":"Notify the surgeon that the client needs further explanation before proceeding"},{"id":"B","text":"Reinforce the surgeon''s explanation and witness the signature"},{"id":"C","text":"Proceed because the consent is already signed"},{"id":"D","text":"Cancel the surgery"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Informed consent requires understanding; the provider must clarify.","B":"Incorrect. The nurse cannot substitute for the provider''s disclosure.","C":"Incorrect. A signed form without understanding is not valid consent.","D":"Incorrect. The nurse does not have authority to cancel surgery."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324005', 'MCQ', 'A nurse overhears two colleagues discussing a celebrity client''s diagnosis in the cafeteria. Which action best protects client confidentiality?', 'Protected health information must not be discussed in public areas; the nurse should intervene.', '{"options":[{"id":"A","text":"Remind the colleagues that discussing clients in public areas violates privacy rules"},{"id":"B","text":"Join the conversation to learn the details"},{"id":"C","text":"Ignore it since they are also staff members"},{"id":"D","text":"Post an anonymous complaint online"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Directly addressing the breach protects confidentiality.","B":"Incorrect. This participates in the breach.","C":"Incorrect. Staff status does not permit public disclosure.","D":"Incorrect. Social media disclosure worsens the breach."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality/HIPAA', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324006', 'MCQ', 'A client with a valid do-not-resuscitate (DNR) order stops breathing. The family at the bedside begs the nurse to "do everything." What should the nurse do?', 'A valid DNR reflects the client''s autonomous wishes and must be honored despite family distress.', '{"options":[{"id":"A","text":"Honor the DNR order and provide comfort measures"},{"id":"B","text":"Begin full CPR because the family requested it"},{"id":"C","text":"Call the ethics committee before acting"},{"id":"D","text":"Ask the family to sign a form rescinding the DNR"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A valid DNR is legally binding and must be followed.","B":"Incorrect. Family cannot override a valid DNR.","C":"Incorrect. There is no time; the order is clear.","D":"Incorrect. Family cannot rescind the client''s directive."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324007', 'MCQ', 'A client refuses a prescribed blood transfusion for religious reasons but is alert and oriented. The provider insists the nurse administer it. What is the nurse''s BEST action?', 'A competent, informed client may refuse treatment; the nurse advocates for that right and documents/notifies the provider.', '{"options":[{"id":"A","text":"Support the client''s right to refuse and notify the provider of the refusal"},{"id":"B","text":"Administer the transfusion as ordered"},{"id":"C","text":"Tell the client the transfusion is mandatory"},{"id":"D","text":"Ask the family to convince the client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A competent client has the right to refuse treatment.","B":"Incorrect. This violates the client''s autonomy and constitutes battery.","C":"Incorrect. Treatment is not mandatory for a competent client.","D":"Incorrect. This is coercive and disrespects autonomy."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324008', 'MCQ', 'A nurse reviews a new order that reads "insulin 10U SQ now." The client''s blood glucose is 74 mg/dL. What should the nurse do FIRST?', 'Nurses must question and clarify orders that appear unsafe before implementing them.', '{"options":[{"id":"A","text":"Hold the dose and clarify the order with the provider"},{"id":"B","text":"Administer the insulin as written"},{"id":"C","text":"Administer half the dose"},{"id":"D","text":"Document the glucose and give the insulin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Giving insulin to a client with borderline-low glucose is unsafe; clarify first.","B":"Incorrect. Administering could cause hypoglycemia.","C":"Incorrect. The nurse cannot alter the dose independently.","D":"Incorrect. Documenting does not resolve the safety concern."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying orders', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324009', 'MCQ', 'A client is being discharged home on warfarin. Which statement indicates the client needs FURTHER teaching before discharge?', 'Safe discharge requires confirming understanding; doubling a warfarin dose is unsafe and indicates a teaching gap.', '{"options":[{"id":"A","text":"\"I''ll take an extra dose if I miss one to catch up.\""},{"id":"B","text":"\"I''ll keep my scheduled INR appointments.\""},{"id":"C","text":"\"I''ll use a soft toothbrush and an electric razor.\""},{"id":"D","text":"\"I''ll keep my intake of leafy greens consistent.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Doubling doses risks bleeding; this needs correction.","B":"Incorrect. This is correct behavior.","C":"Incorrect. This appropriately reduces bleeding risk.","D":"Incorrect. Consistent vitamin K intake is correct."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Admit/transfer/discharge', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324010', 'MCQ', 'Two nurses disagree about the priority of care for a shared client, and the discussion becomes heated in the hallway. What is the charge nurse''s BEST initial action?', 'Effective conflict management moves the discussion to privacy and uses collaboration to reach resolution.', '{"options":[{"id":"A","text":"Move the discussion to a private area and facilitate problem-solving"},{"id":"B","text":"Reassign both nurses to different clients immediately"},{"id":"C","text":"Report both nurses to the manager for discipline"},{"id":"D","text":"Decide the priority and order them to comply"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Privacy and collaborative problem-solving de-escalate the conflict constructively.","B":"Incorrect. Avoidance does not resolve the underlying issue.","C":"Incorrect. Punitive action is premature.","D":"Incorrect. An authoritarian approach ignores collaboration."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324011', 'MCQ', 'A community health nurse confirms a client has active pulmonary tuberculosis. Which action is the nurse legally required to take?', 'Active TB is a mandatory reportable communicable disease; the nurse must notify public health authorities.', '{"options":[{"id":"A","text":"Report the case to the public health department"},{"id":"B","text":"Keep the diagnosis confidential from all agencies"},{"id":"C","text":"Wait for the client''s permission before reporting"},{"id":"D","text":"Report only if the client refuses treatment"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TB is a reportable communicable disease.","B":"Incorrect. Reportable diseases override strict confidentiality for public safety.","C":"Incorrect. Reporting is mandatory and does not require consent.","D":"Incorrect. Reporting is required regardless of treatment status."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_324012', 'MCQ', 'A nurse manager wants to reduce catheter-associated urinary tract infections (CAUTIs) while controlling costs. Which intervention BEST meets both goals?', 'Nurse-driven early removal protocols reduce CAUTI rates and associated costs, meeting both quality and cost goals.', '{"options":[{"id":"A","text":"Implement a nurse-driven protocol for early catheter removal"},{"id":"B","text":"Routinely change catheters every 48 hours"},{"id":"C","text":"Use prophylactic antibiotics for all catheterized clients"},{"id":"D","text":"Insert catheters for all clients to monitor output"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Early removal reduces CAUTIs and shortens costly complications.","B":"Incorrect. Routine changes increase cost without reducing infection.","C":"Incorrect. This drives cost and resistance without proven benefit.","D":"Incorrect. Unnecessary catheters raise infection risk and cost."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Cost-effective care', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_324013', 'SATA', 'Which tasks can the nurse appropriately delegate to unlicensed assistive personnel (UAP)? Select all that apply.', 'UAP may perform stable ADLs and data collection; assessment and teaching remain nursing responsibilities.', '{"options":[{"id":"A","text":"Feeding a client who has no swallowing difficulty"},{"id":"B","text":"Measuring and recording intake and output"},{"id":"C","text":"Obtaining routine vital signs on a stable client"},{"id":"D","text":"Assessing a new client''s pain level for the first time"},{"id":"E","text":"Teaching a client about a new medication"},{"id":"F","text":"Reinforcing ambulation with a stable client"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation to UAP', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_324014', 'SATA', 'A nurse participates in a unit quality-improvement initiative. Which activities are part of an effective QI process? Select all that apply.', 'QI is data-driven, non-punitive, and collaborative, focusing on process improvement rather than blame.', '{"options":[{"id":"A","text":"Collecting and analyzing data on current outcomes"},{"id":"B","text":"Identifying a measurable problem to address"},{"id":"C","text":"Implementing a change and re-measuring results"},{"id":"D","text":"Assigning individual blame for each error"},{"id":"E","text":"Engaging the interdisciplinary team in solutions"},{"id":"F","text":"Hiding adverse events to protect the unit''s reputation"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality improvement', NULL, 'Medium', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_324015', 'SATA', 'Which of the following are protected client rights the nurse must uphold? Select all that apply.', 'Clients have rights to refuse care, access records, confidentiality, and information; they cannot compel unsafe or unethical acts.', '{"options":[{"id":"A","text":"The right to refuse treatment"},{"id":"B","text":"The right to access one''s own medical record"},{"id":"C","text":"The right to confidentiality of health information"},{"id":"D","text":"The right to demand a treatment that is medically contraindicated"},{"id":"E","text":"The right to be informed about the plan of care"},{"id":"F","text":"The right to have staff falsify documentation on request"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', NULL, 'Medium', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_324016', 'SATA', 'A case manager coordinates care for a client with heart failure being discharged. Which actions reflect appropriate case-management responsibilities? Select all that apply.', 'Case managers coordinate services, referrals, and resources but do not prescribe or alter the medical plan independently.', '{"options":[{"id":"A","text":"Arranging home health follow-up visits"},{"id":"B","text":"Coordinating durable medical equipment delivery"},{"id":"C","text":"Facilitating referrals to outpatient services"},{"id":"D","text":"Prescribing the client''s discharge medications"},{"id":"E","text":"Ensuring insurance authorization for services"},{"id":"F","text":"Independently changing the medical plan of care"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Case management', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_324017', 'SATA', 'Which practices reflect legally sound nursing documentation? Select all that apply.', 'Sound documentation is factual, timely, correctly amended, and never pre-charted or left with blanks.', '{"options":[{"id":"A","text":"Charting objective, factual observations"},{"id":"B","text":"Documenting care promptly after it is provided"},{"id":"C","text":"Drawing a single line through an error and initialing it"},{"id":"D","text":"Leaving blank spaces to complete entries later"},{"id":"E","text":"Using only approved abbreviations"},{"id":"F","text":"Charting interventions before they are performed"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_324018', 'SELECT_N', 'A nurse begins the shift with several clients. Select the 3 clients who require assessment before the others.', 'Respiratory depression, a possible surgical abdomen, and dangerous hyperkalemia are all unstable, high-priority cues.', '{"options":[{"id":"A","text":"A client with a respiratory rate of 8 after receiving opioids"},{"id":"B","text":"A postoperative client with a rigid, distended abdomen"},{"id":"C","text":"A client with a potassium of 6.8 mEq/L and peaked T waves"},{"id":"D","text":"A client requesting a warm blanket"},{"id":"E","text":"A client waiting for a routine morning shower"},{"id":"F","text":"A client asking about the lunch menu"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_324019', 'TF', 'A registered nurse may delegate the evaluation of a client''s response to a newly administered medication to unlicensed assistive personnel.', 'Evaluation and clinical judgment cannot be delegated to UAP; they remain the RN''s responsibility.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_324020', 'MATRIX', 'For each task, indicate the lowest-level provider to whom it can be appropriately assigned.', 'UAP handle stable ADLs, LPNs perform routine meds and reinforcement, and RNs retain assessment and care planning.', '{"row_label":"Task","rows":[{"id":"r1","text":"Bathing a stable client"},{"id":"r2","text":"Administering a routine oral medication"},{"id":"r3","text":"Creating the initial nursing care plan"},{"id":"r4","text":"Reinforcing previously taught discharge instructions"},{"id":"r5","text":"Performing the initial admission assessment"}],"columns":[{"id":"c1","text":"UAP"},{"id":"c2","text":"LPN"},{"id":"c3","text":"RN only"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c2","r5":"c3"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation & supervision', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_324021', 'MATRIX_MR', 'For each client need, select all disciplines the nurse should involve in the referral (more than one may apply).', 'Referrals should match each client''s functional, financial, and nutritional needs to the appropriate disciplines.', '{"row_label":"Client","rows":[{"id":"r1","text":"New stroke client with weakness and no home support"},{"id":"r2","text":"Client with poorly controlled diabetes and gait instability"},{"id":"r3","text":"Uninsured client needing a therapeutic renal diet"}],"columns":[{"id":"c1","text":"Physical therapy"},{"id":"c2","text":"Social work"},{"id":"c3","text":"Dietitian"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1","c3"],"r3":["c2","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', NULL, 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_324022', 'CLOZE', 'When prioritizing among stable clients, the nurse should first apply the {1} framework, and among equally unstable clients should consider {2} needs first.', 'The ABC framework and Maslow''s physiological (survival) needs guide prioritization of unstable clients.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"airway-breathing-circulation (ABC)"},{"id":"c2","text":"alphabetical order"},{"id":"c3","text":"room number"}]},{"id":"b2","choices":[{"id":"c1","text":"physiological"},{"id":"c2","text":"self-actualization"},{"id":"c3","text":"esteem"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation frameworks', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_324023', 'HIGHLIGHT', 'The nurse reviews a colleague''s shift. Highlight the observations that represent a breach the nurse should report. The colleague [[documented vital signs that were never taken]]. They [[discussed a client''s HIV status in the elevator]]. They [[washed hands before client contact]]. They [[removed a controlled-substance dose without a witness or waste record]]. They updated the care plan with the team.', 'Falsified charting, public disclosure of PHI, and improper controlled-substance handling are all reportable breaches; hand hygiene and team care planning are appropriate.', '{"chunks":[{"id":"h1","text":"documented vital signs that were never taken"},{"id":"h2","text":"discussed a client''s HIV status in the elevator"},{"id":"h3","text":"removed a controlled-substance dose without a witness or waste record"},{"id":"h4","text":"washed hands before client contact"}]}'::jsonb, '{"correct_ids":["h1","h2","h3"],"feedback":{"h1":"Falsified documentation must be reported.","h2":"A confidentiality breach in a public area.","h3":"Improper controlled-substance handling — reportable.","h4":"Appropriate practice — not a breach."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Reporting unsafe practice', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_324024', 'BOWTIE', 'A competent client refuses further chemotherapy against the family''s wishes. Complete the diagram by selecting the guiding principle, the nurse''s actions, and outcomes to monitor.', 'Autonomy governs a competent client''s refusal; the nurse supports the decision, notifies the provider, and documents while monitoring understanding.', '{"left":{"label":"Nurse actions","tokens":[{"id":"lt1","text":"Support the client''s informed decision"},{"id":"lt2","text":"Notify the provider of the refusal"},{"id":"lt3","text":"Persuade the client to continue treatment"},{"id":"lt4","text":"Ask the family to override the decision"}]},"centre":{"label":"Guiding principle","tokens":[{"id":"ct1","text":"Autonomy"},{"id":"ct2","text":"Nonmaleficence"},{"id":"ct3","text":"Paternalism"}]},"right":{"label":"Outcomes to monitor","tokens":[{"id":"rt1","text":"Client''s continued understanding of the decision"},{"id":"rt2","text":"Documentation of the refusal"},{"id":"rt3","text":"Family''s approval of the plan"},{"id":"rt4","text":"Provider''s personal preference"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Ethical dilemma', NULL, 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_324025', 'DRAG_CLOZE', 'Applying the five rights of delegation, a task should be given to the [1] person for a [2] client situation.', 'Delegation requires the right person and applies to stable, predictable client situations with predictable outcomes.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"right"},{"id":"t2","text":"stable/predictable"},{"id":"t3","text":"cheapest"},{"id":"t4","text":"unstable"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation principles', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_324026', 'DRAG_ORDER', 'A nurse begins a shift with multiple responsibilities. Place the following actions in the correct order for effective time management and prioritization.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Receive and review the shift handoff report"},{"id":"t2","text":"Perform a quick round to assess all assigned clients"},{"id":"t3","text":"Prioritize tasks by client acuity"},{"id":"t4","text":"Delegate appropriate tasks to the team"},{"id":"t5","text":"Reassess and adjust the plan as the shift progresses"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Time management', NULL, 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_324027', 'CLOZE', 'A client with limited English proficiency needs consent explained. The nurse should arrange a {1} and avoid {2} to obtain valid consent.', 'Valid informed consent for a client with limited English requires a qualified interpreter; using family, especially minors, is inappropriate.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"qualified medical interpreter"},{"id":"c2","text":"bilingual visitor from the waiting room"},{"id":"c3","text":"translation phone app alone"}]},{"id":"b2","choices":[{"id":"c1","text":"using the client''s minor child to interpret"},{"id":"c2","text":"documenting the interpreter used"},{"id":"c3","text":"confirming client understanding"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advocacy & referrals', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325001', 'MCQ', 'A charge nurse on a medical unit is assigning tasks. Which task is MOST appropriate to delegate to a licensed practical nurse (LPN)?', 'The LPN may reinforce established teaching and care for stable clients; assessment and care-plan initiation stay with the RN.', '{"options":[{"id":"A","text":"Reinforcing teaching about a low-sodium diet with a stable client"},{"id":"B","text":"Developing the initial nursing care plan for a new admission"},{"id":"C","text":"Administering the first dose of IV chemotherapy"},{"id":"D","text":"Performing the admission assessment on an unstable client"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Reinforcing established teaching is within the LPN scope.","B":"Incorrect. Care-plan development requires the RN''s assessment.","C":"Incorrect. High-risk IV medications remain with the RN.","D":"Incorrect. Initial assessment of an unstable client is an RN duty."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation', 'LPN scope', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325002', 'MCQ', 'A nurse receives report on four clients. Which client should the nurse assess FIRST?', 'Acute hypoxia with altered mentation signals airway/breathing compromise and is the highest priority.', '{"options":[{"id":"A","text":"A client 2 hours post-op reporting incisional pain rated 6/10"},{"id":"B","text":"A client with new-onset confusion and an oxygen saturation of 86%"},{"id":"C","text":"A client awaiting discharge teaching for a new inhaler"},{"id":"D","text":"A client requesting assistance to the bathroom"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Expected post-op pain can be addressed after unstable clients.","B":"Correct. Hypoxia with acute mental status change is the most physiologically unstable.","C":"Incorrect. A stable client awaiting teaching is a low priority.","D":"Incorrect. An ADL request can be delegated and is not urgent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325003', 'MCQ', 'A nurse is giving a telephone SBAR handoff to a provider about a deteriorating client. Which statement belongs in the ''Recommendation'' portion?', 'In SBAR, Recommendation states what the nurse wants done, such as an order or bedside evaluation.', '{"options":[{"id":"A","text":"The client''s blood pressure has dropped to 82/48 mmHg"},{"id":"B","text":"The client was admitted yesterday with pneumonia"},{"id":"C","text":"I am calling about a change in the client''s condition"},{"id":"D","text":"I think the client needs a fluid bolus and a provider evaluation now"}]}'::jsonb, '{"answer":"D","feedback":{"A":"Incorrect. This is Assessment/current data.","B":"Incorrect. This is Background.","C":"Incorrect. This is the Situation opener.","D":"Correct. A specific request/action is the Recommendation."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication', 'SBAR', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325004', 'MCQ', 'A client scheduled for surgery tells the nurse, ''I am not sure what the surgeon is going to remove.'' The consent form is already signed. What is the nurse''s BEST action?', 'Valid informed consent requires client understanding; the provider must clarify before surgery proceeds.', '{"options":[{"id":"A","text":"Reassure the client that the surgeon is highly experienced"},{"id":"B","text":"Witness the consent again and send the client to surgery"},{"id":"C","text":"Notify the surgeon that the client needs further explanation before surgery"},{"id":"D","text":"Explain the surgical procedure and its risks to the client"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Reassurance does not address the missing understanding.","B":"Incorrect. Consent is not valid without understanding.","C":"Correct. Informed consent requires the provider to explain the procedure.","D":"Incorrect. Disclosing the procedure is the provider''s responsibility."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325005', 'MCQ', 'A nurse wants to post about an interesting case on a personal social media account without using the client''s name. Which understanding is correct?', 'Sharing any detail that could identify a client on social media breaches confidentiality regardless of privacy settings.', '{"options":[{"id":"A","text":"Posting is acceptable as long as the client''s name is omitted"},{"id":"B","text":"Any post that could allow identification of the client violates confidentiality"},{"id":"C","text":"Posting is permitted if the account privacy settings are enabled"},{"id":"D","text":"Posting is allowed if the client verbally agreed in conversation"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Indirect identifiers can still breach privacy.","B":"Correct. Room number, diagnosis, and dates can identify a client.","C":"Incorrect. Privacy settings do not authorize sharing PHI.","D":"Incorrect. Verbal agreement does not authorize public disclosure."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality', 'HIPAA / social media', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325006', 'MCQ', 'A conscious, alert client with a valid Do Not Resuscitate (DNR) order asks the nurse to ''do everything'' if the heart stops. What should the nurse do?', 'A competent client may revoke an advance directive at any time; the nurse informs the provider to update the order.', '{"options":[{"id":"A","text":"Honor the existing DNR order because it is legally signed"},{"id":"B","text":"Notify the provider so the DNR status can be reviewed and revised"},{"id":"C","text":"Tell the client the DNR cannot be changed once signed"},{"id":"D","text":"Ask the family to decide since the client is confused"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A competent client may change their wishes.","B":"Correct. A competent client can revoke a directive; the order must be updated.","C":"Incorrect. Directives are revocable by a competent client.","D":"Incorrect. The client is alert and retains decision-making capacity."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325007', 'MCQ', 'A nurse receives a written order for ''digoxin 2.5 mg PO daily.'' The usual maintenance dose is 0.125-0.25 mg. What is the nurse''s priority action?', 'The nurse is accountable for questioning and clarifying an order that appears unsafe before administering it.', '{"options":[{"id":"A","text":"Administer the dose as written since it is a signed order"},{"id":"B","text":"Hold the dose and clarify the order with the prescriber"},{"id":"C","text":"Give the usual maintenance dose instead of the ordered amount"},{"id":"D","text":"Document that the order appears incorrect and give it later"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A nurse must not administer an unsafe dose.","B":"Correct. A tenfold dosing discrepancy must be clarified before administration.","C":"Incorrect. Changing a dose without an order exceeds nursing scope.","D":"Incorrect. Documentation alone does not resolve the unsafe order."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying orders', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325008', 'MCQ', 'A home health nurse notes multiple bruises in various stages of healing on an older adult client whose caregiver answers all questions for them. What is the nurse''s legal responsibility?', 'As a mandatory reporter, the nurse must report reasonable suspicion of abuse without needing proof.', '{"options":[{"id":"A","text":"Report the suspected abuse to adult protective services"},{"id":"B","text":"Confront the caregiver directly about the bruises"},{"id":"C","text":"Wait until abuse can be definitively proven before acting"},{"id":"D","text":"Document the findings and reassess at the next visit"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nurses are mandated reporters of suspected elder abuse.","B":"Incorrect. Confrontation can endanger the client and is not the legal duty.","C":"Incorrect. Reporting requires reasonable suspicion, not proof.","D":"Incorrect. Delayed action does not meet the reporting duty."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', 'Abuse', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325009', 'MCQ', 'A client refuses a prescribed blood transfusion for religious reasons and is fully alert and oriented. Which nursing action best demonstrates client advocacy?', 'Advocacy upholds a competent client''s autonomous right to refuse treatment and communicates it to the care team.', '{"options":[{"id":"A","text":"Support the client''s decision and notify the provider of the refusal"},{"id":"B","text":"Administer the transfusion because it is medically necessary"},{"id":"C","text":"Ask the family to persuade the client to accept the transfusion"},{"id":"D","text":"Tell the client the refusal will be documented as noncompliance"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Advocacy protects the competent client''s right to refuse.","B":"Incorrect. Treating without consent is battery.","C":"Incorrect. This pressures rather than advocates for the client.","D":"Incorrect. Exercising a right is not noncompliance."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325010', 'MCQ', 'A nurse is preparing a client with new home oxygen and limited mobility for discharge. Which referral is MOST appropriate to arrange?', 'Home health provides equipment management and skilled follow-up needed for a new home-oxygen client with mobility limits.', '{"options":[{"id":"A","text":"Home health services for equipment setup and follow-up"},{"id":"B","text":"A dietitian for weight-management counseling"},{"id":"C","text":"A chaplain for spiritual support"},{"id":"D","text":"A financial counselor for insurance questions"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Home health coordinates oxygen equipment and ongoing assessment.","B":"Incorrect. Diet is not the primary need for safe home oxygen use.","C":"Incorrect. Spiritual support is valuable but not the priority need here.","D":"Incorrect. Not the most appropriate first referral for this clinical need."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Discharge planning', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325011', 'MCQ', 'Two nurses on a unit repeatedly disagree loudly about assignment fairness in front of clients. Which is the charge nurse''s BEST initial response?', 'Collaborative problem-solving in private addresses the root cause while protecting professionalism at the bedside.', '{"options":[{"id":"A","text":"Meet privately with both nurses to identify the underlying concern"},{"id":"B","text":"Reassign one nurse to a different unit immediately"},{"id":"C","text":"Report both nurses to the nurse manager for discipline"},{"id":"D","text":"Ignore the dispute since assignments are already made"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Addressing the conflict privately and collaboratively resolves the issue.","B":"Incorrect. Avoidance does not resolve the underlying conflict.","C":"Incorrect. Escalation to discipline is premature.","D":"Incorrect. Ignoring it risks client care and morale."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_325012', 'MCQ', 'A nurse realizes an entry was made in the wrong client''s electronic record. What is the correct action to maintain documentation integrity?', 'Documentation errors are corrected per policy with the original preserved and marked as an error to protect the legal record.', '{"options":[{"id":"A","text":"Delete the entry so the record appears clean"},{"id":"B","text":"Enter a correction per policy, marking it as an error without deleting the original"},{"id":"C","text":"Ask a colleague to remove the entry from the system"},{"id":"D","text":"Leave the entry and add the note to the correct chart only"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Deleting entries destroys the legal record.","B":"Correct. Errors are corrected transparently, preserving the original entry.","C":"Incorrect. Records must not be altered covertly.","D":"Incorrect. The wrong entry must be corrected, not ignored."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_325013', 'SATA', 'A nurse is delegating to unlicensed assistive personnel (UAP). Which tasks are appropriate to delegate? Select all that apply.', 'UAP may perform stable ADLs and routine data collection but not assessment, evaluation, or teaching.', '{"options":[{"id":"A","text":"Measuring and recording vital signs on a stable client"},{"id":"B","text":"Assisting a stable client to ambulate in the hallway"},{"id":"C","text":"Feeding a client without swallowing difficulties"},{"id":"D","text":"Evaluating the effectiveness of pain medication"},{"id":"E","text":"Teaching a client about wound care at discharge"},{"id":"F","text":"Emptying a urinary drainage bag and recording output"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation to UAP', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_325014', 'SATA', 'A nurse reviews the rights guaranteed to a hospitalized client. Which are established client rights? Select all that apply.', 'Clients have rights to refuse care, confidentiality, information, and record access; free care and staff selection are not rights.', '{"options":[{"id":"A","text":"The right to refuse treatment"},{"id":"B","text":"The right to confidentiality of health information"},{"id":"C","text":"The right to be informed about the plan of care"},{"id":"D","text":"The right to demand a specific unlicensed staff assignment"},{"id":"E","text":"The right to access one''s own medical record"},{"id":"F","text":"The right to receive care free of any charges"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client rights', NULL, 'Medium', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_325015', 'SATA', 'A nurse is preparing an end-of-shift handoff report. Which information should be included? Select all that apply.', 'Effective handoff conveys current status, pending results, medications, and follow-up; subjective opinions and gossip are excluded.', '{"options":[{"id":"A","text":"Current problems and changes in the client''s condition"},{"id":"B","text":"Pending laboratory or diagnostic results"},{"id":"C","text":"Medications due in the next shift and recent PRN doses"},{"id":"D","text":"Personal opinions about the client''s family dynamics"},{"id":"E","text":"Outstanding tasks and follow-up needed"},{"id":"F","text":"Gossip about the client shared by another department"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff report', 'SBAR', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_325016', 'SATA', 'A nurse participates in a unit quality-improvement initiative to reduce catheter-associated infections. Which actions reflect appropriate QI practice? Select all that apply.', 'QI focuses on data-driven, systems-level improvement and transparency, not individual blame or concealment.', '{"options":[{"id":"A","text":"Collecting data on catheter days across the unit"},{"id":"B","text":"Reviewing whether evidence-based insertion protocols are followed"},{"id":"C","text":"Identifying individual nurses to blame for infections publicly"},{"id":"D","text":"Implementing a daily review of catheter necessity"},{"id":"E","text":"Tracking infection rates before and after the intervention"},{"id":"F","text":"Concealing infection data from staff to avoid alarm"}]}'::jsonb, '{"answers":["A","B","D","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality improvement', NULL, 'Medium', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_325017', 'SATA', 'A case manager coordinates care for a client with multiple chronic conditions. Which activities are within the case manager''s role? Select all that apply.', 'Case management centers on coordination, resource stewardship, discharge planning, and outcome monitoring, not prescribing or procedures.', '{"options":[{"id":"A","text":"Coordinating referrals among the multidisciplinary team"},{"id":"B","text":"Promoting cost-effective use of resources"},{"id":"C","text":"Facilitating a safe and timely discharge plan"},{"id":"D","text":"Prescribing new medications for the client"},{"id":"E","text":"Monitoring the client''s progress toward outcome goals"},{"id":"F","text":"Performing the client''s surgical procedures"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Case management', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_325018', 'SELECT_N', 'A nurse must prioritize interventions during a busy shift. Select the 3 clients who require the nurse''s attention BEFORE the others.', 'Life-threatening hyperkalemia, acute respiratory distress, and possible surgical complication take priority over comfort and routine needs.', '{"options":[{"id":"A","text":"A client with a potassium of 6.8 mEq/L and peaked T waves"},{"id":"B","text":"A client reporting sudden severe shortness of breath"},{"id":"C","text":"A postoperative client with a rigid, distended abdomen"},{"id":"D","text":"A client requesting a warm blanket"},{"id":"E","text":"A client asking about the lunch menu"},{"id":"F","text":"A stable client due for scheduled discharge teaching"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_325019', 'TF', 'A registered nurse may legally delegate the initial assessment of a newly admitted, unstable client to unlicensed assistive personnel as long as the nurse reviews the findings afterward.', 'Assessment of an unstable client is an RN responsibility that cannot be delegated to UAP under any condition.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_325020', 'TF', 'A durable power of attorney for health care becomes active only when the client is determined to be unable to make their own health care decisions.', 'The health care proxy''s authority activates when the client loses decision-making capacity, not before.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_325021', 'MATRIX', 'For each task, click to indicate whether it may be delegated to the LPN or must be retained by the RN.', 'LPNs may give routine meds and reinforce teaching for stable clients; care-plan initiation and initial teaching require the RN.', '{"row_label":"Task","rows":[{"id":"r1","text":"Administering an oral scheduled medication to a stable client"},{"id":"r2","text":"Creating the initial plan of care for a new admission"},{"id":"r3","text":"Reinforcing previously taught wound-care instructions"},{"id":"r4","text":"Providing the first-time teaching for a new diabetes diagnosis"},{"id":"r5","text":"Monitoring a stable client''s routine tube feeding"}],"columns":[{"id":"c1","text":"Delegate to LPN"},{"id":"c2","text":"Retain for RN"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and scope', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_325022', 'MATRIX_MR', 'For each client need, select all disciplines that would be appropriate referrals (more than one may apply).', 'Referrals are matched to the specific need, and several needs warrant coordination across more than one discipline.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Client with new gait instability and no home support"},{"id":"r2","text":"Client with poorly controlled diabetes and financial barriers to food"},{"id":"r3","text":"Client recovering from a stroke needing mobility retraining and swallow diet planning"}],"columns":[{"id":"c1","text":"Physical Therapy"},{"id":"c2","text":"Social Work"},{"id":"c3","text":"Dietitian"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c2","c3"],"r3":["c1","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary referrals', NULL, 'Medium', 'Apply', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_325023', 'CLOZE', 'After a client falls without injury, the nurse should first {1}, and the completed incident report should be {2}.', 'Client assessment comes first; the incident report is a confidential quality document kept out of the medical record.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"assess the client for injury"},{"id":"c2","text":"call the client''s family"},{"id":"c3","text":"complete the paperwork"}]},{"id":"b2","choices":[{"id":"c1","text":"kept separate from the medical record"},{"id":"c2","text":"filed inside the client''s chart"},{"id":"c3","text":"given to the client"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Incident reporting', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_325024', 'HIGHLIGHT', 'A charge nurse observes a colleague during medication administration. Highlight the findings that indicate an unsafe practice requiring intervention. The nurse [[checks the client''s armband against the MAR]], [[borrows another client''s insulin from the med drawer]], [[documents medications before they are given]], [[performs hand hygiene before preparing medications]], and [[leaves a controlled substance unattended at the bedside]].', 'Borrowing medications, pre-charting, and leaving controlled substances unattended are unsafe and require intervention.', '{"chunks":[{"id":"h1","text":"checks the client''s armband against the MAR"},{"id":"h2","text":"borrows another client''s insulin from the med drawer"},{"id":"h3","text":"documents medications before they are given"},{"id":"h4","text":"performs hand hygiene before preparing medications"},{"id":"h5","text":"leaves a controlled substance unattended at the bedside"}]}'::jsonb, '{"correct_ids":["h2","h3","h5"],"feedback":{"h1":"Correct verification step — safe practice.","h2":"Unsafe — medications must not be borrowed between clients.","h3":"Unsafe — pre-charting is falsification.","h4":"Appropriate infection-control step.","h5":"Unsafe — controlled substances must be secured."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Unsafe practice', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_325025', 'BOWTIE', 'A nurse identifies a client whose condition is deteriorating. Complete the diagram by selecting the priority concern, immediate actions, and outcomes to monitor.', 'Deterioration requires timely provider notification and closer monitoring, with vital-sign trends and mentation as key outcomes.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Notify the provider using SBAR"},{"id":"lt2","text":"Increase monitoring frequency"},{"id":"lt3","text":"Wait until the next scheduled round"},{"id":"lt4","text":"Document and reassess in the morning"}]},"centre":{"label":"Priority concern","tokens":[{"id":"ct1","text":"Client clinical deterioration"},{"id":"ct2","text":"Staffing shortage"},{"id":"ct3","text":"Supply restocking"}]},"right":{"label":"Outcomes to monitor","tokens":[{"id":"rt1","text":"Trend in vital signs"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Visitor satisfaction"},{"id":"rt4","text":"Cafeteria menu preferences"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Deteriorating client escalation', NULL, 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_325026', 'DRAG_CLOZE', 'When organizing the shift, the nurse should complete [1] first and defer [2] until higher-priority care is done.', 'Time-critical clinical care precedes non-urgent, low-priority tasks that can be delegated or delayed.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"an urgent medication due now"},{"id":"t2","text":"restocking the supply cart"},{"id":"t3","text":"updating the bulletin board"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Time management', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_325027', 'DRAG_ORDER', 'A nurse is admitting a new client to the medical unit. Place the nurse''s actions in the correct sequence.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Introduce self and verify client identity"},{"id":"t2","text":"Perform the admission assessment"},{"id":"t3","text":"Initiate the individualized plan of care"},{"id":"t4","text":"Orient the client to the room and call light"},{"id":"t5","text":"Reconcile the client''s home medications"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t4","s3":"t2","s4":"t5","s5":"t3"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Admission process', NULL, 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326001', 'MCQ', 'A nurse on a medical unit receives report on four clients at the start of the shift. Which client should the nurse assess FIRST?', 'Using the ABC framework, a client with a dropping oxygen saturation has the most unstable airway/breathing status and is seen first.', '{"options":[{"id":"A","text":"A client with pneumonia whose oxygen saturation dropped from 94% to 88% on room air"},{"id":"B","text":"A client with diabetes requesting a morning insulin dose"},{"id":"C","text":"A postoperative client whose pain is rated 6 of 10"},{"id":"D","text":"A client awaiting discharge teaching"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A falling saturation reflects an acute airway/breathing problem and takes priority.","B":"Incorrect. Scheduled insulin is important but not the most acutely unstable finding.","C":"Incorrect. Pain is a priority but does not outrank a deteriorating airway.","D":"Incorrect. A stable client awaiting discharge is the lowest acuity."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation by acuity', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326002', 'MCQ', 'A charge nurse is assigning tasks on a busy unit. Which task is MOST appropriate to delegate to a licensed practical nurse (LPN/LVN)?', 'LPNs may administer routine oral medications to stable clients, but assessment and care planning remain RN functions.', '{"options":[{"id":"A","text":"Administering a scheduled oral antibiotic to a stable client"},{"id":"B","text":"Developing the initial nursing plan of care for a new admission"},{"id":"C","text":"Performing the admission assessment on a newly admitted client"},{"id":"D","text":"Administering IV push medication through a central line"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A stable client''s routine oral medication is within LPN scope.","B":"Incorrect. Care planning for a new admission is the RN''s responsibility.","C":"Incorrect. Initial assessment cannot be delegated to the LPN.","D":"Incorrect. IV push medication is generally outside LPN scope in most facilities."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and supervision', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326003', 'MCQ', 'A nurse is giving an SBAR handoff to the oncoming shift. Which statement belongs in the ''Recommendation'' component?', 'In SBAR, Recommendation states what the nurse wants done next, including specific follow-up actions.', '{"options":[{"id":"A","text":"\"Please reassess the client''s blood pressure in one hour and hold the next dose if it is below 100 systolic.\""},{"id":"B","text":"\"The client was admitted yesterday with chest pain.\""},{"id":"C","text":"\"The client''s current blood pressure is 96/58.\""},{"id":"D","text":"\"I am calling about the client in room 4.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A specific action request for the next nurse is a recommendation.","B":"Incorrect. This is background information.","C":"Incorrect. This is the assessment/current situation.","D":"Incorrect. This is the situation identifier."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication (SBAR)', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326004', 'MCQ', 'A client scheduled for surgery tells the nurse, "I still don''t understand what the surgeon is going to remove." The consent form is already signed. What should the nurse do?', 'If a client does not understand the procedure, valid informed consent is absent and the provider must be notified to clarify.', '{"options":[{"id":"A","text":"Notify the surgeon that the client has questions before proceeding"},{"id":"B","text":"Explain the surgical procedure in detail to the client"},{"id":"C","text":"Reassure the client that the surgeon is highly skilled"},{"id":"D","text":"Witness that the signature is valid and send the client to surgery"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Informed consent requires understanding; the provider must clarify.","B":"Incorrect. Disclosure of the procedure is the surgeon''s duty, not the nurse''s.","C":"Incorrect. This does not resolve the lack of informed consent.","D":"Incorrect. A signature without understanding is not valid informed consent."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Informed consent', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326005', 'MCQ', 'A nurse overhears two colleagues discussing a celebrity client''s diagnosis in the cafeteria. Which action by the nurse is MOST appropriate?', 'Discussing identifiable client information in a public place breaches confidentiality regardless of staff authorization.', '{"options":[{"id":"A","text":"Remind the colleagues that discussing client information in a public area violates confidentiality"},{"id":"B","text":"Join the conversation to learn more about the case"},{"id":"C","text":"Ignore it because they are authorized staff members"},{"id":"D","text":"Report the colleagues to the media relations office"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Addressing the breach protects the client''s privacy rights.","B":"Incorrect. Participating extends the breach.","C":"Incorrect. Even authorized staff may not discuss clients in public areas.","D":"Incorrect. This is disproportionate and does not stop the immediate breach."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Confidentiality and privacy', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326006', 'MCQ', 'A client with a valid do-not-resuscitate (DNR) order becomes unresponsive and pulseless. The client''s adult child arrives and demands full resuscitation. What should the nurse do?', 'A valid DNR expresses the client''s autonomous wishes; the nurse honors it even if family members object.', '{"options":[{"id":"A","text":"Honor the DNR order and do not begin CPR"},{"id":"B","text":"Begin full CPR because the family member is present and objecting"},{"id":"C","text":"Call the ethics committee before deciding whether to act"},{"id":"D","text":"Ask the family member to sign a form revoking the DNR"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A valid DNR reflects the client''s own expressed wishes and is followed.","B":"Incorrect. Family objection does not override a valid advance directive.","C":"Incorrect. There is no time to convene ethics during an arrest with a valid DNR.","D":"Incorrect. The family member cannot revoke the competent client''s own directive."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326007', 'MCQ', 'A nurse receives a written order for "heparin 25,000 units subcutaneously every 8 hours." Which action should the nurse take?', 'A nurse who identifies an unsafe or erroneous order must withhold it and clarify with the prescriber before acting.', '{"options":[{"id":"A","text":"Hold the dose and clarify the order with the prescriber"},{"id":"B","text":"Administer the dose exactly as written"},{"id":"C","text":"Adjust the dose to a safe amount and administer it"},{"id":"D","text":"Document the order and give it at the next scheduled time"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The dose is far outside a safe range and must be verified before administration.","B":"Incorrect. Following an unsafe order does not meet the standard of care.","C":"Incorrect. The nurse cannot independently change a prescribed dose.","D":"Incorrect. Documenting without clarifying still risks a harmful dose."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Verifying and implementing orders', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326008', 'MCQ', 'A competent adult client with cancer decides to stop chemotherapy against the provider''s advice. The nurse''s role as a client advocate is BEST demonstrated by which action?', 'Advocacy means ensuring an informed decision and respecting a competent client''s right to refuse treatment.', '{"options":[{"id":"A","text":"Ensuring the client understands the consequences and supporting the client''s informed decision"},{"id":"B","text":"Persuading the client to continue treatment to preserve life"},{"id":"C","text":"Asking the family to convince the client to keep treatment"},{"id":"D","text":"Documenting the client as noncompliant and closing the discussion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Advocacy supports the client''s autonomous, informed choice.","B":"Incorrect. Coercion undermines client autonomy.","C":"Incorrect. This pressures the client and violates autonomy.","D":"Incorrect. This is judgmental and does not advocate for the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Client advocacy and rights', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326009', 'MCQ', 'A client with a new colostomy is being discharged home and expresses anxiety about managing the appliance alone. Which referral is MOST appropriate for the nurse to initiate?', 'Matching the referral to the client''s specific need — ostomy management support at home — provides effective continuity of care.', '{"options":[{"id":"A","text":"A home health nurse with wound/ostomy expertise"},{"id":"B","text":"A dietitian for a low-residue diet consult"},{"id":"C","text":"A physical therapist for mobility training"},{"id":"D","text":"A social worker for transportation assistance"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An ostomy-competent home health nurse directly supports appliance management at home.","B":"Incorrect. Nutrition help is useful but does not address appliance management anxiety.","C":"Incorrect. Mobility is not the client''s stated concern.","D":"Incorrect. Transportation is not the identified need."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Continuity of care / referrals', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326010', 'MCQ', 'Two nurses on a unit repeatedly disagree over the fairness of assignment distribution, and the tension is affecting teamwork. Which approach by the charge nurse is MOST effective?', 'Collaborative conflict resolution brings both parties together to address root causes and reach a shared solution.', '{"options":[{"id":"A","text":"Meet with both nurses together to identify concerns and reach a mutually acceptable solution"},{"id":"B","text":"Assign each nurse to opposite ends of the unit to avoid contact"},{"id":"C","text":"Tell both nurses to keep their opinions to themselves"},{"id":"D","text":"Side with the more senior nurse to settle the matter quickly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Collaboration addresses the underlying issue and preserves the working relationship.","B":"Incorrect. Avoidance does not resolve the underlying conflict.","C":"Incorrect. Suppression leaves the conflict unresolved.","D":"Incorrect. Forcing a win-lose outcome damages team trust."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Conflict management', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326011', 'MCQ', 'A nurse is transferring a stable client from the intensive care unit to a medical-surgical floor. Which action is essential to ensure safe continuity of care?', 'A nurse-to-nurse handoff with verbal and written information is essential for safe transfer between units.', '{"options":[{"id":"A","text":"Provide a complete verbal and written handoff report to the receiving nurse"},{"id":"B","text":"Send the client with the paper chart and let the receiving nurse read it"},{"id":"C","text":"Transfer the client and call the floor if any questions arise later"},{"id":"D","text":"Have the transport aide relay the client''s status to the receiving nurse"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A structured handoff prevents information loss during transfer.","B":"Incorrect. The chart alone does not substitute for an interactive handoff.","C":"Incorrect. Waiting for questions risks missed critical information.","D":"Incorrect. Clinical handoff must occur nurse to nurse."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Admission, transfer, and discharge', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_326012', 'MCQ', 'A nurse manager wants to reduce supply waste on the unit without compromising client safety. Which strategy BEST balances cost-effectiveness and quality care?', 'Cost-effective care reduces waste through efficient practices, never by compromising safety or evidence-based care.', '{"options":[{"id":"A","text":"Educate staff to gather only the supplies needed at the point of care"},{"id":"B","text":"Substitute non-sterile gloves for sterile procedures to save money"},{"id":"C","text":"Reuse single-use catheters after cleaning them"},{"id":"D","text":"Limit the number of dressing changes regardless of wound status"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Reducing unnecessary supply opening lowers waste while maintaining care.","B":"Incorrect. This compromises safety and infection control.","C":"Incorrect. Reusing single-use items violates safety standards.","D":"Incorrect. Withholding needed care to save cost harms clients."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Cost-effective care', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_326013', 'SATA', 'A nurse is deciding which tasks may be delegated to unlicensed assistive personnel (UAP). Which tasks are appropriate to delegate? Select all that apply.', 'UAP may perform stable activities of daily living, routine vital signs, and intake/output recording, but not assessment, evaluation, or care planning.', '{"options":[{"id":"A","text":"Assisting a stable client to ambulate in the hallway"},{"id":"B","text":"Recording a client''s oral intake and urine output"},{"id":"C","text":"Obtaining a routine set of vital signs on a stable client"},{"id":"D","text":"Evaluating whether a client understood discharge teaching"},{"id":"E","text":"Evaluating a client''s response to a new pain medication"},{"id":"F","text":"Developing the client''s plan of care"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation to UAP', NULL, 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_326014', 'SATA', 'A nurse is reviewing situations that require mandatory reporting to authorities. Which situations must the nurse report? Select all that apply.', 'Suspected abuse or neglect of vulnerable persons, certain communicable diseases, and violent injuries are legally reportable; a competent adult''s autonomous refusal is not.', '{"options":[{"id":"A","text":"Suspected physical abuse of a 4-year-old child"},{"id":"B","text":"A newly confirmed case of active tuberculosis"},{"id":"C","text":"Suspected neglect of a dependent older adult"},{"id":"D","text":"A gunshot wound in an adult client"},{"id":"E","text":"A competent adult''s decision to refuse a blood transfusion"},{"id":"F","text":"A client''s request to change primary care providers"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Mandatory reporting', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_326015', 'SATA', 'A unit council is planning a quality/performance improvement (QI) initiative to reduce catheter-associated urinary tract infections. Which actions reflect sound QI practice? Select all that apply.', 'QI is a systematic, data-driven, evidence-based process focused on improving systems, not on blaming individuals.', '{"options":[{"id":"A","text":"Collect baseline data on current infection rates"},{"id":"B","text":"Implement an evidence-based catheter removal protocol"},{"id":"C","text":"Measure outcomes after the change and compare to baseline"},{"id":"D","text":"Identify and discipline individual nurses whose clients develop infections"},{"id":"E","text":"Base the initiative on staff opinion rather than reviewing evidence"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Quality and performance improvement', NULL, 'Medium', 'Understand', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_326016', 'SATA', 'A newly graduated RN is clarifying which actions fall within the RN scope of practice. Which actions are within RN scope? Select all that apply.', 'Assessment, care planning, and client teaching are within RN scope; prescribing and medical diagnosis are provider functions.', '{"options":[{"id":"A","text":"Performing an initial head-to-toe assessment on a new admission"},{"id":"B","text":"Formulating and revising the nursing plan of care"},{"id":"C","text":"Providing client teaching about a new diagnosis"},{"id":"D","text":"Independently prescribing an antibiotic for an infection"},{"id":"E","text":"Independently establishing a medical diagnosis"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Legal scope of practice', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_326017', 'SATA', 'A nurse is coordinating care for a client recovering from a stroke with dysphagia and impaired mobility. Which referrals reflect appropriate interdisciplinary collaboration? Select all that apply.', 'Effective care coordination draws on the appropriate members of the interdisciplinary team to meet the client''s specific deficits.', '{"options":[{"id":"A","text":"Speech-language pathologist for a swallow evaluation"},{"id":"B","text":"Physical therapist for mobility and gait training"},{"id":"C","text":"Occupational therapist for activities of daily living retraining"},{"id":"D","text":"Dietitian for a modified-texture diet plan"},{"id":"E","text":"No referrals; the nurse should manage all rehabilitation alone"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Multidisciplinary collaboration', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_326018', 'TF', 'When an RN delegates a task to unlicensed assistive personnel, the RN transfers all accountability for the outcome of that task to the UAP.', 'The RN who delegates retains accountability for the overall outcome and for appropriate delegation and supervision; the UAP is responsible only for performing the delegated task correctly.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation accountability', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_326019', 'TF', 'A competent client may revoke a previously signed advance directive at any time, either verbally or in writing.', 'Advance directives reflect client autonomy and can be revoked by a competent client at any time through verbal or written means.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Advance directives', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_326020', 'SELECT_N', 'A nurse is managing time at the start of a shift with several pending tasks. Which 3 clients should the nurse prioritize seeing before the others?', 'Unstable or time-sensitive findings — chest pain, a due anticoagulation lab, and signs of a surgical complication — take priority over comfort and non-urgent requests.', '{"options":[{"id":"A","text":"A client reporting new, crushing substernal chest pain"},{"id":"B","text":"A client with a heparin drip whose scheduled aPTT is due to be drawn now"},{"id":"C","text":"A postoperative client with a rigid, distended abdomen and rising heart rate"},{"id":"D","text":"A client requesting fresh drinking water"},{"id":"E","text":"A client asking when breakfast trays will arrive"},{"id":"F","text":"A stable client wanting to review discharge paperwork later today"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Prioritisation', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_326021', 'MATRIX', 'For each task, click to indicate whether it may be delegated to a licensed practical nurse (LPN/LVN) or must be performed by the registered nurse (RN).', 'LPNs may give routine oral medications and reinforce teaching for stable clients, but initial assessment, care planning, and evaluating first-dose reactions remain RN functions.', '{"row_label":"Task","rows":[{"id":"r1","text":"Administering a scheduled oral medication to a stable client"},{"id":"r2","text":"Reinforcing previously taught wound care"},{"id":"r3","text":"Performing the initial admission assessment"},{"id":"r4","text":"Developing the client''s plan of care"},{"id":"r5","text":"Administering the first dose of a new IV antibiotic and monitoring for reaction"}],"columns":[{"id":"c1","text":"May delegate to LPN"},{"id":"c2","text":"Must be done by RN"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c2","r5":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Scope of practice / delegation', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_326022', 'MATRIX_MR', 'For each task, select all care team members to whom the RN may appropriately assign or delegate it.', 'Routine vitals and ADLs may go to UAP; LPNs add stable-client medication administration; initial assessment stays with the RN.', '{"row_label":"Team member","rows":[{"id":"r1","text":"Obtaining routine vital signs on a stable client"},{"id":"r2","text":"Administering a scheduled oral medication to a stable client"},{"id":"r3","text":"Performing the initial nursing assessment of a new admission"},{"id":"r4","text":"Assisting a stable client with bathing and repositioning"}],"columns":[{"id":"c1","text":"LPN/LVN"},{"id":"c2","text":"UAP"},{"id":"c3","text":"RN only"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1"],"r3":["c3"],"r4":["c2"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Delegation and supervision', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_326023', 'CLOZE', 'When a nurse uses SBAR to call a provider about a deteriorating client, the concise statement of the current problem belongs in the {1} component, while the nurse''s request for a specific action belongs in the {2} component.', 'In SBAR, Situation states the current problem and Recommendation states the specific action the nurse is requesting.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"Situation"},{"id":"c2","text":"Background"},{"id":"c3","text":"Assessment"}]},{"id":"b2","choices":[{"id":"c1","text":"Recommendation"},{"id":"c2","text":"Background"},{"id":"c3","text":"Situation"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff communication (SBAR)', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_326024', 'HIGHLIGHT', 'Highlight each entry in the nurse''s note that is documented inappropriately and should be revised. Nursing note: [[Client appears to be faking pain]] to get more medication. [[Client rates pain 8 of 10]] in the right hip. [[The client is a difficult, demanding person]]. [[Repositioned client and offered prescribed analgesic]]. [[Physician was negligent in not ordering imaging sooner]].', 'Documentation must be objective and factual; judgmental labels and accusations of negligence are inappropriate entries.', '{"chunks":[{"id":"h1","text":"Client appears to be faking pain"},{"id":"h2","text":"Client rates pain 8 of 10"},{"id":"h3","text":"The client is a difficult, demanding person"},{"id":"h4","text":"Repositioned client and offered prescribed analgesic"},{"id":"h5","text":"Physician was negligent in not ordering imaging sooner"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"Subjective and judgmental — not objective documentation.","h2":"Appropriate — records the client''s own report objectively.","h3":"Labeling and judgmental — inappropriate for a legal record.","h4":"Appropriate — factual description of nursing actions.","h5":"An accusatory conclusion — inappropriate in the medical record."}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Documentation terminology', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_326025', 'BOWTIE', 'A nurse identifies that an older adult client is unsafe to return home alone after hospitalization. Complete the diagram by selecting the priority issue, the actions to take, and the outcomes to evaluate.', 'An unsafe discharge is addressed through case management and home safety planning, evaluated by a supported plan and arranged community resources.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Initiate a case management / social work referral"},{"id":"lt2","text":"Arrange a home safety evaluation before discharge"},{"id":"lt3","text":"Discharge the client home immediately as planned"},{"id":"lt4","text":"Cancel all outpatient follow-up appointments"}]},"centre":{"label":"Priority issue","tokens":[{"id":"ct1","text":"Unsafe discharge disposition"},{"id":"ct2","text":"Acute respiratory failure"},{"id":"ct3","text":"Uncontrolled hemorrhage"}]},"right":{"label":"Outcomes to evaluate","tokens":[{"id":"rt1","text":"Client has a safe, supported discharge plan in place"},{"id":"rt2","text":"Appropriate community resources are arranged"},{"id":"rt3","text":"Client''s serum potassium is normalized"},{"id":"rt4","text":"Client''s surgical incision has healed"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Care coordination', NULL, 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_326026', 'DRAG_CLOZE', 'Before delegating a task, the nurse confirms the right task, the right circumstance, the [1] person, and provides the right [2] and supervision.', 'The five rights of delegation are the right task, right circumstance, right person, right direction/communication, and right supervision.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"right"},{"id":"t2","text":"direction/communication"},{"id":"t3","text":"prescription"},{"id":"t4","text":"diagnosis"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Five rights of delegation', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_326027', 'DRAG_ORDER', 'A nurse discovers a medication error was made on the previous shift. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Assess the client for adverse effects of the error"},{"id":"t2","text":"Notify the prescriber of the medication error"},{"id":"t3","text":"Implement any new orders to protect the client"},{"id":"t4","text":"Complete an incident/occurrence report"},{"id":"t5","text":"Document the client''s status objectively in the record"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Management of Care', 'Leadership and Management', 'Multisystem', 'Handoff / order of actions', NULL, 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336001', 'MCQ', 'A client on a continuous IV heparin infusion has an aPTT of 96 seconds (control 30 seconds; therapeutic 46-70 seconds). Which action should the nurse take?', 'An aPTT well above the therapeutic range signals over-anticoagulation; the infusion is held and the provider notified.', '{"options":[{"id":"A","text":"Stop the infusion and notify the provider"},{"id":"B","text":"Continue the infusion at the current rate"},{"id":"C","text":"Increase the infusion rate"},{"id":"D","text":"Administer protamine sulfate without an order"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The aPTT is above therapeutic range, indicating over-anticoagulation and bleeding risk.","B":"Incorrect. The value is supratherapeutic and unsafe to continue.","C":"Incorrect. Increasing the rate would worsen the bleeding risk.","D":"Incorrect. Protamine requires a provider order and is reserved for significant bleeding."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Anticoagulants', 'Heparin monitoring', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336002', 'MCQ', 'A nurse administers regular insulin subcutaneously at 0700. At which time is the client at greatest risk for hypoglycemia?', 'Regular insulin peaks 2-4 hours after a subcutaneous dose, when hypoglycemia risk is greatest.', '{"options":[{"id":"A","text":"0730"},{"id":"B","text":"0900-1100"},{"id":"C","text":"1500"},{"id":"D","text":"1900"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Regular insulin has not yet peaked at 30 minutes.","B":"Correct. Regular insulin peaks about 2-4 hours after administration.","C":"Incorrect. This is beyond the peak and near the end of its duration.","D":"Incorrect. Regular insulin''s action is over well before this time."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Peak action', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336003', 'MCQ', 'A client is receiving IV vancomycin. The provider orders a trough level. When should the nurse draw the blood sample?', 'A trough is drawn immediately before the next dose to guide safe vancomycin dosing and avoid nephrotoxicity.', '{"options":[{"id":"A","text":"30 minutes before the next scheduled dose"},{"id":"B","text":"30 minutes after the infusion finishes"},{"id":"C","text":"In the middle of the infusion"},{"id":"D","text":"Any time convenient during the shift"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A trough is drawn just before the next dose to assess the lowest concentration.","B":"Incorrect. That would approximate a peak, not a trough.","C":"Incorrect. Mid-infusion does not reflect a trough level.","D":"Incorrect. Trough timing must be tied to the dosing schedule."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Antibiotics', 'Vancomycin trough', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336004', 'MCQ', 'Fifteen minutes into a packed red blood cell transfusion, a client develops fever, chills, and flank pain. Which action should the nurse take FIRST?', 'Fever, chills, and flank pain suggest an acute hemolytic reaction; stopping the transfusion is the first priority.', '{"options":[{"id":"A","text":"Stop the transfusion"},{"id":"B","text":"Slow the transfusion rate"},{"id":"C","text":"Administer acetaminophen"},{"id":"D","text":"Notify the blood bank"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stopping the transfusion immediately halts exposure to the incompatible blood.","B":"Incorrect. Slowing continues exposure to a potentially incompatible product.","C":"Incorrect. Medication is given after the transfusion is stopped and assessed.","D":"Incorrect. This follows stopping the transfusion and maintaining IV access with saline."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood products', 'Transfusion reaction', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336005', 'MCQ', 'A provider orders 1,000 mL of 0.9% sodium chloride to infuse over 8 hours using tubing with a drop factor of 15 gtt/mL. What flow rate should the nurse set?', '1000 mL over 480 minutes is 2.08 mL/min; multiplied by 15 gtt/mL gives about 31 gtt/min.', '{"options":[{"id":"A","text":"31 gtt/min"},{"id":"B","text":"21 gtt/min"},{"id":"C","text":"42 gtt/min"},{"id":"D","text":"125 gtt/min"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. (1000 mL / 480 min) x 15 gtt/mL = 31 gtt/min.","B":"Incorrect. This reflects a 10 gtt/mL drop factor.","C":"Incorrect. This roughly doubles the correct rate.","D":"Incorrect. This is the mL/hr rate, not gtt/min."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Dosage calculation', 'IV flow rate', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336006', 'MCQ', 'A postoperative client receiving IV morphine has a respiratory rate of 7 breaths/min and is difficult to arouse. Which medication should the nurse anticipate administering?', 'Naloxone is the opioid antagonist used to reverse morphine-induced respiratory depression.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Flumazenil"},{"id":"C","text":"Protamine sulfate"},{"id":"D","text":"Vitamin K"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone reverses opioid-induced respiratory depression.","B":"Incorrect. Flumazenil reverses benzodiazepines, not opioids.","C":"Incorrect. Protamine reverses heparin.","D":"Incorrect. Vitamin K reverses warfarin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Opioids', 'Respiratory depression', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336007', 'MCQ', 'A client receiving total parenteral nutrition (TPN) suddenly becomes shaky, diaphoretic, and confused shortly after the infusion is inadvertently stopped. What is the most likely cause?', 'Sudden interruption of high-dextrose TPN can trigger rebound hypoglycemia; the rate is tapered to prevent this.', '{"options":[{"id":"A","text":"Rebound hypoglycemia"},{"id":"B","text":"Hyperkalemia"},{"id":"C","text":"Air embolism"},{"id":"D","text":"Fluid volume overload"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Abrupt TPN cessation can cause rebound hypoglycemia from continued insulin response.","B":"Incorrect. These symptoms are not characteristic of hyperkalemia.","C":"Incorrect. Air embolism causes sudden dyspnea and chest pain, not this pattern.","D":"Incorrect. Overload presents with dyspnea and edema, not hypoglycemic symptoms."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'TPN', 'Complications', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336008', 'MCQ', 'A nurse reviews new prescriptions for a client with a potassium level of 5.6 mEq/L. Which newly ordered medication should the nurse question?', 'ACE inhibitors reduce potassium excretion; starting one during hyperkalemia should be questioned.', '{"options":[{"id":"A","text":"Lisinopril"},{"id":"B","text":"Metoprolol"},{"id":"C","text":"Amlodipine"},{"id":"D","text":"Hydralazine"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. ACE inhibitors raise potassium and are questionable with existing hyperkalemia.","B":"Incorrect. Beta blockers do not significantly raise potassium in this context.","C":"Incorrect. Calcium channel blockers do not raise potassium.","D":"Incorrect. Hydralazine does not affect potassium levels."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'ACE inhibitors', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336009', 'MCQ', 'A client has a potassium level of 2.8 mEq/L and an order for IV potassium chloride replacement. Which action by the nurse is essential?', 'IV potassium is always diluted and infused slowly via pump; IV push is lethal.', '{"options":[{"id":"A","text":"Administer via an infusion pump at the prescribed rate"},{"id":"B","text":"Give the potassium by IV push"},{"id":"C","text":"Add it to a hanging bag of blood"},{"id":"D","text":"Infuse rapidly to correct the deficit quickly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. IV potassium must be diluted and given by pump at a controlled rate to prevent fatal arrhythmia.","B":"Incorrect. IV push potassium is never given and can cause cardiac arrest.","C":"Incorrect. Medications are never added to blood products.","D":"Incorrect. Rapid potassium infusion is dangerous."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Electrolytes', 'IV potassium', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336010', 'MCQ', 'A client taking lithium reports new vomiting, coarse hand tremor, and slurred speech. The lithium level is 2.1 mEq/L. Which is the nurse''s priority interpretation?', 'A lithium level of 2.1 mEq/L with GI and neuromuscular symptoms indicates toxicity requiring the drug be held.', '{"options":[{"id":"A","text":"The client is showing signs of lithium toxicity"},{"id":"B","text":"The findings are expected therapeutic effects"},{"id":"C","text":"The client needs an increased lithium dose"},{"id":"D","text":"The symptoms indicate a hypoglycemic reaction"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A level above 1.5 mEq/L with these symptoms indicates toxicity.","B":"Incorrect. These are not normal therapeutic effects.","C":"Incorrect. The level is already supratherapeutic.","D":"Incorrect. These are classic lithium toxicity signs, not hypoglycemia."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Psychiatric/Mental Health', 'Psychotropics', 'Lithium', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_336011', 'MCQ', 'Shortly after the first dose of IV penicillin, a client develops stridor, hypotension, and generalized hives. After stopping the drug, which medication should the nurse anticipate administering first?', 'Anaphylaxis is treated first with epinephrine; antihistamines and steroids are adjuncts.', '{"options":[{"id":"A","text":"Epinephrine"},{"id":"B","text":"Diphenhydramine"},{"id":"C","text":"Hydrocortisone"},{"id":"D","text":"Albuterol"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Epinephrine is the first-line drug for anaphylaxis.","B":"Incorrect. Antihistamines are adjuncts given after epinephrine.","C":"Incorrect. Corticosteroids are secondary and delayed in action.","D":"Incorrect. A bronchodilator does not address the systemic reaction first."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Anaphylaxis', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_336012', 'SATA', 'A nurse provides discharge teaching to a client newly prescribed warfarin. Which statements by the client indicate correct understanding? Select all that apply.', 'Consistent vitamin K intake, bleeding precautions, reporting bleeding, and INR monitoring reflect safe warfarin use; adding aspirin or doubling doses increases bleeding risk.', '{"options":[{"id":"A","text":"I will keep my green leafy vegetable intake consistent from week to week"},{"id":"B","text":"I will use a soft toothbrush and an electric razor"},{"id":"C","text":"I will report black, tarry stools to my provider"},{"id":"D","text":"I will take an aspirin daily for extra protection"},{"id":"E","text":"I will have my INR checked regularly"},{"id":"F","text":"I will double the dose if I miss a day"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Anticoagulants', 'Warfarin teaching', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_336013', 'SATA', 'Before administering a medication, which actions are part of the nurse''s safe medication administration process? Select all that apply.', 'Identity verification, triple-checking, allergy assessment, and lab review support safe administration; charting before giving and leaving meds unobserved are unsafe.', '{"options":[{"id":"A","text":"Verify the client''s identity using two identifiers"},{"id":"B","text":"Check the medication against the order three times"},{"id":"C","text":"Assess for known allergies to the drug"},{"id":"D","text":"Document the medication before it is actually given"},{"id":"E","text":"Review relevant lab values and contraindications"},{"id":"F","text":"Leave the medication at the bedside for the client to take later"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Pre-administration review', 'Rights of administration', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_336014', 'SATA', 'A nurse prepares to draw up NPH and regular insulin in one syringe. Which actions are correct? Select all that apply.', 'Air is injected into the cloudy vial first, but clear insulin is withdrawn before cloudy to avoid contaminating the short-acting vial; NPH is rolled, not shaken.', '{"options":[{"id":"A","text":"Inject air into the NPH vial first"},{"id":"B","text":"Draw up the regular (clear) insulin before the NPH (cloudy) insulin"},{"id":"C","text":"Gently roll the NPH vial to mix it"},{"id":"D","text":"Draw up the NPH insulin first, then the regular insulin"},{"id":"E","text":"Shake the NPH vial vigorously to disperse it"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Administration technique', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_336015', 'SATA', 'A nurse cares for a client with a central venous access device. Which actions reduce the risk of central-line complications? Select all that apply.', 'Sterile technique, hub disinfection, Valsalva during tubing changes to prevent air embolism, and site assessment all reduce CVAD complications; dressings are changed on schedule.', '{"options":[{"id":"A","text":"Use sterile technique when accessing the line"},{"id":"B","text":"Scrub the hub before each access"},{"id":"C","text":"Have the client perform the Valsalva maneuver during tubing changes"},{"id":"D","text":"Leave the dressing in place indefinitely to avoid disturbing the site"},{"id":"E","text":"Assess the insertion site for redness and drainage"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Central venous access', 'CVAD care', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_336016', 'SATA', 'A client is receiving furosemide. Which findings should the nurse monitor as potential adverse effects? Select all that apply.', 'Loop diuretics cause potassium loss, volume depletion with orthostatic changes, dehydration, and ototoxicity with rapid IV push.', '{"options":[{"id":"A","text":"Hypokalemia"},{"id":"B","text":"Orthostatic hypotension"},{"id":"C","text":"Ototoxicity with rapid IV administration"},{"id":"D","text":"Hyperkalemia"},{"id":"E","text":"Dehydration"},{"id":"F","text":"Fluid volume overload"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Furosemide monitoring', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_336017', 'SELECT_N', 'A nurse assesses a peripheral IV site. Which 2 findings indicate infiltration rather than phlebitis?', 'Infiltration produces cool, swollen, taut tissue and impaired flow; warmth, redness, and a cord suggest phlebitis.', '{"options":[{"id":"A","text":"Cool, swollen, taut skin around the site"},{"id":"B","text":"Slowed or stopped infusion flow"},{"id":"C","text":"Warmth and redness along the vein"},{"id":"D","text":"A palpable venous cord"},{"id":"E","text":"Purulent drainage at the site"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IV site care', 'Infiltration', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_336018', 'TF', 'A nurse should administer a scheduled dose of digoxin to an adult client whose apical heart rate is 52 beats per minute.', 'Digoxin is withheld when the apical pulse is below 60 beats/min in an adult because of the risk of further bradycardia and toxicity.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'High-risk medications', 'Digoxin', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_336019', 'MATRIX', 'For each reversal agent, click to indicate the drug or overdose it counteracts.', 'Protamine reverses heparin, vitamin K and FFP reverse warfarin, and naloxone reverses opioids.', '{"row_label":"Antidote","rows":[{"id":"r1","text":"Protamine sulfate"},{"id":"r2","text":"Vitamin K (phytonadione)"},{"id":"r3","text":"Naloxone"},{"id":"r4","text":"Fresh frozen plasma"}],"columns":[{"id":"c1","text":"Heparin"},{"id":"c2","text":"Warfarin"},{"id":"c3","text":"Opioid"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medications', 'Reversal agents', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_336020', 'MATRIX_MR', 'For each medication, select all correct teaching points that apply.', 'Levothyroxine is taken on an empty stomach; warfarin requires INR monitoring; metformin is taken with food to reduce GI upset; prednisone is taken with food and requires glucose monitoring.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Levothyroxine"},{"id":"r2","text":"Warfarin"},{"id":"r3","text":"Metformin"},{"id":"r4","text":"Prednisone"}],"columns":[{"id":"c1","text":"Take with food"},{"id":"c2","text":"Monitor a lab value"},{"id":"c3","text":"Take on an empty stomach"}]}'::jsonb, '{"cells":{"r1":["c3"],"r2":["c2"],"r3":["c1"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication education', 'Timing and food', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_336021', 'CLOZE', 'A client on an insulin drip has a blood glucose of 54 mg/dL and is alert. The nurse should first give {1}, then recheck the glucose in {2}.', 'For a conscious hypoglycemic client, 15 g of oral carbohydrate is given and glucose rechecked in 15 minutes (the rule of 15).', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"15 g of a fast-acting oral carbohydrate"},{"id":"c2","text":"a subcutaneous dose of glucagon"},{"id":"c3","text":"the next scheduled insulin dose"}]},{"id":"b2","choices":[{"id":"c1","text":"15 minutes"},{"id":"c2","text":"2 hours"},{"id":"c3","text":"8 hours"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Hypoglycemia response', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_336022', 'HIGHLIGHT', 'A client has been receiving IV gentamicin for 6 days. Highlight the findings that indicate a serious adverse drug effect. The client reports [[new ringing in the ears]]. Appetite is [[normal]]. Urine output has dropped to [[18 mL/hr]]. Serum creatinine is [[2.4 mg/dL]]. Temperature is [[37.1°C]].', 'Aminoglycosides such as gentamicin cause ototoxicity (tinnitus) and nephrotoxicity (oliguria, rising creatinine).', '{"chunks":[{"id":"h1","text":"new ringing in the ears"},{"id":"h2","text":"normal"},{"id":"h3","text":"18 mL/hr"},{"id":"h4","text":"2.4 mg/dL"},{"id":"h5","text":"37.1°C"}]}'::jsonb, '{"correct_ids":["h1","h3","h4"],"feedback":{"h1":"Tinnitus signals aminoglycoside ototoxicity.","h2":"A normal appetite is not an adverse effect.","h3":"Oliguria suggests nephrotoxicity.","h4":"A rising creatinine indicates renal injury.","h5":"This temperature is within normal limits."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Aminoglycosides', 'Adverse effects', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_336023', 'BOWTIE', 'A client is found somnolent with a respiratory rate of 6 after receiving IV hydromorphone. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Opioid-induced respiratory depression is managed with naloxone and ventilatory support while monitoring respiratory rate and level of consciousness.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer naloxone as prescribed"},{"id":"lt2","text":"Provide supplemental oxygen and support ventilation"},{"id":"lt3","text":"Administer the next opioid dose"},{"id":"lt4","text":"Place the client flat and restrict stimulation"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Opioid-induced respiratory depression"},{"id":"ct2","text":"Hypoglycemia"},{"id":"ct3","text":"Anaphylaxis"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Respiratory rate"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Overdose management', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_336024', 'DRAG_ORDER', 'A nurse is preparing to administer a unit of packed red blood cells. Place the steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Verify the prescription and confirm informed consent"},{"id":"t2","text":"Obtain baseline vital signs"},{"id":"t3","text":"Verify the blood product with a second nurse at the bedside"},{"id":"t4","text":"Begin the transfusion slowly and stay with the client for the first 15 minutes"},{"id":"t5","text":"Monitor vital signs and adjust the rate per protocol"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood products', 'Transfusion administration', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337001', 'MCQ', 'A client on a continuous IV heparin infusion has an aPTT result of 96 seconds (control 30 seconds; therapeutic 46-70 seconds). Which action should the nurse take?', 'An aPTT above the therapeutic range reflects excessive heparin effect; the nurse holds the infusion and notifies the provider, anticipating protamine if bleeding occurs.', '{"options":[{"id":"A","text":"Stop the infusion and notify the provider"},{"id":"B","text":"Increase the infusion rate as ordered"},{"id":"C","text":"Administer vitamin K"},{"id":"D","text":"Continue the infusion and recheck in 24 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An aPTT well above the therapeutic range signals over-anticoagulation and bleeding risk; the infusion is held per protocol.","B":"Incorrect. The value is supratherapeutic; increasing worsens bleeding risk.","C":"Incorrect. Vitamin K reverses warfarin, not heparin.","D":"Incorrect. A supratherapeutic aPTT requires prompt action."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin monitoring', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337002', 'MCQ', 'A client receives regular insulin subcutaneously at 0700. At which time should the nurse be most alert for signs of hypoglycemia?', 'Regular (short-acting) insulin peaks approximately 2-3 hours post-dose, the window of greatest hypoglycemia risk.', '{"options":[{"id":"A","text":"0715"},{"id":"B","text":"0930"},{"id":"C","text":"1500"},{"id":"D","text":"1900"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Regular insulin has not yet peaked at 15 minutes.","B":"Correct. Regular insulin peaks about 2-3 hours after subcutaneous administration.","C":"Incorrect. This is beyond regular insulin''s peak.","D":"Incorrect. This reflects a long-acting insulin, not regular."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Onset and peak', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337003', 'MCQ', 'A nurse teaches a client newly prescribed furosemide. Which client statement indicates the teaching was effective?', 'Loop diuretics cause potassium loss; increasing dietary potassium counters hypokalemia.', '{"options":[{"id":"A","text":"\"I will eat more bananas and oranges.\""},{"id":"B","text":"\"I will take the dose right before bedtime.\""},{"id":"C","text":"\"I should limit fluids to avoid dehydration.\""},{"id":"D","text":"\"I will use a salt substitute freely.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Furosemide wastes potassium, so potassium-rich foods help prevent hypokalemia.","B":"Incorrect. Dosing is best in the morning to avoid nocturia.","C":"Incorrect. Fluid intake is individualized; blanket restriction is not standard teaching.","D":"Incorrect. Salt substitutes contain potassium and can be risky depending on the regimen."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Loop diuretic teaching', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337004', 'MCQ', 'One hour after receiving IV morphine, a postoperative client has a respiratory rate of 7 breaths/min and is difficult to arouse. After ensuring airway and oxygenation, which medication should the nurse anticipate administering?', 'Opioid-induced respiratory depression is reversed with naloxone, the specific opioid antagonist.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Flumazenil"},{"id":"C","text":"Acetylcysteine"},{"id":"D","text":"Protamine sulfate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone is the opioid antagonist that reverses respiratory depression.","B":"Incorrect. Flumazenil reverses benzodiazepines, not opioids.","C":"Incorrect. Acetylcysteine is the antidote for acetaminophen toxicity.","D":"Incorrect. Protamine reverses heparin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Opioids', 'Respiratory depression', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337005', 'MCQ', 'Fifteen minutes into a packed red blood cell transfusion, a client reports low back pain, chills, and has a temperature rise from 37.0°C to 38.6°C. Which action should the nurse take FIRST?', 'Signs of an acute hemolytic reaction require immediate cessation of the transfusion with saline to maintain the line, then provider and blood bank notification.', '{"options":[{"id":"A","text":"Stop the transfusion and keep the IV line open with normal saline"},{"id":"B","text":"Slow the transfusion rate and continue monitoring"},{"id":"C","text":"Administer acetaminophen and continue the transfusion"},{"id":"D","text":"Notify the blood bank before stopping the infusion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stopping the transfusion immediately halts further exposure while maintaining IV access.","B":"Incorrect. A suspected reaction requires stopping, not slowing, the transfusion.","C":"Incorrect. The transfusion must be stopped before any treatment.","D":"Incorrect. Stopping the transfusion precedes notification."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Blood products', 'Transfusion reaction', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337006', 'MCQ', 'A provider orders 1,000 mL of 0.9% sodium chloride to infuse over 8 hours using tubing with a drop factor of 15 gtt/mL. What flow rate in drops per minute should the nurse set (rounded to the nearest whole number)?', 'gtt/min = (volume x drop factor) / total minutes = (1000 x 15) / 480 = 31 gtt/min.', '{"options":[{"id":"A","text":"31 gtt/min"},{"id":"B","text":"21 gtt/min"},{"id":"C","text":"42 gtt/min"},{"id":"D","text":"63 gtt/min"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. (1000 mL x 15 gtt/mL) / (8 x 60 min) = 31.25, rounded to 31 gtt/min.","B":"Incorrect. This underestimates the required rate.","C":"Incorrect. This overestimates the required rate.","D":"Incorrect. This doubles the correct rate."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Dosage calculation', 'IV flow rate', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337007', 'MCQ', 'A client started on lisinopril calls the clinic. Which reported symptom requires the nurse to advise the client to seek immediate evaluation?', 'Angioedema (facial, lip, or tongue swelling) is a life-threatening ACE inhibitor reaction requiring immediate intervention.', '{"options":[{"id":"A","text":"Swelling of the lips and tongue"},{"id":"B","text":"A persistent dry cough"},{"id":"C","text":"Mild dizziness when standing quickly"},{"id":"D","text":"A metallic taste in the mouth"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Angioedema is a potentially life-threatening ACE inhibitor reaction requiring emergency care.","B":"Incorrect. A dry cough is a common, non-emergent ACE inhibitor effect.","C":"Incorrect. Orthostatic dizziness is managed with position changes, not emergency care.","D":"Incorrect. Taste changes are bothersome but not emergent."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'ACE inhibitor teaching', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337008', 'MCQ', 'A client receiving IV vancomycin has a serum trough level of 25 mcg/mL (therapeutic 10-20 mcg/mL) and a rising creatinine. Which action is the nurse''s priority?', 'A vancomycin trough above range with rising creatinine indicates nephrotoxicity risk; the nurse holds the dose and notifies the provider.', '{"options":[{"id":"A","text":"Hold the next dose and notify the provider"},{"id":"B","text":"Administer the next dose over a longer time"},{"id":"C","text":"Encourage the client to increase fluid intake only"},{"id":"D","text":"Draw a peak level immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A supratherapeutic trough with rising creatinine signals nephrotoxicity; the dose is held pending provider guidance.","B":"Incorrect. Slowing infusion addresses red-man syndrome, not an elevated trough.","C":"Incorrect. Hydration alone does not address a toxic level.","D":"Incorrect. The elevated trough already indicates the priority is to hold and notify."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Antibiotics', 'Vancomycin trough', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337009', 'MCQ', 'A client is receiving total parenteral nutrition (TPN) through a central line. The nurse notes the current bag is empty and the next bag is unavailable from pharmacy. Which action is most appropriate?', 'TPN delivers high dextrose; an interruption requires a dextrose-containing solution to prevent rebound hypoglycemia until TPN resumes.', '{"options":[{"id":"A","text":"Hang 10% dextrose in water until the next TPN bag arrives"},{"id":"B","text":"Stop the infusion and flush the line with saline"},{"id":"C","text":"Slow the empty bag''s tubing to a keep-vein-open rate"},{"id":"D","text":"Infuse a bag of 0.9% sodium chloride"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Abrupt TPN cessation risks rebound hypoglycemia; a dextrose solution maintains glucose.","B":"Incorrect. Abruptly stopping TPN can cause rebound hypoglycemia.","C":"Incorrect. An empty bag delivers no glucose.","D":"Incorrect. Saline provides no dextrose to prevent hypoglycemia."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'TPN', 'Complication recognition', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337010', 'MCQ', 'A client with rheumatoid arthritis is prescribed weekly oral methotrexate. Which client statement indicates a need for further teaching?', 'Oral methotrexate for rheumatoid arthritis is a once-weekly dose; daily administration leads to fatal toxicity, so this statement needs correction.', '{"options":[{"id":"A","text":"\"I will take this medication every day for the best effect.\""},{"id":"B","text":"\"I will take folic acid as prescribed.\""},{"id":"C","text":"\"I will avoid alcohol while on this drug.\""},{"id":"D","text":"\"I will report a sore throat or fever.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Methotrexate for RA is dosed weekly; daily dosing causes severe toxicity and requires correction.","B":"Incorrect. Folic acid reduces methotrexate side effects.","C":"Incorrect. Avoiding alcohol lowers hepatotoxicity risk.","D":"Incorrect. These may signal bone marrow suppression and should be reported."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Musculoskeletal', 'High-risk medications', 'Methotrexate teaching', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_337011', 'MCQ', 'While changing the cap on a client''s central venous catheter, the nurse observes the client suddenly develop dyspnea, chest pain, and anxiety. Which position should the nurse place the client in?', 'Suspected air embolism from a central line is managed by placing the client in the left lateral Trendelenburg position to trap air in the right ventricle.', '{"options":[{"id":"A","text":"Left side-lying with the head down (Trendelenburg)"},{"id":"B","text":"High Fowler''s position"},{"id":"C","text":"Right side-lying with head elevated"},{"id":"D","text":"Supine with legs elevated"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Left lateral Trendelenburg traps a suspected air embolus in the right ventricle, away from the pulmonary outflow.","B":"Incorrect. This does not trap the air embolus.","C":"Incorrect. Right-side positioning does not trap the embolus favorably.","D":"Incorrect. This does not address air embolism positioning."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Central venous access', 'Air embolism', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_337012', 'SATA', 'A nurse provides discharge teaching to a client starting warfarin. Which instructions should the nurse include? Select all that apply.', 'Warfarin teaching emphasizes consistent vitamin K intake, bleeding precautions, INR monitoring, and avoiding additional antiplatelet or double dosing.', '{"options":[{"id":"A","text":"Keep a consistent intake of green leafy vegetables"},{"id":"B","text":"Report unusual bruising or dark, tarry stools"},{"id":"C","text":"Attend scheduled INR blood draws"},{"id":"D","text":"Use a soft-bristled toothbrush"},{"id":"E","text":"Take an aspirin daily for extra protection"},{"id":"F","text":"Double the dose if a dose is missed"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Consistent vitamin K intake keeps the INR stable.","B":"Correct. These signal bleeding, a key warfarin risk.","C":"Correct. INR monitoring guides dosing.","D":"Correct. This reduces gum bleeding.","E":"Incorrect. Adding aspirin increases bleeding risk without a specific order.","F":"Incorrect. Doubling doses raises bleeding risk; missed-dose instructions come from the provider."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin teaching', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_337013', 'SATA', 'A nurse assesses a peripheral IV site. Which findings indicate infiltration rather than phlebitis? Select all that apply.', 'Infiltration presents with coolness, swelling, taut skin, and slowed flow, distinguishing it from the warmth and redness of phlebitis.', '{"options":[{"id":"A","text":"Cool skin around the insertion site"},{"id":"B","text":"Swelling and taut skin at the site"},{"id":"C","text":"Slowed or stopped infusion flow"},{"id":"D","text":"Redness with a palpable warm cord along the vein"},{"id":"E","text":"Purulent drainage at the site"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Coolness reflects fluid leaking into tissue.","B":"Correct. Edema is a hallmark of infiltration.","C":"Correct. Fluid escaping into tissue slows the flow.","D":"Incorrect. A warm, red cord indicates phlebitis.","E":"Incorrect. Purulence suggests infection, not infiltration."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IV infusion monitoring', 'Infiltration', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_337014', 'SATA', 'A nurse prepares to mix regular and NPH insulin in one syringe. Which actions are correct? Select all that apply.', 'Correct technique injects air into NPH first, then draws clear (regular) before cloudy (NPH), gently resuspending NPH by rolling.', '{"options":[{"id":"A","text":"Inject air into the NPH vial first"},{"id":"B","text":"Withdraw the regular (clear) insulin before the NPH"},{"id":"C","text":"Roll the NPH vial gently between the palms"},{"id":"D","text":"Withdraw the NPH insulin before the regular insulin"},{"id":"E","text":"Shake both vials vigorously before use"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Air is injected into the cloudy (NPH) vial first without touching the solution.","B":"Correct. Draw up clear before cloudy to avoid contaminating the regular vial.","C":"Correct. Gentle rolling resuspends NPH without foaming.","D":"Incorrect. Drawing cloudy first contaminates the clear vial.","E":"Incorrect. Shaking causes foaming and inaccurate dosing."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Mixing insulins', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_337015', 'SATA', 'Before administering medications to a newly admitted client, which pre-administration data should the nurse verify? Select all that apply.', 'Safe pre-administration review includes allergies, pertinent labs, the reconciled medication list, and interaction screening.', '{"options":[{"id":"A","text":"The client''s documented allergies"},{"id":"B","text":"Relevant laboratory values"},{"id":"C","text":"The client''s current home medication list"},{"id":"D","text":"Potential drug-drug interactions"},{"id":"E","text":"The client''s preferred meal times only"},{"id":"F","text":"The client''s insurance provider"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Allergy verification prevents reactions.","B":"Correct. Labs such as potassium or renal function affect safety.","C":"Correct. Reconciliation prevents interactions and omissions.","D":"Correct. Interaction checking prevents adverse events.","E":"Incorrect. While useful, meal preference is not a core safety check.","F":"Incorrect. Insurance is not a clinical pre-administration safety check."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication reconciliation', 'Pre-administration review', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_337016', 'SATA', 'A client has a prescription for IV potassium chloride. Which nursing actions ensure safe administration? Select all that apply.', 'Safe IV potassium requires confirmed urine output, dilution, pump control, and site monitoring; it is never given by IV push.', '{"options":[{"id":"A","text":"Verify the client has adequate urine output before infusing"},{"id":"B","text":"Always dilute potassium and infuse via a pump"},{"id":"C","text":"Assess the IV site for patency and irritation"},{"id":"D","text":"Administer undiluted potassium by IV push for a rapid effect"},{"id":"E","text":"Encourage the client to report burning at the site"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Adequate renal function is confirmed to prevent hyperkalemia.","B":"Correct. Diluted, pump-controlled infusion prevents cardiac toxicity.","C":"Correct. Potassium is irritating and can cause phlebitis.","D":"Incorrect. IV push potassium is fatal and never given.","E":"Correct. Burning may indicate irritation or infiltration."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Electrolytes', 'Potassium administration', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_337017', 'SELECT_N', 'A nurse is about to administer digoxin. Which 3 findings should prompt the nurse to withhold the dose and notify the provider?', 'Digoxin is withheld for bradycardia below 60, hypokalemia (which increases toxicity), and supratherapeutic serum levels.', '{"options":[{"id":"A","text":"Apical heart rate of 52 beats/min"},{"id":"B","text":"Serum potassium of 2.9 mEq/L"},{"id":"C","text":"Serum digoxin level of 2.6 ng/mL"},{"id":"D","text":"Blood pressure of 128/78 mmHg"},{"id":"E","text":"Apical heart rate of 74 beats/min"},{"id":"F","text":"Serum potassium of 4.1 mEq/L"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. A rate below 60 warrants holding digoxin.","B":"Correct. Hypokalemia potentiates digoxin toxicity.","C":"Correct. This exceeds the therapeutic range (0.5-2 ng/mL).","D":"Incorrect. This is a normal blood pressure.","E":"Incorrect. This is within a safe range for digoxin.","F":"Incorrect. This is a normal potassium level."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin', 'Pre-administration check', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_337018', 'TF', 'Lactated Ringer''s solution is the appropriate IV fluid to prime tubing and infuse with packed red blood cells.', 'Only 0.9% normal saline is compatible with blood products; calcium in lactated Ringer''s can cause clotting, and dextrose solutions cause hemolysis.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Blood products', 'Compatible fluid', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_337019', 'MATRIX', 'For each medication, click to identify the correct reversal agent or antidote.', 'Naloxone reverses opioids, vitamin K reverses warfarin, and protamine sulfate reverses heparin.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Heparin"},{"id":"r2","text":"Warfarin"},{"id":"r3","text":"Morphine"},{"id":"r4","text":"Hydromorphone"}],"columns":[{"id":"c1","text":"Naloxone"},{"id":"c2","text":"Vitamin K"},{"id":"c3","text":"Protamine sulfate"}]}'::jsonb, '{"cells":{"r1":"c3","r2":"c2","r3":"c1","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medications', 'Antidotes', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_337020', 'MATRIX_MR', 'For each medication, select all parameters the nurse should monitor (more than one may apply).', 'Digoxin requires heart rate and potassium monitoring, furosemide affects potassium, insulin affects glucose, and beta blockers require heart rate monitoring.', '{"row_label":"Medication class","rows":[{"id":"r1","text":"Digoxin"},{"id":"r2","text":"Furosemide"},{"id":"r3","text":"Insulin glargine"},{"id":"r4","text":"Metoprolol"}],"columns":[{"id":"c1","text":"Heart rate"},{"id":"c2","text":"Serum potassium"},{"id":"c3","text":"Blood glucose"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c2"],"r3":["c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication education', 'Monitoring parameters', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_337021', 'CLOZE', 'A conscious client on insulin becomes diaphoretic and shaky with a blood glucose of 54 mg/dL. The nurse should first give {1}, and if the client were unconscious the nurse would administer {2}.', 'A conscious hypoglycemic client receives fast-acting oral carbohydrate; an unconscious client cannot swallow and requires IV dextrose or glucagon.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"4 ounces of fruit juice"},{"id":"c2","text":"a dose of regular insulin"},{"id":"c3","text":"a high-fiber meal"}]},{"id":"b2","choices":[{"id":"c1","text":"IV dextrose or glucagon"},{"id":"c2","text":"oral glucose tablets"},{"id":"c3","text":"long-acting insulin"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Hypoglycemia response', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_337022', 'BOWTIE', 'A client on furosemide has a potassium of 2.8 mEq/L. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Loop-diuretic-induced hypokalemia is managed with potassium replacement and cardiac monitoring, tracking the ECG and serum potassium.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer prescribed potassium replacement"},{"id":"lt2","text":"Place the client on a cardiac monitor"},{"id":"lt3","text":"Administer additional furosemide"},{"id":"lt4","text":"Restrict all dietary potassium"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Hypokalemia"},{"id":"ct2","text":"Hyperkalemia"},{"id":"ct3","text":"Hypernatremia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"ECG for dysrhythmias"},{"id":"rt2","text":"Serum potassium level"},{"id":"rt3","text":"Serum calcium level"},{"id":"rt4","text":"White blood cell count"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Electrolytes', 'Hypokalemia', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_337023', 'DRAG_CLOZE', 'A medication is ordered at 5 mg/kg for a client weighing 70 kg. The total dose is [1]. If the drug is supplied as 100 mg/mL, the nurse will draw up [2].', '5 mg/kg x 70 kg = 350 mg; 350 mg / 100 mg/mL = 3.5 mL.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"350 mg"},{"id":"t2","text":"3.5 mL"},{"id":"t3","text":"35 mg"},{"id":"t4","text":"7 mL"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Dosage calculation', 'Weight-based dosing', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_337024', 'DRAG_ORDER', 'Place the steps for initiating a packed red blood cell transfusion in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Verify the prescription and confirm informed consent"},{"id":"t2","text":"Obtain baseline vital signs"},{"id":"t3","text":"Verify blood product and client identity with a second nurse"},{"id":"t4","text":"Begin the transfusion slowly for the first 15 minutes"},{"id":"t5","text":"Reassess vital signs after 15 minutes"},{"id":"t6","text":"Discard the empty bag in biohazard waste"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Blood products', 'Transfusion procedure', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338001', 'MCQ', 'A client receiving a continuous IV heparin infusion has an aPTT of 96 seconds (control 30 seconds; therapeutic 46-70). What is the nurse''s priority action?', 'An aPTT far above the therapeutic range signals excessive anticoagulation, so the infusion is held and the provider notified.', '{"options":[{"id":"A","text":"Stop the infusion and notify the provider"},{"id":"B","text":"Increase the infusion rate to reach steady state"},{"id":"C","text":"Administer vitamin K"},{"id":"D","text":"Continue the infusion and recheck in 6 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An aPTT well above therapeutic indicates over-anticoagulation and bleeding risk; hold and notify.","B":"Incorrect. The value is already supratherapeutic.","C":"Incorrect. Vitamin K reverses warfarin, not heparin.","D":"Incorrect. Continuing risks hemorrhage."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin monitoring', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338002', 'MCQ', 'A client receives NPH insulin 20 units subcutaneously at 0700. At what approximate time should the nurse be most alert for signs of hypoglycemia?', 'NPH is intermediate-acting with a peak around 4-12 hours, so hypoglycemia risk is greatest mid-to-late in that window.', '{"options":[{"id":"A","text":"0730"},{"id":"B","text":"1100-1900"},{"id":"C","text":"Immediately after injection"},{"id":"D","text":"24 hours later"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. NPH does not peak this early.","B":"Correct. NPH peaks roughly 4-12 hours after administration.","C":"Incorrect. That describes rapid-acting insulin onset, not NPH peak.","D":"Incorrect. NPH duration is about 12-18 hours."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Peak action', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338003', 'MCQ', 'A client is receiving IV vancomycin. Which laboratory result requires the nurse to hold the next dose and notify the provider?', 'Vancomycin is nephrotoxic; a doubling of creatinine indicates renal injury and warrants holding the drug.', '{"options":[{"id":"A","text":"Serum creatinine rising from 0.9 to 2.1 mg/dL"},{"id":"B","text":"Potassium 4.0 mEq/L"},{"id":"C","text":"Hemoglobin 13 g/dL"},{"id":"D","text":"Sodium 138 mEq/L"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rising creatinine signals nephrotoxicity, a key vancomycin risk.","B":"Incorrect. This is normal.","C":"Incorrect. This is normal.","D":"Incorrect. This is normal."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Antibiotics', 'Vancomycin', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338004', 'MCQ', 'A provider orders 1,000 mL of normal saline to infuse over 8 hours using tubing with a drop factor of 15 gtt/mL. What rate should the nurse set in drops per minute?', 'Drops/min = (total volume x drop factor) / total minutes = (1000 x 15) / 480 = 31 gtt/min.', '{"options":[{"id":"A","text":"31 gtt/min"},{"id":"B","text":"21 gtt/min"},{"id":"C","text":"42 gtt/min"},{"id":"D","text":"15 gtt/min"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. (1000 mL x 15 gtt/mL) / 480 min = 31 gtt/min.","B":"Incorrect. That uses a drop factor of 10.","C":"Incorrect. That doubles the correct rate.","D":"Incorrect. That ignores the volume and time."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Dosage calculation', 'IV flow rate', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338005', 'MCQ', 'A client who received IV morphine has a respiratory rate of 6/min and is difficult to arouse. After ensuring airway and oxygen, which medication should the nurse anticipate administering?', 'Opioid-induced respiratory depression is reversed with the antagonist naloxone.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Flumazenil"},{"id":"C","text":"Protamine sulfate"},{"id":"D","text":"Acetylcysteine"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone is the opioid antagonist that reverses respiratory depression.","B":"Incorrect. Flumazenil reverses benzodiazepines.","C":"Incorrect. Protamine reverses heparin.","D":"Incorrect. Acetylcysteine treats acetaminophen toxicity."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Opioids', 'Overdose reversal', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338006', 'MCQ', 'Fifteen minutes into a packed red blood cell transfusion, a client develops fever, chills, flank pain, and dark urine. What is the nurse''s first action?', 'Fever, flank pain, and hemoglobinuria suggest an acute hemolytic reaction; stopping the transfusion is the priority.', '{"options":[{"id":"A","text":"Stop the transfusion and keep the IV open with normal saline"},{"id":"B","text":"Slow the transfusion and continue monitoring"},{"id":"C","text":"Administer acetaminophen and continue"},{"id":"D","text":"Increase the transfusion rate to finish quickly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stopping the transfusion immediately halts further hemolysis; saline maintains venous access and renal perfusion.","B":"Incorrect. A hemolytic reaction requires stopping, not slowing.","C":"Incorrect. This delays stopping a dangerous reaction.","D":"Incorrect. This worsens the reaction."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood products', 'Transfusion reaction', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338007', 'MCQ', 'A client newly started on lisinopril reports a persistent dry cough. Which is the most appropriate nursing response?', 'A dry cough is a classic ACE-inhibitor effect from bradykinin accumulation and is commonly resolved by switching to an ARB.', '{"options":[{"id":"A","text":"Explain this is a known effect and notify the provider, who may switch to an ARB"},{"id":"B","text":"Tell the client to stop the drug immediately and no follow-up is needed"},{"id":"C","text":"Reassure the client the cough indicates the drug is working"},{"id":"D","text":"Administer a prescribed antibiotic for the cough"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. ACE-inhibitor cough is common and often managed by switching to an ARB.","B":"Incorrect. Clients should not abruptly self-discontinue without guidance.","C":"Incorrect. Cough is an adverse effect, not a therapeutic marker.","D":"Incorrect. The cough is drug-induced, not infectious."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'ACE inhibitors', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338008', 'MCQ', 'A client receiving total parenteral nutrition (TPN) suddenly becomes diaphoretic, shaky, and confused shortly after the infusion was abruptly stopped when the bag emptied. What does the nurse suspect?', 'TPN delivers high dextrose; abrupt stoppage leaves circulating insulin unopposed, producing hypoglycemia.', '{"options":[{"id":"A","text":"Rebound hypoglycemia"},{"id":"B","text":"Air embolism"},{"id":"C","text":"Fluid volume overload"},{"id":"D","text":"Catheter-related infection"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Abrupt TPN cessation can cause rebound hypoglycemia from continued high insulin levels.","B":"Incorrect. Air embolism presents with dyspnea and chest pain.","C":"Incorrect. Overload presents with crackles and edema.","D":"Incorrect. Infection presents with fever over hours to days."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'Parenteral nutrition', 'TPN complications', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338009', 'MCQ', 'A client on lithium reports coarse hand tremor, vomiting, and slurred speech. The lithium level is 1.9 mEq/L. Which intervention should the nurse prioritize?', 'Lithium levels above 1.5 mEq/L with neuro/GI symptoms indicate toxicity, so the dose is held and the provider notified.', '{"options":[{"id":"A","text":"Hold the next lithium dose and notify the provider"},{"id":"B","text":"Administer the next scheduled dose on time"},{"id":"C","text":"Restrict all fluids and sodium"},{"id":"D","text":"Reassure the client these are expected therapeutic effects"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A level of 1.9 mEq/L with symptoms indicates toxicity; hold the drug and notify.","B":"Incorrect. This worsens toxicity.","C":"Incorrect. Sodium restriction increases lithium retention.","D":"Incorrect. These are toxicity signs, not therapeutic effects."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Psychiatric/Mental Health', 'Psychotropics', 'Lithium toxicity', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338010', 'MCQ', 'While changing the injection cap on a client''s central venous catheter, the nurse should instruct the client to perform which action to reduce the risk of air embolism?', 'Having the client perform Valsalva during cap or tubing changes raises intrathoracic pressure and prevents air aspiration into a central line.', '{"options":[{"id":"A","text":"Bear down and hold the breath (Valsalva maneuver)"},{"id":"B","text":"Take rapid deep breaths"},{"id":"C","text":"Sit fully upright"},{"id":"D","text":"Cough forcefully"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Valsalva increases intrathoracic pressure, preventing air from entering the catheter.","B":"Incorrect. Deep inspiration lowers intrathoracic pressure and can draw air in.","C":"Incorrect. Upright positioning increases air-entry risk during a cap change.","D":"Incorrect. Coughing does not reliably prevent air entry during the change."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Central venous access devices', 'Air embolism prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_338011', 'MCQ', 'During peripheral IV administration of a vesicant chemotherapy agent, the client reports burning at the site, and the nurse notes swelling and no blood return. What should the nurse do first?', 'Extravasation of a vesicant requires stopping the infusion while leaving the catheter in place for aspiration and antidote.', '{"options":[{"id":"A","text":"Stop the infusion but leave the catheter in place"},{"id":"B","text":"Flush the line with a rapid saline bolus"},{"id":"C","text":"Immediately remove the catheter"},{"id":"D","text":"Apply firm pressure and continue the infusion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stopping halts further tissue exposure; the catheter stays to allow aspiration and antidote instillation.","B":"Incorrect. Flushing pushes more vesicant into tissue.","C":"Incorrect. The catheter may be needed to aspirate drug and give an antidote.","D":"Incorrect. Continuing worsens tissue damage."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Chemotherapy', 'Extravasation', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_338012', 'SATA', 'A nurse teaches a client newly prescribed warfarin. Which statements should be included? Select all that apply.', 'Warfarin teaching emphasizes consistent vitamin K intake, bleeding precautions, INR monitoring, and avoiding additional antiplatelet or double dosing.', '{"options":[{"id":"A","text":"Keep your green leafy vegetable intake consistent from day to day"},{"id":"B","text":"Report unusual bruising, blood in urine, or black stools"},{"id":"C","text":"Attend regular INR blood-test appointments"},{"id":"D","text":"Use a soft toothbrush and an electric razor"},{"id":"E","text":"Take an aspirin daily for extra protection"},{"id":"F","text":"Double the dose if you miss a day"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Anticoagulants', 'Warfarin teaching', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_338013', 'SATA', 'A client is receiving furosemide for heart failure. Which assessment findings should the nurse monitor for as potential adverse effects? Select all that apply.', 'Furosemide causes potassium loss, volume depletion with orthostasis, dehydration-related azotemia, and ototoxicity with rapid IV administration.', '{"options":[{"id":"A","text":"Hypokalemia"},{"id":"B","text":"Orthostatic hypotension"},{"id":"C","text":"Ototoxicity with rapid IV push"},{"id":"D","text":"Elevated blood urea nitrogen"},{"id":"E","text":"Hyperkalemia"},{"id":"F","text":"Weight gain"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Loop diuretic monitoring', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_338014', 'SATA', 'Before administering a medication, which actions support the rights of medication administration? Select all that apply.', 'The rights include right client (two identifiers), drug, dose, route, time, and documentation performed after administration.', '{"options":[{"id":"A","text":"Verify the client using two identifiers"},{"id":"B","text":"Check the medication against the order for drug, dose, and route"},{"id":"C","text":"Confirm the correct time of administration"},{"id":"D","text":"Document the medication after it is given"},{"id":"E","text":"Administer first and chart it during the next shift"},{"id":"F","text":"Use the room number alone to identify the client"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Fundamentals of Nursing', 'Multisystem', 'Rights of administration', 'Medication safety', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_338015', 'SATA', 'A nurse prepares to mix regular and NPH insulin in one syringe. Which steps are correct? Select all that apply.', 'Air is injected into NPH then regular; the clear regular insulin is drawn first to avoid contaminating the vial with NPH, and NPH is gently rolled, not shaken.', '{"options":[{"id":"A","text":"Inject air into the NPH vial first without withdrawing insulin"},{"id":"B","text":"Inject air into the regular vial, then withdraw the regular insulin"},{"id":"C","text":"Draw up the regular (clear) insulin before the NPH (cloudy)"},{"id":"D","text":"Draw up the NPH insulin before the regular insulin"},{"id":"E","text":"Roll the NPH vial between the palms to mix"},{"id":"F","text":"Shake both vials vigorously before drawing up"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Mixing insulins', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_338016', 'SATA', 'A client receiving patient-controlled analgesia (PCA) with morphine is being monitored. Which findings should prompt the nurse to intervene? Select all that apply.', 'Respiratory depression, desaturation, oversedation, and PCA-by-proxy are safety concerns requiring intervention.', '{"options":[{"id":"A","text":"Respiratory rate of 8/min"},{"id":"B","text":"Oxygen saturation dropping to 88%"},{"id":"C","text":"Increasing sedation and difficulty arousing"},{"id":"D","text":"A family member pressing the PCA button for the client"},{"id":"E","text":"Respiratory rate of 16/min"},{"id":"F","text":"Client rating pain 4/10 and awake"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Musculoskeletal', 'High-risk medications', 'Opioid safety', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_338017', 'TF', 'Lactated Ringer''s solution is the appropriate IV fluid to prime tubing and infuse with packed red blood cells.', 'Only 0.9% normal saline is compatible with blood products; the calcium in Lactated Ringer''s can promote clotting.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Blood products', 'Compatible IV fluid', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_338018', 'SELECT_N', 'Before administering digoxin, the nurse reviews the client''s data. Which 2 findings would cause the nurse to hold the dose and notify the provider?', 'Digoxin is held for an apical rate below 60/min, and hypokalemia potentiates digoxin toxicity, so both warrant holding and notifying.', '{"options":[{"id":"A","text":"Apical heart rate of 52/min"},{"id":"B","text":"Serum potassium of 2.9 mEq/L"},{"id":"C","text":"Blood pressure of 118/76 mmHg"},{"id":"D","text":"Serum potassium of 4.2 mEq/L"},{"id":"E","text":"Apical heart rate of 78/min"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Pre-administration data review', 'Digoxin', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_338019', 'MATRIX', 'For each reversal agent, click the medication or toxin it is used to counteract.', 'Protamine reverses heparin, vitamin K reverses warfarin, and flumazenil reverses benzodiazepines.', '{"row_label":"Antidote","rows":[{"id":"r1","text":"Protamine sulfate"},{"id":"r2","text":"Vitamin K (phytonadione)"},{"id":"r3","text":"Flumazenil"}],"columns":[{"id":"c1","text":"Heparin"},{"id":"c2","text":"Warfarin"},{"id":"c3","text":"Benzodiazepines"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'High-risk medications', 'Reversal agents', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_338020', 'MATRIX_MR', 'For each medication, select all correct routes or techniques of administration.', 'Enoxaparin is subcutaneous, iron dextran uses Z-track IM or IV to avoid staining, and regular insulin may be subcutaneous or IV.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Enoxaparin"},{"id":"r2","text":"Iron dextran"},{"id":"r3","text":"Regular insulin"}],"columns":[{"id":"c1","text":"Subcutaneous"},{"id":"c2","text":"Intramuscular Z-track"},{"id":"c3","text":"Intravenous"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2","c3"],"r3":["c1","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication routes', 'Injection technique', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_338021', 'CLOZE', 'A client needs IV potassium replacement. The nurse knows potassium must never be given by {1}, and the maximum peripheral infusion rate should not exceed {2}.', 'IV potassium is never pushed because it can cause fatal arrhythmias, and peripheral infusion is limited to about 10 mEq/hour.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"IV push"},{"id":"c2","text":"slow infusion pump"},{"id":"c3","text":"diluted drip"}]},{"id":"b2","choices":[{"id":"c1","text":"10 mEq/hour"},{"id":"c2","text":"40 mEq/hour"},{"id":"c3","text":"60 mEq/hour"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Electrolytes', 'Potassium administration', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_338022', 'HIGHLIGHT', 'A client receives the first dose of IV ceftriaxone. Highlight the findings that indicate a developing anaphylactic reaction. The client is [[alert and oriented]], reports [[lip and tongue swelling]], has [[audible wheezing]], blood pressure [[82/48 mmHg]], temperature [[37.1°C]], and [[widespread hives]].', 'Angioedema, wheezing, hypotension, and urticaria together indicate anaphylaxis, whereas normal orientation and temperature do not.', '{"chunks":[{"id":"h1","text":"alert and oriented"},{"id":"h2","text":"lip and tongue swelling"},{"id":"h3","text":"audible wheezing"},{"id":"h4","text":"82/48 mmHg"},{"id":"h5","text":"37.1°C"},{"id":"h6","text":"widespread hives"}]}'::jsonb, '{"correct_ids":["h2","h3","h4","h6"],"feedback":{"h1":"Normal mental status is not a sign of anaphylaxis.","h2":"Angioedema is a hallmark of anaphylaxis.","h3":"Bronchospasm produces wheezing in anaphylaxis.","h4":"Hypotension reflects distributive shock.","h5":"This temperature is normal.","h6":"Urticaria is a common anaphylaxis finding."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Adverse drug reaction', 'Anaphylaxis recognition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_338023', 'BOWTIE', 'A client on an insulin drip has a blood glucose of 48 mg/dL and is diaphoretic but awake and able to swallow. Complete the diagram.', 'Awake hypoglycemia is treated with 15 g oral carbohydrate and a recheck in 15 minutes, monitoring glucose and neurologic status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Give 15 g of oral fast-acting carbohydrate"},{"id":"lt2","text":"Recheck blood glucose in 15 minutes"},{"id":"lt3","text":"Administer the next scheduled insulin dose"},{"id":"lt4","text":"Withhold all food until the provider rounds"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Hypoglycemia"},{"id":"ct2","text":"Diabetic ketoacidosis"},{"id":"ct3","text":"Hyperosmolar hyperglycemic state"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood glucose level"},{"id":"rt2","text":"Level of consciousness"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Urine ketones"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Hypoglycemia management', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_338024', 'DRAG_CLOZE', 'A nurse assesses a peripheral IV site that is cool, pale, and swollen with a sluggish infusion. This indicates [1], and the priority action is to [2] the infusion.', 'A cool, pale, swollen site indicates infiltration, so the infusion is stopped and the catheter removed.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"infiltration"},{"id":"t2","text":"stop"},{"id":"t3","text":"phlebitis"},{"id":"t4","text":"speed up"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'IV infusion monitoring', 'Site assessment', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339001', 'MCQ', 'A client on a continuous IV heparin infusion has an aPTT of 96 seconds (control 30 seconds; therapeutic 46-70 seconds). Which action should the nurse take?', 'An aPTT above the therapeutic range indicates over-anticoagulation, so the infusion is held and the provider notified.', '{"options":[{"id":"A","text":"Stop the infusion and notify the provider"},{"id":"B","text":"Continue the infusion at the current rate"},{"id":"C","text":"Increase the infusion rate"},{"id":"D","text":"Administer vitamin K"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The aPTT is supratherapeutic, raising bleeding risk; the infusion should be held per protocol.","B":"Incorrect. The value exceeds the therapeutic range and requires action.","C":"Incorrect. Increasing would worsen the bleeding risk.","D":"Incorrect. Protamine sulfate, not vitamin K, reverses heparin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Heparin monitoring', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339002', 'MCQ', 'A client receives NPH insulin 20 units subcutaneously at 0700. During which time period should the nurse be most alert for hypoglycemia?', 'NPH is intermediate-acting and peaks about 4-12 hours after a morning dose, placing the highest hypoglycemia risk mid-day.', '{"options":[{"id":"A","text":"1000-1600"},{"id":"B","text":"0700-0730"},{"id":"C","text":"0730-0800"},{"id":"D","text":"1900-2200"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. NPH peaks roughly 4-12 hours after administration, so this window carries the greatest hypoglycemia risk.","B":"Incorrect. NPH has no rapid onset within the first half hour.","C":"Incorrect. NPH onset is 1-2 hours, not immediate.","D":"Incorrect. This is beyond NPH''s typical peak."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Peak action', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339003', 'MCQ', 'One hour after receiving IV morphine, a postoperative client has a respiratory rate of 8 breaths/min and is difficult to arouse. Which medication should the nurse anticipate administering?', 'Respiratory depression and sedation after morphine indicate opioid toxicity, reversed by the antagonist naloxone.', '{"options":[{"id":"A","text":"Naloxone"},{"id":"B","text":"Flumazenil"},{"id":"C","text":"Acetylcysteine"},{"id":"D","text":"Protamine sulfate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Naloxone is the opioid antagonist that reverses opioid-induced respiratory depression.","B":"Incorrect. Flumazenil reverses benzodiazepines, not opioids.","C":"Incorrect. Acetylcysteine is the antidote for acetaminophen toxicity.","D":"Incorrect. Protamine reverses heparin."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Respiratory', 'Opioids', 'Respiratory depression', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339004', 'MCQ', 'A client receiving IV vancomycin has a trough level of 25 mcg/mL (therapeutic 10-20 mcg/mL) and a rising serum creatinine. Which is the nurse''s priority action?', 'A supratherapeutic vancomycin trough with rising creatinine indicates nephrotoxicity, so the dose is withheld pending provider guidance.', '{"options":[{"id":"A","text":"Hold the next dose and notify the provider"},{"id":"B","text":"Administer the next dose as scheduled"},{"id":"C","text":"Increase the infusion rate"},{"id":"D","text":"Encourage the client to limit oral fluids"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An elevated trough with rising creatinine signals nephrotoxicity, so the dose is held and reported.","B":"Incorrect. Continuing worsens the nephrotoxic risk.","C":"Incorrect. Rapid infusion causes red man syndrome and does not address toxicity.","D":"Incorrect. Fluid restriction would worsen renal perfusion."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Antibiotics', 'Vancomycin', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339005', 'MCQ', 'A client newly started on lisinopril reports a persistent dry cough. Which is the nurse''s best response?', 'A persistent dry cough is a classic ACE inhibitor effect from bradykinin buildup, often managed by switching to an ARB.', '{"options":[{"id":"A","text":"This is a known effect of the drug; report it to the provider, who may switch to another class"},{"id":"B","text":"Stop taking the medication immediately and avoid all blood pressure drugs"},{"id":"C","text":"The cough indicates a serious allergic reaction requiring epinephrine"},{"id":"D","text":"Double the dose to relieve the cough"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dry cough from bradykinin accumulation is common with ACE inhibitors and may warrant a switch to an ARB.","B":"Incorrect. Abrupt discontinuation without guidance is unsafe.","C":"Incorrect. A dry cough is not anaphylaxis.","D":"Incorrect. Increasing the dose does not resolve the cough and is unsafe."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Antihypertensives', 'ACE inhibitors', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339006', 'MCQ', 'Fifteen minutes into a packed red blood cell transfusion, a client develops flank pain, fever, and dark urine. Which action should the nurse take FIRST?', 'Flank pain, fever, and hemoglobinuria signal an acute hemolytic reaction; the nurse stops the transfusion first and keeps the line open with saline.', '{"options":[{"id":"A","text":"Stop the transfusion and keep the IV line open with normal saline"},{"id":"B","text":"Slow the transfusion rate and continue monitoring"},{"id":"C","text":"Administer acetaminophen and continue the transfusion"},{"id":"D","text":"Flush the line with dextrose 5% in water"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These signs suggest an acute hemolytic reaction; stopping the transfusion while maintaining IV access is the priority.","B":"Incorrect. A hemolytic reaction requires immediate cessation, not slowing.","C":"Incorrect. This addresses a mild febrile reaction, not hemolysis.","D":"Incorrect. Blood tubing is maintained with normal saline, not dextrose."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Blood products', 'Transfusion reaction', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339007', 'MCQ', 'A provider prescribes enoxaparin 1 mg/kg subcutaneously every 12 hours for a client who weighs 70 kg. The prefilled syringe contains 100 mg/mL. How many milliliters should the nurse administer per dose?', 'The dose is 70 mg (70 kg x 1 mg/kg), and at 100 mg/mL that equals 0.7 mL.', '{"options":[{"id":"A","text":"0.7 mL"},{"id":"B","text":"0.35 mL"},{"id":"C","text":"1.4 mL"},{"id":"D","text":"7 mL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. 70 kg x 1 mg/kg = 70 mg; 70 mg divided by 100 mg/mL = 0.7 mL.","B":"Incorrect. This halves the correct dose.","C":"Incorrect. This doubles the correct dose.","D":"Incorrect. This misplaces the decimal by tenfold."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Musculoskeletal', 'Dosage calculation', 'Weight-based dosing', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339008', 'MCQ', 'A client taking lithium reports new nausea, coarse hand tremor, and slurred speech. The lithium level is 1.8 mEq/L. Which is the nurse''s priority action?', 'A lithium level above 1.5 mEq/L with GI and neurologic symptoms reflects toxicity, so the dose is held.', '{"options":[{"id":"A","text":"Hold the lithium and notify the provider"},{"id":"B","text":"Administer the next scheduled dose"},{"id":"C","text":"Restrict the client''s sodium and fluid intake"},{"id":"D","text":"Reassure the client that these are expected therapeutic effects"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A level of 1.8 mEq/L with neurologic signs indicates toxicity; the drug is held and the provider notified.","B":"Incorrect. Giving more lithium worsens toxicity.","C":"Incorrect. Sodium restriction raises lithium levels and worsens toxicity.","D":"Incorrect. These are signs of toxicity, not expected effects."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Neurological', 'Psychotropics', 'Lithium', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339009', 'MCQ', 'A client receiving total parenteral nutrition suddenly has diaphoresis, shakiness, and a blood glucose of 52 mg/dL shortly after the infusion was abruptly stopped. Which is the most likely cause?', 'Abruptly stopping dextrose-rich TPN leaves endogenous insulin unopposed, producing rebound hypoglycemia.', '{"options":[{"id":"A","text":"Rebound hypoglycemia from abrupt TPN discontinuation"},{"id":"B","text":"Air embolism from the central line"},{"id":"C","text":"Catheter-related bloodstream infection"},{"id":"D","text":"Refeeding syndrome"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stopping high-dextrose TPN abruptly leaves circulating insulin unopposed, causing rebound hypoglycemia.","B":"Incorrect. Air embolism causes respiratory distress, not hypoglycemia.","C":"Incorrect. Infection presents with fever, not acute hypoglycemia.","D":"Incorrect. Refeeding involves electrolyte shifts, not this abrupt-stop hypoglycemia pattern."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'GI', 'TPN', 'Complications', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339010', 'MCQ', 'A nurse notes that a peripheral IV site is cool, pale, and swollen, and the infusion has slowed. Which action should the nurse take FIRST?', 'A cool, pale, swollen site with slowed flow signals infiltration, so the nurse stops the infusion and removes the catheter first.', '{"options":[{"id":"A","text":"Stop the infusion and discontinue the IV"},{"id":"B","text":"Increase the infusion rate to clear the line"},{"id":"C","text":"Apply a warm compress and continue the infusion"},{"id":"D","text":"Flush the catheter with heparin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cool, pale, edematous tissue indicates infiltration; the infusion is stopped and the catheter removed.","B":"Incorrect. Increasing the rate worsens fluid leakage into tissue.","C":"Incorrect. The infusion must be stopped before any comfort measure.","D":"Incorrect. Flushing an infiltrated line pushes more fluid into tissue."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Integumentary', 'IV therapy', 'Infiltration', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_339011', 'MCQ', 'Before administering the first dose of IV ceftriaxone, the client states they had hives and lip swelling after taking penicillin. Which is the nurse''s best action?', 'A prior penicillin reaction with hives and angioedema raises cephalosporin cross-sensitivity risk, so the nurse holds the drug and notifies the provider.', '{"options":[{"id":"A","text":"Hold the medication and notify the provider of the reaction"},{"id":"B","text":"Administer the ceftriaxone as prescribed since it is a different drug"},{"id":"C","text":"Give a dose of diphenhydramine and then administer the antibiotic"},{"id":"D","text":"Document the allergy and proceed with the infusion"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cephalosporins may cross-react with penicillin allergy; a history of anaphylactoid symptoms warrants holding and reporting.","B":"Incorrect. Cross-sensitivity risk makes administration unsafe without provider input.","C":"Incorrect. Premedication does not remove the cross-reactivity risk and requires an order.","D":"Incorrect. Documenting alone without holding the drug endangers the client."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Allergy assessment', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_339012', 'SATA', 'A nurse teaches a client starting warfarin. Which statements should be included? Select all that apply.', 'Warfarin teaching emphasizes consistent vitamin K intake, bleeding precautions, monitoring, and avoiding additional antiplatelet drugs.', '{"options":[{"id":"A","text":"Keep your intake of green leafy vegetables consistent from day to day"},{"id":"B","text":"Report any bleeding gums, blood in urine, or black stools"},{"id":"C","text":"Use a soft toothbrush and an electric razor"},{"id":"D","text":"Take an aspirin daily to boost the effect"},{"id":"E","text":"Skip your INR blood tests once you feel well"},{"id":"F","text":"Wear or carry medical identification about your therapy"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Hematologic', 'Anticoagulants', 'Warfarin teaching', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_339013', 'SATA', 'A client is receiving IV furosemide for heart failure. Which findings should the nurse monitor as potential adverse effects? Select all that apply.', 'Loop diuretics cause potassium loss, volume depletion with orthostasis, and ototoxicity when pushed rapidly.', '{"options":[{"id":"A","text":"Hypokalemia"},{"id":"B","text":"Orthostatic hypotension"},{"id":"C","text":"Ototoxicity with rapid IV push"},{"id":"D","text":"Hyperkalemia"},{"id":"E","text":"Dehydration"},{"id":"F","text":"Fluid overload"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Renal/Genitourinary', 'Diuretics', 'Furosemide monitoring', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_339014', 'SATA', 'Which practices support safe administration of high-alert medications? Select all that apply.', 'Independent double-checks, dose verification, smart pumps, and clear labeling reduce high-alert medication errors.', '{"options":[{"id":"A","text":"Use an independent double-check by a second nurse for IV insulin"},{"id":"B","text":"Verify the dose against weight-based limits for IV heparin"},{"id":"C","text":"Program IV infusions using smart-pump drug libraries"},{"id":"D","text":"Store concentrated electrolytes on the general unit for quick access"},{"id":"E","text":"Label all syringes clearly with drug name and concentration"},{"id":"F","text":"Rely on memory of standard doses to save time"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication safety', 'High-alert medications', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_339015', 'SATA', 'A client receiving chemotherapy has an absolute neutrophil count of 400/mm3. Which precautions should the nurse implement? Select all that apply.', 'Neutropenic precautions include a private room, avoiding sources of microbes, strict hand hygiene, and vigilant fever monitoring while avoiding rectal trauma.', '{"options":[{"id":"A","text":"Place the client in a private room"},{"id":"B","text":"Avoid fresh flowers and raw fruits and vegetables"},{"id":"C","text":"Perform meticulous hand hygiene before contact"},{"id":"D","text":"Take a rectal temperature every 4 hours"},{"id":"E","text":"Monitor for fever as an early sign of infection"},{"id":"F","text":"Encourage visits from anyone with a mild cold"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Chemotherapy', 'Neutropenia precautions', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_339016', 'SATA', 'A client has a newly inserted central venous catheter. Which nursing actions are appropriate? Select all that apply.', 'Central line care requires x-ray confirmation, sterile dressing changes, hub disinfection, and recognition of air embolism management.', '{"options":[{"id":"A","text":"Confirm tip placement with a chest x-ray before infusing"},{"id":"B","text":"Use sterile technique for dressing changes"},{"id":"C","text":"Clamp the catheter and position the client left-side down if air embolism is suspected"},{"id":"D","text":"Routinely draw blood from the line without flushing afterward"},{"id":"E","text":"Scrub the needleless connector before each access"},{"id":"F","text":"Leave the insertion-site dressing in place indefinitely regardless of soiling"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Central venous access', 'Care and complications', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_339017', 'SELECT_N', 'A nurse prepares to mix regular and NPH insulin in one syringe. Which 3 steps are correct?', 'Air is injected into the cloudy vial first, the cloudy insulin is gently resuspended, and clear insulin is drawn before cloudy to avoid contaminating the fast-acting vial.', '{"options":[{"id":"A","text":"Inject air into the NPH vial first without withdrawing insulin"},{"id":"B","text":"Withdraw the regular (clear) insulin before the NPH (cloudy) insulin"},{"id":"C","text":"Roll the NPH vial gently between the palms to resuspend it"},{"id":"D","text":"Withdraw the NPH insulin first, then the regular insulin"},{"id":"E","text":"Shake the NPH vial vigorously to mix it"},{"id":"F","text":"Inject air into the regular vial and immediately withdraw NPH"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Mixing insulins', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_339018', 'TF', 'When only half of a prefilled opioid syringe is administered, the nurse may discard the remaining half alone and document it later without another nurse present.', 'Wasting a controlled substance requires a second licensed nurse to witness and co-sign the disposal at the time it occurs.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Musculoskeletal', 'Controlled substances', 'Wasting narcotics', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_339019', 'MATRIX', 'For each drug, click the correct reversal agent or antidote.', 'Naloxone reverses opioids, vitamin K counters warfarin, and flumazenil reverses benzodiazepines.', '{"row_label":"Antidote","rows":[{"id":"r1","text":"Morphine overdose"},{"id":"r2","text":"Warfarin over-anticoagulation"},{"id":"r3","text":"Midazolam oversedation"},{"id":"r4","text":"Hydromorphone respiratory depression"}],"columns":[{"id":"c1","text":"Naloxone"},{"id":"c2","text":"Vitamin K"},{"id":"c3","text":"Flumazenil"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Medication antidotes', 'Reversal agents', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_339020', 'MATRIX_MR', 'For each medication, select all laboratory values the nurse should review before administering (more than one may apply).', 'Warfarin needs INR, potassium-sparing and nephrotoxic drugs need potassium/creatinine, and digoxin toxicity is potentiated by hypokalemia and renal impairment.', '{"row_label":"Medication","rows":[{"id":"r1","text":"Warfarin"},{"id":"r2","text":"Spironolactone"},{"id":"r3","text":"Gentamicin"},{"id":"r4","text":"Digoxin"}],"columns":[{"id":"c1","text":"Serum potassium"},{"id":"c2","text":"INR/PT"},{"id":"c3","text":"Serum creatinine"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1","c3"],"r3":["c3"],"r4":["c1","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Multisystem', 'Pre-administration lab review', 'Baseline labs', 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_339021', 'CLOZE', 'A client is given insulin lispro at mealtime. The nurse should ensure the meal is served within {1} because this insulin''s rapid onset increases the risk of {2} if the client does not eat.', 'Rapid-acting lispro begins working within about 15 minutes, so a missed meal quickly precipitates hypoglycemia.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"15 minutes"},{"id":"c2","text":"2 hours"},{"id":"c3","text":"6 hours"}]},{"id":"b2","choices":[{"id":"c1","text":"hypoglycemia"},{"id":"c2","text":"hyperkalemia"},{"id":"c3","text":"metabolic alkalosis"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Endocrine', 'Insulin', 'Onset and hypoglycemia', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_339022', 'HIGHLIGHT', 'The nurse reviews a client before giving digoxin. Highlight the findings that require the nurse to hold the dose and notify the provider. Apical heart rate [[52 beats/min]]. Reports [[nausea and seeing yellow halos]]. Serum potassium [[2.9 mEq/L]]. Blood pressure [[124/78]]. Temperature [[37.1°C]].', 'Bradycardia, GI/visual toxicity signs, and hypokalemia all require holding digoxin and notifying the provider.', '{"chunks":[{"id":"h1","text":"52 beats/min"},{"id":"h2","text":"nausea and seeing yellow halos"},{"id":"h3","text":"2.9 mEq/L"},{"id":"h4","text":"124/78"},{"id":"h5","text":"37.1°C"}]}'::jsonb, '{"correct_ids":["h1","h2","h3"],"feedback":{"h1":"An apical rate below 60 warrants holding digoxin.","h2":"Classic signs of digoxin toxicity.","h3":"Hypokalemia potentiates digoxin toxicity.","h4":"Normal blood pressure — no concern.","h5":"Normal temperature — no concern."}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'Digoxin', 'Pre-administration assessment', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_339023', 'BOWTIE', 'During an IV penicillin infusion, a client develops wheezing, hypotension, and facial swelling. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Wheezing, hypotension, and angioedema indicate anaphylaxis; the nurse stops the drug and gives epinephrine while monitoring airway and blood pressure.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the infusion immediately"},{"id":"lt2","text":"Prepare to administer epinephrine"},{"id":"lt3","text":"Slow the infusion and observe"},{"id":"lt4","text":"Encourage oral fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Anaphylaxis"},{"id":"ct2","text":"Fluid overload"},{"id":"ct3","text":"Hypoglycemia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Airway and oxygen saturation"},{"id":"rt2","text":"Blood pressure"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Immune', 'Antibiotics', 'Anaphylaxis', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_339024', 'DRAG_CLOZE', 'A provider prescribes 1,000 mL of normal saline to infuse over 8 hours. Using a pump, the nurse sets the rate to [1]. If the bag must instead run over 4 hours, the rate becomes [2].', '1,000 mL over 8 hours is 125 mL/hr; the same volume over 4 hours doubles to 250 mL/hr.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"125 mL/hr"},{"id":"t2","text":"250 mL/hr"},{"id":"t3","text":"1,000 mL/hr"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Pharmacology', 'Cardiovascular', 'IV infusion', 'Flow-rate calculation', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343001', 'MCQ', 'A nurse observes continuous bubbling in the water-seal chamber of a client''s chest drainage system that was not present an hour ago. Which action should the nurse take FIRST?', 'Continuous bubbling in the water-seal chamber indicates an air leak; assessing connections is the first, least invasive step.', '{"options":[{"id":"A","text":"Assess the tubing and connections for an air leak"},{"id":"B","text":"Clamp the chest tube near the insertion site"},{"id":"C","text":"Increase the wall suction pressure"},{"id":"D","text":"Strip the chest tube vigorously"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. New continuous bubbling in the water-seal chamber suggests an air leak in the system; the nurse checks connections first.","B":"Incorrect. Clamping can cause a tension pneumothorax.","C":"Incorrect. This does not address a leak and may not change water-seal bubbling.","D":"Incorrect. Stripping generates dangerous negative pressure and is not indicated."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Continuous bubbling', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343002', 'MCQ', 'A high-pressure alarm sounds on the ventilator of an intubated client who is coughing and restless. Which is the most likely cause?', 'High-pressure alarms reflect increased resistance such as secretions, biting, or kinking; low-pressure alarms reflect leaks or disconnection.', '{"options":[{"id":"A","text":"Accumulated secretions in the airway"},{"id":"B","text":"A disconnection in the ventilator circuit"},{"id":"C","text":"A cuff leak around the endotracheal tube"},{"id":"D","text":"An oversized endotracheal tube"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Secretions increase airway resistance and trigger the high-pressure alarm; suctioning is indicated.","B":"Incorrect. A disconnect causes a low-pressure alarm.","C":"Incorrect. A cuff leak lowers pressure and triggers a low-pressure alarm.","D":"Incorrect. This is not an acute cause of a high-pressure alarm."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', 'High-pressure alarm', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343003', 'MCQ', 'A client with diabetic ketoacidosis is receiving an insulin infusion. The serum potassium is now 3.4 mEq/L, down from 5.1 mEq/L. Which action should the nurse anticipate?', 'Insulin shifts potassium intracellularly; falling potassium during DKA treatment requires replacement to prevent arrhythmias.', '{"options":[{"id":"A","text":"Notify the provider and prepare to add potassium to the IV fluids"},{"id":"B","text":"Stop the insulin infusion permanently"},{"id":"C","text":"Administer sodium polystyrene sulfonate"},{"id":"D","text":"Restrict all potassium-containing foods"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Insulin drives potassium into cells; replacement is needed to prevent life-threatening hypokalemia.","B":"Incorrect. Insulin is still needed; potassium is replaced instead.","C":"Incorrect. This lowers potassium and would worsen the hypokalemia.","D":"Incorrect. The client needs more potassium, not less."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', 'Potassium during treatment', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343004', 'MCQ', 'A nurse assesses a client 12 hours after ileostomy creation. Which finding requires immediate follow-up?', 'A healthy stoma is red and moist; a dusky or purple stoma signals compromised blood supply and is an emergency.', '{"options":[{"id":"A","text":"A dusky, purplish stoma"},{"id":"B","text":"A stoma that is beefy red and moist"},{"id":"C","text":"Small amount of blood when cleaning the stoma"},{"id":"D","text":"Loose, liquid effluent in the pouch"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dusky or purple stoma indicates ischemia and must be reported immediately.","B":"Incorrect. This is a healthy, expected finding.","C":"Incorrect. Minor bleeding with cleaning is expected due to vascularity.","D":"Incorrect. Liquid output is expected from a new ileostomy."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', 'New ileostomy output', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343005', 'MCQ', 'During the first hemodialysis treatment, a client develops a headache, nausea, and confusion. The nurse recognizes these as signs of which complication?', 'Disequilibrium syndrome results from rapid shifts of solutes and water causing cerebral edema, common early in dialysis.', '{"options":[{"id":"A","text":"Dialysis disequilibrium syndrome"},{"id":"B","text":"Air embolism"},{"id":"C","text":"Hypercalcemia"},{"id":"D","text":"Vascular access infection"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rapid solute removal causes cerebral edema, producing headache, nausea, and confusion, especially with the first treatments.","B":"Incorrect. Air embolism presents with acute dyspnea, chest pain, and cyanosis.","C":"Incorrect. These are not classic hypercalcemia findings in this context.","D":"Incorrect. Infection presents with local redness, warmth, and fever."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', 'Disequilibrium syndrome', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343006', 'MCQ', 'A client with suspected sepsis has a lactate of 4.2 mmol/L, BP 88/52 mmHg, and warm flushed skin. After obtaining cultures, which intervention should the nurse prioritize?', 'Early sepsis with elevated lactate and hypotension is treated with prompt fluid resuscitation after cultures are drawn.', '{"options":[{"id":"A","text":"Administer a rapid isotonic crystalloid fluid bolus"},{"id":"B","text":"Apply warm blankets to raise the temperature"},{"id":"C","text":"Restrict IV fluids to prevent overload"},{"id":"D","text":"Place the client in reverse Trendelenburg"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An elevated lactate with hypotension indicates hypoperfusion; aggressive fluid resuscitation is the priority.","B":"Incorrect. This does not treat hypoperfusion.","C":"Incorrect. Fluid resuscitation is needed in early septic shock.","D":"Incorrect. This does not address the underlying hypoperfusion."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', 'Lactate and perfusion', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343007', 'MCQ', 'A client with a traumatic brain injury develops a BP of 178/60 mmHg, HR of 48 bpm, and irregular respirations. The nurse recognizes these findings as indicating which condition?', 'Cushing''s triad (hypertension with widening pulse pressure, bradycardia, irregular respirations) is a late sign of increased ICP.', '{"options":[{"id":"A","text":"Increased intracranial pressure"},{"id":"B","text":"Hypovolemic shock"},{"id":"C","text":"Neurogenic bladder"},{"id":"D","text":"Autonomic dysreflexia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Widening pulse pressure, bradycardia, and irregular respirations are Cushing''s triad, a late sign of rising ICP.","B":"Incorrect. Shock produces hypotension and tachycardia.","C":"Incorrect. This is unrelated to these vital signs.","D":"Incorrect. Dysreflexia occurs with spinal cord injury above T6, not TBI."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased intracranial pressure', 'Cushing''s triad', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343008', 'MCQ', 'A nurse reviewing telemetry notes tall, peaked T waves and a widening QRS complex in a client with renal failure. Which laboratory value best correlates with these changes?', 'Hyperkalemia produces tall peaked T waves, widened QRS, and can progress to sine-wave patterns and cardiac arrest.', '{"options":[{"id":"A","text":"Potassium 6.8 mEq/L"},{"id":"B","text":"Calcium 10.2 mg/dL"},{"id":"C","text":"Sodium 138 mEq/L"},{"id":"D","text":"Magnesium 2.0 mg/dL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Peaked T waves and a widening QRS are hallmark ECG changes of hyperkalemia.","B":"Incorrect. This is a normal calcium level.","C":"Incorrect. This is a normal sodium level and does not cause these changes.","D":"Incorrect. This is a normal magnesium level."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Telemetry monitoring', 'Hyperkalemia ECG', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343009', 'MCQ', 'A nurse is suctioning a client''s tracheostomy. Which action indicates safe technique?', 'Suction is applied only during withdrawal, limited to 10-15 seconds per pass, to minimize hypoxia and trauma.', '{"options":[{"id":"A","text":"Applying suction only while withdrawing the catheter"},{"id":"B","text":"Applying continuous suction during insertion"},{"id":"C","text":"Suctioning for 30 seconds per pass"},{"id":"D","text":"Instilling 5 mL of normal saline before each pass"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Suction is applied intermittently during withdrawal to limit hypoxia and mucosal trauma.","B":"Incorrect. Suctioning during insertion causes hypoxia and trauma.","C":"Incorrect. Each pass should not exceed 10-15 seconds.","D":"Incorrect. Routine saline instillation is not recommended."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Tracheostomy suctioning', 'Technique', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343010', 'MCQ', 'A client following a large anterior myocardial infarction has BP 82/54 mmHg, cool clammy skin, crackles, and urine output of 15 mL/hr. Which type of shock do these findings indicate?', 'Cardiogenic shock from pump failure produces hypotension, pulmonary congestion, cool skin, and oliguria.', '{"options":[{"id":"A","text":"Cardiogenic shock"},{"id":"B","text":"Distributive shock"},{"id":"C","text":"Hypovolemic shock"},{"id":"D","text":"Obstructive shock"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pump failure after a large MI causes hypotension, pulmonary congestion, and poor perfusion.","B":"Incorrect. Distributive shock typically causes warm skin and vasodilation early.","C":"Incorrect. Hypovolemia would not typically produce pulmonary crackles.","D":"Incorrect. The picture points to pump failure, not an obstructive cause."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Hemodynamics', 'Cardiogenic shock', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343011', 'MCQ', 'A postoperative client coughs and reports that the abdominal incision ''gave way,'' revealing a loop of bowel protruding through the wound. After calling for help, which action should the nurse take?', 'For evisceration, cover exposed organs with sterile saline-moistened gauze and prepare the client for emergency surgery.', '{"options":[{"id":"A","text":"Cover the wound with sterile saline-moistened gauze"},{"id":"B","text":"Reinsert the bowel gently into the abdomen"},{"id":"C","text":"Apply a dry pressure dressing"},{"id":"D","text":"Position the client with legs flat and extended"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Evisceration is managed by covering the organs with sterile saline-soaked gauze to keep them moist until surgery.","B":"Incorrect. The nurse never attempts to replace eviscerated organs.","C":"Incorrect. A dry dressing can adhere and damage exposed tissue.","D":"Incorrect. Low-Fowler''s with knees bent reduces tension on the wound."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Wound care', 'Dehiscence', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_343012', 'MCQ', 'A client with ARDS remains hypoxemic (SpO2 86%) despite a high FiO2. Which finding best explains the persistent hypoxemia?', 'ARDS produces increased capillary permeability and noncardiogenic pulmonary edema, impairing oxygen diffusion and causing refractory hypoxemia.', '{"options":[{"id":"A","text":"Increased alveolar-capillary membrane permeability causing pulmonary edema"},{"id":"B","text":"Bronchospasm from an allergic reaction"},{"id":"C","text":"Excessive mucus plugging of the large airways"},{"id":"D","text":"Left ventricular failure with elevated filling pressures"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. ARDS causes noncardiogenic pulmonary edema and impaired gas exchange, producing refractory hypoxemia.","B":"Incorrect. Bronchospasm is not the defining mechanism of ARDS.","C":"Incorrect. This is not the primary ARDS mechanism.","D":"Incorrect. ARDS is noncardiogenic pulmonary edema."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acute respiratory distress syndrome', 'Refractory hypoxemia', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_343013', 'SATA', 'A nurse assesses a client with suspected diabetic ketoacidosis. Which findings support this diagnosis? Select all that apply.', 'DKA presents with hyperglycemia, ketosis, metabolic acidosis (low bicarbonate), Kussmaul respirations, and fruity breath.', '{"options":[{"id":"A","text":"Kussmaul respirations"},{"id":"B","text":"Fruity-smelling breath"},{"id":"C","text":"Blood glucose of 480 mg/dL"},{"id":"D","text":"Serum bicarbonate of 12 mEq/L"},{"id":"E","text":"Cold, clammy skin with normal glucose"},{"id":"F","text":"Serum ketones absent"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', 'Assessment findings', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_343014', 'SATA', 'A nurse is caring for a client with a chest tube. Which observations require immediate nursing intervention? Select all that apply.', 'Disconnection, spillage, and sudden large bloody output are emergencies; tidaling and suction-chamber bubbling are expected findings.', '{"options":[{"id":"A","text":"The chest tube becomes disconnected from the drainage system"},{"id":"B","text":"The drainage collection chamber tips over and spills"},{"id":"C","text":"Sudden drainage of 200 mL of bright red blood in 15 minutes"},{"id":"D","text":"Gentle tidaling in the water-seal chamber with respiration"},{"id":"E","text":"Intermittent bubbling in the suction-control chamber"},{"id":"F","text":"The dressing at the insertion site is dry and intact"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube care', 'Emergency management', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_343015', 'SATA', 'A nurse assesses a client with fluid volume excess. Which findings would the nurse expect? Select all that apply.', 'Fluid overload produces bounding pulses, JVD, crackles, and acute weight gain; flat veins and dry membranes indicate deficit.', '{"options":[{"id":"A","text":"Bounding pulse"},{"id":"B","text":"Jugular vein distention"},{"id":"C","text":"Bilateral lung crackles"},{"id":"D","text":"Weight gain over 24 hours"},{"id":"E","text":"Flat neck veins"},{"id":"F","text":"Poor skin turgor and dry mucous membranes"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid volume excess', 'Assessment findings', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_343016', 'SATA', 'A nurse monitors a trauma client for early (compensatory) hypovolemic shock. Which findings support this stage? Select all that apply.', 'Compensatory shock produces sympathetic responses: tachycardia, vasoconstriction (cool pale skin), restlessness, and oliguria.', '{"options":[{"id":"A","text":"Tachycardia"},{"id":"B","text":"Cool, pale skin"},{"id":"C","text":"Restlessness and anxiety"},{"id":"D","text":"Decreased urine output"},{"id":"E","text":"Warm, flushed extremities"},{"id":"F","text":"Bradycardia with hypertension"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Hypovolemic shock', 'Compensatory signs', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_343017', 'SATA', 'A nurse cares for a newborn receiving phototherapy for hyperbilirubinemia. Which interventions are appropriate? Select all that apply.', 'Phototherapy requires eye protection, maximal skin exposure, and monitoring for hyperthermia and dehydration; lotions are avoided.', '{"options":[{"id":"A","text":"Apply opaque eye shields over the newborn''s eyes"},{"id":"B","text":"Keep the newborn undressed except for a diaper"},{"id":"C","text":"Monitor temperature and hydration status frequently"},{"id":"D","text":"Apply lotion or oil to the exposed skin"},{"id":"E","text":"Keep the newborn fully clothed under the lights"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', 'Newborn hyperbilirubinemia', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_343018', 'SELECT_N', 'A client in adrenal (Addisonian) crisis is admitted. Which 3 findings would the nurse expect?', 'Adrenal crisis from cortisol and aldosterone deficiency causes hypotension, hyperkalemia, and hyponatremia.', '{"options":[{"id":"A","text":"Hypotension"},{"id":"B","text":"Hyperkalemia"},{"id":"C","text":"Hyponatremia"},{"id":"D","text":"Hypertension"},{"id":"E","text":"Hypokalemia"},{"id":"F","text":"Hypernatremia"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Addisonian crisis', 'Priority findings', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_343019', 'TF', 'If a client''s chest tube is accidentally pulled out of the chest, the nurse''s first action should be to clamp the insertion site tightly with a hemostat.', 'If a chest tube dislodges, the nurse covers the site with a sterile occlusive dressing taped on three sides to create a flutter valve, not a clamp.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube emergency', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_343020', 'TF', 'A client with a spinal cord injury at T4 who develops a sudden pounding headache and blood pressure of 200/110 mmHg should first be placed in a sitting position while the nurse searches for the triggering stimulus.', 'Autonomic dysreflexia is a hypertensive emergency; sitting the client up lowers cerebral pressure while the trigger, often a full bladder, is removed.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Autonomic dysreflexia', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_343021', 'MATRIX', 'For each arterial blood gas result, click to specify whether it reflects respiratory acidosis or metabolic acidosis.', 'A high PaCO2 with low pH is respiratory acidosis; a low HCO3 with low pH and normal PaCO2 is metabolic acidosis.', '{"row_label":"Arterial blood gas","rows":[{"id":"r1","text":"pH 7.30, PaCO2 55 mmHg, HCO3 24 mEq/L"},{"id":"r2","text":"pH 7.28, PaCO2 38 mmHg, HCO3 16 mEq/L"},{"id":"r3","text":"pH 7.31, PaCO2 60 mmHg, HCO3 26 mEq/L"},{"id":"r4","text":"pH 7.25, PaCO2 36 mmHg, HCO3 14 mEq/L"}],"columns":[{"id":"c1","text":"Respiratory acidosis"},{"id":"c2","text":"Metabolic acidosis"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acid-base imbalance', 'ABG interpretation', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_343022', 'MATRIX', 'For each clinical finding, click to specify whether it is more characteristic of diabetic ketoacidosis (DKA) or hyperosmolar hyperglycemic state (HHS).', 'DKA features ketosis, Kussmaul breathing, and acidosis; HHS features extreme hyperglycemia and dehydration with little ketosis.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Marked ketosis and fruity breath"},{"id":"r2","text":"Glucose often above 600 mg/dL with minimal ketones"},{"id":"r3","text":"Kussmaul respirations"},{"id":"r4","text":"Profound dehydration in an older adult with type 2 diabetes"}],"columns":[{"id":"c1","text":"DKA"},{"id":"c2","text":"HHS"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Glycemic emergencies', 'DKA vs HHS', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_343023', 'MATRIX_MR', 'For each electrolyte imbalance, select all clinical findings commonly associated with it (more than one may apply).', 'Potassium imbalances cause weakness and dysrhythmias; hypocalcemia causes neuromuscular irritability (Trousseau sign) and dysrhythmias.', '{"row_label":"Electrolyte imbalance","rows":[{"id":"r1","text":"Hypokalemia"},{"id":"r2","text":"Hyperkalemia"},{"id":"r3","text":"Hypocalcemia"}],"columns":[{"id":"c1","text":"Muscle weakness"},{"id":"c2","text":"Cardiac dysrhythmia"},{"id":"c3","text":"Positive Trousseau sign"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c1","c2"],"r3":["c2","c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Electrolyte imbalance', 'Associated findings', 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_343024', 'CLOZE', 'A client''s serum sodium is 122 mEq/L. The nurse recognizes this as {1} and monitors most closely for {2}.', 'A sodium of 122 mEq/L is hyponatremia, which causes cerebral edema and neurologic changes such as confusion and seizures.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"hyponatremia"},{"id":"c2","text":"hypernatremia"},{"id":"c3","text":"hyperkalemia"}]},{"id":"b2","choices":[{"id":"c1","text":"seizures and altered mental status"},{"id":"c2","text":"constipation"},{"id":"c3","text":"hypertension"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid and electrolyte imbalance', 'Hyponatremia', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_343025', 'CLOZE', 'A client with a core temperature of 41°C, hot dry skin, and confusion is experiencing {1}. The nurse''s priority intervention is {2}.', 'Heat stroke is a life-threatening failure of thermoregulation; priority care is rapid cooling to lower the core temperature.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"heat stroke"},{"id":"c2","text":"heat cramps"},{"id":"c3","text":"hypothermia"}]},{"id":"b2","choices":[{"id":"c1","text":"rapid active cooling"},{"id":"c2","text":"applying warm blankets"},{"id":"c3","text":"restricting all fluids"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Temperature regulation', 'Heat stroke', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_343026', 'HIGHLIGHT', 'A nurse assesses a postoperative client. Highlight the findings that indicate a possible pulmonary embolism. The client reports [[sudden sharp chest pain]] and [[shortness of breath]]. Respiratory rate is [[32 breaths/min]]. SpO2 is [[88% on room air]]. Temperature is [[37.1°C]]. Bowel sounds are [[present in all quadrants]].', 'Sudden pleuritic chest pain, dyspnea, tachypnea, and hypoxemia point to pulmonary embolism; normal temperature and bowel sounds do not.', '{"chunks":[{"id":"h1","text":"sudden sharp chest pain"},{"id":"h2","text":"shortness of breath"},{"id":"h3","text":"32 breaths/min"},{"id":"h4","text":"88% on room air"},{"id":"h5","text":"37.1°C"},{"id":"h6","text":"present in all quadrants"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Pleuritic chest pain is a classic PE symptom.","h2":"Acute dyspnea is a hallmark of PE.","h3":"Tachypnea is an expected PE finding.","h4":"Hypoxemia supports PE.","h5":"This temperature is essentially normal.","h6":"Normal bowel sounds are unrelated to PE."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Complication recognition', 'Pulmonary embolism', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_343027', 'BOWTIE', 'A client develops muffled heart sounds, jugular vein distention, and hypotension after cardiac surgery. Complete the diagram by selecting the actions to take, the condition, and the parameters to monitor.', 'Beck''s triad (muffled heart sounds, JVD, hypotension) signals cardiac tamponade requiring urgent notification, pericardiocentesis, and hemodynamic monitoring.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Notify the surgeon immediately"},{"id":"lt2","text":"Prepare for pericardiocentesis"},{"id":"lt3","text":"Encourage the client to ambulate"},{"id":"lt4","text":"Restrict IV fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Cardiac tamponade"},{"id":"ct2","text":"Pulmonary edema"},{"id":"ct3","text":"Deep vein thrombosis"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Blood pressure and pulse pressure"},{"id":"rt2","text":"Heart sounds and central venous pressure"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Complication recognition', 'Cardiac tamponade', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_343028', 'DRAG_ORDER', 'A client with hyperthyroidism develops thyroid storm with a temperature of 40.5°C, HR 160 bpm, and agitation. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Ensure a patent airway and administer oxygen"},{"id":"t2","text":"Apply a cooling blanket to lower temperature"},{"id":"t3","text":"Administer prescribed beta-blocker and antithyroid medication"},{"id":"t4","text":"Continuously monitor cardiac rhythm and vital signs"},{"id":"t5","text":"Document the interventions and response"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Emergency care procedures', 'Thyroid storm', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344001', 'MCQ', 'A nurse observes that the water-seal chamber of a client''s chest drainage system no longer fluctuates (tidals) with respiration. The client had continuous tidaling since insertion. Which action should the nurse take FIRST?', 'Absent tidaling signals either lung re-expansion or an obstruction; the nurse assesses the tubing for kinks/loops before other actions.', '{"options":[{"id":"A","text":"Check the tubing for kinks or dependent loops"},{"id":"B","text":"Clamp the chest tube and notify the provider"},{"id":"C","text":"Strip and milk the entire length of tubing"},{"id":"D","text":"Increase the wall suction pressure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cessation of tidaling most often means the tubing is obstructed or the lung has re-expanded; assess for obstruction first.","B":"Incorrect. Clamping a functioning chest tube risks tension pneumothorax.","C":"Incorrect. Aggressive stripping generates high negative pressure and is not the first assessment.","D":"Incorrect. Suction is set by the water column, not wall pressure, and this does not address obstruction."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Tidaling', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344002', 'MCQ', 'A client on a volume-controlled ventilator triggers a high-pressure alarm. The client is coughing and the SpO2 is dropping. Which is the most likely cause the nurse should address?', 'High-pressure alarms reflect increased resistance/decreased compliance—commonly secretions, coughing, or biting; suctioning addresses the obstruction.', '{"options":[{"id":"A","text":"Secretions obstructing the airway"},{"id":"B","text":"A disconnection at the ventilator circuit"},{"id":"C","text":"A cuff leak around the endotracheal tube"},{"id":"D","text":"The tidal volume set too low"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Increased airway resistance from secretions raises peak pressure; suctioning is indicated.","B":"Incorrect. A disconnection triggers a low-pressure alarm.","C":"Incorrect. A leak lowers pressure and triggers a low-pressure alarm.","D":"Incorrect. Low tidal volume does not raise peak airway pressure."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', 'High-pressure alarm', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344003', 'MCQ', 'A nurse is caring for a client with a newly placed arteriovenous (AV) fistula in the left arm. Which finding requires immediate provider notification?', 'A patent fistula has a palpable thrill and audible bruit; loss of both signals thrombosis requiring urgent intervention.', '{"options":[{"id":"A","text":"Absence of a bruit and thrill over the fistula"},{"id":"B","text":"A palpable thrill on light palpation"},{"id":"C","text":"Mild bruising at the surgical site"},{"id":"D","text":"An audible swishing sound on auscultation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A missing bruit/thrill indicates the fistula has clotted—an emergency for access patency.","B":"Incorrect. A thrill is the expected sign of a patent fistula.","C":"Incorrect. Mild bruising after placement is expected.","D":"Incorrect. A bruit is the normal auscultatory finding of patency."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', 'AV fistula', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344004', 'MCQ', 'On the first postoperative day, a nurse assesses a new colostomy and notes the stoma is dusky purple and dry. What does this finding indicate?', 'A viable stoma is pink/red and moist; a purple, dusky, or dry stoma indicates ischemia or necrosis requiring urgent reporting.', '{"options":[{"id":"A","text":"Compromised blood supply to the stoma"},{"id":"B","text":"Normal expected postoperative appearance"},{"id":"C","text":"Adequate perfusion with mild edema"},{"id":"D","text":"Expected bruising from surgical manipulation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dusky, dark, or dry stoma signals ischemia and must be reported immediately.","B":"Incorrect. A healthy stoma is pink-to-red, moist, and shiny.","C":"Incorrect. Adequate perfusion produces a pink/red color.","D":"Incorrect. Dusky/purple with dryness reflects ischemia, not simple bruising."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', 'Stoma assessment', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344005', 'MCQ', 'A client with a urinary tract infection has a temperature of 38.9°C, heart rate 112, respiratory rate 24, and blood pressure 92/56. Lactate is 3.2 mmol/L. Which condition should the nurse suspect?', 'A known infection with SIRS criteria, hypotension, and lactate >2 mmol/L reflects sepsis with hypoperfusion.', '{"options":[{"id":"A","text":"Sepsis with hypoperfusion"},{"id":"B","text":"Simple dehydration"},{"id":"C","text":"An anaphylactic reaction"},{"id":"D","text":"Neurogenic shock"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Infection plus tachycardia, tachypnea, hypotension, and elevated lactate indicate sepsis with tissue hypoperfusion.","B":"Incorrect. Dehydration does not explain the elevated lactate with a known infection source.","C":"Incorrect. There is no allergen exposure, wheezing, or urticaria described.","D":"Incorrect. Neurogenic shock features bradycardia, not tachycardia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', 'Early recognition', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344006', 'MCQ', 'A nurse monitors a client with a traumatic brain injury and notes blood pressure rising to 168/62, heart rate 48, and irregular respirations. Which complication do these findings indicate?', 'The Cushing triad—hypertension with widened pulse pressure, bradycardia, and irregular respirations—is a late sign of increased ICP.', '{"options":[{"id":"A","text":"Increased intracranial pressure (Cushing triad)"},{"id":"B","text":"Hypovolemic shock"},{"id":"C","text":"Autonomic dysreflexia"},{"id":"D","text":"Diabetes insipidus"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Widening pulse pressure, bradycardia, and irregular respirations are the Cushing triad of rising ICP.","B":"Incorrect. Hypovolemic shock causes hypotension and tachycardia.","C":"Incorrect. Dysreflexia occurs with spinal cord injury above T6, not TBI.","D":"Incorrect. DI presents with polyuria and hypernatremia, not this vital-sign pattern."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased intracranial pressure', 'Cushing triad', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344007', 'MCQ', 'A client in diabetic ketoacidosis is receiving an insulin infusion. The serum potassium is now 3.3 mEq/L. Which action should the nurse anticipate?', 'Insulin shifts potassium intracellularly; a level of 3.3 mEq/L requires replacement to avoid dangerous hypokalemia during DKA treatment.', '{"options":[{"id":"A","text":"Adding potassium replacement to the IV fluids"},{"id":"B","text":"Stopping the insulin infusion permanently"},{"id":"C","text":"Administering sodium bicarbonate"},{"id":"D","text":"Restricting all IV fluids"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Insulin drives potassium into cells; with a low level, replacement is added to prevent life-threatening hypokalemia.","B":"Incorrect. Insulin is needed to correct the ketoacidosis; potassium is replaced instead.","C":"Incorrect. Bicarbonate is reserved for severe acidosis and would worsen hypokalemia.","D":"Incorrect. DKA requires aggressive fluid resuscitation."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', 'Potassium management', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344008', 'MCQ', 'A telemetry monitor shows a wide-complex regular rhythm at 180 bpm. The client is alert, reports palpitations, and has a blood pressure of 118/70. Which is the nurse''s priority action?', 'Stable (perfusing) ventricular tachycardia is managed with antiarrhythmics; defibrillation is reserved for pulseless rhythms.', '{"options":[{"id":"A","text":"Prepare for antiarrhythmic administration per protocol"},{"id":"B","text":"Deliver an unsynchronized defibrillation shock"},{"id":"C","text":"Begin chest compressions immediately"},{"id":"D","text":"Withhold treatment and continue monitoring"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stable ventricular tachycardia with a pulse is treated pharmacologically per ACLS.","B":"Incorrect. Defibrillation is for pulseless VT/VF, not a stable client with a pulse.","C":"Incorrect. The client has a pulse and is alert; CPR is not indicated.","D":"Incorrect. Sustained VT requires intervention even when the client is stable."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Telemetry', 'Ventricular tachycardia', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344009', 'MCQ', 'A newborn is receiving phototherapy for hyperbilirubinemia. Which nursing action best supports safe and effective treatment?', 'Effective phototherapy requires eye protection, maximal skin exposure, frequent repositioning, and increased feedings to excrete bilirubin.', '{"options":[{"id":"A","text":"Cover the newborn''s eyes and maximize skin exposure"},{"id":"B","text":"Dress the newborn warmly and limit feedings"},{"id":"C","text":"Apply lotion to the skin before therapy"},{"id":"D","text":"Keep the newborn under lights continuously without repositioning"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Eye shields prevent retinal damage while maximal skin exposure increases light-mediated bilirubin breakdown.","B":"Incorrect. Clothing blocks light and feedings must increase to promote bilirubin excretion.","C":"Incorrect. Lotions can cause burns under phototherapy lights.","D":"Incorrect. Frequent repositioning exposes all skin surfaces and prevents pressure areas."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', 'Neonatal hyperbilirubinemia', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344010', 'MCQ', 'A client on peritoneal dialysis reports abdominal pain, and the nurse notes cloudy dialysate return and a fever. Which complication should the nurse suspect?', 'Cloudy dialysate outflow with abdominal pain and fever indicates peritonitis, the most common serious PD complication.', '{"options":[{"id":"A","text":"Peritonitis"},{"id":"B","text":"Catheter migration"},{"id":"C","text":"Dialysate leak"},{"id":"D","text":"Hypervolemia"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cloudy effluent with abdominal pain and fever is the hallmark of PD-associated peritonitis.","B":"Incorrect. Migration causes poor drainage, not cloudy fluid with fever.","C":"Incorrect. A leak presents as fluid at the exit site, not cloudy return with fever.","D":"Incorrect. Hypervolemia causes edema and hypertension, not cloudy effluent."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', 'Peritonitis', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344011', 'MCQ', 'A nurse is performing endotracheal suctioning on a client whose heart rate drops from 88 to 52 during the procedure. What should the nurse do FIRST?', 'Suction-induced bradycardia signals vagal response and hypoxemia; the nurse stops and oxygenates before proceeding.', '{"options":[{"id":"A","text":"Stop suctioning and oxygenate the client"},{"id":"B","text":"Increase the suction pressure to finish quickly"},{"id":"C","text":"Continue suctioning for a full 30 seconds"},{"id":"D","text":"Instill saline and repeat the pass"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Bradycardia during suctioning reflects vagal stimulation/hypoxia; stopping and hyperoxygenating restores stability.","B":"Incorrect. Higher pressure worsens hypoxia and mucosal trauma.","C":"Incorrect. Prolonged suctioning intensifies hypoxia and bradycardia.","D":"Incorrect. Saline instillation is not evidence-based and delays reoxygenation."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Suctioning', 'Complication prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344012', 'MCQ', 'A client with acute kidney injury has a potassium of 6.8 mEq/L. The ECG shows peaked T waves and a widening QRS. Which prescription should the nurse anticipate administering FIRST?', 'With ECG changes of severe hyperkalemia, IV calcium is given first to stabilize the myocardium before potassium-lowering measures.', '{"options":[{"id":"A","text":"IV calcium gluconate"},{"id":"B","text":"Oral sodium polystyrene sulfonate"},{"id":"C","text":"Intravenous furosemide alone"},{"id":"D","text":"A potassium-sparing diuretic"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Calcium gluconate stabilizes the cardiac membrane immediately, protecting against lethal arrhythmias.","B":"Incorrect. It removes potassium slowly and does not protect the heart acutely.","C":"Incorrect. Diuresis is limited in AKI and is not the immediate cardioprotective step.","D":"Incorrect. This would raise potassium further."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Fluid and electrolyte imbalance', 'Hyperkalemia', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_344013', 'MCQ', 'A postoperative client coughs and suddenly reports that the abdominal incision has ''given way.'' The nurse observes a loop of bowel protruding through the wound. What is the nurse''s priority action?', 'For wound evisceration, cover the viscera with sterile saline-soaked gauze, position with knees flexed, and notify the surgeon urgently.', '{"options":[{"id":"A","text":"Cover the wound with sterile saline-moistened gauze"},{"id":"B","text":"Attempt to reinsert the bowel into the abdomen"},{"id":"C","text":"Apply a dry pressure dressing firmly"},{"id":"D","text":"Position the client with legs flat and straight"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Evisceration requires covering exposed viscera with sterile moist dressings to prevent drying while awaiting surgery.","B":"Incorrect. Never push exposed organs back in; this causes contamination and injury.","C":"Incorrect. Dry pressure damages exposed tissue; moist coverage is required.","D":"Incorrect. Low-Fowler with knees bent reduces abdominal tension."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Wound care', 'Dehiscence', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_344014', 'SATA', 'A nurse assesses a client with suspected hypovolemic shock. Which findings support this diagnosis? Select all that apply.', 'Hypovolemic shock produces compensatory tachycardia, vasoconstriction (cool clammy skin), oliguria, and a narrowed pulse pressure.', '{"options":[{"id":"A","text":"Tachycardia"},{"id":"B","text":"Cool, clammy skin"},{"id":"C","text":"Decreased urine output"},{"id":"D","text":"Narrowing pulse pressure"},{"id":"E","text":"Bounding peripheral pulses"},{"id":"F","text":"Warm, flushed skin"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Shock', 'Hypovolemic shock', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_344015', 'SATA', 'A nurse discovers that a client''s chest tube has become disconnected from the drainage system. Which actions are appropriate? Select all that apply.', 'A disconnected chest tube is placed in sterile water to re-establish a water seal while assessing the client and setting up a new system.', '{"options":[{"id":"A","text":"Submerge the end of the chest tube in sterile water"},{"id":"B","text":"Notify the provider"},{"id":"C","text":"Assess respiratory status and oxygen saturation"},{"id":"D","text":"Prepare a new sterile drainage system"},{"id":"E","text":"Clamp the chest tube for an extended period"},{"id":"F","text":"Reconnect using non-sterile tape without cleaning"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Emergency response', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_344016', 'SATA', 'A client with Addison''s disease is admitted in adrenal crisis. Which findings does the nurse expect? Select all that apply.', 'Cortisol and aldosterone deficiency in adrenal crisis produce hypotension, hyperkalemia, hyponatremia, and hypoglycemia.', '{"options":[{"id":"A","text":"Hypotension"},{"id":"B","text":"Hyperkalemia"},{"id":"C","text":"Hyponatremia"},{"id":"D","text":"Hypoglycemia"},{"id":"E","text":"Hypertension"},{"id":"F","text":"Hypokalemia"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Addisonian crisis', 'Acute adrenal insufficiency', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_344017', 'SATA', 'A nurse assesses a client with worsening pneumonia for signs of impaired oxygenation. Which findings indicate hypoxemia? Select all that apply.', 'Early hypoxemia causes restlessness, tachypnea, and accessory muscle use; central cyanosis is a late sign.', '{"options":[{"id":"A","text":"Restlessness and confusion"},{"id":"B","text":"Tachypnea"},{"id":"C","text":"Use of accessory muscles"},{"id":"D","text":"Central cyanosis"},{"id":"E","text":"Bradypnea with calm affect"},{"id":"F","text":"Warm dry skin with slow respirations"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acute respiratory distress', 'Hypoxemia recognition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_344018', 'SATA', 'A nurse monitors a client 2 days after abdominal surgery for paralytic ileus. Which assessment findings support this complication? Select all that apply.', 'Paralytic ileus presents with absent bowel sounds, distension, no flatus, and nausea/vomiting from stalled peristalsis.', '{"options":[{"id":"A","text":"Absent bowel sounds"},{"id":"B","text":"Abdominal distension"},{"id":"C","text":"Failure to pass flatus"},{"id":"D","text":"Nausea and vomiting"},{"id":"E","text":"Frequent loose stools"},{"id":"F","text":"Hyperactive high-pitched bowel sounds"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Postoperative care', 'Paralytic ileus', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_344019', 'SATA', 'A client is brought to the emergency department with suspected heat stroke. Which interventions are appropriate? Select all that apply.', 'Heat stroke is managed with active external cooling, fluid resuscitation, and continuous temperature monitoring; antipyretics are ineffective for environmental hyperthermia.', '{"options":[{"id":"A","text":"Remove excess clothing"},{"id":"B","text":"Apply cool packs to the axillae and groin"},{"id":"C","text":"Initiate IV fluid resuscitation"},{"id":"D","text":"Monitor core temperature continuously"},{"id":"E","text":"Administer antipyretics as the primary cooling method"},{"id":"F","text":"Wrap the client in warm blankets"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Temperature regulation', 'Heat stroke', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_344020', 'SELECT_N', 'A client''s serum magnesium is 1.1 mEq/L. Which 3 findings should the nurse expect with this imbalance?', 'Hypomagnesemia increases neuromuscular excitability—positive Trousseau''s, hyperreflexia—and predisposes to torsades de pointes.', '{"options":[{"id":"A","text":"Positive Trousseau''s sign"},{"id":"B","text":"Hyperactive deep tendon reflexes"},{"id":"C","text":"Cardiac dysrhythmias (torsades de pointes)"},{"id":"D","text":"Diminished deep tendon reflexes"},{"id":"E","text":"Bradycardia with warm flushed skin"},{"id":"F","text":"Respiratory depression"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Fluid and electrolyte imbalance', 'Hypomagnesemia', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_344021', 'TF', 'Continuous bubbling in the water-seal chamber of a chest drainage system during both inspiration and expiration is a normal, expected finding.', 'Continuous bubbling in the water-seal chamber indicates an air leak in the system and must be investigated, not a normal finding.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tube management', 'Air leak', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_344022', 'MATRIX', 'For each arterial blood gas result, click to classify the primary acid-base disturbance.', 'A high PaCO2 with low pH indicates respiratory acidosis; a low HCO3 with low pH and normal/low PaCO2 indicates metabolic acidosis.', '{"row_label":"Arterial blood gas","rows":[{"id":"r1","text":"pH 7.28, PaCO2 58, HCO3 25 (COPD exacerbation)"},{"id":"r2","text":"pH 7.30, PaCO2 38, HCO3 16 (diabetic ketoacidosis)"},{"id":"r3","text":"pH 7.26, PaCO2 60, HCO3 26 (opioid overdose, hypoventilation)"},{"id":"r4","text":"pH 7.25, PaCO2 36, HCO3 14 (severe diarrhea)"}],"columns":[{"id":"c1","text":"Respiratory acidosis"},{"id":"c2","text":"Metabolic acidosis"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acid-base balance', 'ABG interpretation', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_344023', 'MATRIX_MR', 'For each clinical feature, select all types of shock in which it is commonly seen.', 'Tachycardia is common to all shock states; early septic shock causes warm vasodilated skin; cardiogenic shock produces congestion; hypovolemia stems from fluid loss.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Tachycardia"},{"id":"r2","text":"Warm flushed skin in early phase"},{"id":"r3","text":"Jugular venous distension/pulmonary congestion"},{"id":"r4","text":"Fluid loss as the primary trigger"}],"columns":[{"id":"c1","text":"Hypovolemic"},{"id":"c2","text":"Septic"},{"id":"c3","text":"Cardiogenic"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c2"],"r3":["c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Shock', 'Shock classification', 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_344024', 'CLOZE', 'A client with a small-cell lung cancer has a serum sodium of 118 mEq/L, concentrated urine, and low serum osmolality. The nurse recognizes these findings are consistent with {1}, and the priority intervention is {2}.', 'SIADH causes dilutional hyponatremia with concentrated urine and low serum osmolality; fluid restriction is the cornerstone treatment.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"SIADH"},{"id":"c2","text":"diabetes insipidus"},{"id":"c3","text":"adrenal crisis"}]},{"id":"b2","choices":[{"id":"c1","text":"fluid restriction"},{"id":"c2","text":"administering IV free water"},{"id":"c3","text":"encouraging increased oral fluids"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'SIADH', 'Sodium imbalance', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_344025', 'HIGHLIGHT', 'A nurse assesses a client 6 hours after cardiac surgery. Highlight the findings that suggest cardiac tamponade. The client is alert. Blood pressure [[86/68]]. Heart sounds are [[muffled and distant]]. There is [[jugular venous distension]]. Temperature is [[37.1°C]]. The chest-tube drainage has [[abruptly stopped]]. Skin is warm and dry.', 'Cardiac tamponade features Beck''s triad—hypotension with narrowed pulse pressure, muffled heart sounds, and JVD—often with an abrupt drop in chest-tube output.', '{"chunks":[{"id":"h1","text":"86/68"},{"id":"h2","text":"muffled and distant"},{"id":"h3","text":"jugular venous distension"},{"id":"h4","text":"37.1°C"},{"id":"h5","text":"abruptly stopped"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h5"],"feedback":{"h1":"Narrowed pulse pressure/hypotension is part of Beck''s triad.","h2":"Muffled heart sounds are a classic tamponade sign.","h3":"JVD from impaired venous return completes Beck''s triad.","h4":"A normal temperature is unrelated to tamponade.","h5":"Sudden cessation of chest-tube drainage can precede tamponade from clot accumulation."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Complication recognition', 'Cardiac tamponade', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_344026', 'BOWTIE', 'A postoperative client suddenly develops dyspnea, pleuritic chest pain, tachycardia, and a drop in SpO2. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Acute PE is managed with oxygen and upright positioning while monitoring oxygenation and respiratory status; ambulation and calf massage risk dislodging further emboli.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer supplemental oxygen"},{"id":"lt2","text":"Elevate the head of the bed"},{"id":"lt3","text":"Encourage vigorous ambulation"},{"id":"lt4","text":"Massage the affected calf"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Pulmonary embolism"},{"id":"ct2","text":"Pneumothorax"},{"id":"ct3","text":"Myocardial infarction"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Oxygen saturation"},{"id":"rt2","text":"Respiratory rate and effort"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Pulmonary embolism', 'Acute complication', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_344027', 'DRAG_CLOZE', 'A client with hyperparathyroidism has a serum calcium of [1] mg/dL, and the nurse expects the deep tendon reflexes to be [2].', 'Hyperparathyroidism causes hypercalcemia (calcium ~12.5 mg/dL), which depresses neuromuscular excitability and diminishes deep tendon reflexes.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"12.5"},{"id":"t2","text":"diminished"},{"id":"t3","text":"9.0"},{"id":"t4","text":"brisk"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Fluid and electrolyte imbalance', 'Hypercalcemia', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_344028', 'DRAG_ORDER', 'A client is experiencing thyroid storm with fever 40°C, heart rate 160, and agitation. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Ensure a patent airway and apply oxygen"},{"id":"t2","text":"Initiate active cooling measures"},{"id":"t3","text":"Administer prescribed beta-blocker and antithyroid medication"},{"id":"t4","text":"Continuously monitor cardiac rhythm"},{"id":"t5","text":"Document the interventions and response"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Emergency care procedures', 'Thyroid storm', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345001', 'MCQ', 'A nurse observes continuous vigorous bubbling in the water-seal chamber of a client''s closed chest drainage system. What does this finding most likely indicate?', 'Continuous bubbling in the water-seal chamber indicates an air leak somewhere between the client and the system.', '{"options":[{"id":"A","text":"An air leak in the system"},{"id":"B","text":"Normal lung re-expansion"},{"id":"C","text":"Adequate suction pressure"},{"id":"D","text":"Complete drainage of pleural fluid"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Continuous bubbling in the water-seal chamber signals an air leak that must be located.","B":"Incorrect. Intermittent bubbling with respiration is normal, not continuous vigorous bubbling.","C":"Incorrect. Suction is regulated in the suction-control chamber, not the water seal.","D":"Incorrect. Fluid drainage collects in the collection chamber."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tubes', 'Water-seal chamber', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345002', 'MCQ', 'A client with diabetic ketoacidosis is receiving an IV insulin infusion. The serum glucose has fallen to 250 mg/dL. Which prescription should the nurse anticipate next?', 'When glucose reaches ~200-250 mg/dL in DKA, dextrose is added so insulin can continue clearing ketones without causing hypoglycemia.', '{"options":[{"id":"A","text":"Add dextrose 5% to the IV fluids"},{"id":"B","text":"Stop the insulin infusion immediately"},{"id":"C","text":"Administer a 50 mL bolus of D50"},{"id":"D","text":"Give an oral hypoglycemic agent"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Dextrose is added at ~200-250 mg/dL to prevent hypoglycemia while the insulin continues clearing ketones.","B":"Incorrect. Insulin must continue to close the anion gap and clear ketones.","C":"Incorrect. The client is not hypoglycemic; a bolus is not indicated.","D":"Incorrect. Oral agents have no role in acute DKA management."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345003', 'MCQ', 'A high-pressure alarm sounds on the ventilator of an intubated client. The nurse notes the client is biting the tube and coughing. Which action should the nurse take first?', 'High-pressure alarms indicate increased airway resistance; assessing for secretions, biting, or kinks addresses the common causes.', '{"options":[{"id":"A","text":"Suction the airway and assess for secretions or kinks"},{"id":"B","text":"Increase the tidal volume"},{"id":"C","text":"Check all tubing connections for disconnection"},{"id":"D","text":"Silence the alarm and continue monitoring"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A high-pressure alarm reflects increased resistance, often from secretions, biting, or kinking.","B":"Incorrect. Raising tidal volume worsens the pressure problem.","C":"Incorrect. Disconnection causes a low-pressure alarm, not high-pressure.","D":"Incorrect. Silencing without addressing the cause is unsafe."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Mechanical ventilation', 'High-pressure alarm', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345004', 'MCQ', 'A nurse is caring for a client with a newly matured arteriovenous fistula in the left arm. Which action protects the access?', 'Blood pressure measurement, venipuncture, and constriction on the fistula arm can thrombose or damage the access and are avoided.', '{"options":[{"id":"A","text":"Ensure no blood pressures or venipunctures are taken in the left arm"},{"id":"B","text":"Apply a warm compress and elevate the arm continuously"},{"id":"C","text":"Keep the arm wrapped in an elastic bandage"},{"id":"D","text":"Palpate for a pulse but avoid checking for a thrill"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pressure and punctures on the fistula arm can cause clotting or damage the access.","B":"Incorrect. Continuous elevation is not required and warmth is not a routine measure.","C":"Incorrect. Constrictive wraps compromise flow through the fistula.","D":"Incorrect. The nurse should assess for a thrill and bruit to confirm patency."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Hemodialysis', 'AV fistula', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345005', 'MCQ', 'A client with suspected sepsis has a lactate of 4.2 mmol/L and a blood pressure of 82/48 mmHg after a 30 mL/kg crystalloid bolus. Which intervention should the nurse anticipate next?', 'Septic shock with hypotension refractory to fluid resuscitation requires a vasopressor; norepinephrine is first-line.', '{"options":[{"id":"A","text":"Initiate a norepinephrine infusion"},{"id":"B","text":"Administer a diuretic to improve urine output"},{"id":"C","text":"Withhold further fluids and reassess in 4 hours"},{"id":"D","text":"Give a beta-blocker to control the heart rate"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Persistent hypotension after adequate fluids indicates a vasopressor, with norepinephrine first-line.","B":"Incorrect. Diuretics worsen hypotension in a hypoperfused client.","C":"Incorrect. A 4-hour delay in refractory septic shock is dangerous.","D":"Incorrect. Beta-blockade further lowers cardiac output and pressure."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Sepsis', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345006', 'MCQ', 'A nurse caring for a client with a head injury notes a rising blood pressure, widening pulse pressure, and bradycardia. How should the nurse interpret these findings?', 'Cushing''s triad (hypertension, widening pulse pressure, bradycardia) signals dangerously elevated intracranial pressure.', '{"options":[{"id":"A","text":"Cushing''s triad indicating increased intracranial pressure"},{"id":"B","text":"Early compensated hypovolemic shock"},{"id":"C","text":"An expected response to pain"},{"id":"D","text":"Normal autonomic variation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hypertension with widening pulse pressure and bradycardia is Cushing''s triad, a late ICP sign.","B":"Incorrect. Hypovolemic shock produces tachycardia and narrowing pulse pressure.","C":"Incorrect. Pain typically raises heart rate, not lowers it.","D":"Incorrect. This triad is a neurologic emergency."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Neurological', 'Increased intracranial pressure', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345007', 'MCQ', 'A neonate with hyperbilirubinemia is placed under phototherapy. Which nursing action is most important during treatment?', 'During phototherapy the neonate''s eyes are shielded to prevent retinal damage while maximizing skin exposure.', '{"options":[{"id":"A","text":"Cover the neonate''s eyes with opaque shields"},{"id":"B","text":"Dress the neonate in a cotton shirt"},{"id":"C","text":"Apply lotion to the exposed skin"},{"id":"D","text":"Limit feedings to reduce stooling"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Eye shields protect the retina from phototherapy light damage.","B":"Incorrect. Skin exposure is maximized (only diaper) to increase effectiveness.","C":"Incorrect. Lotions can cause burns under phototherapy lights.","D":"Incorrect. Frequent feeding promotes bilirubin excretion in stool."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Pediatrics', 'Hematologic', 'Phototherapy', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345008', 'MCQ', 'A client with a new ileostomy reports the output has become watery and increased to over 1500 mL in 8 hours. Which complication should the nurse monitor for most closely?', 'Ileostomy effluent is liquid and rich in electrolytes; high output leads to dehydration and electrolyte imbalance.', '{"options":[{"id":"A","text":"Fluid and electrolyte imbalance"},{"id":"B","text":"Constipation"},{"id":"C","text":"Stomal prolapse"},{"id":"D","text":"Wound dehiscence"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. High-volume liquid ileostomy output causes dehydration and sodium/potassium loss.","B":"Incorrect. Liquid high-volume output is the opposite of constipation.","C":"Incorrect. Prolapse is unrelated to output volume changes.","D":"Incorrect. Dehiscence is not indicated by output changes."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Ostomy care', 'Ileostomy', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345009', 'MCQ', 'A client in acute kidney injury has a serum potassium of 6.8 mEq/L and peaked T waves on the ECG. Which prescribed medication should the nurse administer first to protect the heart?', 'With ECG changes from hyperkalemia, IV calcium gluconate is given first to stabilize the cardiac membrane before potassium-lowering measures.', '{"options":[{"id":"A","text":"IV calcium gluconate"},{"id":"B","text":"Oral sodium polystyrene sulfonate"},{"id":"C","text":"IV regular insulin with dextrose"},{"id":"D","text":"Oral potassium-sparing diuretic"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Calcium gluconate stabilizes the cardiac membrane immediately, protecting against arrhythmias.","B":"Incorrect. It lowers potassium but acts slowly and does not protect the myocardium.","C":"Incorrect. This shifts potassium intracellularly but does not stabilize the membrane first.","D":"Incorrect. This would worsen hyperkalemia."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid and electrolyte imbalance', 'Hyperkalemia', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345010', 'MCQ', 'A client has a temporary transvenous pacemaker set at a rate of 70. The nurse notes on the monitor pacer spikes that are not followed by a QRS complex. How should the nurse interpret this?', 'Pacer spikes not followed by a QRS complex indicate failure to capture, meaning the electrical stimulus is not depolarizing the heart.', '{"options":[{"id":"A","text":"Failure to capture"},{"id":"B","text":"Failure to sense"},{"id":"C","text":"Normal pacemaker function"},{"id":"D","text":"Oversensing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Pacer spikes without a subsequent QRS indicate the stimulus is not depolarizing the myocardium (failure to capture).","B":"Incorrect. Failure to sense produces spikes falling on intrinsic beats.","C":"Incorrect. Each spike should be followed by a paced complex.","D":"Incorrect. Oversensing causes inappropriate inhibition, not spikes without capture."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Pacing devices', 'Temporary pacemaker', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345011', 'MCQ', 'A client with acute respiratory distress syndrome remains hypoxemic despite a high FiO2. The provider increases positive end-expiratory pressure (PEEP). The nurse understands the primary benefit of PEEP is to:', 'PEEP maintains alveolar patency at end-expiration, recruiting alveoli and improving oxygenation in ARDS.', '{"options":[{"id":"A","text":"Keep alveoli open at end-expiration to improve oxygenation"},{"id":"B","text":"Decrease airway secretions"},{"id":"C","text":"Reduce the work of the diaphragm during exhalation"},{"id":"D","text":"Lower the mean arterial pressure"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. PEEP prevents alveolar collapse, increasing surface area for gas exchange.","B":"Incorrect. PEEP does not clear secretions.","C":"Incorrect. This does not describe PEEP''s mechanism.","D":"Incorrect. High PEEP can reduce venous return, an adverse effect, not the goal."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'ARDS', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345012', 'MCQ', 'A nurse is managing negative-pressure wound therapy (NPWT) on a client''s abdominal wound. Which finding indicates the therapy is functioning correctly?', 'Properly functioning NPWT compresses the foam into a firm, collapsed shape with an airtight seal maintaining negative pressure.', '{"options":[{"id":"A","text":"The foam dressing is collapsed and firm with an intact seal"},{"id":"B","text":"The foam dressing is expanded and soft"},{"id":"C","text":"Continuous audible hissing at the dressing edge"},{"id":"D","text":"Bright red bleeding filling the canister rapidly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A collapsed, raisin-like foam under an airtight seal confirms suction is being maintained.","B":"Incorrect. An expanded foam indicates a loss of suction or air leak.","C":"Incorrect. Hissing indicates an air leak in the seal.","D":"Incorrect. Rapid bright-red drainage is a complication requiring the therapy to be stopped."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Integumentary', 'Wound care', 'Negative-pressure wound therapy', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_345013', 'MCQ', 'A client has an arterial line for continuous blood pressure monitoring. The nurse notes a dampened waveform and an unexpectedly low reading. Which action should the nurse take first?', 'A dampened arterial waveform is usually caused by air, clot, or kinking; the nurse troubleshoots the system and confirms the pressure with a cuff before treating.', '{"options":[{"id":"A","text":"Check the line for kinks, air bubbles, and clot, then verify with a cuff pressure"},{"id":"B","text":"Administer a fluid bolus for hypotension"},{"id":"C","text":"Increase the pressure bag to 500 mmHg"},{"id":"D","text":"Remove the arterial line immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dampened tracing usually reflects a mechanical problem; verifying against a cuff confirms the true pressure.","B":"Incorrect. Treating a possibly artifactual reading before verifying is unsafe.","C":"Incorrect. The pressure bag is maintained at 300 mmHg; overinflation is not the fix.","D":"Incorrect. Troubleshooting precedes removal of the access."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Hemodynamics', 'Arterial line', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_345014', 'SATA', 'A nurse assesses a client with suspected hypovolemic shock. Which findings support this diagnosis? Select all that apply.', 'Hypovolemic shock produces compensatory tachycardia, vasoconstriction with cool clammy skin, oliguria, and a narrowing pulse pressure.', '{"options":[{"id":"A","text":"Tachycardia"},{"id":"B","text":"Cool, clammy skin"},{"id":"C","text":"Decreased urine output"},{"id":"D","text":"Narrowing pulse pressure"},{"id":"E","text":"Bounding peripheral pulses"},{"id":"F","text":"Flushed, warm extremities"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Shock', 'Hypovolemic shock', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_345015', 'SATA', 'A nurse is caring for a client with a chest tube. Which situations require immediate nursing intervention? Select all that apply.', 'Disconnection, dislodgement, and signs of tension pneumothorax demand immediate action; tidaling and modest serosanguineous drainage are expected.', '{"options":[{"id":"A","text":"The chest tube becomes disconnected from the drainage system"},{"id":"B","text":"The chest tube is accidentally pulled out of the chest"},{"id":"C","text":"Sudden onset of severe respiratory distress and tracheal deviation"},{"id":"D","text":"Gentle tidaling of fluid in the water-seal chamber with respiration"},{"id":"E","text":"50 mL of serosanguineous drainage over the past shift"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tubes', 'Emergency management', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_345016', 'SATA', 'A client is admitted in acute adrenal (Addisonian) crisis. Which findings does the nurse expect? Select all that apply.', 'Cortisol and aldosterone deficiency in Addisonian crisis cause hypotension, hyperkalemia, hyponatremia, and hypoglycemia.', '{"options":[{"id":"A","text":"Hypotension"},{"id":"B","text":"Hyperkalemia"},{"id":"C","text":"Hyponatremia"},{"id":"D","text":"Hypoglycemia"},{"id":"E","text":"Hypertension"},{"id":"F","text":"Hypokalemia"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Addisonian crisis', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_345017', 'SATA', 'A nurse assesses a postoperative abdominal surgery client for paralytic ileus. Which findings support this complication? Select all that apply.', 'Paralytic ileus presents with absent bowel sounds, distension, obstipation, and nausea/vomiting rather than diarrhea or hyperactive sounds.', '{"options":[{"id":"A","text":"Absent bowel sounds"},{"id":"B","text":"Abdominal distension"},{"id":"C","text":"No passage of flatus or stool"},{"id":"D","text":"Nausea and vomiting"},{"id":"E","text":"Frequent loose stools"},{"id":"F","text":"Hyperactive high-pitched bowel sounds"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'GI', 'Postoperative care', 'Paralytic ileus', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_345018', 'SATA', 'A client on peritoneal dialysis is being monitored for peritonitis. Which findings should the nurse report? Select all that apply.', 'Peritonitis in peritoneal dialysis is signaled by cloudy effluent, abdominal pain, rebound tenderness, and fever; clear effluent is normal.', '{"options":[{"id":"A","text":"Cloudy dialysate outflow"},{"id":"B","text":"Abdominal pain and tenderness"},{"id":"C","text":"Fever"},{"id":"D","text":"Clear, straw-colored effluent"},{"id":"E","text":"Rebound tenderness"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Peritoneal dialysis', 'Peritonitis', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_345019', 'SATA', 'A client is brought to the emergency department with heat stroke. Which nursing interventions are appropriate? Select all that apply.', 'Heat stroke management centers on rapid active cooling, removing clothing, cool fluids, and continuous temperature monitoring.', '{"options":[{"id":"A","text":"Apply cooling blankets and cold packs to the groin and axillae"},{"id":"B","text":"Remove excess clothing"},{"id":"C","text":"Monitor core temperature continuously"},{"id":"D","text":"Administer cool IV fluids as prescribed"},{"id":"E","text":"Encourage vigorous ambulation to increase circulation"},{"id":"F","text":"Wrap the client in warm blankets"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Temperature regulation', 'Heat stroke', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_345020', 'SELECT_N', 'A nurse is performing endotracheal suctioning. Which 3 actions reduce the risk of hypoxemia and airway trauma?', 'Preoxygenation, limiting passes to 10-15 seconds, and suctioning only on withdrawal minimize hypoxemia and mucosal trauma.', '{"options":[{"id":"A","text":"Hyperoxygenate the client before suctioning"},{"id":"B","text":"Limit each suction pass to 10-15 seconds"},{"id":"C","text":"Apply suction only while withdrawing the catheter"},{"id":"D","text":"Apply continuous suction during insertion and withdrawal"},{"id":"E","text":"Instill 10 mL of saline routinely before each pass"},{"id":"F","text":"Suction repeatedly without rest until the airway is clear"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Suctioning', NULL, 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_345021', 'TF', 'A client with jugular venous distension, muffled heart sounds, and hypotension is exhibiting Beck''s triad, which suggests cardiac tamponade.', 'Beck''s triad — JVD, muffled heart sounds, and hypotension — is the classic presentation of cardiac tamponade.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Cardiovascular', 'Cardiac tamponade', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_345022', 'MATRIX', 'For each arterial blood gas result, click to classify the primary acid-base disturbance.', 'A high PaCO2 with low pH is respiratory acidosis; a low HCO3 with low pH is metabolic acidosis; a low PaCO2 with high pH is respiratory alkalosis.', '{"row_label":"Arterial blood gas","rows":[{"id":"r1","text":"pH 7.30, PaCO2 55, HCO3 24"},{"id":"r2","text":"pH 7.30, PaCO2 38, HCO3 16"},{"id":"r3","text":"pH 7.50, PaCO2 28, HCO3 24"},{"id":"r4","text":"pH 7.28, PaCO2 60, HCO3 25"}],"columns":[{"id":"c1","text":"Respiratory acidosis"},{"id":"c2","text":"Metabolic acidosis"},{"id":"c3","text":"Respiratory alkalosis"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Acid-base balance', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_345023', 'MATRIX_MR', 'For each condition, select all clinical findings the nurse would expect to observe.', 'Septic shock shows hypotension, tachycardia, and fever; hypovolemic shock shows hypotension with compensatory tachycardia; neurogenic shock causes hypotension with bradycardia, not tachycardia or fever.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Septic shock"},{"id":"r2","text":"Hypovolemic shock"},{"id":"r3","text":"Neurogenic shock"}],"columns":[{"id":"c1","text":"Hypotension"},{"id":"c2","text":"Tachycardia"},{"id":"c3","text":"Fever"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1","c2"],"r3":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Multisystem', 'Complication recognition', NULL, 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_345024', 'CLOZE', 'A client with syndrome of inappropriate antidiuretic hormone (SIADH) retains water, which causes the serum sodium to be {1}, and the priority nursing intervention is to {2}.', 'SIADH causes dilutional hyponatremia from water retention; fluid restriction is the cornerstone of management.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"low"},{"id":"c2","text":"high"},{"id":"c3","text":"unchanged"}]},{"id":"b2","choices":[{"id":"c1","text":"restrict fluids"},{"id":"c2","text":"encourage free water intake"},{"id":"c3","text":"administer a hypotonic infusion"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'SIADH', NULL, 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_345025', 'HIGHLIGHT', 'A nurse reassesses a postoperative client 2 days after hip surgery. Highlight the findings that require immediate follow-up. The client reports [[sudden sharp chest pain]] and [[shortness of breath]]. Temperature is [[37.1°C]]. SpO2 is [[86% on room air]]. The right calf is [[warm, red, and swollen]]. Appetite is [[normal]].', 'Sudden chest pain, dyspnea, hypoxemia, and calf signs of DVT together point to pulmonary embolism requiring immediate follow-up.', '{"chunks":[{"id":"h1","text":"sudden sharp chest pain"},{"id":"h2","text":"shortness of breath"},{"id":"h3","text":"37.1°C"},{"id":"h4","text":"86% on room air"},{"id":"h5","text":"warm, red, and swollen"},{"id":"h6","text":"normal"}]}'::jsonb, '{"correct_ids":["h1","h2","h4","h5"],"feedback":{"h1":"Sudden pleuritic chest pain suggests pulmonary embolism.","h2":"Acute dyspnea is a hallmark of PE.","h3":"This temperature is within normal range.","h4":"Significant hypoxemia requires urgent action.","h5":"Signs of DVT, the likely embolic source.","h6":"A normal appetite is not concerning."}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Complication recognition', 'Pulmonary embolism', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_345026', 'BOWTIE', 'A client presents with polyuria, fruity breath, glucose 480 mg/dL, and Kussmaul respirations. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'DKA is treated with fluids and insulin while closely monitoring glucose and potassium, which shifts with insulin therapy.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer IV isotonic fluids"},{"id":"lt2","text":"Begin IV insulin infusion"},{"id":"lt3","text":"Administer a rapid dextrose bolus"},{"id":"lt4","text":"Restrict all IV fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Diabetic ketoacidosis"},{"id":"ct2","text":"Hypoglycemia"},{"id":"ct3","text":"Diabetes insipidus"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Serum potassium"},{"id":"rt2","text":"Blood glucose"},{"id":"rt3","text":"Serum calcium"},{"id":"rt4","text":"Intraocular pressure"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Endocrine', 'Diabetic ketoacidosis', NULL, 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_345027', 'DRAG_CLOZE', 'A client has a serum sodium of [1]. The nurse recognizes this as hyponatremia and monitors closely for [2].', 'A sodium of 128 mEq/L is hyponatremia, which causes cerebral edema and places the client at risk for seizures.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"128 mEq/L"},{"id":"t2","text":"seizures"},{"id":"t3","text":"constipation"},{"id":"t4","text":"148 mEq/L"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Renal/Genitourinary', 'Fluid and electrolyte imbalance', 'Hyponatremia', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_345028', 'DRAG_ORDER', 'A client''s chest tube becomes disconnected from the drainage system. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Submerge the tube end in sterile water"},{"id":"t2","text":"Assess the client''s respiratory status"},{"id":"t3","text":"Reconnect to a new sterile drainage system"},{"id":"t4","text":"Notify the provider"},{"id":"t5","text":"Document the event"},{"id":"t6","text":"Obtain an order for a follow-up chest x-ray"}]}'::jsonb, '{"slots":{"s1":"t2","s2":"t1","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Physiological Adaptation', 'Medical-Surgical', 'Respiratory', 'Chest tubes', 'Accidental disconnection', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332001', 'MCQ', 'A client with major depressive disorder says, "There is no point in going on. Nothing will ever get better." Which response by the nurse is most therapeutic?', 'Reflecting the client''s feeling while directly assessing suicidal ideation is both therapeutic and safe.', '{"options":[{"id":"A","text":"\"You have so much to live for; try to think positively.\""},{"id":"B","text":"\"It sounds like you are feeling hopeless right now. Are you thinking of harming yourself?\""},{"id":"C","text":"\"Why do you feel that nothing will get better?\""},{"id":"D","text":"\"Everyone feels down sometimes; this will pass.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This dismisses the client''s feelings and offers false reassurance.","B":"Correct. It reflects the feeling and directly assesses suicide risk.","C":"Incorrect. ''Why'' questions can feel confrontational and demand justification.","D":"Incorrect. Minimizing the client''s distress blocks communication."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', 'Depression', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332002', 'MCQ', 'A client admitted 48 hours ago after abrupt cessation of heavy alcohol use becomes agitated, diaphoretic, and reports seeing bugs on the wall. Vital signs show BP 168/98 and HR 116. Which complication should the nurse suspect?', 'Delirium tremens presents 48-72 hours after the last drink with autonomic instability and hallucinations and is potentially life-threatening.', '{"options":[{"id":"A","text":"Wernicke encephalopathy"},{"id":"B","text":"Alcohol withdrawal delirium (delirium tremens)"},{"id":"C","text":"Korsakoff syndrome"},{"id":"D","text":"Opioid withdrawal"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Wernicke presents with confusion, ataxia, and ophthalmoplegia, not this hyperadrenergic picture.","B":"Correct. Autonomic hyperactivity with hallucinations 48-72 hours after cessation indicates DTs.","C":"Incorrect. Korsakoff is a chronic memory disorder, not acute agitation.","D":"Incorrect. Opioid withdrawal causes GI and flu-like symptoms without visual hallucinations."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Alcohol withdrawal', NULL, 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332003', 'MCQ', 'A client in an acute manic episode is intrusive, hyperverbal, and unable to sit through a group activity. Which nursing intervention is most appropriate?', 'A calm, low-stimulation setting with an outlet for excess energy helps de-escalate acute mania.', '{"options":[{"id":"A","text":"Encourage the client to join a competitive card game with peers"},{"id":"B","text":"Provide a structured, low-stimulation environment with solitary physical activity"},{"id":"C","text":"Confront the client firmly about the disruptive behavior in group"},{"id":"D","text":"Allow the client to lead the unit community meeting"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Stimulating, competitive activities escalate manic behavior.","B":"Correct. Reducing stimulation and channeling energy safely supports the manic client.","C":"Incorrect. Confrontation can trigger agitation and is not therapeutic.","D":"Incorrect. This increases stimulation and grandiosity."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Bipolar disorder', 'Acute mania', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332004', 'MCQ', 'A client with schizophrenia tells the nurse, "The voices are telling me the food is poisoned." Which response by the nurse is most therapeutic?', 'Presenting reality while validating the client''s emotional experience builds trust without reinforcing the hallucination.', '{"options":[{"id":"A","text":"\"There is no one talking to you; the food is safe.\""},{"id":"B","text":"\"I do not hear any voices, but I understand this is frightening for you.\""},{"id":"C","text":"\"What exactly are the voices saying about the food?\""},{"id":"D","text":"\"You should ignore the voices and eat your meal.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Arguing about the reality of the hallucination is nontherapeutic.","B":"Correct. The nurse presents reality while acknowledging the client''s feelings.","C":"Incorrect. Focusing on hallucination content can reinforce it.","D":"Incorrect. Dismissing the experience blocks trust and communication."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Schizophrenia', 'Hallucinations', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332005', 'MCQ', 'A woman in the emergency department has bruises in various stages of healing and her partner answers all questions for her. What is the nurse''s priority action?', 'Interviewing the client alone establishes safety and enables honest disclosure of possible abuse.', '{"options":[{"id":"A","text":"Document the injuries and discharge with the partner"},{"id":"B","text":"Interview the client alone in a private setting"},{"id":"C","text":"Confront the partner about the suspected abuse"},{"id":"D","text":"Call the police immediately"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This does not address the client''s safety or allow private disclosure.","B":"Correct. Separating the client from the partner allows a safe, confidential assessment.","C":"Incorrect. Confrontation can escalate danger to the client.","D":"Incorrect. In most cases a competent adult decides on reporting; safety assessment comes first."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Community Health', 'Multisystem', 'Abuse and neglect', 'Intimate partner violence', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332006', 'MCQ', 'The spouse of a client who died an hour ago sits silently and then says, "This cannot be real. I keep expecting him to walk in." Which stage of grief does this reflect?', 'Disbelief and an inability to accept that the loss occurred are characteristic of the denial stage of grief.', '{"options":[{"id":"A","text":"Acceptance"},{"id":"B","text":"Denial"},{"id":"C","text":"Bargaining"},{"id":"D","text":"Anger"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Acceptance involves coming to terms with the loss.","B":"Correct. Disbelief and difficulty accepting the reality of the loss reflect denial.","C":"Incorrect. Bargaining involves making deals to postpone the loss.","D":"Incorrect. Anger involves resentment or blame."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Medical-Surgical', 'Multisystem', 'End-of-life care', 'Grief', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332007', 'MCQ', 'A client in the waiting room begins hyperventilating, trembling, and states, "I feel like I''m going to die." The nurse identifies a panic-level anxiety. Which intervention is most appropriate first?', 'During panic-level anxiety, the client''s perceptual field is narrowed; a calm presence and simple, concrete communication are most effective.', '{"options":[{"id":"A","text":"Provide detailed teaching about anxiety triggers"},{"id":"B","text":"Stay with the client and speak in short, simple sentences"},{"id":"C","text":"Leave the client alone to regain composure"},{"id":"D","text":"Encourage the client to describe childhood stressors"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. During panic the client cannot process complex teaching.","B":"Correct. Presence and simple direction help ground a client in panic-level anxiety.","C":"Incorrect. Leaving a client in panic increases fear and risk.","D":"Incorrect. Exploring history is inappropriate during acute panic."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety disorders', 'Panic', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332008', 'MCQ', 'A nurse is caring for an adolescent hospitalized with anorexia nervosa. Which intervention best supports the treatment plan during meals?', 'Supervising the client during and after meals is a standard intervention that prevents purging and maintains a consistent structure.', '{"options":[{"id":"A","text":"Allow the client to eat alone to reduce anxiety"},{"id":"B","text":"Remain with the client during meals and for a period afterward"},{"id":"C","text":"Negotiate the number of calories the client will consume"},{"id":"D","text":"Praise the client extensively for finishing the meal"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Unsupervised meals allow food hiding and purging behaviors.","B":"Correct. Supervision during and after meals prevents purging and reinforces structure.","C":"Incorrect. Bargaining over intake reinforces control struggles.","D":"Incorrect. Excessive focus on food and weight is counterproductive."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anorexia nervosa', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332009', 'MCQ', 'An older adult with dementia becomes increasingly confused and agitated each evening. Which nursing intervention best addresses this pattern?', 'Sundowning is eased by adequate lighting, environmental cues, and predictable routines that reduce disorientation.', '{"options":[{"id":"A","text":"Schedule stimulating activities in the late afternoon"},{"id":"B","text":"Increase ambient lighting and maintain a consistent evening routine"},{"id":"C","text":"Restrain the client at the first sign of agitation"},{"id":"D","text":"Keep the room dim and quiet with no orienting cues"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Increased stimulation worsens evening agitation.","B":"Correct. Adequate light and routine reduce sundowning-related confusion.","C":"Incorrect. Restraints increase agitation and are a last resort.","D":"Incorrect. Reduced light and lack of cues increase disorientation."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Medical-Surgical', 'Neurological', 'Dementia', 'Sundowning', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332010', 'MCQ', 'A client declines a blood transfusion due to religious beliefs despite understanding the risk. Which nursing response best demonstrates culturally competent care?', 'Culturally competent care respects the informed client''s right to refuse and seeks acceptable alternatives that align with their beliefs.', '{"options":[{"id":"A","text":"Arrange for the provider to convince the client to accept the transfusion"},{"id":"B","text":"Respect the client''s decision and explore acceptable alternatives with the team"},{"id":"C","text":"Document that the client is noncompliant with care"},{"id":"D","text":"Administer the transfusion once the client is asleep"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Pressuring the client disregards autonomy.","B":"Correct. Honoring autonomy while seeking alternatives respects the client''s beliefs.","C":"Incorrect. An informed refusal is a right, not noncompliance.","D":"Incorrect. This violates autonomy and is unethical and illegal."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Community Health', 'Multisystem', 'Cultural and spiritual care', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332011', 'MCQ', 'A client experiences a stillbirth at 38 weeks. Which nursing action best supports the grieving parents?', 'Offering parents the choice to hold, name, and create memories with their baby facilitates the grieving process after perinatal loss.', '{"options":[{"id":"A","text":"Remove the infant quickly to spare the parents distress"},{"id":"B","text":"Offer the parents the option to hold and name their baby"},{"id":"C","text":"Reassure the parents they can have another baby"},{"id":"D","text":"Avoid discussing the loss unless the parents raise it"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Denying contact can complicate the grieving process.","B":"Correct. Providing choices for contact and mementos supports healthy grieving.","C":"Incorrect. This minimizes the loss of this baby.","D":"Incorrect. Sensitive acknowledgment of the loss is supportive."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Maternity', 'Reproductive', 'Perinatal loss', 'Grief', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_332012', 'MCQ', 'A client on the inpatient unit is pacing, clenching fists, and speaking loudly to staff. Which is the nurse''s most appropriate initial action to de-escalate the situation?', 'Early de-escalation uses a calm demeanor, respect for personal space, and verbal engagement before more restrictive measures.', '{"options":[{"id":"A","text":"Approach quickly and place a hand on the client''s shoulder"},{"id":"B","text":"Maintain a calm voice, allow personal space, and offer to talk"},{"id":"C","text":"Tell the client that seclusion will occur if behavior continues"},{"id":"D","text":"Gather several staff to physically surround the client"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Sudden touch can be perceived as threatening and escalate aggression.","B":"Correct. A calm approach with adequate space and offered support de-escalates rising aggression.","C":"Incorrect. Threats often escalate the situation.","D":"Incorrect. Surrounding the client can provoke a fight-or-flight response."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', 'Aggression', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_332013', 'SATA', 'A nurse assesses a client for suicide risk. Which findings increase the client''s risk? Select all that apply.', 'A concrete plan with lethal means, giving away possessions, a sudden unexplained calm, and prior attempts all elevate suicide risk.', '{"options":[{"id":"A","text":"A specific plan and access to a firearm"},{"id":"B","text":"Recent giving away of prized possessions"},{"id":"C","text":"A sudden calm after a period of severe depression"},{"id":"D","text":"Strong social support and future-oriented goals"},{"id":"E","text":"History of a prior suicide attempt"},{"id":"F","text":"Active engagement in a hobby the client enjoys"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk assessment', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_332014', 'SATA', 'Which techniques demonstrate therapeutic communication? Select all that apply.', 'Silence, restating, open-ended questions, and broad openings encourage the client to express themselves; false reassurance and changing the subject are blocks.', '{"options":[{"id":"A","text":"Using silence to allow the client to reflect"},{"id":"B","text":"Offering false reassurance that everything will be fine"},{"id":"C","text":"Restating what the client said in your own words"},{"id":"D","text":"Asking open-ended questions"},{"id":"E","text":"Changing the subject when the topic is uncomfortable"},{"id":"F","text":"Making broad opening statements to let the client set direction"}]}'::jsonb, '{"answers":["A","C","D","F"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Medium', 'Understand', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_332015', 'SATA', 'A client is undergoing opioid withdrawal. Which manifestations does the nurse expect? Select all that apply.', 'Opioid withdrawal produces flu-like autonomic symptoms; visual hallucinations and withdrawal seizures are characteristic of alcohol or sedative withdrawal instead.', '{"options":[{"id":"A","text":"Rhinorrhea and lacrimation"},{"id":"B","text":"Muscle aches and abdominal cramping"},{"id":"C","text":"Yawning and piloerection"},{"id":"D","text":"Visual hallucinations of insects"},{"id":"E","text":"Diarrhea and nausea"},{"id":"F","text":"Seizures within 24 hours of last dose"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Opioid withdrawal', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_332016', 'SATA', 'Which findings should raise the nurse''s suspicion of child physical abuse? Select all that apply.', 'Inconsistent histories, injuries in varied healing stages, delayed care, and spiral fractures in a nonambulatory infant are red flags for abuse.', '{"options":[{"id":"A","text":"Injuries inconsistent with the reported mechanism"},{"id":"B","text":"Multiple bruises in various stages of healing"},{"id":"C","text":"Delay in seeking medical care for a significant injury"},{"id":"D","text":"A single bruise over the shin in an active child"},{"id":"E","text":"Spiral fracture in a nonambulatory infant"},{"id":"F","text":"Age-appropriate developmental milestones"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Community Health', 'Multisystem', 'Child abuse', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_332017', 'SATA', 'A nurse teaches a newly diagnosed client about adaptive coping strategies. Which client statements indicate effective coping? Select all that apply.', 'Seeking support, exercise, journaling, and information-seeking are adaptive; substance use and avoidance are maladaptive coping.', '{"options":[{"id":"A","text":"\"I joined a support group for people with my condition.\""},{"id":"B","text":"\"I have started taking daily walks to manage my stress.\""},{"id":"C","text":"\"I''ve been having a few extra drinks to help me relax at night.\""},{"id":"D","text":"\"I write in a journal about how I''m feeling.\""},{"id":"E","text":"\"I avoid thinking about the diagnosis so it doesn''t upset me.\""},{"id":"F","text":"\"I ask my nurse questions so I understand my care plan.\""}]}'::jsonb, '{"answers":["A","B","D","F"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Coping with life changes', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_332018', 'SELECT_N', 'A nurse is establishing a therapeutic milieu on an inpatient psychiatric unit. Which 3 actions support this environment?', 'A therapeutic milieu relies on consistency, safe structure, and social engagement, not unpredictability or isolation.', '{"options":[{"id":"A","text":"Maintain consistent daily routines and clear unit expectations"},{"id":"B","text":"Encourage client participation in group activities"},{"id":"C","text":"Enforce rules unpredictably to keep clients alert"},{"id":"D","text":"Provide a safe, structured, and respectful environment"},{"id":"E","text":"Isolate clients from one another to reduce conflict"},{"id":"F","text":"Discourage clients from expressing negative feelings"}],"select_count":3}'::jsonb, '{"answers":["A","B","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Milieu therapy', NULL, 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_332019', 'TF', 'Asking a client directly whether they are thinking about suicide will increase the likelihood that the client attempts suicide.', 'Directly and calmly asking about suicidal ideation does not plant the idea; it opens communication and is an essential part of risk assessment.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide assessment', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_332020', 'MATRIX', 'For each client statement, click to identify the defense mechanism being used.', 'Denial refuses to accept reality, projection attributes one''s feelings to others, and rationalization justifies behavior with plausible excuses.', '{"row_label":"Statement","rows":[{"id":"r1","text":"\"I only drink socially; I could stop any time. My tests are just wrong.\""},{"id":"r2","text":"\"My boss is the one who has a problem with anger, not me.\""},{"id":"r3","text":"\"I failed the exam because the questions were unfair and poorly written.\""},{"id":"r4","text":"\"There is nothing wrong with me; the doctors made a mistake.\""}],"columns":[{"id":"c1","text":"Projection"},{"id":"c2","text":"Denial"},{"id":"c3","text":"Rationalization"}]}'::jsonb, '{"cells":{"r1":"c2","r2":"c1","r3":"c3","r4":"c2"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Defense mechanisms', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_332021', 'MATRIX_MR', 'For each observation, select all diagnoses commonly associated with it (may support more than one).', 'Flight of ideas typifies mania, psychomotor retardation depression, and disorganized thought schizophrenia; grandiosity can appear in both mania and schizophrenia.', '{"row_label":"Behavior","rows":[{"id":"r1","text":"Flight of ideas and pressured speech"},{"id":"r2","text":"Psychomotor retardation and anhedonia"},{"id":"r3","text":"Disorganized thinking and flat affect"},{"id":"r4","text":"Grandiosity"}],"columns":[{"id":"c1","text":"Major depression"},{"id":"c2","text":"Acute mania"},{"id":"c3","text":"Schizophrenia"}]}'::jsonb, '{"cells":{"r1":["c2"],"r2":["c1"],"r3":["c3"],"r4":["c2","c3"]},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Mental status assessment', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_332022', 'CLOZE', 'A veteran reports nightmares, avoidance of crowds, and exaggerated startle six months after combat. The nurse recognizes these findings are most consistent with {1}, and the priority nursing focus is to {2}.', 'Re-experiencing, avoidance, and hyperarousal after trauma indicate PTSD; establishing safety and trust is the priority before deeper processing.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"post-traumatic stress disorder"},{"id":"c2","text":"generalized anxiety disorder"},{"id":"c3","text":"obsessive-compulsive disorder"}]},{"id":"b2","choices":[{"id":"c1","text":"establish safety and a trusting relationship"},{"id":"c2","text":"encourage detailed retelling of the trauma immediately"},{"id":"c3","text":"discourage discussion of the event"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Post-traumatic stress disorder', NULL, 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_332023', 'HIGHLIGHT', 'Highlight the statements in the nurse''s note that indicate increased suicide risk. Client states [[I have been giving my things away]]. Reports [[sleeping well and eating regularly]]. States [[everyone would be better off without me]]. Notes [[looking forward to a family trip next month]]. Reports [[I finally feel at peace with my decision]].', 'Giving away belongings, feelings of being a burden, and a sudden peaceful resolve are all warning signs of elevated suicide risk.', '{"chunks":[{"id":"h1","text":"I have been giving my things away"},{"id":"h2","text":"sleeping well and eating regularly"},{"id":"h3","text":"everyone would be better off without me"},{"id":"h4","text":"looking forward to a family trip next month"},{"id":"h5","text":"I finally feel at peace with my decision"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"Giving away possessions is a warning sign.","h2":"This is a reassuring finding, not a risk cue.","h3":"This expresses hopelessness and burdensomeness.","h4":"Future orientation is protective.","h5":"A sudden calm may signal a formed suicide plan."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk cues', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_332024', 'BOWTIE', 'A client is escalating toward physical aggression. Complete the diagram by selecting the priority concern, actions to take, and parameters to monitor.', 'The priority in escalating agitation is safety; calm verbal de-escalation and reduced stimulation are used while monitoring cues and response.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Use a calm voice and maintain personal space"},{"id":"lt2","text":"Offer PRN medication and reduce stimulation"},{"id":"lt3","text":"Argue with the client''s reasoning"},{"id":"lt4","text":"Corner the client to prevent escape"}]},"centre":{"label":"Priority concern","tokens":[{"id":"ct1","text":"Risk for harm to self or others"},{"id":"ct2","text":"Risk for constipation"},{"id":"ct3","text":"Risk for fluid volume excess"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Escalation of nonverbal cues"},{"id":"rt2","text":"Response to interventions and staff safety"},{"id":"rt3","text":"Daily caloric intake"},{"id":"rt4","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Acute agitation', NULL, 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_332025', 'DRAG_CLOZE', 'A client whose loss occurred two years ago remains unable to function, avoids all reminders, and feels the loss as fresh as day one. The nurse recognizes this as [1] grief, which differs from [2] grief that gradually eases over time.', 'Persistent, disabling grief that does not ease over time is complicated grief, in contrast to uncomplicated grief that resolves gradually.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"complicated"},{"id":"t2","text":"uncomplicated"},{"id":"t3","text":"anticipatory"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Loss and grief', NULL, 'Medium', 'Understand', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_332026', 'DRAG_ORDER', 'A client discloses active suicidal ideation with a plan. Place the nurse''s actions in priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Ensure the client is not left alone"},{"id":"t2","text":"Remove access to potential means of self-harm"},{"id":"t3","text":"Notify the provider and initiate suicide precautions"},{"id":"t4","text":"Establish a therapeutic, supportive relationship"},{"id":"t5","text":"Document the assessment and interventions"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicidal client management', NULL, 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_332027', 'SELECT_N', 'A nurse supports a family during a client''s transition to hospice care. Which 2 actions best support the family''s coping?', 'Facilitating emotional expression and connecting the family to support resources promote healthy coping during end-of-life transitions.', '{"options":[{"id":"A","text":"Encourage the family to express their feelings and concerns"},{"id":"B","text":"Provide information about available support and bereavement resources"},{"id":"C","text":"Reassure the family that the client will likely recover"},{"id":"D","text":"Limit the family''s time at the bedside to reduce their distress"},{"id":"E","text":"Discourage discussion of death in front of the client"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Medical-Surgical', 'Multisystem', 'End-of-life care', 'Support systems', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333001', 'MCQ', 'A client hospitalized for major depression suddenly appears calm and cheerful after two weeks of withdrawn, tearful behavior and begins giving away personal belongings. Which interpretation should most concern the nurse?', 'An abrupt lift in mood with giving away possessions may indicate the client has resolved to die and now has the energy to act, raising acute suicide risk.', '{"options":[{"id":"A","text":"The antidepressant is finally taking full effect"},{"id":"B","text":"The client may have decided on and planned suicide"},{"id":"C","text":"The client is ready for discharge planning"},{"id":"D","text":"The client is masking anger toward staff"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A sudden mood lift with giving away possessions is an ominous sign, not simple recovery.","B":"Correct. Sudden calm plus giving away belongings can signal a formed suicide plan and increased energy to act.","C":"Incorrect. This presentation warrants closer observation, not discharge.","D":"Incorrect. The pattern points to suicide risk rather than displaced anger."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Depression', 'Suicide risk', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333002', 'MCQ', 'A client newly diagnosed with breast cancer says, "There''s no point in treatment; I''m going to die anyway." Which nurse response is most therapeutic?', 'Reflecting the underlying feeling and using an open-ended invitation validates the client and encourages further expression.', '{"options":[{"id":"A","text":"\"You shouldn''t talk like that; the treatments today are very effective.\""},{"id":"B","text":"\"It sounds like you''re feeling hopeless right now. Can you tell me more?\""},{"id":"C","text":"\"Why do you feel that way when the doctor is optimistic?\""},{"id":"D","text":"\"Let''s focus on something positive instead.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This dismisses feelings and offers false reassurance.","B":"Correct. Reflecting the feeling and inviting elaboration keeps communication open.","C":"Incorrect. ''Why'' questions can feel confrontational and put the client on the defensive.","D":"Incorrect. Changing the subject blocks communication."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333003', 'MCQ', 'A client with schizophrenia tells the nurse that voices are telling him he is worthless. Which response best addresses the client''s safety and reality?', 'The nurse presents reality gently while assessing for command hallucinations that direct self-harm, which is a priority safety concern.', '{"options":[{"id":"A","text":"\"The voices are not real; try to ignore them.\""},{"id":"B","text":"\"I don''t hear any voices, but I understand they feel real to you. Are the voices telling you to harm yourself?\""},{"id":"C","text":"\"What exactly are the voices saying about other people?\""},{"id":"D","text":"\"You are not worthless; you are a valuable person.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Arguing about the reality of the voices is nontherapeutic.","B":"Correct. This presents reality without arguing and assesses for command hallucinations.","C":"Incorrect. This can reinforce the hallucination without assessing safety.","D":"Incorrect. This does not assess for command hallucinations or safety."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Schizophrenia', 'Hallucinations', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333004', 'MCQ', 'A client in an acute manic episode is loud, intrusive, and unable to sit through a meal. Which nursing intervention best supports the client''s nutrition?', 'During mania hyperactivity increases caloric need while distractibility prevents sitting; portable high-calorie foods let the client eat on the move.', '{"options":[{"id":"A","text":"Serve meals in the busy dining room to encourage socialization"},{"id":"B","text":"Provide high-calorie finger foods and fluids the client can eat while moving"},{"id":"C","text":"Restrict the client to bed until the client agrees to eat a full meal"},{"id":"D","text":"Withhold food until the client''s behavior calms"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. A stimulating environment worsens distractibility during mania.","B":"Correct. Portable, high-calorie foods meet nutritional needs when the client cannot sit still.","C":"Incorrect. This is restrictive and unlikely to succeed during mania.","D":"Incorrect. Withholding food risks nutritional deficit."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Bipolar disorder', 'Mania', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333005', 'MCQ', 'A client experiencing a panic attack in the hallway is hyperventilating and states, "I feel like I''m dying." Which action should the nurse take first?', 'During panic-level anxiety the priority is to remain present, ensure safety, and use short simple directions because the client''s ability to process information is severely narrowed.', '{"options":[{"id":"A","text":"Explain the physiology of panic attacks in detail"},{"id":"B","text":"Stay with the client and speak calmly using short, simple sentences"},{"id":"C","text":"Leave to obtain an anti-anxiety medication order"},{"id":"D","text":"Encourage the client to describe the childhood origin of the anxiety"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. During peak anxiety the client cannot process detailed teaching.","B":"Correct. A calm presence and simple direction reduce anxiety and provide safety.","C":"Incorrect. Leaving a panicking client alone increases fear.","D":"Incorrect. Insight work is inappropriate during acute panic."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety disorders', 'Panic', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333006', 'MCQ', 'A client admitted 48 hours ago after stopping heavy daily alcohol use becomes tremulous, diaphoretic, and reports seeing insects on the wall. Which assessment finding most indicates the client is progressing toward a life-threatening complication?', 'Escalating autonomic hyperactivity (hypertension, tachycardia) with hallucinations signals progression toward delirium tremens, a medical emergency.', '{"options":[{"id":"A","text":"Requesting to call a family member"},{"id":"B","text":"Blood pressure 172/104 mmHg and heart rate 122 bpm"},{"id":"C","text":"Complaints of a mild headache"},{"id":"D","text":"Desire to sleep during the afternoon"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This is not a sign of physiological deterioration.","B":"Correct. Rising autonomic instability signals progression toward delirium tremens.","C":"Incorrect. A mild headache is common and not immediately dangerous.","D":"Incorrect. This does not indicate autonomic crisis."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Substance withdrawal', 'Alcohol', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333007', 'MCQ', 'A widow states four months after her husband''s death, "I still set two plates at dinner sometimes, then I remember." Which response reflects the nurse''s understanding of normal grief?', 'Transient reminders and habits months into bereavement reflect normal grief; the nurse validates and normalizes the experience.', '{"options":[{"id":"A","text":"\"That suggests you may be developing complicated grief and need therapy.\""},{"id":"B","text":"\"Adjusting to the loss takes time, and moments like that are a normal part of grieving.\""},{"id":"C","text":"\"You should put away his belongings so you can move on faster.\""},{"id":"D","text":"\"Try not to think about him so you don''t feel sad.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. This is a normal grief experience, not necessarily pathological.","B":"Correct. This normalizes the experience while remaining supportive.","C":"Incorrect. Rushing the process is not therapeutic.","D":"Incorrect. Avoidance blocks healthy grieving."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Grief and loss', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333008', 'MCQ', 'A nurse is caring for a client with anorexia nervosa on a behavioral treatment protocol. Which nursing approach best supports the plan of care during meals?', 'Staying with the client during and after meals prevents purging behaviors and enforces the behavioral protocol, while praise should focus on healthy behaviors rather than weight.', '{"options":[{"id":"A","text":"Allow the client to eat alone to reduce mealtime anxiety"},{"id":"B","text":"Remain with the client during and for a set period after meals"},{"id":"C","text":"Negotiate portion sizes with the client at each meal"},{"id":"D","text":"Praise the client primarily for weight gained"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Unsupervised meals allow purging or hiding food.","B":"Correct. Supervision during and after meals prevents purging and supports intake goals.","C":"Incorrect. Bargaining over food undermines the structured protocol.","D":"Incorrect. Focusing on weight reinforces the disorder''s preoccupation."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Eating disorders', 'Anorexia nervosa', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333009', 'MCQ', 'A client on the unit is pacing, clenching his fists, and speaking in a loud voice about being treated unfairly. Which is the nurse''s most appropriate initial action?', 'De-escalation begins with a calm nonthreatening demeanor, respecting personal space, and acknowledging feelings before setting limits.', '{"options":[{"id":"A","text":"Approach closely and place a hand on the client''s shoulder to reassure him"},{"id":"B","text":"Maintain a calm voice, keep a safe distance, and acknowledge the client''s feelings"},{"id":"C","text":"Tell the client he will be placed in seclusion if he does not calm down"},{"id":"D","text":"Ignore the behavior so as not to reinforce it"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Physical contact and close proximity can escalate aggression.","B":"Correct. A calm tone, personal space, and validation begin de-escalation.","C":"Incorrect. Threatening escalates rather than de-escalates.","D":"Incorrect. Ignoring rising agitation risks it escalating to violence."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'De-escalation', 'Aggression', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333010', 'MCQ', 'During triage a woman with a fractured wrist gives an explanation inconsistent with her injury, and her partner answers all questions for her. Which nursing action is most appropriate?', 'Separating the client from the partner to interview her privately provides a safe opportunity to assess for intimate partner violence.', '{"options":[{"id":"A","text":"Confront the partner about the suspected abuse in the room"},{"id":"B","text":"Interview the client privately, away from the partner"},{"id":"C","text":"Document that abuse has occurred and notify police"},{"id":"D","text":"Ask the partner to describe how the injury happened"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Confronting the partner can endanger the client.","B":"Correct. A private interview allows the client to speak safely.","C":"Incorrect. Abuse is suspected, not confirmed, and adult reporting rules vary.","D":"Incorrect. The partner may control or coerce the account."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Community Health', 'Psychiatric/Mental Health', 'Abuse and neglect', 'Intimate partner violence', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333011', 'MCQ', 'A client from a culture that values family decision-making asks that the nurse discuss test results with his adult son rather than himself. Which response best demonstrates culturally competent care?', 'Culturally competent care respects the client''s family-centered decision-making while using proper consent to share protected information.', '{"options":[{"id":"A","text":"\"By law I can only share results directly with you.\""},{"id":"B","text":"\"I want to respect how you make decisions. Would you like to sign a consent so I can share results with your son?\""},{"id":"C","text":"\"It is healthier for you to hear the results yourself.\""},{"id":"D","text":"\"Your son can read the results in the chart later.\""}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Clients may designate others to receive information.","B":"Correct. This honors the cultural preference while meeting privacy requirements.","C":"Incorrect. This imposes the nurse''s values.","D":"Incorrect. This bypasses proper consent and the client''s wishes."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Medical-Surgical', 'Psychiatric/Mental Health', 'Cultural care', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333012', 'MCQ', 'A client with moderate dementia becomes increasingly agitated and disoriented each evening. Which environmental intervention should the nurse implement to reduce this behavior?', 'Sundowning agitation is reduced by well-lit, calm, low-stimulation evening environments that limit shadows and confusing cues.', '{"options":[{"id":"A","text":"Turn off all lights early to promote sleep"},{"id":"B","text":"Increase evening lighting and reduce noise and clutter"},{"id":"C","text":"Schedule stimulating group activities in the evening"},{"id":"D","text":"Provide caffeinated tea to keep the client alert"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Darkness and shadows increase confusion during sundowning.","B":"Correct. Adequate lighting with a calm environment reduces sundowning agitation.","C":"Incorrect. Evening stimulation worsens agitation.","D":"Incorrect. Caffeine increases agitation and disrupts sleep."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Dementia', 'Sundowning', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_333013', 'MCQ', 'A client recently diagnosed with type 1 diabetes states, "The lab must have mixed up my results; I feel perfectly fine." Which defense mechanism is the client using?', 'Refusing to acknowledge a threatening diagnosis by disputing its reality is denial, an early coping response to loss or illness.', '{"options":[{"id":"A","text":"Projection"},{"id":"B","text":"Denial"},{"id":"C","text":"Displacement"},{"id":"D","text":"Rationalization"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Projection attributes one''s own feelings to others.","B":"Correct. Refusing to accept the diagnosis is denial.","C":"Incorrect. Displacement redirects feelings to a safer target.","D":"Incorrect. Rationalization offers logical-sounding excuses for behavior."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Coping', 'Defense mechanisms', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_333014', 'SATA', 'A nurse assesses a client for major depressive disorder. Which findings support this diagnosis? Select all that apply.', 'Anhedonia, sleep disturbance, worthlessness/guilt, and psychomotor retardation are core depressive features; flight of ideas and grandiosity indicate mania.', '{"options":[{"id":"A","text":"Loss of interest in previously enjoyed activities"},{"id":"B","text":"Early morning awakening with inability to return to sleep"},{"id":"C","text":"Feelings of worthlessness and excessive guilt"},{"id":"D","text":"Psychomotor retardation"},{"id":"E","text":"Flight of ideas and pressured speech"},{"id":"F","text":"Grandiose delusions"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Depression', 'Assessment', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_333015', 'SATA', 'A nurse manages a therapeutic milieu on an inpatient psychiatric unit. Which nursing actions support a therapeutic environment? Select all that apply.', 'A therapeutic milieu relies on consistency, structure, client involvement, appropriate activities, and safety; inconsistency and rigid distance undermine it.', '{"options":[{"id":"A","text":"Maintain consistent unit rules and daily structure"},{"id":"B","text":"Encourage clients to participate in unit governance and decisions"},{"id":"C","text":"Provide activities matched to clients'' abilities"},{"id":"D","text":"Keep client interactions strictly formal and minimal"},{"id":"E","text":"Ensure physical and emotional safety on the unit"},{"id":"F","text":"Allow rules to change based on each staff member''s preference"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic milieu', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_333016', 'SATA', 'A nurse is talking with a client experiencing situational stress. Which nurse statements are therapeutic communication techniques? Select all that apply.', 'Exploring, validating, using silence, and restating are therapeutic; false reassurance and ''why'' questions are communication blocks.', '{"options":[{"id":"A","text":"\"Tell me more about what happened.\" (exploring)"},{"id":"B","text":"\"You seem worried. Is that right?\" (validating)"},{"id":"C","text":"\"Everything will work out fine, don''t worry.\" (false reassurance)"},{"id":"D","text":"Sitting quietly and allowing silence"},{"id":"E","text":"\"Why did you make that choice?\" (demanding explanation)"},{"id":"F","text":"\"So what I hear you saying is that you feel overwhelmed.\" (restating)"}]}'::jsonb, '{"answers":["A","B","D","F"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_333017', 'SATA', 'A nurse assesses a newly admitted client for risk of violence toward others. Which findings increase this risk? Select all that apply.', 'Past violence, command hallucinations, motor agitation, and stimulant intoxication all raise the risk of violence; cooperation and ordinary questions do not.', '{"options":[{"id":"A","text":"History of previous violent behavior"},{"id":"B","text":"Command hallucinations to harm others"},{"id":"C","text":"Escalating motor agitation and pacing"},{"id":"D","text":"Cooperative participation in the admission interview"},{"id":"E","text":"Active intoxication with a stimulant"},{"id":"F","text":"Requesting information about visiting hours"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Violence potential', 'Risk assessment', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_333018', 'SATA', 'A nurse cares for a client and family during the client''s final days of a terminal illness. Which nursing actions provide appropriate psychosocial support? Select all that apply.', 'End-of-life psychosocial care includes facilitating expression, honoring cultural/spiritual needs, supporting client autonomy, and offering presence; predicting the exact time of death and suppressing emotion are not therapeutic.', '{"options":[{"id":"A","text":"Encourage the family to share memories and say what they need to say"},{"id":"B","text":"Respect the client''s cultural and spiritual practices"},{"id":"C","text":"Tell the family exactly when death will occur to help them prepare"},{"id":"D","text":"Allow the client to direct decisions about their care as able"},{"id":"E","text":"Provide presence and permit silence when words are not needed"},{"id":"F","text":"Discourage crying to keep the client calm"}]}'::jsonb, '{"answers":["A","B","D","E"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'End-of-life care', 'Psychosocial support', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_333019', 'SELECT_N', 'A client is undergoing opioid withdrawal. Which 3 findings are consistent with this condition?', 'Opioid withdrawal produces autonomic and flu-like signs (rhinorrhea, lacrimation, myalgia, cramping, piloerection); respiratory depression, miosis, and euphoria reflect intoxication instead.', '{"options":[{"id":"A","text":"Rhinorrhea and lacrimation"},{"id":"B","text":"Muscle aches and abdominal cramping"},{"id":"C","text":"Piloerection and yawning"},{"id":"D","text":"Respiratory depression"},{"id":"E","text":"Pinpoint pupils"},{"id":"F","text":"Euphoria and sedation"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Substance misuse', 'Opioid withdrawal', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_333020', 'SELECT_N', 'A client is coping with the recent loss of employment and reports feeling overwhelmed. Which 2 nursing actions best strengthen the client''s support systems?', 'Mobilizing existing relationships and connecting the client with community resources builds support; isolation and minimizing feelings weaken coping.', '{"options":[{"id":"A","text":"Help the client identify family and friends who can offer support"},{"id":"B","text":"Refer the client to a community support or job-transition group"},{"id":"C","text":"Advise the client to avoid discussing the situation with others"},{"id":"D","text":"Encourage the client to handle the situation independently"},{"id":"E","text":"Tell the client that others have coped with worse"}],"select_count":2}'::jsonb, '{"answers":["A","B"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Support systems', 'Coping resources', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_333021', 'TF', 'Directly asking a client whether they have thoughts of suicide increases the likelihood that the client will attempt suicide.', 'Asking directly about suicidal ideation does not plant the idea; it opens communication and allows accurate risk assessment and intervention.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide assessment', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_333022', 'TF', 'When a client''s spoken words conflict with the client''s body language and tone, the nurse should recognize that the nonverbal cues often more accurately reflect the client''s true feelings.', 'Nonverbal communication frequently conveys underlying emotion more accurately than words, especially when the two are incongruent; the nurse explores the discrepancy.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Nonverbal cues', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_333023', 'MATRIX', 'For each nurse statement, click to specify whether it is a therapeutic or a nontherapeutic communication technique.', 'General leads, exploring, and reflecting feelings are therapeutic; false reassurance and giving advice are communication blocks.', '{"row_label":"Statement","rows":[{"id":"r1","text":"\"Go on, I''m listening.\""},{"id":"r2","text":"\"Don''t worry, everything will be fine.\""},{"id":"r3","text":"\"You mentioned feeling alone. Tell me more.\""},{"id":"r4","text":"\"If I were you, I would take the medication.\""},{"id":"r5","text":"\"It sounds like this has been frightening for you.\""}],"columns":[{"id":"c1","text":"Therapeutic"},{"id":"c2","text":"Nontherapeutic"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Therapeutic communication', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_333024', 'MATRIX_MR', 'For each clinical finding, select all disorders in which the finding is commonly seen (a finding may apply to more than one).', 'Anhedonia is depressive, flight of ideas and grandiosity are manic, hallucinations are psychotic, and impaired concentration crosses all three.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Anhedonia"},{"id":"r2","text":"Auditory hallucinations"},{"id":"r3","text":"Flight of ideas"},{"id":"r4","text":"Impaired concentration"},{"id":"r5","text":"Grandiosity"}],"columns":[{"id":"c1","text":"Major depression"},{"id":"c2","text":"Bipolar mania"},{"id":"c3","text":"Schizophrenia"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c3"],"r3":["c2"],"r4":["c1","c2","c3"],"r5":["c2"]},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Mental illness recognition', NULL, 'Medium', 'Analyze', '{}', 7, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_333025', 'CLOZE', 'A client paces, has a narrowed perceptual field, and can focus only when redirected. The nurse determines the client is experiencing {1} anxiety and the priority intervention is to {2}.', 'A markedly narrowed perceptual field with need for redirection reflects severe anxiety; a calm presence with simple directions is the priority.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"severe"},{"id":"c2","text":"mild"},{"id":"c3","text":"panic"}]},{"id":"b2","choices":[{"id":"c1","text":"remain calm and use short, simple directions"},{"id":"c2","text":"provide detailed health teaching"},{"id":"c3","text":"leave the client alone to rest"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Anxiety', 'Levels of anxiety', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_333026', 'HIGHLIGHT', 'Highlight the findings in the nurse''s note that indicate increased suicide risk. Client states [[he has a plan and access to a firearm]]. Reports [[feeling like a burden to everyone]]. Sleeping and eating [[within normal limits]]. Has [[given away a treasured guitar]]. States he [[looks forward to a family reunion next month]].', 'A specific plan with lethal means, perceived burdensomeness, and giving away possessions increase risk; normal vegetative signs and future orientation are protective or neutral.', '{"chunks":[{"id":"h1","text":"he has a plan and access to a firearm"},{"id":"h2","text":"feeling like a burden to everyone"},{"id":"h3","text":"within normal limits"},{"id":"h4","text":"given away a treasured guitar"},{"id":"h5","text":"looks forward to a family reunion next month"}]}'::jsonb, '{"correct_ids":["h1","h2","h4"],"feedback":{"h1":"A specific plan with lethal means is a major risk factor.","h2":"Perceived burdensomeness raises suicide risk.","h3":"Normal sleep and appetite are not a warning sign.","h4":"Giving away prized possessions can signal a suicide plan.","h5":"Future orientation is a protective factor, not a risk."}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Suicide risk', 'Warning signs', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_333027', 'BOWTIE', 'A client 3 days after abrupt cessation of heavy alcohol use is confused, tremulous, and hallucinating with vital sign instability. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Delirium tremens is treated with benzodiazepines and a calm environment while monitoring vital signs, orientation, and seizure activity.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Administer prescribed benzodiazepine"},{"id":"lt2","text":"Provide a calm, low-stimulation environment"},{"id":"lt3","text":"Encourage caffeine to increase alertness"},{"id":"lt4","text":"Place the client in a bright, busy dayroom"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Delirium tremens"},{"id":"ct2","text":"Opioid withdrawal"},{"id":"ct3","text":"Panic disorder"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Vital signs and orientation"},{"id":"rt2","text":"Seizure activity"},{"id":"rt3","text":"Deep tendon reflexes for hyperthyroidism"},{"id":"rt4","text":"24-hour urine catecholamines"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health', 'Alcohol withdrawal', 'Delirium tremens', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340001', 'MCQ', 'A nurse reviews the telemetry of a client and notes a regular rhythm at 40 bpm with more P waves than QRS complexes and a progressively lengthening PR interval until a QRS is dropped. Which action should the nurse take first?', 'A second-degree AV block (Mobitz I) with bradycardia requires the nurse to first assess perfusion/hemodynamic status before treatment.', '{"options":[{"id":"A","text":"Continue monitoring and document the rhythm"},{"id":"B","text":"Assess the client''s blood pressure and level of consciousness"},{"id":"C","text":"Prepare to administer a beta-blocker"},{"id":"D","text":"Perform synchronized cardioversion"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Symptomatic bradycardia at 40 bpm warrants intervention, not passive monitoring.","B":"Correct. Determining hemodynamic tolerance of the bradyarrhythmia guides the urgency of treatment.","C":"Incorrect. Beta-blockers further slow the heart rate and are contraindicated.","D":"Incorrect. Cardioversion treats tachyarrhythmias, not a bradycardic block."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'ECG monitoring', 'Rhythm interpretation', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340002', 'MCQ', 'A nurse prepares to administer medication through a newly inserted nasogastric tube. Which method is the most reliable to verify tube placement before use?', 'Radiographic confirmation is the gold standard before first use of a newly placed NG tube.', '{"options":[{"id":"A","text":"Auscultate over the epigastrium while injecting air"},{"id":"B","text":"Confirm placement with a radiograph"},{"id":"C","text":"Place the tube''s end in water and observe for bubbling"},{"id":"D","text":"Aspirate and measure the length of external tubing"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. The air-bolus ''whoosh'' test is unreliable and no longer recommended.","B":"Correct. X-ray is the gold standard for verifying initial NG tube placement.","C":"Incorrect. Bubbling is not a valid indicator of gastric placement.","D":"Incorrect. External length checks confirm migration later but not initial placement."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube', 'Placement verification', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340003', 'MCQ', 'A client with type 2 diabetes taking metformin is scheduled for a CT scan with iodinated contrast. Which laboratory value should the nurse prioritize reviewing before the procedure?', 'Renal function (creatinine) must be assessed before contrast in metformin users to reduce nephropathy and lactic acidosis risk.', '{"options":[{"id":"A","text":"Serum creatinine"},{"id":"B","text":"Serum sodium"},{"id":"C","text":"Hemoglobin A1c"},{"id":"D","text":"White blood cell count"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Impaired renal function increases the risk of contrast-induced nephropathy and lactic acidosis with metformin.","B":"Incorrect. Sodium is not the primary concern with contrast and metformin.","C":"Incorrect. A1c reflects long-term glucose control, not procedural risk.","D":"Incorrect. WBC does not predict contrast nephrotoxicity."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Diagnostic-test monitoring', 'Contrast studies', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340004', 'MCQ', 'During a colonoscopy under moderate (procedural) sedation, the nurse notes the client''s SpO2 has fallen from 98% to 88% and respirations are shallow at 8/min. Which action should the nurse take first?', 'Oversedation with hypoventilation is first managed by stimulation and prompting breathing before escalation to reversal or airway devices.', '{"options":[{"id":"A","text":"Stimulate the client and encourage deep breaths"},{"id":"B","text":"Administer the full reversal dose of naloxone"},{"id":"C","text":"Document the finding and continue the procedure"},{"id":"D","text":"Prepare for immediate endotracheal intubation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Verbal/tactile stimulation and prompting breathing is the first, least invasive airway intervention for oversedation.","B":"Incorrect. Reversal is escalated only after basic airway measures fail.","C":"Incorrect. Falling SpO2 with hypoventilation requires intervention.","D":"Incorrect. Intubation is premature before simpler measures are tried."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Moderate sedation', 'Monitoring', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340005', 'MCQ', 'A client receiving a continuous IV heparin infusion has an aPTT result of 110 seconds (control 30 seconds). Based on this trend, which action should the nurse anticipate?', 'An aPTT more than 2.5 times control is supratherapeutic for heparin, so the nurse holds/decreases the infusion and notifies the provider.', '{"options":[{"id":"A","text":"Increase the heparin infusion rate"},{"id":"B","text":"Hold or decrease the infusion and notify the provider"},{"id":"C","text":"Administer vitamin K"},{"id":"D","text":"Continue the current rate and recheck in 24 hours"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. The aPTT is supratherapeutic; increasing the dose raises bleeding risk.","B":"Correct. An aPTT >2.5 times control is supratherapeutic and increases bleeding risk, so the infusion is reduced or held.","C":"Incorrect. Vitamin K reverses warfarin, not heparin; protamine is the heparin antidote.","D":"Incorrect. A supratherapeutic value requires prompt adjustment."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'Anticoagulation', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340006', 'MCQ', 'A laboring client''s fetal monitor shows recurrent late decelerations with minimal variability. Which action should the nurse take first?', 'Late decelerations indicate uteroplacental insufficiency; repositioning to improve perfusion is the first intrauterine resuscitation step.', '{"options":[{"id":"A","text":"Reposition the client to a lateral position"},{"id":"B","text":"Increase the oxytocin infusion"},{"id":"C","text":"Document and continue routine monitoring"},{"id":"D","text":"Prepare for immediate forceps delivery"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Late decelerations reflect uteroplacental insufficiency; repositioning improves placental perfusion as the first intrauterine resuscitation measure.","B":"Incorrect. Oxytocin should be reduced or stopped, not increased, with late decelerations.","C":"Incorrect. Late decelerations are non-reassuring and require intervention.","D":"Incorrect. Intrauterine resuscitation is attempted before operative delivery."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive', 'Fetal monitoring', 'Deceleration patterns', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340007', 'MCQ', 'A nurse is caring for a client on bed rest 2 days after a total hip arthroplasty. Which assessment finding related to venous thromboembolism prevention requires immediate follow-up?', 'Unilateral calf swelling, warmth, and tenderness suggest DVT, a complication requiring immediate assessment and reporting.', '{"options":[{"id":"A","text":"Sequential compression devices inflating on both legs"},{"id":"B","text":"Unilateral calf swelling with warmth and tenderness"},{"id":"C","text":"Antiembolism stockings applied smoothly without wrinkles"},{"id":"D","text":"Client performing ankle pumps every hour"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Functioning SCDs are the expected preventive measure.","B":"Correct. These are classic signs of deep vein thrombosis and require immediate follow-up.","C":"Incorrect. Properly applied stockings are a normal preventive finding.","D":"Incorrect. Ankle pumps are an encouraged preventive exercise."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Venous-return devices', 'Antiembolism prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340008', 'MCQ', 'A nurse observes that an indwelling urinary catheter drainage bag is resting on the floor next to the client''s bed. Which action should the nurse take?', 'The drainage bag must stay below bladder level and off the floor to preserve gravity drainage and reduce CAUTI risk.', '{"options":[{"id":"A","text":"Secure the bag below bladder level on the bed frame"},{"id":"B","text":"Hang the bag on the IV pole above the bladder"},{"id":"C","text":"Clamp the tubing until the next assessment"},{"id":"D","text":"Leave the bag as is if it is draining well"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Keeping the bag below the bladder but off the floor maintains gravity drainage and reduces infection risk.","B":"Incorrect. A bag above bladder level causes reflux and infection risk.","C":"Incorrect. Clamping causes urinary stasis and is not indicated routinely.","D":"Incorrect. A bag on the floor is a contamination hazard."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Urinary catheter', 'CAUTI prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340009', 'MCQ', 'A nurse obtains a point-of-care blood glucose of 48 mg/dL on a client who is alert and able to swallow. Which action should the nurse take first?', 'A conscious hypoglycemic client who can swallow receives 15 g of oral fast-acting carbohydrate first, following the rule of 15.', '{"options":[{"id":"A","text":"Give 15 g of a fast-acting oral carbohydrate"},{"id":"B","text":"Administer IV 50% dextrose"},{"id":"C","text":"Give the scheduled dose of insulin"},{"id":"D","text":"Recheck the glucose in one hour"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. For a conscious client with hypoglycemia, 15 g of oral fast-acting carbohydrate is the first-line treatment.","B":"Incorrect. IV dextrose is reserved for clients who cannot safely swallow.","C":"Incorrect. Insulin would worsen the hypoglycemia.","D":"Incorrect. Hypoglycemia must be treated immediately, not deferred."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Point-of-care testing', 'Glucose monitoring', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340010', 'MCQ', 'A client returns to the unit after a bronchoscopy in which a topical anesthetic was used on the throat. Which nursing action is the priority before offering fluids?', 'After throat anesthesia for bronchoscopy, oral intake is withheld until the gag reflex returns to prevent aspiration.', '{"options":[{"id":"A","text":"Assess the return of the gag reflex"},{"id":"B","text":"Measure the client''s oral temperature"},{"id":"C","text":"Encourage the client to cough forcefully"},{"id":"D","text":"Offer a large glass of cold water immediately"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The gag reflex must return before oral intake to prevent aspiration after throat anesthesia.","B":"Incorrect. Temperature is not the priority for aspiration prevention.","C":"Incorrect. Forceful coughing is not required and may irritate the airway.","D":"Incorrect. Fluids are withheld until the gag reflex returns."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Response to procedures', 'Post-bronchoscopy care', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_340011', 'MCQ', 'A client receiving continuous enteral feeding through a PEG tube must be repositioned for a bed bath. To reduce the risk of aspiration during and after feeding, the nurse should maintain the head of the bed at which minimum elevation?', 'During enteral feeding the head of bed is kept at least 30 degrees to reduce reflux and aspiration risk.', '{"options":[{"id":"A","text":"Flat (0 degrees)"},{"id":"B","text":"15 degrees"},{"id":"C","text":"30 degrees"},{"id":"D","text":"Prone position"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. A flat position increases reflux and aspiration risk.","B":"Incorrect. This is below the recommended minimum for enteral feeding.","C":"Correct. Keeping the head of bed at 30–45 degrees reduces reflux and aspiration during enteral feeding.","D":"Incorrect. Prone positioning is inappropriate during enteral feeding."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Percutaneous feeding tube', 'Aspiration prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_340012', 'SATA', 'A nurse provides pre-operative teaching to a client scheduled for abdominal surgery. Which instructions help reduce the risk of postoperative complications? Select all that apply.', 'Incentive spirometry, splinting, leg exercises, and assisted early ambulation prevent atelectasis, VTE, and falls; prolonged bed rest and refusing analgesia increase complications.', '{"options":[{"id":"A","text":"Use the incentive spirometer 10 times each hour while awake"},{"id":"B","text":"Splint the incision with a pillow when coughing"},{"id":"C","text":"Perform leg exercises and ankle pumps while in bed"},{"id":"D","text":"Remain on strict bed rest for the first five days"},{"id":"E","text":"Report to staff before getting out of bed the first time"},{"id":"F","text":"Avoid all pain medication to stay alert"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Pre-operative education', 'Post-op complication prevention', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_340013', 'SATA', 'A nurse reviews the labs of a client with acute kidney injury and notes a potassium of 6.8 mEq/L. Which findings would the nurse expect to correlate with this value? Select all that apply.', 'Hyperkalemia produces peaked T waves, dysrhythmias, muscle weakness, and increased GI motility (diarrhea); constipation reflects hypokalemia.', '{"options":[{"id":"A","text":"Peaked T waves on the ECG"},{"id":"B","text":"Muscle weakness"},{"id":"C","text":"Cardiac dysrhythmias"},{"id":"D","text":"Constipation and abdominal distention"},{"id":"E","text":"Increased deep tendon reflexes without change"},{"id":"F","text":"Diarrhea or hyperactive bowel sounds"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Lab-value interpretation', 'Hyperkalemia', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_340014', 'SATA', 'A nurse is preparing to administer a unit of packed red blood cells. Which actions reduce the risk of a transfusion reaction? Select all that apply.', 'Two-nurse verification, two identifiers, normal saline priming, and early bedside monitoring prevent/detect reactions; dextrose lyses cells and units must infuse within 4 hours.', '{"options":[{"id":"A","text":"Verify the blood product with a second nurse at the bedside"},{"id":"B","text":"Confirm the client''s identity using two identifiers"},{"id":"C","text":"Prime the tubing with 0.9% normal saline"},{"id":"D","text":"Prime the tubing with dextrose 5% in water"},{"id":"E","text":"Stay with the client during the first 15 minutes"},{"id":"F","text":"Infuse the entire unit over 6 hours to be safe"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Blood/specimen collection', 'Blood transfusion safety', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_340015', 'SATA', 'A nurse assesses a peripheral IV site and suspects infiltration. Which findings support this concern? Select all that apply.', 'Infiltration presents with coolness, edema, blanching, tautness, and slowed flow; redness, warmth, streaking, and purulence indicate phlebitis or infection.', '{"options":[{"id":"A","text":"Cool, swollen skin around the insertion site"},{"id":"B","text":"Sluggish or absent flow of the infusion"},{"id":"C","text":"Blanching and taut skin at the site"},{"id":"D","text":"A red streak tracking up the vein with warmth"},{"id":"E","text":"Purulent drainage from the insertion site"},{"id":"F","text":"Client reports tightness at the site"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Complication recognition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_340016', 'SATA', 'A nurse reviews serial vital signs on a postoperative client. Which trends should prompt the nurse to suspect early sepsis and escalate care? Select all that apply.', 'Rising temperature, tachycardia, tachypnea, and falling blood pressure are early sepsis trends; stable urine output and SpO2 are reassuring.', '{"options":[{"id":"A","text":"Temperature rising from 37.0°C to 38.6°C"},{"id":"B","text":"Heart rate climbing from 82 to 116 bpm"},{"id":"C","text":"Respiratory rate increasing from 16 to 24/min"},{"id":"D","text":"Blood pressure trending from 122/78 to 96/54 mmHg"},{"id":"E","text":"Urine output steady at 60 mL/hr"},{"id":"F","text":"Oxygen saturation stable at 98% on room air"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Vital-sign trends', 'Early sepsis recognition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_340017', 'SELECT_N', 'A nurse prepares a client for an oral glucose tolerance test. Which 3 instructions are appropriate to ensure valid results and client safety?', 'An OGTT requires fasting, staying available for timed draws, and monitoring for hypoglycemia; eating, exercising, or sipping the solution slowly invalidates results.', '{"options":[{"id":"A","text":"Fast for 8 hours before the test"},{"id":"B","text":"Report symptoms of hypoglycemia during the test"},{"id":"C","text":"Remain in the testing area between blood draws"},{"id":"D","text":"Drink the glucose solution over 2 hours slowly"},{"id":"E","text":"Perform vigorous exercise during the test"},{"id":"F","text":"Eat a high-carbohydrate breakfast the morning of the test"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Diagnostic-test monitoring', 'Pre-procedure preparation', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_340018', 'TF', 'After a cardiac catheterization performed through the right femoral artery, it is appropriate for the nurse to keep the client''s head of bed elevated at 60 degrees with the affected leg flexed for the first several hours.', 'The affected extremity must be kept straight and the head of bed low (usually ≤30 degrees) to prevent bleeding from the femoral access site.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Diagnostic-test monitoring', 'Post-cardiac catheterization', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_340019', 'MATRIX', 'For each assessment finding after starting therapy, click to indicate whether it is an expected response or an adverse effect requiring follow-up.', 'Diuresis, a therapeutic INR, and controlled BP are expected; hypokalemia and tinnitus (salicylate toxicity) are adverse effects requiring follow-up.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Urine output increases after IV furosemide"},{"id":"r2","text":"Serum potassium falls to 2.8 mEq/L on a loop diuretic"},{"id":"r3","text":"INR reaches 2.5 on warfarin therapy"},{"id":"r4","text":"Ringing in the ears after high-dose aspirin"},{"id":"r5","text":"Blood pressure decreases to 128/80 mmHg on an antihypertensive"}],"columns":[{"id":"c1","text":"Expected response"},{"id":"c2","text":"Adverse effect"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Response to treatments', 'Expected vs adverse', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_340020', 'CLOZE', 'One hour after a thoracentesis, a client develops sudden dyspnea and diminished breath sounds on the procedure side. The nurse recognizes these findings most likely indicate {1} and should first {2}.', 'Pneumothorax is a known complication of thoracentesis; the nurse assesses respiratory status/oxygenation and notifies the provider promptly.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"a pneumothorax"},{"id":"c2","text":"an allergic reaction"},{"id":"c3","text":"hypoglycemia"}]},{"id":"b2","choices":[{"id":"c1","text":"assess vital signs and oxygen saturation and notify the provider"},{"id":"c2","text":"reposition the client for the next procedure"},{"id":"c3","text":"offer oral fluids and reassess in the morning"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Response to procedures', 'Post-thoracentesis assessment', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_340021', 'HIGHLIGHT', 'The nurse reviews a client 6 hours after abdominal surgery. Highlight the findings that require immediate follow-up. Vital signs: BP [[92/56]], HR [[122]]. Temperature [[37.1°C]]. Surgical dressing shows [[an expanding area of bright red drainage]]. Pain rated 4/10, relieved by medication. Urine output [[20 mL over the last 2 hours]]. Lung sounds clear bilaterally.', 'Hypotension, tachycardia, expanding bright-red drainage, and oliguria together suggest postoperative hemorrhage and need urgent action.', '{"chunks":[{"id":"h1","text":"92/56"},{"id":"h2","text":"122"},{"id":"h3","text":"an expanding area of bright red drainage"},{"id":"h4","text":"20 mL over the last 2 hours"},{"id":"h5","text":"37.1°C"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Hypotension may indicate hypovolemia or hemorrhage.","h2":"Tachycardia is an early compensatory sign of blood loss.","h3":"Active fresh bleeding at the incision requires immediate follow-up.","h4":"Oliguria (<30 mL/hr) suggests poor perfusion.","h5":"This temperature is within normal range."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Focused assessment', 'Post-operative trend recognition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_340022', 'BOWTIE', 'A client 3 days after knee replacement suddenly reports pleuritic chest pain and dyspnea with SpO2 of 88%. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Sudden dyspnea, pleuritic pain, and hypoxemia after joint surgery suggest PE; treatment includes oxygen and provider notification while monitoring oxygenation and respiratory status.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Apply supplemental oxygen"},{"id":"lt2","text":"Notify the provider immediately"},{"id":"lt3","text":"Encourage vigorous ambulation"},{"id":"lt4","text":"Massage the affected calf"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Pulmonary embolism"},{"id":"ct2","text":"Wound infection"},{"id":"ct3","text":"Hypoglycemia"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Oxygen saturation"},{"id":"rt2","text":"Respiratory rate and effort"},{"id":"rt3","text":"Bowel sounds"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Complication recognition', 'Post-op DVT/PE risk', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_340023', 'DRAG_CLOZE', 'A client''s serum creatinine has risen from 1.0 to 2.4 mg/dL over 48 hours. The nurse interprets this trend as [1] and, before the next dose of a nephrotoxic antibiotic, should [2].', 'A rising creatinine indicates declining renal function; the nurse withholds/questions nephrotoxic drugs and notifies the provider.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"worsening renal function"},{"id":"t2","text":"notify the provider and review the medication"},{"id":"t3","text":"improving renal function"},{"id":"t4","text":"administer the dose as scheduled without concern"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Lab-value interpretation', 'Renal function trend', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_340024', 'DRAG_ORDER', 'A client receiving packed red blood cells suddenly develops fever, chills, and back pain. Place the nurse''s actions in the correct priority order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Stop the transfusion immediately"},{"id":"t2","text":"Keep the IV line open with normal saline"},{"id":"t3","text":"Assess the client''s vital signs"},{"id":"t4","text":"Notify the provider and blood bank"},{"id":"t5","text":"Document the reaction and interventions"},{"id":"t6","text":"Restart the same unit slowly"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Response to treatments', 'Transfusion reaction response', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341001', 'MCQ', 'A nurse is caring for a client 2 hours after a cardiac catheterization performed through the right femoral artery. Which assessment finding requires immediate follow-up?', 'An expanding groin mass after femoral arterial access indicates hematoma or active bleeding, a priority vascular complication.', '{"options":[{"id":"A","text":"Dull ache at the insertion site rated 2/10"},{"id":"B","text":"A firm, enlarging area of swelling at the groin site"},{"id":"C","text":"Blood pressure of 118/74 mmHg"},{"id":"D","text":"Palpable pedal pulse rated 2+ bilaterally"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Mild discomfort is expected after catheterization.","B":"Correct. An enlarging mass suggests hematoma or bleeding, a vascular complication needing immediate action.","C":"Incorrect. This is a normal blood pressure.","D":"Incorrect. Equal palpable pulses indicate adequate perfusion."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Diagnostic-test monitoring', 'Cardiac catheterization', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341002', 'MCQ', 'A nurse inserts a nasogastric tube for decompression. Before initiating suction, which method is the most reliable to confirm correct placement?', 'Radiographic verification is the most reliable way to confirm initial NG tube placement before use.', '{"options":[{"id":"A","text":"Auscultate air injected over the epigastrium"},{"id":"B","text":"Obtain a radiograph of the tube tip"},{"id":"C","text":"Ask the client to speak"},{"id":"D","text":"Place the external end in water and watch for bubbles"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. The air-bolus method is unreliable and no longer recommended.","B":"Correct. X-ray confirmation is the gold standard for initial NG tube placement.","C":"Incorrect. Ability to speak does not rule out airway placement.","D":"Incorrect. Bubbling is not a valid confirmation method."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG/GI tube', 'Placement verification', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341003', 'MCQ', 'A client is scheduled for a contrast-enhanced CT scan. Which laboratory value should the nurse report to the provider before the study?', 'An elevated creatinine reflects reduced renal function and increases the risk of contrast-induced nephropathy, warranting provider notification.', '{"options":[{"id":"A","text":"Serum creatinine 2.4 mg/dL"},{"id":"B","text":"Hemoglobin 13.2 g/dL"},{"id":"C","text":"Sodium 139 mEq/L"},{"id":"D","text":"White blood cell count 7,500/mm3"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevated creatinine indicates renal impairment, raising the risk of contrast-induced nephropathy.","B":"Incorrect. This hemoglobin is within normal range.","C":"Incorrect. This sodium value is normal.","D":"Incorrect. This WBC count is normal."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Lab-value interpretation', 'Contrast nephropathy', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341004', 'MCQ', 'A laboring client''s electronic fetal monitor shows repetitive late decelerations. Which nursing action should the nurse take FIRST?', 'Late decelerations reflect uteroplacental insufficiency; repositioning to improve perfusion is the priority first action.', '{"options":[{"id":"A","text":"Document the pattern and continue monitoring"},{"id":"B","text":"Reposition the client to the left side"},{"id":"C","text":"Increase the oxytocin infusion rate"},{"id":"D","text":"Prepare for immediate cesarean birth"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Late decelerations require intervention, not just observation.","B":"Correct. Repositioning improves uteroplacental perfusion and is the first intrauterine resuscitation measure.","C":"Incorrect. Oxytocin should be stopped, not increased, with late decelerations.","D":"Incorrect. Conservative measures are attempted before surgical intervention."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive', 'Fetal monitoring', 'Late decelerations', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341005', 'MCQ', 'A nurse is caring for a postoperative client with sequential compression devices ordered for DVT prophylaxis. Which finding would cause the nurse to withhold their application?', 'An existing DVT contraindicates sequential compression because mechanical compression may dislodge the thrombus and cause embolism.', '{"options":[{"id":"A","text":"The client reports mild incisional pain"},{"id":"B","text":"A newly identified deep vein thrombosis in the calf"},{"id":"C","text":"The client is on bed rest"},{"id":"D","text":"The client has a body mass index of 31"}]}'::jsonb, '{"answer":"B","feedback":{"A":"Incorrect. Incisional pain does not contraindicate SCDs.","B":"Correct. An existing DVT is a contraindication because compression could dislodge the clot.","C":"Incorrect. Bed rest is an indication, not a contraindication, for SCDs.","D":"Incorrect. Obesity is a risk factor for DVT and supports prophylaxis."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Venous-return devices', 'Sequential compression devices', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341006', 'MCQ', 'A telemetry monitor shows a client''s heart rhythm has become irregularly irregular with no discernible P waves and a ventricular rate of 140 bpm. Which is the nurse''s priority concern?', 'An irregularly irregular rhythm without P waves indicates atrial fibrillation; atrial stasis raises the risk of thrombus and embolic stroke.', '{"options":[{"id":"A","text":"Risk of thrombus formation and embolic stroke"},{"id":"B","text":"Development of a first-degree AV block"},{"id":"C","text":"Progression to sinus bradycardia"},{"id":"D","text":"Onset of a bundle branch block"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Atrial fibrillation with rapid rate promotes atrial stasis, clot formation, and reduced cardiac output.","B":"Incorrect. First-degree block presents with a prolonged PR interval, not absent P waves.","C":"Incorrect. The rate is elevated, not slow.","D":"Incorrect. This finding describes atrial fibrillation, not a conduction block of the ventricles."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'In-scope testing (ECG)', 'Rhythm recognition', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341007', 'MCQ', 'A nurse is managing an indwelling urinary catheter for a client. Which action best reduces the risk of catheter-associated urinary tract infection?', 'Maintaining the drainage bag below bladder level and preserving the closed system are key CAUTI-prevention measures.', '{"options":[{"id":"A","text":"Keeping the drainage bag below the level of the bladder"},{"id":"B","text":"Irrigating the catheter with sterile saline every shift"},{"id":"C","text":"Disconnecting the tubing to obtain a urine sample"},{"id":"D","text":"Coiling excess tubing above the bladder"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A dependent drainage bag prevents backflow of urine into the bladder, reducing infection risk.","B":"Incorrect. Routine irrigation breaks the closed system and increases infection risk.","C":"Incorrect. Breaking the closed system introduces pathogens.","D":"Incorrect. Dependent loops or elevation impair drainage."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Urinary catheter', 'CAUTI prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341008', 'MCQ', 'A client is receiving moderate (conscious) sedation for an endoscopy. Which assessment finding requires the nurse''s immediate intervention?', 'The primary hazard of moderate sedation is respiratory depression; falling oxygen saturation demands immediate airway and oxygenation support.', '{"options":[{"id":"A","text":"Oxygen saturation falling to 87% on room air"},{"id":"B","text":"Drowsiness with response to verbal stimuli"},{"id":"C","text":"Blood pressure of 124/78 mmHg"},{"id":"D","text":"Heart rate of 82 bpm"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Respiratory depression with desaturation is the most dangerous risk of sedation and needs immediate action.","B":"Incorrect. Responsiveness to voice is the expected level of moderate sedation.","C":"Incorrect. This blood pressure is normal.","D":"Incorrect. This heart rate is within normal limits."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Moderate sedation', 'Monitoring', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341009', 'MCQ', 'A nurse provides discharge teaching to a client after abdominal surgery. Which instruction best helps prevent postoperative atelectasis?', 'Frequent incentive spirometry, deep breathing, and early mobility expand the lungs and prevent postoperative atelectasis.', '{"options":[{"id":"A","text":"Use the incentive spirometer 10 times each hour while awake"},{"id":"B","text":"Limit ambulation until the incision fully heals"},{"id":"C","text":"Avoid coughing to protect the surgical incision"},{"id":"D","text":"Take shallow breaths to reduce incisional pain"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Incentive spirometry promotes lung expansion and prevents atelectasis.","B":"Incorrect. Early ambulation helps prevent pulmonary complications.","C":"Incorrect. Controlled coughing with splinting clears secretions.","D":"Incorrect. Shallow breathing promotes atelectasis."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre/post-operative care', 'Atelectasis prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341010', 'MCQ', 'A client receives continuous enteral feeding through a percutaneous endoscopic gastrostomy (PEG) tube. Which intervention most reduces the risk of aspiration?', 'Elevating the head of the bed during and after enteral feeding is the primary measure to prevent aspiration.', '{"options":[{"id":"A","text":"Keeping the head of the bed elevated at least 30 to 45 degrees"},{"id":"B","text":"Flushing the tube with 10 mL of air before feeding"},{"id":"C","text":"Positioning the client supine during feeding"},{"id":"D","text":"Holding the feeding if residual is 50 mL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Head-of-bed elevation reduces reflux and aspiration during enteral feeding.","B":"Incorrect. Air does not prevent aspiration and is not routine practice.","C":"Incorrect. A flat position increases reflux and aspiration risk.","D":"Incorrect. A residual of 50 mL is within acceptable limits."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Percutaneous feeding tube', 'Aspiration prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_341011', 'MCQ', 'Fifteen minutes after starting a packed red blood cell transfusion, a child develops fever, chills, and flank pain. What is the nurse''s priority action?', 'Fever, chills, and flank pain during transfusion suggest an acute hemolytic reaction; stopping the infusion while maintaining IV access is the priority.', '{"options":[{"id":"A","text":"Stop the transfusion and keep the IV line open with normal saline"},{"id":"B","text":"Slow the transfusion rate and continue monitoring"},{"id":"C","text":"Administer an antipyretic and reassess in 30 minutes"},{"id":"D","text":"Increase the rate to complete the transfusion quickly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. These signs suggest a hemolytic reaction; stopping the transfusion immediately is the priority.","B":"Incorrect. A suspected hemolytic reaction requires stopping, not slowing, the transfusion.","C":"Incorrect. Delaying while blood continues infusing endangers the client.","D":"Incorrect. This worsens a transfusion reaction."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Pediatrics', 'Hematologic', 'Blood/specimen collection', 'Transfusion monitoring', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_341012', 'SATA', 'A nurse assesses a client''s peripheral IV site. Which findings indicate infiltration? Select all that apply.', 'Infiltration produces coolness, swelling, pallor, taut skin, and slowed flow; redness with a streak or purulent drainage indicates phlebitis or infection instead.', '{"options":[{"id":"A","text":"Cool skin around the insertion site"},{"id":"B","text":"Swelling at and above the insertion site"},{"id":"C","text":"Slowed or stopped infusion flow"},{"id":"D","text":"Pale, taut skin near the catheter"},{"id":"E","text":"A red streak tracking up the vein"},{"id":"F","text":"Purulent drainage from the site"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Complication recognition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_341013', 'SATA', 'A nurse reviews a client''s serum potassium of 2.9 mEq/L. Which assessment findings would the nurse expect? Select all that apply.', 'Hypokalemia causes muscle weakness, decreased GI motility, and dysrhythmias; hyperreflexia, diarrhea, and peaked T waves are associated with hyperkalemia.', '{"options":[{"id":"A","text":"Muscle weakness"},{"id":"B","text":"Diminished bowel sounds"},{"id":"C","text":"Cardiac dysrhythmias"},{"id":"D","text":"Hyperactive deep tendon reflexes"},{"id":"E","text":"Diarrhea"},{"id":"F","text":"Peaked T waves on the ECG"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Lab-value interpretation', 'Hypokalemia', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_341014', 'SATA', 'A nurse teaches a client about reducing the risk of venous thromboembolism after orthopedic surgery. Which instructions should be included? Select all that apply.', 'Leg exercises, early ambulation, hydration, and antiembolism stockings prevent VTE; leg crossing impairs venous return and massaging a tender calf could dislodge a clot.', '{"options":[{"id":"A","text":"Perform ankle pumps and leg exercises while in bed"},{"id":"B","text":"Ambulate as early as the provider permits"},{"id":"C","text":"Stay adequately hydrated"},{"id":"D","text":"Wear prescribed antiembolism stockings"},{"id":"E","text":"Cross the legs at the knees when sitting"},{"id":"F","text":"Massage the calves if they feel tender"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre/post-operative education', 'VTE prevention', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_341015', 'SATA', 'A nurse monitors a client after a colonoscopy with polyp removal. Which findings should be reported to the provider? Select all that apply.', 'Abdominal rigidity, frank bleeding, and fever suggest perforation or hemorrhage; mild cramping, flatus, and residual sedation drowsiness are expected.', '{"options":[{"id":"A","text":"Rigid, distended abdomen"},{"id":"B","text":"Bright red rectal bleeding"},{"id":"C","text":"Temperature of 38.6°C (101.5°F)"},{"id":"D","text":"Mild abdominal cramping"},{"id":"E","text":"Passing small amounts of flatus"},{"id":"F","text":"Feeling drowsy from sedation"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Response to procedures', 'Post-colonoscopy', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_341016', 'SATA', 'A nurse reviews trended vital signs over several hours for a postoperative client. Which trends suggest early clinical deterioration requiring escalation? Select all that apply.', 'A rising respiratory rate and heart rate with a falling blood pressure are early warning trends of deterioration; stable temperature and saturation are reassuring.', '{"options":[{"id":"A","text":"Respiratory rate rising from 16 to 26 breaths/min"},{"id":"B","text":"Heart rate climbing from 82 to 116 bpm"},{"id":"C","text":"Systolic blood pressure falling from 122 to 96 mmHg"},{"id":"D","text":"Temperature stable at 36.8°C"},{"id":"E","text":"Oxygen saturation steady at 98%"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Vital-sign trends', 'Early deterioration', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_341017', 'SELECT_N', 'A nurse prepares a client for an abdominal paracentesis. Which 3 actions should the nurse take before the procedure?', 'Emptying the bladder reduces perforation risk, baseline weight/girth allows comparison, and verified consent is required before an invasive procedure.', '{"options":[{"id":"A","text":"Have the client void to empty the bladder"},{"id":"B","text":"Obtain baseline weight and abdominal girth"},{"id":"C","text":"Verify that informed consent is signed"},{"id":"D","text":"Position the client flat and supine"},{"id":"E","text":"Withhold all fluids for 12 hours"},{"id":"F","text":"Administer a cleansing enema"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Diagnostic-test monitoring', 'Paracentesis', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_341018', 'TF', 'After a percutaneous renal biopsy, the nurse should encourage the client to ambulate in the hallway immediately to prevent complications.', 'After renal biopsy the client must remain on bed rest for several hours to reduce the risk of bleeding, not ambulate immediately.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Diagnostic-test monitoring', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_341019', 'MATRIX', 'For each laboratory value, click to indicate whether it is within the expected reference range or a critical value requiring provider notification.', 'Severe hyperkalemia, marked thrombocytopenia, and a supratherapeutic INR are critical values; normal sodium and hemoglobin fall within reference range.', '{"row_label":"Laboratory value","rows":[{"id":"r1","text":"Potassium 6.8 mEq/L"},{"id":"r2","text":"Sodium 140 mEq/L"},{"id":"r3","text":"Platelets 22,000/mm3"},{"id":"r4","text":"Hemoglobin 13.5 g/dL"},{"id":"r5","text":"INR 6.0 on warfarin"}],"columns":[{"id":"c1","text":"Within reference range"},{"id":"c2","text":"Critical value"}]}'::jsonb, '{"cells":{"r1":"c2","r2":"c1","r3":"c2","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'Critical values', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_341020', 'MATRIX_MR', 'For each finding, select all complications it could indicate (a finding may point to more than one).', 'Tachycardia with hypotension may reflect hemorrhage or fluid shifts, fever with leukocytosis suggests infection, crackles with bounding pulse indicate overload, and falling hemoglobin points to bleeding.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Tachycardia and hypotension"},{"id":"r2","text":"Fever with elevated white blood cell count"},{"id":"r3","text":"Bounding pulse with crackles"},{"id":"r4","text":"Falling hemoglobin with restlessness"}],"columns":[{"id":"c1","text":"Hemorrhage"},{"id":"c2","text":"Infection"},{"id":"c3","text":"Fluid overload"}]}'::jsonb, '{"cells":{"r1":["c1","c3"],"r2":["c2"],"r3":["c3"],"r4":["c1"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Focused assessment', 'Complication recognition', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_341021', 'CLOZE', 'A client''s arterial blood gas shows pH 7.30, PaCO2 58 mmHg, and HCO3 25 mEq/L. The nurse interprets this as {1}, and anticipates focusing interventions on {2}.', 'A low pH with elevated PaCO2 and normal bicarbonate indicates uncompensated respiratory acidosis; treatment targets improving alveolar ventilation.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"respiratory acidosis"},{"id":"c2","text":"metabolic alkalosis"},{"id":"c3","text":"respiratory alkalosis"}]},{"id":"b2","choices":[{"id":"c1","text":"improving ventilation"},{"id":"c2","text":"restricting fluids"},{"id":"c3","text":"administering bicarbonate"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Lab-value interpretation', 'Arterial blood gases', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_341022', 'HIGHLIGHT', 'Highlight the findings on this postoperative neurosurgical client that require immediate follow-up. The client is resting quietly. Pupils [[unequal, right sluggish]]. Reports [[worsening headache]]. Blood pressure [[168/60]]. Heart rate [[52]]. Temperature [[37.1°C]]. Incision [[dry and intact]].', 'Unequal pupils, worsening headache, widening pulse pressure, and bradycardia together indicate increasing intracranial pressure and require immediate action; the intact incision and normal temperature do not.', '{"chunks":[{"id":"h1","text":"unequal, right sluggish"},{"id":"h2","text":"worsening headache"},{"id":"h3","text":"168/60"},{"id":"h4","text":"52"},{"id":"h5","text":"37.1°C"},{"id":"h6","text":"dry and intact"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Unequal, sluggish pupils suggest rising intracranial pressure.","h2":"A worsening headache is an early sign of increased ICP.","h3":"Widening pulse pressure is part of Cushing''s triad.","h4":"Bradycardia with hypertension signals increased ICP.","h5":"This is a normal temperature and does not require follow-up.","h6":"An intact, dry incision is an expected finding."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological', 'Trend recognition', 'Neuro checks', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_341023', 'BOWTIE', 'A client on a heparin infusion has an activated partial thromboplastin time (aPTT) far above the therapeutic range and new bruising. Complete the diagram by selecting the complication, actions to take, and parameters to monitor.', 'A supratherapeutic aPTT with bruising signals excessive anticoagulation; the nurse stops heparin, readies its antidote protamine, and monitors aPTT and bleeding. Vitamin K reverses warfarin, not heparin.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Stop the heparin infusion"},{"id":"lt2","text":"Prepare protamine sulfate"},{"id":"lt3","text":"Increase the heparin rate"},{"id":"lt4","text":"Administer vitamin K"}]},"centre":{"label":"Complication","tokens":[{"id":"ct1","text":"Heparin-induced bleeding risk"},{"id":"ct2","text":"Deep vein thrombosis"},{"id":"ct3","text":"Hypovolemic dehydration"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"aPTT"},{"id":"rt2","text":"Signs of active bleeding"},{"id":"rt3","text":"Serum potassium"},{"id":"rt4","text":"Deep tendon reflexes"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Response to treatments', 'Anticoagulation', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_341024', 'DRAG_CLOZE', 'A client''s point-of-care blood glucose is 54 mg/dL with shakiness and diaphoresis. The nurse identifies this as [1] and, because the client is alert and able to swallow, administers [2] first.', 'A glucose of 54 mg/dL with adrenergic symptoms indicates hypoglycemia; for an alert client the first treatment is 15 grams of a fast-acting oral carbohydrate.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"hypoglycemia"},{"id":"t2","text":"15 grams of oral carbohydrate"},{"id":"t3","text":"hyperglycemia"},{"id":"t4","text":"intravenous insulin"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Lab-value interpretation', 'Glucose monitoring', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342001', 'MCQ', 'A nurse monitoring a client on telemetry notes a run of six wide, bizarre QRS complexes at a rate of 160 followed by a return to sinus rhythm. The client is asymptomatic. Which action should the nurse take NEXT?', 'Nonsustained VT in a stable client is investigated for reversible causes such as hypokalemia or hypomagnesemia before escalation.', '{"options":[{"id":"A","text":"Check the most recent serum potassium and magnesium levels"},{"id":"B","text":"Prepare immediately for synchronized cardioversion"},{"id":"C","text":"Begin chest compressions"},{"id":"D","text":"Document the finding and take no further action"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Nonsustained VT is often provoked by electrolyte disturbance, which should be assessed and corrected.","B":"Incorrect. Cardioversion is not indicated for a stable, asymptomatic client with a self-terminating run.","C":"Incorrect. The client has a perfusing rhythm and is asymptomatic.","D":"Incorrect. Nonsustained VT is a warning cue that warrants investigation of a cause."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'ECG monitoring', 'Rhythm interpretation', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342002', 'MCQ', 'A nurse is preparing to administer medication through a newly inserted nasogastric tube. Which finding most reliably confirms correct gastric placement before use?', 'Radiographic confirmation is the standard for verifying initial nasogastric tube placement before use.', '{"options":[{"id":"A","text":"An X-ray report confirming the tip is below the diaphragm"},{"id":"B","text":"Auscultation of air insufflated into the tube"},{"id":"C","text":"Absence of coughing during insertion"},{"id":"D","text":"The client''s ability to speak clearly"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Radiographic confirmation is the most reliable method for verifying initial NG placement.","B":"Incorrect. The auscultatory (whoosh) method is unreliable and no longer recommended.","C":"Incorrect. A tube can enter the airway without coughing, especially in sedated clients.","D":"Incorrect. Speech does not confirm gastric versus respiratory placement."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube', 'Placement verification', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342003', 'MCQ', 'A client scheduled for a contrast-enhanced CT scan has a serum creatinine of 2.4 mg/dL and a BUN of 38 mg/dL. Which action should the nurse take FIRST?', 'An elevated creatinine raises contrast-induced nephropathy risk, so the provider must be notified before contrast is given.', '{"options":[{"id":"A","text":"Notify the provider before the contrast is administered"},{"id":"B","text":"Encourage the client to void immediately before the scan"},{"id":"C","text":"Administer the ordered contrast as scheduled"},{"id":"D","text":"Restrict oral fluids for 8 hours before the scan"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Elevated creatinine indicates impaired renal function and increased risk of contrast-induced nephropathy.","B":"Incorrect. Voiding does not address the renal risk of contrast.","C":"Incorrect. Contrast could worsen renal function and should be reconsidered.","D":"Incorrect. Hydration, not restriction, protects the kidneys against contrast."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Lab-value interpretation', 'Renal function', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342004', 'MCQ', 'During a colonoscopy under moderate sedation, the nurse notes the client''s SpO2 has dropped from 97% to 88% and respirations are shallow at 8/min. Which action should the nurse take FIRST?', 'The first response to sedation-related hypoventilation is stimulation and supplemental oxygen before pharmacologic reversal.', '{"options":[{"id":"A","text":"Stimulate the client and encourage deep breaths while applying oxygen"},{"id":"B","text":"Administer the full dose of naloxone immediately"},{"id":"C","text":"Document the values and continue monitoring"},{"id":"D","text":"Increase the sedation to keep the client comfortable"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Stimulation and oxygen address the immediate oversedation and hypoventilation.","B":"Incorrect. Reversal is escalated only if stimulation and oxygen fail.","C":"Incorrect. A falling SpO2 with hypoventilation requires immediate intervention.","D":"Incorrect. More sedation would worsen respiratory depression."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Moderate sedation', 'Monitoring', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342005', 'MCQ', 'A laboring client''s external fetal monitor shows repetitive decelerations that begin after the peak of each contraction and return to baseline after the contraction ends. Which action should the nurse take FIRST?', 'Late decelerations indicate uteroplacental insufficiency; the first nursing action is repositioning to optimize perfusion.', '{"options":[{"id":"A","text":"Reposition the client to a left lateral position"},{"id":"B","text":"Increase the oxytocin infusion rate"},{"id":"C","text":"Document as a reassuring pattern"},{"id":"D","text":"Prepare for immediate cesarean birth"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Late decelerations suggest uteroplacental insufficiency; repositioning improves placental perfusion.","B":"Incorrect. Increasing oxytocin would worsen the insufficiency.","C":"Incorrect. Late decelerations are nonreassuring.","D":"Incorrect. Intrauterine resuscitation measures are tried first."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Maternity', 'Reproductive', 'Fetal monitoring', 'Late decelerations', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342006', 'MCQ', 'A nurse is caring for a postoperative client with sequential compression devices ordered. The client asks why they are needed. Which explanation is most accurate?', 'Sequential compression devices enhance venous return to reduce venous stasis and DVT risk during immobility.', '{"options":[{"id":"A","text":"They promote venous return and reduce the risk of blood clots in the legs"},{"id":"B","text":"They keep the legs warm to improve circulation to the surgical site"},{"id":"C","text":"They strengthen the calf muscles during bed rest"},{"id":"D","text":"They prevent pressure injuries on the heels"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. SCDs enhance venous return, lowering deep-vein thrombosis risk during immobility.","B":"Incorrect. Warmth is not the therapeutic mechanism.","C":"Incorrect. SCDs do not build muscle.","D":"Incorrect. Pressure injury prevention is a separate intervention."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Venous-return devices', 'SCDs', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342007', 'MCQ', 'A client receiving a continuous heparin infusion has an aPTT of 110 seconds (therapeutic range 60-80 seconds). Which action should the nurse anticipate?', 'An aPTT above the therapeutic range signals excessive anticoagulation; the heparin infusion is held and the provider notified.', '{"options":[{"id":"A","text":"Stopping the infusion and notifying the provider"},{"id":"B","text":"Increasing the infusion rate to reach a higher target"},{"id":"C","text":"Administering vitamin K"},{"id":"D","text":"Continuing the current rate and rechecking in 24 hours"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A supratherapeutic aPTT raises bleeding risk, so the infusion is held and the provider notified.","B":"Incorrect. The value is already above range; increasing worsens bleeding risk.","C":"Incorrect. Vitamin K reverses warfarin, not heparin.","D":"Incorrect. A markedly elevated aPTT requires prompt intervention."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Lab-value interpretation', 'Anticoagulation', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342008', 'MCQ', 'A nurse assesses a client with an indwelling urinary catheter and notes the drainage bag resting on the floor. Which intervention is the priority to reduce infection risk?', 'A catheter drainage bag must stay below bladder level and off the floor to prevent reflux and contamination.', '{"options":[{"id":"A","text":"Secure the bag below bladder level but off the floor on the bed frame"},{"id":"B","text":"Raise the bag above the level of the bladder"},{"id":"C","text":"Clamp the tubing to stop drainage"},{"id":"D","text":"Disconnect and rinse the drainage bag"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Keeping the bag below the bladder yet off the floor prevents reflux and contamination.","B":"Incorrect. Raising the bag promotes reflux of urine and infection.","C":"Incorrect. Clamping causes stasis and increases infection risk.","D":"Incorrect. Breaking the closed system increases infection risk."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Urinary catheter', 'Complication prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342009', 'MCQ', 'A nurse plans to obtain a fasting point-of-care glucose. The client received a dose of insulin glargine 30 minutes ago but has not yet eaten. Which action is most appropriate?', 'After insulin without food, promptly obtaining the glucose identifies hypoglycemia risk before further intervention.', '{"options":[{"id":"A","text":"Obtain the glucose now and hold the meal until the value is reviewed"},{"id":"B","text":"Wait two hours before checking the glucose"},{"id":"C","text":"Give a full meal before checking glucose"},{"id":"D","text":"Cancel the glucose check since insulin was given"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Checking glucose promptly detects hypoglycemia risk after insulin without food.","B":"Incorrect. Delaying could miss developing hypoglycemia.","C":"Incorrect. Feeding first would invalidate the fasting value and delay assessment.","D":"Incorrect. Monitoring is more important after insulin was administered."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Endocrine', 'Diagnostic-test monitoring', 'Point-of-care glucose', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342010', 'MCQ', 'A client returns to the unit after placement of a percutaneous endoscopic gastrostomy (PEG) tube. Which assessment finding requires immediate provider notification?', 'Abdominal rigidity with increasing pain after PEG placement suggests peritonitis and requires immediate notification.', '{"options":[{"id":"A","text":"Firm abdominal rigidity with increasing pain around the site"},{"id":"B","text":"A small amount of serosanguineous drainage at the insertion site"},{"id":"C","text":"Mild redness immediately around the tube"},{"id":"D","text":"The client reports feeling hungry"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rigidity and worsening pain suggest peritonitis, a serious complication.","B":"Incorrect. Scant serosanguineous drainage is expected early after placement.","C":"Incorrect. Slight redness is common in the first day.","D":"Incorrect. Hunger is not an emergency finding."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'Percutaneous feeding tube', 'Post-procedure care', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_342011', 'MCQ', 'Four hours after application of a long-leg cast, a client reports increasing pain unrelieved by analgesics and numbness in the toes. Which action should the nurse take FIRST?', 'Pain out of proportion with numbness after casting warrants an immediate neurovascular assessment for compartment syndrome.', '{"options":[{"id":"A","text":"Assess capillary refill, pulses, and sensation distal to the cast"},{"id":"B","text":"Administer an additional dose of opioid analgesic"},{"id":"C","text":"Elevate the leg above heart level and reassess in an hour"},{"id":"D","text":"Apply a warm compress over the cast"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Escalating pain and numbness raise concern for compartment syndrome; a neurovascular check is done first.","B":"Incorrect. More analgesia could mask worsening ischemia.","C":"Incorrect. Delaying assessment risks irreversible damage.","D":"Incorrect. Heat does not address compartment syndrome and delays care."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Musculoskeletal', 'Pre/post-operative care', 'Neurovascular assessment', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_342012', 'SATA', 'A nurse is providing preoperative teaching to a client scheduled for abdominal surgery. Which instructions help prevent postoperative pulmonary complications? Select all that apply.', 'Incentive spirometry, splinted coughing, repositioning, and deep breathing mobilize secretions and prevent atelectasis.', '{"options":[{"id":"A","text":"Use the incentive spirometer 10 times each hour while awake"},{"id":"B","text":"Splint the incision with a pillow when coughing"},{"id":"C","text":"Turn and reposition every 2 hours"},{"id":"D","text":"Perform deep-breathing exercises regularly"},{"id":"E","text":"Remain flat and still to protect the incision"},{"id":"F","text":"Avoid coughing to prevent wound dehiscence"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Pre-operative education', 'Complication prevention', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_342013', 'SATA', 'A nurse is monitoring a client 15 minutes into a packed red blood cell transfusion. Which findings indicate a possible acute hemolytic transfusion reaction? Select all that apply.', 'Flank pain, fever, hemoglobinuria, and hypotension are hallmark signs of an acute hemolytic transfusion reaction.', '{"options":[{"id":"A","text":"Flank or lower back pain"},{"id":"B","text":"Fever and chills"},{"id":"C","text":"Dark or red-tinged urine"},{"id":"D","text":"Sudden hypotension"},{"id":"E","text":"Gradual rise in hemoglobin"},{"id":"F","text":"Decreasing heart rate to 55 bpm"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Hematologic', 'Blood/specimen collection', 'Transfusion monitoring', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_342014', 'SATA', 'A nurse assesses a peripheral IV site and suspects infiltration. Which findings support this conclusion? Select all that apply.', 'Infiltration produces coolness, swelling, taut skin, and impaired flow, whereas warmth and streaking suggest phlebitis or infection.', '{"options":[{"id":"A","text":"Coolness of the surrounding skin"},{"id":"B","text":"Swelling around the insertion site"},{"id":"C","text":"Slowed or stopped infusion flow"},{"id":"D","text":"Warmth and a red streak up the vein"},{"id":"E","text":"Purulent drainage at the site"},{"id":"F","text":"Blanching or taut skin at the site"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Complication recognition', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_342015', 'SATA', 'A nurse reviews serial vital signs over several hours for a postoperative client. Which trends suggest early clinical deterioration warranting escalation? Select all that apply.', 'Rising respiratory rate and heart rate with falling blood pressure and oxygen saturation are early warning signs of deterioration.', '{"options":[{"id":"A","text":"Respiratory rate rising from 16 to 26/min"},{"id":"B","text":"Systolic blood pressure falling from 122 to 96 mmHg"},{"id":"C","text":"Heart rate climbing from 78 to 112 bpm"},{"id":"D","text":"SpO2 declining from 97% to 91% on room air"},{"id":"E","text":"Temperature stable at 36.9°C"},{"id":"F","text":"Urine output steady at 50 mL/hr"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Vital-sign trends', 'Early deterioration', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_342016', 'SATA', 'A nurse cares for a client who just completed a lumbar puncture. Which postprocedure interventions are appropriate? Select all that apply.', 'Lying flat, hydration, site monitoring, and headache assessment reduce and detect post-lumbar-puncture complications.', '{"options":[{"id":"A","text":"Encourage increased fluid intake"},{"id":"B","text":"Keep the client lying flat as ordered"},{"id":"C","text":"Monitor the puncture site for leakage of fluid"},{"id":"D","text":"Assess for headache"},{"id":"E","text":"Ambulate the client immediately to prevent clots"},{"id":"F","text":"Restrict all oral fluids for 6 hours"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Neurological', 'Diagnostic-test monitoring', 'Post-lumbar puncture', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_342017', 'SELECT_N', 'A client has a nasogastric tube set to low intermittent suction. Which 3 findings should prompt the nurse to notify the provider?', 'Hypokalemia, a nonfunctioning distended abdomen, and bloody drainage are complications requiring provider notification.', '{"options":[{"id":"A","text":"Serum potassium of 3.0 mEq/L"},{"id":"B","text":"No drainage output for the past 6 hours with abdominal distention"},{"id":"C","text":"Coffee-ground or frankly bloody drainage"},{"id":"D","text":"300 mL of greenish gastric drainage over a shift"},{"id":"E","text":"The client reports mild nasal discomfort"},{"id":"F","text":"Intermittent bubbling in the suction canister"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'GI', 'NG tube', 'Complication prevention', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_342018', 'TF', 'A client with a serum potassium of 6.8 mEq/L and peaked T waves on the ECG can safely wait until the next scheduled provider round for treatment.', 'Severe hyperkalemia with ECG changes is a life-threatening emergency requiring immediate intervention, not a delay.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Renal/Genitourinary', 'Diagnostic-test monitoring', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_342019', 'MATRIX', 'For each IV site finding, click to indicate whether it best reflects infiltration or phlebitis.', 'Infiltration causes cool swelling and taut skin; phlebitis causes warmth, redness, and a cord along the vein.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Cool, swollen, taut skin at the site"},{"id":"r2","text":"Warmth with a palpable cord along the vein"},{"id":"r3","text":"Redness tracking up the vein"},{"id":"r4","text":"Blanched skin with slowed infusion"}],"columns":[{"id":"c1","text":"Infiltration"},{"id":"c2","text":"Phlebitis"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c2","r4":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Peripheral IV', 'Complication differentiation', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_342020', 'MATRIX_MR', 'For each laboratory value, select all appropriate nurse responses (more than one may apply).', 'Low potassium and magnesium are critical and predispose to dysrhythmias, whereas the normal sodium and calcium need no urgent action.', '{"row_label":"Lab value","rows":[{"id":"r1","text":"Potassium 2.8 mEq/L"},{"id":"r2","text":"Sodium 138 mEq/L"},{"id":"r3","text":"Magnesium 1.1 mEq/L"},{"id":"r4","text":"Calcium 9.2 mg/dL"}],"columns":[{"id":"c1","text":"Notify provider promptly"},{"id":"c2","text":"Anticipate cardiac monitoring"},{"id":"c3","text":"Reassess as routine, no urgent action"}]}'::jsonb, '{"cells":{"r1":["c1","c2"],"r2":["c3"],"r3":["c1","c2"],"r4":["c3"]},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Lab-value interpretation', 'Critical values', 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_342021', 'CLOZE', 'An ABG shows pH 7.30, PaCO2 55 mmHg, and HCO3 24 mEq/L. The nurse interprets this as {1}, most consistent with {2}.', 'A low pH with an elevated PaCO2 and normal bicarbonate indicates uncompensated respiratory acidosis from hypoventilation.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"respiratory acidosis"},{"id":"c2","text":"metabolic alkalosis"},{"id":"c3","text":"respiratory alkalosis"}]},{"id":"b2","choices":[{"id":"c1","text":"hypoventilation"},{"id":"c2","text":"excess vomiting"},{"id":"c3","text":"hyperventilation"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Respiratory', 'Diagnostic-test monitoring', 'Arterial blood gas', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_342022', 'HIGHLIGHT', 'Highlight the assessment findings in this postoperative note that require immediate follow-up. The client is drowsy but rousable. Temperature [[37.1°C]]. Respiratory rate [[8/min]]. SpO2 [[89% on room air]]. Blood pressure 118/74. Reports [[incisional pain rated 3/10]]. Surgical dressing [[saturated with bright red blood]].', 'A low respiratory rate, hypoxemia, and a blood-saturated dressing are urgent postoperative cues requiring follow-up.', '{"chunks":[{"id":"h1","text":"37.1°C"},{"id":"h2","text":"8/min"},{"id":"h3","text":"89% on room air"},{"id":"h4","text":"incisional pain rated 3/10"},{"id":"h5","text":"saturated with bright red blood"}]}'::jsonb, '{"correct_ids":["h2","h3","h5"],"feedback":{"h1":"Normal temperature — no follow-up needed.","h2":"Respiratory depression — needs immediate follow-up.","h3":"Hypoxemia — needs immediate follow-up.","h4":"Mild expected postoperative pain.","h5":"Active hemorrhage — urgent."}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Multisystem', 'Trend recognition', 'Post-operative assessment', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_342023', 'BOWTIE', 'A postoperative client has rising heart rate, falling blood pressure, and a distended, firm surgical site. Complete the diagram by selecting the condition, actions to take, and parameters to monitor.', 'Tachycardia, hypotension, and a firm distended site indicate postoperative hemorrhage, managed with pressure and fluids while monitoring H&H and vital signs.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Apply direct pressure and notify the surgeon"},{"id":"lt2","text":"Increase IV fluid rate as ordered"},{"id":"lt3","text":"Ambulate the client to improve circulation"},{"id":"lt4","text":"Withhold all fluids"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Postoperative hemorrhage"},{"id":"ct2","text":"Pulmonary embolism"},{"id":"ct3","text":"Urinary retention"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Hemoglobin and hematocrit"},{"id":"rt2","text":"Blood pressure and heart rate"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Blood glucose"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Complication recognition', 'Postoperative bleeding', 'Medium', 'Evaluate', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_342024', 'DRAG_CLOZE', 'The nurse teaches that antiembolism stockings should be applied [1] and removed [2] to inspect the skin.', 'Antiembolism stockings are applied before rising, while leg veins are least distended, and removed once or twice daily for skin inspection.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"before the client gets out of bed in the morning"},{"id":"t2","text":"once or twice daily"},{"id":"t3","text":"only at bedtime"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Physiological Integrity', 'Reduction of Risk Potential', 'Medical-Surgical', 'Cardiovascular', 'Venous-return devices', 'Antiembolism stockings', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327001', 'MCQ', 'A nurse admits a client with suspected active pulmonary tuberculosis. Which room assignment and protective measure should the nurse arrange?', 'Active TB spreads by airborne droplet nuclei, requiring a negative-pressure room and a fit-tested N95 respirator.', '{"options":[{"id":"A","text":"Private negative-pressure room; staff wear an N95 respirator"},{"id":"B","text":"Semi-private room; staff wear a surgical mask"},{"id":"C","text":"Private positive-pressure room; staff wear a gown and gloves"},{"id":"D","text":"Any room; staff perform hand hygiene only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Airborne precautions require a negative-pressure room and fit-tested N95.","B":"Incorrect. A surgical mask does not filter airborne droplet nuclei.","C":"Incorrect. Positive pressure pushes contaminated air out to the corridor.","D":"Incorrect. TB requires airborne, not standard-only, precautions."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Transmission-based precautions', 'Airborne precautions', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327002', 'MCQ', 'A nurse finishes caring for a client with Clostridioides difficile infection. Which hand hygiene method is most appropriate before leaving the room?', 'C. difficile forms spores resistant to alcohol; soap-and-water washing with friction is required to physically remove them.', '{"options":[{"id":"A","text":"Wash hands with soap and water"},{"id":"B","text":"Use alcohol-based hand rub only"},{"id":"C","text":"Apply hand sanitizer, then don clean gloves"},{"id":"D","text":"Rinse hands with water alone"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. C. difficile spores are not killed by alcohol; friction with soap and water is required.","B":"Incorrect. Alcohol does not inactivate C. difficile spores.","C":"Incorrect. Gloves over unwashed hands do not remove spores.","D":"Incorrect. Water without soap fails to remove spores mechanically."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', 'Alcohol rub vs soap', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327003', 'MCQ', 'A nurse is removing personal protective equipment after leaving a contact-precaution room. After removing gloves and gown, which item should be removed next?', 'Doffing order removes the most contaminated items first; hand hygiene is performed between steps and goggles are handled by the clean strap.', '{"options":[{"id":"A","text":"Perform hand hygiene, then remove goggles"},{"id":"B","text":"Remove the N95 respirator inside the room"},{"id":"C","text":"Remove goggles by the front lens"},{"id":"D","text":"Leave the room before any further removal"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. After gown and gloves, hand hygiene precedes removing the goggles by the clean strap.","B":"Incorrect. A respirator is removed after exiting, not before goggles here.","C":"Incorrect. The front is contaminated; handle by the strap.","D":"Incorrect. Eye protection is removed before or as leaving, not left on indefinitely."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', 'Doffing sequence', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327004', 'MCQ', 'A nurse is about to administer medication to a client who is confused and cannot state a name. Which action correctly verifies the client''s identity?', 'Two client-specific identifiers such as name and date of birth on the wristband, matched to the record, are required, especially when the client cannot participate.', '{"options":[{"id":"A","text":"Compare the name and date of birth on the wristband with the medication record"},{"id":"B","text":"Use the room and bed number to confirm identity"},{"id":"C","text":"Ask the client in the next bed to confirm the name"},{"id":"D","text":"Administer the medication because the chart is at the bedside"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two identifiers matched against the record verify identity when the client cannot respond.","B":"Incorrect. Location is not an acceptable identifier.","C":"Incorrect. Another client is not a reliable identifier.","D":"Incorrect. Chart location does not verify the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', 'Two identifiers', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327005', 'MCQ', 'A nurse working on a postpartum unit is approached by a person in scrubs without an identification badge who offers to take an infant for tests. Which action should the nurse take?', 'Newborn abduction prevention requires that infants be transported only by staff with proper unit identification; an unbadged individual is a red flag.', '{"options":[{"id":"A","text":"Do not release the infant and verify the person''s identity with the unit"},{"id":"B","text":"Release the infant since the person is wearing scrubs"},{"id":"C","text":"Ask the mother whether it is acceptable to take the infant"},{"id":"D","text":"Walk the infant to the test area yourself without checking"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Infants are released only to identified staff wearing proper unit identification.","B":"Incorrect. Scrubs alone do not confirm authorized staff.","C":"Incorrect. The mother cannot verify staff credentials.","D":"Incorrect. This ignores the security concern of an unbadged person."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Multisystem', 'Newborn security', 'Abduction prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327006', 'MCQ', 'A nurse must reposition a heavy, immobile client higher in bed. Which technique best protects both nurse and client from injury?', 'Safe handling uses friction-reducing devices and adequate personnel, keeping the back straight and load close to reduce injury to nurse and client.', '{"options":[{"id":"A","text":"Use a friction-reducing slide sheet with a second staff member"},{"id":"B","text":"Bend at the waist and pull the client up alone"},{"id":"C","text":"Grasp under the client''s arms and drag upward"},{"id":"D","text":"Raise the head of the bed and let the client slide down"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Mechanical aids and teamwork reduce shear and staff strain.","B":"Incorrect. Bending at the waist and solo lifting risk back injury.","C":"Incorrect. Axillary dragging risks brachial plexus and skin injury.","D":"Incorrect. This increases shear on the sacrum."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Ergonomics', 'Safe client handling', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327007', 'MCQ', 'A nurse discovers that a colleague documented a medication as given but the dose is still in the drawer. What is the most appropriate initial action?', 'The priority is to assess the client for effects of the missed dose, then file a factual incident report so the near-miss can be reviewed.', '{"options":[{"id":"A","text":"Assess the client and complete an incident report"},{"id":"B","text":"Record the discrepancy in the client''s chart as an error"},{"id":"C","text":"Confront the colleague publicly at the nurses'' station"},{"id":"D","text":"Discard the dose and say nothing to avoid conflict"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Client safety is assessed first, then the event is objectively documented.","B":"Incorrect. Incident reports, not the medical record, capture the event, and the client comes first.","C":"Incorrect. Public confrontation does not address client safety.","D":"Incorrect. Concealing a near-miss prevents system learning and endangers the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Error and near-miss reporting', 'Incident reports', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327008', 'MCQ', 'During a sterile dressing change, the nurse notices the outer 1-inch border of the sterile field has become damp from saline. How should the nurse interpret this field?', 'A sterile field that becomes wet is considered contaminated because moisture allows microorganisms to strike through from the underlying surface.', '{"options":[{"id":"A","text":"The entire field is contaminated because moisture wicks microorganisms through"},{"id":"B","text":"Only the damp border is unsterile; the center remains usable"},{"id":"C","text":"The field is sterile as long as nothing touched the damp area"},{"id":"D","text":"The field can be dried with a sterile towel and reused"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A wet field allows strike-through contamination and is no longer sterile.","B":"Incorrect. Moisture provides a path for microorganisms across the field.","C":"Incorrect. Wetness itself breaks sterility via strike-through.","D":"Incorrect. Once contaminated by moisture, the field is discarded."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Sterile technique', 'Sterile field maintenance', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327009', 'MCQ', 'A client is placed in bilateral soft wrist restraints for pulling at a central line after other measures failed. Which nursing action is essential during restraint use?', 'Restrained clients require frequent neurovascular and skin assessment, periodic release with range of motion, and securing to the bed frame with a quick-release tie.', '{"options":[{"id":"A","text":"Assess circulation and skin under the restraint and release it periodically"},{"id":"B","text":"Tie the restraints to the side rails for quick access"},{"id":"C","text":"Leave the restraints on continuously until the provider rounds"},{"id":"D","text":"Apply the restraints using a quick-release square knot at the wrist"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Restrained limbs need frequent neurovascular checks and periodic release with ROM.","B":"Incorrect. Restraints are secured to the bed frame, never the side rails.","C":"Incorrect. Continuous restraint without release risks tissue injury.","D":"Incorrect. Knots go at the frame, not the wrist, and must not tighten."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Neurological', 'Restraints', 'Monitoring requirements', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327010', 'MCQ', 'A client scheduled for surgery reports itching and hives when blowing up balloons and swelling after eating bananas and avocados. Which precaution is most important for the nurse to implement?', 'The latex-fruit syndrome (banana, avocado, kiwi) with balloon reactions signals latex allergy, requiring a latex-free environment to prevent anaphylaxis.', '{"options":[{"id":"A","text":"Prepare a latex-free environment and equipment for the client"},{"id":"B","text":"Restrict only the client''s diet during the hospital stay"},{"id":"C","text":"Administer a prophylactic antihistamine and proceed as usual"},{"id":"D","text":"Document the allergy and take no further action"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Balloon reactions plus banana/avocado cross-reactivity indicate latex allergy.","B":"Incorrect. Diet alone ignores the latex exposure risk in the OR.","C":"Incorrect. Premedication does not replace avoiding latex.","D":"Incorrect. Documentation without environmental change leaves the client exposed."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Allergy assessment', 'Latex allergy', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327011', 'MCQ', 'A nurse enters the room of an agitated client who is pacing, clenching fists, and shouting. Which action best protects the nurse''s safety while de-escalating?', 'During potential violence, the nurse keeps a clear escape route, maintains distance and a calm tone, and avoids cornering the client or being cornered.', '{"options":[{"id":"A","text":"Maintain an open exit path and keep a calm, nonthreatening distance"},{"id":"B","text":"Stand close and place a hand on the client''s shoulder"},{"id":"C","text":"Position yourself between the client and the door"},{"id":"D","text":"Raise your voice to command the client to sit down"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. An unobstructed exit and personal space reduce the nurse''s risk during escalation.","B":"Incorrect. Touch and closeness can trigger further aggression.","C":"Incorrect. Blocking the exit traps both parties and escalates threat.","D":"Incorrect. A raised voice heightens agitation."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health', 'Violence and security', 'De-escalation and staff safety', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_327012', 'MCQ', 'A home-care nurse visits a client newly started on home oxygen. Which observation requires immediate correction?', 'Oxygen supports combustion; open flames such as a burning candle near the source pose an immediate fire risk and must be eliminated.', '{"options":[{"id":"A","text":"A lit candle burning on the table near the oxygen concentrator"},{"id":"B","text":"A ''No Smoking'' sign posted on the front door"},{"id":"C","text":"Oxygen tubing running along the baseboard to the chair"},{"id":"D","text":"A fire extinguisher stored in the kitchen"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Open flames near oxygen are a fire hazard and must be removed at once.","B":"Incorrect. This is an appropriate safety measure.","C":"Incorrect. Secured tubing is acceptable if not a trip hazard.","D":"Incorrect. Having an extinguisher is a positive safety finding."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home safety assessment', 'Oxygen therapy safety', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_327013', 'SATA', 'A nurse is reviewing standard precautions with a new orientee. Which actions correctly reflect standard precautions? Select all that apply.', 'Standard precautions apply to all clients and include hand hygiene, appropriate PPE for anticipated fluid exposure, and never recapping needles.', '{"options":[{"id":"A","text":"Perform hand hygiene before and after client contact"},{"id":"B","text":"Wear gloves when contact with body fluids is anticipated"},{"id":"C","text":"Dispose of used needles in a puncture-resistant sharps container"},{"id":"D","text":"Wear a gown when clothing may be soiled with body fluids"},{"id":"E","text":"Recap needles by hand after use"},{"id":"F","text":"Apply standard precautions only to clients with known infections"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Standard precautions', 'Application', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_327014', 'SATA', 'A nurse is implementing fall precautions for an older adult at high risk. Which interventions are appropriate? Select all that apply.', 'Fall precautions lower the bed, keep the call light reachable, ensure clear lighting and nonskid footwear; four raised rails are a restraint and dim lighting increases fall risk.', '{"options":[{"id":"A","text":"Keep the bed in the lowest position with wheels locked"},{"id":"B","text":"Place the call light within the client''s reach"},{"id":"C","text":"Ensure a clear, well-lit path to the bathroom"},{"id":"D","text":"Provide nonskid footwear when ambulating"},{"id":"E","text":"Raise all four side rails to prevent the client from getting up"},{"id":"F","text":"Keep the room dim at all times to promote rest"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Fall prevention', 'Environmental measures', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_327015', 'SATA', 'A client is placed on contact precautions for MRSA colonization. Which nursing actions are required? Select all that apply.', 'Contact precautions require gown and gloves, dedicated equipment, hand hygiene, and limited transport; airborne measures such as N95 and negative pressure are not indicated for MRSA.', '{"options":[{"id":"A","text":"Don a gown and gloves before entering the room"},{"id":"B","text":"Use dedicated equipment such as a stethoscope for this client"},{"id":"C","text":"Perform hand hygiene after removing gloves"},{"id":"D","text":"Wear an N95 respirator for all care"},{"id":"E","text":"Place the client in a negative-pressure room"},{"id":"F","text":"Limit transport of the client outside the room to essential purposes"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Contact precautions', 'MRSA', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_327016', 'SATA', 'A nurse manages a blood spill and contaminated supplies in a client room. Which actions are appropriate? Select all that apply.', 'Biohazard handling requires PPE, disinfection, and disposal of contaminated items and sharps in labeled biohazard and puncture-resistant containers, not regular trash.', '{"options":[{"id":"A","text":"Don gloves before cleaning the blood spill"},{"id":"B","text":"Discard blood-soaked dressings in a biohazard container"},{"id":"C","text":"Clean the spill with an approved disinfectant"},{"id":"D","text":"Place used sharps in a puncture-resistant container"},{"id":"E","text":"Throw contaminated gloves in the regular trash"},{"id":"F","text":"Wipe the spill with a dry paper towel and leave the area"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Biohazard handling', 'Spill and waste management', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_327017', 'SATA', 'A small fire ignites in a client''s trash can. Which immediate actions reflect correct fire-response priorities? Select all that apply.', 'The RACE sequence is Rescue, Alarm, Contain, and Extinguish/Evacuate; opening windows feeds oxygen to the fire and elevators must not be used.', '{"options":[{"id":"A","text":"Rescue any clients in immediate danger"},{"id":"B","text":"Activate the fire alarm"},{"id":"C","text":"Close doors to contain the fire"},{"id":"D","text":"Use an extinguisher on a small, contained fire"},{"id":"E","text":"Open windows to ventilate the smoke"},{"id":"F","text":"Use the elevators to evacuate quickly"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Emergency preparedness', 'Fire response (RACE)', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_327018', 'SELECT_N', 'A nurse receives a new medication order that appears illegible and possibly contains a dangerous abbreviation. Which 3 actions are appropriate before administering?', 'An unclear or unsafe order must be clarified with the prescriber, cross-checked, and withheld until verified; guessing or administering first endangers the client.', '{"options":[{"id":"A","text":"Contact the prescriber to clarify the order"},{"id":"B","text":"Verify the order against the pharmacy record"},{"id":"C","text":"Withhold the medication until the order is clarified"},{"id":"D","text":"Interpret the abbreviation based on what seems most likely"},{"id":"E","text":"Administer the dose and clarify afterward"},{"id":"F","text":"Ask another nurse to guess the intended dose"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Treatment-order verification', 'Unclear prescriptions', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_327019', 'TF', 'When donning sterile gloves, the nurse may touch the outside surface of the first glove with bare fingers as long as hand hygiene was performed first.', 'Sterile gloving requires touching only the inside cuff with bare hands; the outer surface must remain untouched by ungloved skin to preserve sterility.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Surgical asepsis', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_327020', 'MATRIX', 'For each client, click to indicate which transmission-based precaution is required.', 'TB and measles require airborne precautions; meningococcal disease and influenza require droplet; C. difficile requires contact precautions.', '{"row_label":"Client","rows":[{"id":"r1","text":"Client with active pulmonary tuberculosis"},{"id":"r2","text":"Client with meningococcal meningitis"},{"id":"r3","text":"Client with Clostridioides difficile diarrhea"},{"id":"r4","text":"Client with measles (rubeola)"},{"id":"r5","text":"Client with seasonal influenza"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Transmission-based precautions', 'Precaution matching', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_327021', 'MATRIX_MR', 'For each scenario, select all PPE items the nurse should wear.', 'PPE is matched to the precaution and task: airborne care needs an N95 plus gloves/gown when soiling is likely; contact care needs gloves and gown; a routine venipuncture needs gloves.', '{"row_label":"PPE item","rows":[{"id":"r1","text":"Suctioning a client on airborne precautions for TB"},{"id":"r2","text":"Bathing a client on contact precautions for MRSA"},{"id":"r3","text":"Drawing blood from a client on standard precautions"}],"columns":[{"id":"c1","text":"Gloves"},{"id":"c2","text":"Gown"},{"id":"c3","text":"N95 respirator"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1","c2"],"r3":["c1"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE selection', 'Precaution-based PPE', 'Medium', 'Analyze', '{}', 6, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_327022', 'CLOZE', 'A client with severe neutropenia requires {1} precautions, so the nurse should {2}.', 'A neutropenic client needs a protective environment; fresh flowers and standing water harbor organisms and are removed to reduce infection risk.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"protective (reverse isolation)"},{"id":"c2","text":"airborne"},{"id":"c3","text":"droplet"}]},{"id":"b2","choices":[{"id":"c1","text":"remove fresh flowers and standing water from the room"},{"id":"c2","text":"place the client in a negative-pressure room"},{"id":"c3","text":"restrict the client to soap-and-water hand hygiene only"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Neutropenic precautions', 'Protective environment', 'Medium', 'Analyze', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_327023', 'HIGHLIGHT', 'A home-care nurse assesses an older adult''s home. Highlight the findings that increase the client''s risk of falling. The client has [[loose throw rugs in the hallway]]. There are [[grab bars installed in the shower]]. The stairs have [[no handrail]]. The kitchen is [[brightly lit]]. Electrical [[cords run across the walkway]].', 'Loose rugs, absent stair handrails, and cords across walkways are trip hazards; grab bars and good lighting are protective factors.', '{"chunks":[{"id":"h1","text":"loose throw rugs in the hallway"},{"id":"h2","text":"grab bars installed in the shower"},{"id":"h3","text":"no handrail"},{"id":"h4","text":"brightly lit"},{"id":"h5","text":"cords run across the walkway"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"Loose rugs are a common trip hazard.","h2":"Grab bars reduce fall risk — a positive finding.","h3":"Stairs without a handrail increase fall risk.","h4":"Good lighting reduces fall risk.","h5":"Cords across walkways are a trip hazard."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Musculoskeletal', 'Home safety assessment', 'Fall hazards', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_327024', 'BOWTIE', 'A nurse sustains a needlestick from a used hollow-bore needle. Complete the diagram by selecting the priority actions, the immediate risk, and the follow-up steps.', 'After a needlestick the nurse washes the site, reports the exposure, and follows up with an exposure report and baseline/source testing for bloodborne pathogens.', '{"left":{"label":"Immediate actions","tokens":[{"id":"lt1","text":"Wash the site with soap and water"},{"id":"lt2","text":"Report the exposure to the supervisor"},{"id":"lt3","text":"Squeeze the wound and suck out the blood"},{"id":"lt4","text":"Apply a chemical disinfectant into the puncture"}]},"centre":{"label":"Immediate risk","tokens":[{"id":"ct1","text":"Bloodborne pathogen exposure"},{"id":"ct2","text":"Latex allergic reaction"},{"id":"ct3","text":"Airborne infection"}]},"right":{"label":"Follow-up steps","tokens":[{"id":"rt1","text":"Complete an incident/exposure report"},{"id":"rt2","text":"Obtain baseline bloodwork and source testing"},{"id":"rt3","text":"Return to work with no further action"},{"id":"rt4","text":"Recap the needle and reuse the syringe"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Sharps injury', 'Needlestick response', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_327025', 'DRAG_CLOZE', 'Before entering the room of a client on droplet precautions, the nurse should apply a [1], and the client should wear a [2] when transported outside the room.', 'Droplet precautions require staff to wear a surgical mask on entry, and the client dons a surgical mask during any necessary transport.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"surgical mask"},{"id":"t2","text":"surgical mask on the client"},{"id":"t3","text":"N95 respirator"},{"id":"t4","text":"negative-pressure hood"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Safe equipment use', 'Isolation equipment', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_327026', 'DRAG_ORDER', 'A nurse prepares to enter the room of a client requiring full personal protective equipment. Place the donning steps in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene"},{"id":"t2","text":"Put on the gown"},{"id":"t3","text":"Put on the mask or respirator"},{"id":"t4","text":"Put on goggles or face shield"},{"id":"t5","text":"Put on gloves"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', 'Donning sequence', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328001', 'MCQ', 'A client is admitted with a productive cough, night sweats, and a positive acid-fast bacilli sputum smear. Which action should the nurse take to protect other clients and staff?', 'Suspected pulmonary tuberculosis requires airborne precautions: a negative-pressure room and a fit-tested N95 respirator.', '{"options":[{"id":"A","text":"Place the client in a negative-pressure room and wear an N95 respirator"},{"id":"B","text":"Place the client in a private room and wear a surgical mask within 3 feet"},{"id":"C","text":"Cohort the client with another pneumonia client"},{"id":"D","text":"Apply contact precautions with gown and gloves only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Suspected tuberculosis requires airborne precautions with an airborne infection isolation room and a fit-tested N95.","B":"Incorrect. A surgical mask and droplet precautions are insufficient for airborne organisms.","C":"Incorrect. Suspected TB cannot be cohorted with non-TB clients.","D":"Incorrect. Contact precautions do not address airborne transmission."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Transmission-based precautions', 'Airborne', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328002', 'MCQ', 'A nurse is caring for a client with Clostridioides difficile infection. After removing gloves and gown, which hand-hygiene method is MOST appropriate before leaving the room?', 'C. difficile forms alcohol-resistant spores; only soap-and-water washing mechanically removes them.', '{"options":[{"id":"A","text":"Wash hands with soap and water"},{"id":"B","text":"Use an alcohol-based hand rub"},{"id":"C","text":"Apply a foaming antiseptic gel"},{"id":"D","text":"Rinse hands with water only"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. C. difficile spores are not killed by alcohol; mechanical removal with soap and water is required.","B":"Incorrect. Alcohol does not eliminate C. difficile spores.","C":"Incorrect. Antiseptic gels are alcohol-based and ineffective against spores.","D":"Incorrect. Water alone does not remove pathogens effectively."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Hand hygiene', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328003', 'MCQ', 'A nurse is removing personal protective equipment after caring for a client on contact and droplet precautions. Which item should the nurse remove LAST?', 'Doffing sequence removes gloves, goggles, gown, then mask/respirator last after exiting the room.', '{"options":[{"id":"A","text":"Mask or respirator"},{"id":"B","text":"Gloves"},{"id":"C","text":"Gown"},{"id":"D","text":"Goggles"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The mask is removed last, after leaving the room, because it protects against inhaled pathogens until the end.","B":"Incorrect. Gloves are the most contaminated item and are removed first.","C":"Incorrect. The gown is removed after gloves but before the mask.","D":"Incorrect. Eye protection is removed before the mask."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE', 'Doffing sequence', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328004', 'MCQ', 'A nurse must reposition a heavy, immobile client higher in bed. Which action best protects both the nurse and the client from injury?', 'Friction-reducing devices plus adequate staff prevent back injury to the nurse and shearing to the client.', '{"options":[{"id":"A","text":"Use a friction-reducing slide sheet with a second staff member"},{"id":"B","text":"Lift the client alone by pulling under the arms"},{"id":"C","text":"Raise the bed to its lowest position and pull the client up"},{"id":"D","text":"Ask the client to grab the side rail and pull independently"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Mechanical aids and team lifting reduce musculoskeletal injury risk.","B":"Incorrect. Pulling under the arms risks shoulder injury and back strain.","C":"Incorrect. Working at waist height, not the lowest setting, protects the nurse''s back.","D":"Incorrect. An immobile client cannot safely reposition independently."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Ergonomics and safe handling', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328005', 'MCQ', 'A nurse discovers that a colleague nearly administered a medication to the wrong client but caught the error before giving it. What is the nurse''s most appropriate action?', 'Near-miss reporting is a non-punitive quality-improvement tool that captures latent system errors before harm occurs.', '{"options":[{"id":"A","text":"Encourage completion of a near-miss (incident) report"},{"id":"B","text":"Do nothing because no harm reached the client"},{"id":"C","text":"Document the event in the client''s medical record"},{"id":"D","text":"Report the colleague to the state board of nursing"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Near-miss reporting drives system improvement and is non-punitive.","B":"Incorrect. Near misses must be reported to prevent future errors.","C":"Incorrect. Incident reports are not filed in the medical record.","D":"Incorrect. A caught near miss is a quality-improvement matter, not board reportable."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Error and near-miss reporting', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328006', 'MCQ', 'A person in scrubs the nurse does not recognize, wearing no facility identification badge, asks to take a newborn to the nursery for tests. What should the nurse do FIRST?', 'Newborn security protocols require staff-identity verification before any infant is transferred.', '{"options":[{"id":"A","text":"Do not release the infant and verify the person''s identity"},{"id":"B","text":"Release the infant so testing is not delayed"},{"id":"C","text":"Ask the parents whether they recognize the person"},{"id":"D","text":"Escort the person and infant to the nursery together"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Infant abduction prevention requires confirming identity before any transfer.","B":"Incorrect. Releasing an unverified person risks abduction.","C":"Incorrect. Parents may not know staff; identity verification is the nurse''s responsibility.","D":"Incorrect. The infant should not leave until identity is confirmed."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Reproductive', 'Newborn security', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328007', 'MCQ', 'Before administering a blood transfusion, which method meets the standard for correctly identifying the client?', 'Safe identification requires two client-specific identifiers (e.g., name and DOB) verified against the wristband, never the room number.', '{"options":[{"id":"A","text":"Check two identifiers such as name and date of birth against the wristband"},{"id":"B","text":"Call the client by name and proceed when they answer"},{"id":"C","text":"Verify the room and bed number"},{"id":"D","text":"Confirm the client''s diagnosis with the chart"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two client-specific identifiers must be verified against the record.","B":"Incorrect. A confused or medicated client may answer to any name.","C":"Incorrect. Room/bed number is not a client-specific identifier.","D":"Incorrect. Diagnosis is not an approved identifier."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328008', 'MCQ', 'During a sterile dressing change, the nurse notices the edge of the sterile field has become wet from saline. What should the nurse do?', 'Moisture causes strike-through contamination; a wet sterile field is considered contaminated and must be replaced.', '{"options":[{"id":"A","text":"Consider the field contaminated and set up a new sterile field"},{"id":"B","text":"Dry the area with a sterile gauze and continue"},{"id":"C","text":"Use only the dry portion of the field"},{"id":"D","text":"Cover the wet area with a second sterile drape"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A wet field wicks microorganisms and is considered contaminated by strike-through.","B":"Incorrect. Moisture has already compromised sterility.","C":"Incorrect. Once contaminated, the field cannot be partially salvaged safely.","D":"Incorrect. Layering does not restore the compromised field."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Sterile technique', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328009', 'MCQ', 'A nurse receives a written order that reads ''digoxin 0.25 mg IV daily.'' The client''s most recent potassium is 2.9 mEq/L. What should the nurse do?', 'Verifying an order against relevant labs is a safety duty; hypokalemia potentiates digoxin toxicity, so the dose is held and clarified.', '{"options":[{"id":"A","text":"Hold the dose and contact the prescriber about the low potassium"},{"id":"B","text":"Administer the dose as ordered"},{"id":"C","text":"Give half the dose to be safe"},{"id":"D","text":"Administer oral potassium first, then the digoxin"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Hypokalemia increases digoxin toxicity risk; the order should be verified before administration.","B":"Incorrect. Giving digoxin with hypokalemia risks toxicity.","C":"Incorrect. A nurse cannot independently alter a prescribed dose.","D":"Incorrect. This requires a prescriber order and does not immediately correct the level."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Treatment-order verification', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328010', 'MCQ', 'A nurse accidentally breaks a mercury thermometer, spilling mercury on the floor. Which action is most appropriate?', 'Mercury is a hazardous material; the area is ventilated and the hazardous-materials spill protocol is followed rather than routine cleanup.', '{"options":[{"id":"A","text":"Ventilate the area, avoid touching it, and follow the facility hazardous-spill protocol"},{"id":"B","text":"Wipe it up with paper towels and discard in the regular trash"},{"id":"C","text":"Vacuum the mercury beads immediately"},{"id":"D","text":"Rinse the mercury down the sink drain"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Mercury is a hazardous material requiring containment per protocol, not routine cleanup.","B":"Incorrect. Mercury cannot go in regular trash and vaporizes when disturbed.","C":"Incorrect. Vacuuming aerosolizes mercury and increases exposure.","D":"Incorrect. Mercury must never enter the drain; it is an environmental hazard."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Biohazard handling', NULL, 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328011', 'MCQ', 'A nurse is teaching a parent of an 8-month-old about home safety. Which statement by the parent indicates a need for further teaching?', 'A crawling infant can reach under-sink cabinets; toxic products must be stored in locked, high locations.', '{"options":[{"id":"A","text":"\"I keep the cleaning products in the cabinet under the sink.\""},{"id":"B","text":"\"I installed gates at the top and bottom of the stairs.\""},{"id":"C","text":"\"I set the water heater to 120°F (49°C).\""},{"id":"D","text":"\"I put covers on all the electrical outlets.\""}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Under-sink storage is within reach of a mobile infant and needs correction.","B":"Incorrect. Stair gates are appropriate for this age.","C":"Incorrect. This setting reduces scald risk and is correct.","D":"Incorrect. Outlet covers are appropriate safety measures."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pediatrics', 'Multisystem', 'Injury prevention', 'Home safety', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_328012', 'MCQ', 'During a mass-casualty event using disaster triage, which client should the nurse tag as the HIGHEST priority for immediate treatment?', 'Disaster triage prioritizes salvageable, immediately life-threatening injuries; a tension pneumothorax is treatable and tagged immediate.', '{"options":[{"id":"A","text":"An adult with a tension pneumothorax and severe respiratory distress"},{"id":"B","text":"A client with a massive head injury who is not breathing after airway repositioning"},{"id":"C","text":"An adult with a closed femur fracture who is alert"},{"id":"D","text":"A client with minor abrasions who is walking"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A survivable but immediately life-threatening injury is tagged immediate (red).","B":"Incorrect. In disaster triage this client is expectant, not immediate.","C":"Incorrect. Stable fractures are delayed (yellow).","D":"Incorrect. Ambulatory minor injuries are minimal (green)."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Emergency preparedness', 'Triage', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_328013', 'SATA', 'A nurse is reviewing standard precautions with a new graduate. Which actions are consistent with standard precautions? Select all that apply.', 'Standard precautions apply to all clients: hand hygiene, PPE based on anticipated exposure, and safe sharps disposal without recapping.', '{"options":[{"id":"A","text":"Perform hand hygiene before and after client contact"},{"id":"B","text":"Wear gloves when contact with body fluids is anticipated"},{"id":"C","text":"Dispose of used needles in a puncture-resistant container without recapping"},{"id":"D","text":"Wear a gown when splashing of body fluids is likely"},{"id":"E","text":"Recap needles using both hands before disposal"},{"id":"F","text":"Apply an N95 respirator for all client contact"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Standard precautions', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_328014', 'SATA', 'A nurse is implementing fall-prevention measures for a hospitalized older adult identified as high risk. Which interventions are appropriate? Select all that apply.', 'Evidence-based fall prevention lowers the bed, secures the call light, provides nonskid footwear, and uses exit alarms; four raised rails are a restraint and dim lighting increases risk.', '{"options":[{"id":"A","text":"Keep the bed in the lowest position with wheels locked"},{"id":"B","text":"Ensure the call light is within reach"},{"id":"C","text":"Provide nonskid footwear"},{"id":"D","text":"Place a bed-exit alarm on the high-risk client"},{"id":"E","text":"Raise all four side rails to keep the client in bed"},{"id":"F","text":"Keep the room dimly lit at all times"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Fall prevention', NULL, 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_328015', 'SATA', 'A client has a provider order for bilateral soft wrist restraints for safety. Which nursing responsibilities apply while restraints are in use? Select all that apply.', 'Restraint safety requires frequent circulatory/skin assessment, quick-release ties to the movable bed frame, periodic release, and time-limited renewable orders.', '{"options":[{"id":"A","text":"Assess circulation, skin, and range of motion at regular intervals"},{"id":"B","text":"Secure the restraint ties to the movable part of the bed frame"},{"id":"C","text":"Release the restraints periodically to reposition and check the skin"},{"id":"D","text":"Ensure a time-limited order is renewed per policy"},{"id":"E","text":"Tie the restraints with a knot that requires scissors to remove"},{"id":"F","text":"Keep the client restrained continuously without reassessment"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Restraints', NULL, 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_328016', 'SATA', 'A nurse is about to administer an antibiotic when the client reports a previous reaction. Which reported reactions require the nurse to withhold the drug and notify the prescriber? Select all that apply.', 'Hives, angioedema, and bronchospasm are hypersensitivity reactions requiring the drug to be withheld; nausea and taste changes are non-allergic side effects.', '{"options":[{"id":"A","text":"Hives and generalized itching after a prior dose"},{"id":"B","text":"Swelling of the lips and tongue with the same drug class"},{"id":"C","text":"Wheezing and shortness of breath after a similar antibiotic"},{"id":"D","text":"Mild nausea that resolved with food"},{"id":"E","text":"A metallic taste in the mouth"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pharmacology', 'Immune', 'Allergy assessment', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_328017', 'SATA', 'A nurse is caring for a client using home oxygen therapy. Which safety measures should the nurse teach? Select all that apply.', 'Oxygen supports combustion, so it must be kept from flames, static-generating fabrics, and petroleum products, and tanks stored securely upright.', '{"options":[{"id":"A","text":"Keep the oxygen at least 6 feet from open flames"},{"id":"B","text":"Post ''No Smoking'' signs in the home"},{"id":"C","text":"Avoid using petroleum-based lip products"},{"id":"D","text":"Store oxygen tanks upright and secured"},{"id":"E","text":"Use wool blankets to reduce static buildup"},{"id":"F","text":"Apply electric heating pads near the tubing"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Integumentary', 'Safe equipment use', 'Oxygen safety', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_328018', 'SELECT_N', 'A client is placed on contact precautions for a multidrug-resistant organism. Which 3 actions are required?', 'Contact precautions require gown and gloves on entry, dedicated equipment, and hand hygiene after PPE removal; respirators and negative pressure are for airborne organisms.', '{"options":[{"id":"A","text":"Don a gown and gloves before entering the room"},{"id":"B","text":"Use dedicated equipment such as a stethoscope for this client"},{"id":"C","text":"Perform hand hygiene after removing PPE"},{"id":"D","text":"Wear an N95 respirator upon entering"},{"id":"E","text":"Keep the door closed with negative-pressure airflow"},{"id":"F","text":"Transport the client without any barrier precautions"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Transmission-based precautions', 'Contact', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_328019', 'TF', 'When wearing sterile gloves, the nurse may safely handle sterile items positioned below the waist as long as the gloves have not touched a non-sterile surface.', 'Anything below waist level or out of the line of vision is considered non-sterile, regardless of glove contact.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Sterile technique', NULL, 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_328020', 'MATRIX', 'For each client, click to indicate which type of transmission-based precaution is required.', 'Measles and disseminated zoster are airborne; pertussis and meningococcus are droplet; scabies is contact.', '{"row_label":"Client scenario","rows":[{"id":"r1","text":"Client with pertussis (whooping cough)"},{"id":"r2","text":"Client with active measles (rubeola)"},{"id":"r3","text":"Client with scabies infestation"},{"id":"r4","text":"Client with meningococcal meningitis"},{"id":"r5","text":"Client with disseminated herpes zoster"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c2","r2":"c1","r3":"c3","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Transmission-based precautions', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_328021', 'MATRIX_MR', 'For each task, select all personal protective equipment the nurse should wear (more than one may apply).', 'PPE is matched to the anticipated exposure and route: airborne TB adds an N95, contact organisms require gloves and gown, and routine venipuncture needs gloves.', '{"row_label":"Finding","rows":[{"id":"r1","text":"Suctioning a client with suspected tuberculosis"},{"id":"r2","text":"Bathing a client with a C. difficile infection"},{"id":"r3","text":"Starting a peripheral IV on a client with no known infection"},{"id":"r4","text":"Performing oral care on a client with MRSA in sputum"}],"columns":[{"id":"c1","text":"Gloves"},{"id":"c2","text":"Gown"},{"id":"c3","text":"N95 respirator"}]}'::jsonb, '{"cells":{"r1":["c1","c2","c3"],"r2":["c1","c2"],"r3":["c1"],"r4":["c1","c2"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE selection', NULL, 'Medium', 'Analyze', '{}', 8, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_328022', 'CLOZE', 'During a small fire in a client''s room, the nurse should first {1}, and when using the fire extinguisher should aim the nozzle at the {2}.', 'The RACE mnemonic begins with Rescue; the PASS technique aims the extinguisher at the base of the fire.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"rescue clients from immediate danger"},{"id":"c2","text":"activate the sprinkler system"},{"id":"c3","text":"document the event"}]},{"id":"b2","choices":[{"id":"c1","text":"base of the fire"},{"id":"c2","text":"top of the flames"},{"id":"c3","text":"smoke above the fire"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Fire safety', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_328023', 'HIGHLIGHT', 'A home-health nurse assesses an older adult''s living space. Highlight the findings that increase the client''s risk for falls. The client has [[loose throw rugs in the hallway]], [[grab bars installed in the bathroom]], [[dim lighting on the staircase]], a [[nightlight in the bedroom]], and [[electrical cords running across the walkway]].', 'Loose rugs, poor stair lighting, and cords across walkways are modifiable fall hazards; grab bars and nightlights are protective.', '{"chunks":[{"id":"h1","text":"loose throw rugs in the hallway"},{"id":"h2","text":"grab bars installed in the bathroom"},{"id":"h3","text":"dim lighting on the staircase"},{"id":"h4","text":"nightlight in the bedroom"},{"id":"h5","text":"electrical cords running across the walkway"}]}'::jsonb, '{"correct_ids":["h1","h3","h5"],"feedback":{"h1":"Loose rugs are a common trip hazard.","h2":"Grab bars reduce fall risk.","h3":"Poor lighting increases fall risk on stairs.","h4":"A nightlight improves safety.","h5":"Cords across walkways are a trip hazard."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Home environmental safety', NULL, 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_328024', 'BOWTIE', 'A nurse sustains a needlestick from a used hollow-bore needle. Complete the diagram by selecting the immediate actions, the concern, and the follow-up steps.', 'A needlestick is a bloodborne pathogen exposure; the site is washed and allowed to bleed, then reported immediately for baseline testing and prophylaxis.', '{"left":{"label":"Immediate actions","tokens":[{"id":"lt1","text":"Wash the site with soap and water"},{"id":"lt2","text":"Allow the wound to bleed freely"},{"id":"lt3","text":"Apply a tourniquet above the site"},{"id":"lt4","text":"Scrub the site with bleach"}]},"centre":{"label":"Primary concern","tokens":[{"id":"ct1","text":"Bloodborne pathogen exposure"},{"id":"ct2","text":"Local wound infection only"},{"id":"ct3","text":"Allergic reaction"}]},"right":{"label":"Follow-up steps","tokens":[{"id":"rt1","text":"Report the exposure per facility protocol"},{"id":"rt2","text":"Obtain baseline post-exposure testing"},{"id":"rt3","text":"Resume duties without documentation"},{"id":"rt4","text":"Wait one week before reporting"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'Needlestick exposure', NULL, 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DCZ_328025', 'DRAG_CLOZE', 'A nurse observes a coworker repeatedly failing to perform hand hygiene between clients. The nurse should first [1] and, if the behavior continues, [2].', 'Unsafe practice is first addressed directly with the peer; unresolved concerns are escalated up the chain of command to the manager.', '{"slots":[{"id":"s1","target_text":""},{"id":"s2","target_text":""}],"tokens":[{"id":"t1","text":"speak to the coworker directly about the observation"},{"id":"t2","text":"report the concern to the nurse manager"},{"id":"t3","text":"ignore it as none of the nurse''s concern"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Reporting unsafe practice', NULL, 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_328026', 'DRAG_ORDER', 'A nurse is preparing to enter the room of a client on airborne and contact precautions. Place the steps for donning PPE in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene"},{"id":"t2","text":"Put on the gown"},{"id":"t3","text":"Apply the N95 respirator"},{"id":"t4","text":"Put on goggles"},{"id":"t5","text":"Put on gloves"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Immune', 'PPE donning sequence', NULL, 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329001', 'MCQ', 'A nurse is assigned to a client newly diagnosed with active pulmonary tuberculosis. Which action by the nurse indicates correct implementation of precautions?', 'Active TB spreads by droplet nuclei, requiring a negative-pressure room and an N95 respirator.', '{"options":[{"id":"A","text":"Wearing a fitted N95 respirator before entering the room"},{"id":"B","text":"Placing the client in a room with positive-pressure airflow"},{"id":"C","text":"Wearing a surgical mask and gown when giving care"},{"id":"D","text":"Keeping the room door open for observation"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. TB requires airborne precautions with an N95 or higher respirator.","B":"Incorrect. Airborne precautions require negative-pressure airflow.","C":"Incorrect. A surgical mask does not filter airborne droplet nuclei.","D":"Incorrect. The door must remain closed to maintain negative pressure."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Transmission-based precautions', 'Airborne precautions', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329002', 'MCQ', 'A nurse is removing personal protective equipment after leaving a contact-precautions room. Which item should the nurse remove FIRST?', 'The CDC doffing sequence removes gloves first because they are the most contaminated item.', '{"options":[{"id":"A","text":"Gloves"},{"id":"B","text":"Mask"},{"id":"C","text":"Goggles"},{"id":"D","text":"Gown"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Gloves are the most contaminated and are removed first.","B":"Incorrect. The mask is removed last, after hand hygiene.","C":"Incorrect. Eye protection is removed after gloves and gown.","D":"Incorrect. The gown is removed after gloves."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'PPE', 'Doffing sequence', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329003', 'MCQ', 'A nurse cares for a client with Clostridioides difficile infection. Which action best reduces transmission of this organism?', 'C. difficile spores resist alcohol; mechanical removal by handwashing with soap and water is required.', '{"options":[{"id":"A","text":"Washing hands with soap and water after client contact"},{"id":"B","text":"Using alcohol-based hand rub after removing gloves"},{"id":"C","text":"Applying droplet precautions with a surgical mask"},{"id":"D","text":"Placing the client in a negative-pressure room"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. C. difficile spores are not killed by alcohol; soap and water are required.","B":"Incorrect. Alcohol does not eliminate C. difficile spores.","C":"Incorrect. C. difficile requires contact, not droplet, precautions.","D":"Incorrect. Negative pressure is for airborne pathogens."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'GI', 'Isolation precautions', 'Hand hygiene agent', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329004', 'MCQ', 'A client is placed in bilateral soft wrist restraints for safety after repeatedly pulling at an endotracheal tube. How often should the nurse assess circulation, skin integrity, and range of motion for the restrained extremities?', 'Restrained extremities require assessment at least every 2 hours to prevent neurovascular and skin injury.', '{"options":[{"id":"A","text":"Every 2 hours"},{"id":"B","text":"Every 8 hours"},{"id":"C","text":"Once per shift"},{"id":"D","text":"Only when the client complains"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Restrained limbs are assessed at least every 2 hours.","B":"Incorrect. This interval is too long and risks injury.","C":"Incorrect. Once per shift is insufficient for a restrained client.","D":"Incorrect. A confused or sedated client may not report problems."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Restraints', 'Monitoring', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329005', 'MCQ', 'A nurse discovers that a client received a double dose of a scheduled medication given by a colleague. After assessing the client, which action should the nurse take?', 'Medication errors require immediate assessment, provider notification, and an incident report; the report is not filed in the chart.', '{"options":[{"id":"A","text":"Complete an incident report and notify the provider"},{"id":"B","text":"Document the error only in the nurse''s personal log"},{"id":"C","text":"Record the details of the error in the client''s chart as a mistake"},{"id":"D","text":"Wait to see whether the client develops symptoms before acting"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Reporting and notifying the provider ensures safety and follow-up.","B":"Incorrect. Errors must be reported through the formal system.","C":"Incorrect. The incident report is a separate risk-management document, not charted.","D":"Incorrect. Delaying notification endangers the client."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Error and near-miss reporting', 'Incident reports', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329006', 'MCQ', 'Before administering a blood transfusion, a nurse prepares to verify the client''s identity. Which method meets the standard for client identification?', 'Two client-specific identifiers, such as name and date of birth, must be verified before high-risk procedures.', '{"options":[{"id":"A","text":"Checking the client''s name and date of birth against the wristband"},{"id":"B","text":"Asking the client to confirm the room and bed number"},{"id":"C","text":"Confirming the name posted above the bed"},{"id":"D","text":"Verifying the medical record number alone"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two client-specific identifiers are required.","B":"Incorrect. Room number is not an acceptable identifier.","C":"Incorrect. Posted signs are not reliable identifiers.","D":"Incorrect. Two distinct identifiers are required, not one."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Client identification', 'Two identifiers', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329007', 'MCQ', 'A home-health nurse assesses the home of an older adult with a history of falls. Which finding requires the most immediate intervention?', 'Loose rugs, especially near stairs, are a leading cause of serious falls in older adults.', '{"options":[{"id":"A","text":"Loose throw rugs at the top of a staircase"},{"id":"B","text":"A nightlight in the hallway"},{"id":"C","text":"Grab bars installed in the shower"},{"id":"D","text":"A cordless phone kept near the bed"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Rugs near stairs pose an immediate fall and injury hazard.","B":"Incorrect. A nightlight promotes safety.","C":"Incorrect. Grab bars reduce fall risk.","D":"Incorrect. An accessible phone supports safety."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Home and environmental safety', 'Fall prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329008', 'MCQ', 'A nurse working on a postpartum unit observes an unfamiliar person in scrubs without a hospital identification badge attempting to remove a newborn from the nursery. What is the nurse''s priority action?', 'An unidentified person removing a newborn is a potential abduction; the nurse must stop it and activate security immediately.', '{"options":[{"id":"A","text":"Prevent the person from leaving with the infant and alert security"},{"id":"B","text":"Ask the person to complete a visitor sign-in sheet"},{"id":"C","text":"Assume the person is a new staff member and continue working"},{"id":"D","text":"Escort the person to the charge nurse''s office"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Protecting the infant and activating security are the priority.","B":"Incorrect. This delays protection of the infant.","C":"Incorrect. Unverified access is a security threat.","D":"Incorrect. The infant must not leave the unit unverified."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Maternity', 'Reproductive', 'Security', 'Newborn abduction prevention', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329009', 'MCQ', 'A nurse must reposition a large, immobile client higher in bed. Which action best protects the nurse from injury?', 'Friction-reducing devices and adequate staff assistance are the safest way to reposition heavy clients.', '{"options":[{"id":"A","text":"Use a friction-reducing device and get additional staff to assist"},{"id":"B","text":"Lock the knees and bend at the waist to pull the client up"},{"id":"C","text":"Raise the head of the bed to a high-Fowler''s position first"},{"id":"D","text":"Pull the client up alone using the draw sheet"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Mechanical aids and teamwork reduce musculoskeletal injury.","B":"Incorrect. Bending at the waist strains the back.","C":"Incorrect. This works against gravity, increasing effort.","D":"Incorrect. Repositioning a large client alone risks injury."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Musculoskeletal', 'Ergonomics and safe handling', 'Body mechanics', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329010', 'MCQ', 'A client with a documented anaphylactic reaction to penicillin has a new prescription for cefazolin. What is the nurse''s best action?', 'A history of anaphylaxis to penicillin creates cross-sensitivity risk with cephalosporins; the order should be clarified.', '{"options":[{"id":"A","text":"Hold the medication and clarify the order with the provider"},{"id":"B","text":"Administer the cefazolin as prescribed"},{"id":"C","text":"Give an antihistamine before the cefazolin"},{"id":"D","text":"Administer a test dose of penicillin first"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Cephalosporins carry cross-sensitivity risk with penicillin allergy.","B":"Incorrect. This risks a cross-reactive anaphylactic response.","C":"Incorrect. Premedication does not make giving it safe after anaphylaxis.","D":"Incorrect. Re-exposing to penicillin is dangerous."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Pharmacology', 'Immune', 'Allergy assessment', 'Cross-sensitivity', 'Medium', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329011', 'MCQ', 'While setting up a sterile dressing change, a nurse notices that the outer inch of the sterile drape is hanging below the edge of the table. How should the nurse proceed?', 'A sterile field is maintained only at or above waist/tabletop level; anything below the table edge is contaminated.', '{"options":[{"id":"A","text":"Consider the area below the table edge contaminated and avoid it"},{"id":"B","text":"Continue, since the drape itself came from a sterile package"},{"id":"C","text":"Fold the hanging portion back onto the sterile field"},{"id":"D","text":"Spray the hanging portion with antiseptic solution"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Anything below the table surface is considered unsterile.","B":"Incorrect. Sterility below the tabletop cannot be assured.","C":"Incorrect. This contaminates the field.","D":"Incorrect. Spraying does not restore sterility."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Integumentary', 'Sterile technique', 'Sterile field', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MCQ_329012', 'MCQ', 'A nurse notices a coworker preparing to administer an intravenous medication without scanning the client''s wristband or the medication barcode, contrary to unit policy. What is the nurse''s most appropriate action?', 'Unsafe practice is first addressed directly and then escalated through the chain of command.', '{"options":[{"id":"A","text":"Address the observation with the coworker directly and, if unresolved, notify the charge nurse"},{"id":"B","text":"Say nothing to avoid conflict with the coworker"},{"id":"C","text":"Report the coworker to the state board of nursing immediately"},{"id":"D","text":"Scan the medication for the coworker to speed things up"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Direct communication followed by escalation protects the client.","B":"Incorrect. Ignoring an unsafe practice endangers the client.","C":"Incorrect. The chain of command should be used first.","D":"Incorrect. This does not address the unsafe practice."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Leadership and Management', 'Multisystem', 'Reporting unsafe staff practice', 'Chain of command', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_329013', 'SATA', 'A nurse teaches new staff about hand hygiene. Which situations require hand hygiene? Select all that apply.', 'Hand hygiene is performed before and after gloving, before entering and after leaving a room, and after client contact — not just when visibly soiled.', '{"options":[{"id":"A","text":"Before donning gloves for a procedure"},{"id":"B","text":"After removing gloves"},{"id":"C","text":"Before entering a client''s room"},{"id":"D","text":"After contact with a client''s intact skin"},{"id":"E","text":"Only when hands are visibly soiled"},{"id":"F","text":"Only at the start and end of the shift"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Standard precautions', 'Hand hygiene', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_329014', 'SATA', 'A client has a wound infected with methicillin-resistant Staphylococcus aureus (MRSA). Which interventions are appropriate for this client? Select all that apply.', 'MRSA requires contact precautions: gown, gloves, private/cohort room, dedicated equipment, and hand hygiene — not airborne measures.', '{"options":[{"id":"A","text":"Wear gloves and a gown when providing direct care"},{"id":"B","text":"Place the client in a private room or cohort with a similarly infected client"},{"id":"C","text":"Dedicate equipment such as a stethoscope to the client"},{"id":"D","text":"Perform hand hygiene before and after care"},{"id":"E","text":"Require all visitors to wear an N95 respirator"},{"id":"F","text":"Maintain the room under negative pressure"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Integumentary', 'Transmission-based precautions', 'Contact precautions', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_329015', 'SATA', 'A nurse admits a client with a history of generalized tonic-clonic seizures. Which seizure precautions should the nurse implement? Select all that apply.', 'Seizure precautions include padded rails, available suction and oxygen, and a low bed; forcing objects into the mouth and restraining limbs are contraindicated.', '{"options":[{"id":"A","text":"Pad the side rails of the bed"},{"id":"B","text":"Keep suction equipment available at the bedside"},{"id":"C","text":"Have oxygen readily available"},{"id":"D","text":"Insert a padded tongue blade during a seizure"},{"id":"E","text":"Restrain the client''s limbs during a seizure"},{"id":"F","text":"Keep the bed in the lowest position"}]}'::jsonb, '{"answers":["A","B","C","F"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Neurological', 'Injury prevention', 'Seizure precautions', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_329016', 'SATA', 'During a mass-casualty incident, a nurse performs triage. Which clients should be tagged for immediate (highest priority) care? Select all that apply.', 'Immediate (red) tags go to survivable life threats such as airway obstruction, hemorrhage, and tension pneumothorax; minor injuries and nonsurvivable injuries are lower priority.', '{"options":[{"id":"A","text":"A client with an airway obstruction"},{"id":"B","text":"A client with active, uncontrolled hemorrhage"},{"id":"C","text":"A client with tension pneumothorax"},{"id":"D","text":"A client with a closed fracture of the forearm"},{"id":"E","text":"A client with full-thickness burns over 90% of the body and no pulse"},{"id":"F","text":"A client with minor lacerations who is ambulatory"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Community Health', 'Multisystem', 'Emergency preparedness', 'Triage', 'Medium', 'Analyze', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SATA_329017', 'SATA', 'A nurse reviews safe handling of biohazardous materials. Which actions are correct? Select all that apply.', 'Sharps go in puncture-resistant containers without recapping; PPE is worn for spills, biohazard waste is bagged and labeled, and containers are replaced when about two-thirds full.', '{"options":[{"id":"A","text":"Dispose of used needles in a puncture-resistant sharps container"},{"id":"B","text":"Avoid recapping needles after use"},{"id":"C","text":"Wear appropriate PPE when cleaning a blood spill"},{"id":"D","text":"Recap needles using both hands before disposal"},{"id":"E","text":"Place blood-soaked dressings in a labeled biohazard bag"},{"id":"F","text":"Fill the sharps container completely to the top before replacing it"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Biohazard and hazardous material handling', 'Sharps and spills', 'Medium', 'Apply', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_SELN_329018', 'SELECT_N', 'A nurse teaches a client using home oxygen therapy about safety. Which 3 instructions should the nurse include?', 'Home oxygen safety includes keeping oxygen away from flames, posting no-smoking signs, and avoiding petroleum products; tanks are stored upright and flow rates are not self-adjusted.', '{"options":[{"id":"A","text":"Keep the oxygen at least 6 feet from open flames and heat sources"},{"id":"B","text":"Post ''No Smoking'' signs in the home"},{"id":"C","text":"Avoid using petroleum-based products around the face"},{"id":"D","text":"Store the oxygen tank lying flat under the bed"},{"id":"E","text":"Use wool blankets to reduce static near the tank"},{"id":"F","text":"Turn up the flow rate whenever short of breath"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Safe equipment use', 'Oxygen safety', 'Medium', 'Apply', '{}', 3, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_329019', 'TF', 'A client with seasonal influenza requires airborne precautions, including placement in a negative-pressure room.', 'Influenza spreads by large droplets and requires droplet precautions with a surgical mask, not airborne precautions.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"B","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Respiratory', 'Transmission-based precautions', 'Droplet precautions', 'Medium', 'Understand', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_TF_329020', 'TF', 'If a prescribed medication dose appears to exceed the safe range, the nurse should withhold the dose and clarify the order with the prescriber before administering it.', 'Nurses are responsible for verifying that orders are safe and must clarify a questionable dose before administration.', '{"options":[{"id":"A","text":"True"},{"id":"B","text":"False"}]}'::jsonb, '{"answer":"A","feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Treatment-order verification', 'Clarifying orders', 'Medium', 'Apply', '{}', 1, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MAT_329021', 'MATRIX', 'For each condition, click to indicate the type of transmission-based precaution required.', 'Measles and varicella are airborne; pertussis and meningococcal disease are droplet; C. difficile is contact.', '{"row_label":"Condition","rows":[{"id":"r1","text":"Measles (rubeola)"},{"id":"r2","text":"Pertussis (whooping cough)"},{"id":"r3","text":"Clostridioides difficile"},{"id":"r4","text":"Varicella (chickenpox)"},{"id":"r5","text":"Neisseria meningitidis meningitis"}],"columns":[{"id":"c1","text":"Airborne"},{"id":"c2","text":"Droplet"},{"id":"c3","text":"Contact"}]}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1","r5":"c2"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Multisystem', 'Transmission-based precautions', 'Precaution type', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_MMR_329022', 'MATRIX_MR', 'For each situation, select all personal protective equipment the nurse should wear.', 'PPE is matched to anticipated exposure; splash-generating tasks require gloves, gown, and eye protection.', '{"row_label":"Situation","rows":[{"id":"r1","text":"Emptying a urinary drainage bag"},{"id":"r2","text":"Irrigating a wound expected to splash"},{"id":"r3","text":"Suctioning an airway with copious secretions"},{"id":"r4","text":"Performing oral care on a client with copious secretions"}],"columns":[{"id":"c1","text":"Gloves"},{"id":"c2","text":"Gown"},{"id":"c3","text":"Face shield/goggles"}]}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c1","c2","c3"],"r3":["c1","c2","c3"],"r4":["c1","c3"]},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'PPE', 'PPE selection', 'Medium', 'Analyze', '{}', 9, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_CLZ_329023', 'CLOZE', 'A nurse sustains a needlestick injury from a used hollow-bore needle. The nurse should first {1}, and then {2}.', 'After a needlestick, the site is washed with soap and water, then the exposure is reported promptly so post-exposure prophylaxis can be evaluated.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"wash the site with soap and water"},{"id":"c2","text":"apply a tourniquet above the site"},{"id":"c3","text":"squeeze the site to force out blood"}]},{"id":"b2","choices":[{"id":"c1","text":"report the exposure to employee health"},{"id":"c2","text":"resume client care and monitor for symptoms"},{"id":"c3","text":"discard the incident to avoid paperwork"}]}]}'::jsonb, '{"answers":{"b1":"c1","b2":"c1"},"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'Standard precautions', 'Post-exposure', 'Medium', 'Apply', '{}', 2, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_HL_329024', 'HIGHLIGHT', 'Highlight the findings that increase this client''s risk for falls. The client is [[80 years old]], takes [[a sedative-hypnotic at bedtime]], reports [[orthostatic dizziness on standing]], has a [[history of two falls in the past year]], eats a regular diet, and has [[clear vision with corrective lenses]].', 'Advanced age, sedatives, orthostatic dizziness, and prior falls all raise fall risk; corrected clear vision does not.', '{"chunks":[{"id":"h1","text":"80 years old"},{"id":"h2","text":"a sedative-hypnotic at bedtime"},{"id":"h3","text":"orthostatic dizziness on standing"},{"id":"h4","text":"history of two falls in the past year"},{"id":"h5","text":"clear vision with corrective lenses"}]}'::jsonb, '{"correct_ids":["h1","h2","h3","h4"],"feedback":{"h1":"Advanced age raises fall risk.","h2":"Sedatives impair balance and alertness.","h3":"Orthostatic dizziness increases fall risk.","h4":"Prior falls strongly predict future falls.","h5":"Corrected clear vision is not a risk factor."}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Neurological', 'Injury prevention', 'Fall risk cues', 'Medium', 'Analyze', '{}', 4, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_BT_329025', 'BOWTIE', 'A client develops hives, wheezing, and hypotension shortly after a nurse dons latex gloves for a procedure. Complete the diagram by selecting the actions to take, the condition, and the parameters to monitor.', 'Sudden hives, wheezing, and hypotension after latex exposure indicate anaphylaxis; remove latex, give epinephrine, and monitor airway and blood pressure.', '{"left":{"label":"Actions to take","tokens":[{"id":"lt1","text":"Remove all latex products from contact"},{"id":"lt2","text":"Prepare to administer epinephrine as prescribed"},{"id":"lt3","text":"Apply latex gloves to the other hand"},{"id":"lt4","text":"Continue the procedure quickly"}]},"centre":{"label":"Condition","tokens":[{"id":"ct1","text":"Latex allergy anaphylaxis"},{"id":"ct2","text":"Contact dermatitis"},{"id":"ct3","text":"Vasovagal syncope"}]},"right":{"label":"Parameters to monitor","tokens":[{"id":"rt1","text":"Airway and respiratory status"},{"id":"rt2","text":"Blood pressure"},{"id":"rt3","text":"Deep tendon reflexes"},{"id":"rt4","text":"Bowel sounds"}]}}'::jsonb, '{"left":["lt1","lt2"],"centre":"ct1","right":["rt1","rt2"],"feedback":{}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Medical-Surgical', 'Immune', 'Emergency response', 'Latex allergy', 'Medium', 'Analyze', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP'),
('NCLEX_DO_329026', 'DRAG_ORDER', 'A nurse prepares to enter the room of a client on contact and droplet precautions. Place the steps for donning personal protective equipment in the correct order.', NULL, '{"slots":[{"id":"s1","target_text":"1st action"},{"id":"s2","target_text":"2nd action"},{"id":"s3","target_text":"3rd action"},{"id":"s4","target_text":"4th action"},{"id":"s5","target_text":"5th action"}],"tokens":[{"id":"t1","text":"Perform hand hygiene"},{"id":"t2","text":"Put on the gown"},{"id":"t3","text":"Put on the mask"},{"id":"t4","text":"Put on goggles or face shield"},{"id":"t5","text":"Put on gloves"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb, 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Fundamentals of Nursing', 'Multisystem', 'PPE', 'Donning sequence', 'Medium', 'Apply', '{}', 5, TRUE, TRUE, FALSE, 'DEV_CAT_POOL', 'CATPREP')
